        (, , uint256 lpAmountAdded) = router.addLiquidityETH{value: ethForPool}(
            token,
            tokensForPool,
            _minWithSlippage(tokensForPool),
            _minWithSlippage(ethForPool),
            address(locker), // LP tokens mint straight to the locker -- never pass through this factory
            block.timestamp + 15 minutes
        );
        lpAmount = lpAmountAdded;

        pair = IUniswapV2FactoryMinimal(router.factory()).getPair(token, router.WETH());
        require(pair != address(0), "BondingCurveFactory: pair not found after addLiquidityETH");
        pairOf[token] = pair;

        uint256 effectiveRewardBps = rewardsDistributor != address(0) ? curve.taxRewardBps : 0;
        uint256 effectiveCreatorRewardBps = creatorRewardsDistributor != address(0) ? curve.taxCreatorRewardBps : 0;
        LaunchedToken(token).configureTax(
            pair, curve.taxPlatformFeeWallet, curve.taxFeeBps, curve.taxPriceFeed, curve.taxGraduationTargetUsd, curve.taxMaxOracleStaleness,
            rewardsDistributor, effectiveRewardBps, creatorRewardsDistributor, effectiveCreatorRewardBps,
            feeWalletDistributor
        );

        uint256 unlockTime = block.timestamp + lpLockDuration;
        lockId = locker.lock(pair, curve.creator, lpAmount, unlockTime);

        emit CurveGraduated(token, pair, ethForPool, tokensForPool, lpAmount, unlockTime, lockId);
    }

    // ---- views ----

    function quoteBuy(address token, uint256 ethIn) external view returns (uint256 tokensOut, uint256 feeAmount) {
        Curve storage curve = curves[token];
        require(curve.totalSupply > 0, "BondingCurveFactory: unknown curve");
        (tokensOut, feeAmount, ) = _quoteBuy(curve, ethIn);
    }

    function quoteSell(address token, uint256 tokenAmountIn) external view returns (uint256 ethOut, uint256 feeAmount) {
        Curve storage curve = curves[token];
        require(curve.totalSupply > 0, "BondingCurveFactory: unknown curve");
        SellQuote memory quote = _quoteSell(curve, tokenAmountIn);
        ethOut = quote.netEthOut;
        feeAmount = quote.feeAmount;
    }

    function curveState(address token)
        external
        view
        returns (
            address creator,
            uint256 totalSupply_,
            uint256 curveSupply,
            uint256 tokensRemaining,
            uint256 virtualEthReserve,
            uint256 virtualTokenReserve,
            uint256 realEthReserve,
            uint256 poolSeedTargetWei_,
            uint256 curveFeeBps_,
            bool graduated,
            uint256 createdAt
        )
    {
        Curve storage curve = curves[token];
        require(curve.totalSupply > 0, "BondingCurveFactory: unknown curve");
        return (
            curve.creator,
            curve.totalSupply,
            curve.curveSupply,
            curve.tokensRemaining,
            curve.virtualEthReserve,
            curve.virtualTokenReserve,
            curve.realEthReserve,
            curve.poolSeedTargetWei,
            curve.curveFeeBps,
            curve.graduated,
            curve.createdAt
        );
    }

    /// @notice The seven post-graduation tax terms this specific curve is
    /// locked into (Finding 4) -- snapshotted once, at createCurveToken()
    /// time, and applied verbatim in _doGraduate whenever this curve
    /// eventually graduates, regardless of what setTaxDefaults() has done
    /// to the live globals in the meantime.
    function curveTaxConfig(address token)
        external
        view
        returns (
            address taxPlatformFeeWallet,
            uint256 taxFeeBps,
            address taxPriceFeed,
            uint256 taxGraduationTargetUsd,
            uint256 taxMaxOracleStaleness,
            uint256 taxRewardBps,
            uint256 taxCreatorRewardBps
        )
    {
        Curve storage curve = curves[token];
        require(curve.totalSupply > 0, "BondingCurveFactory: unknown curve");
        return (
            curve.taxPlatformFeeWallet,
            curve.taxFeeBps,
            curve.taxPriceFeed,
            curve.taxGraduationTargetUsd,
            curve.taxMaxOracleStaleness,
            curve.taxRewardBps,
            curve.taxCreatorRewardBps
        );
    }

    function tokensOf(address creator_) external view returns (address[] memory) {
        return _tokensByCreator[creator_];
    }

    function allTokens() external view returns (address[] memory) {
        return _tokenList;
    }

    /// @notice Previews the address createCurveToken() will deploy to for a
    /// given (creator, salt) pair -- see TokenFactory.predictTokenAddress
    /// for the full explanation; applies identically here.
    function predictTokenAddress(address creator_, uint256 salt) external view returns (address) {
        return Clones.predictDeterministicAddress(tokenImplementation, _deriveTokenSalt(creator_, salt), address(this));
    }

    // ---- admin ----

    function setCurveFeeBps(uint256 newBps) external onlyOwner {
        require(newBps <= MAX_FEE_BPS, "BondingCurveFactory: feeBps exceeds MAX_FEE_BPS ceiling");
        curveFeeBps = newBps;
        emit CurveFeeBpsUpdated(newBps);
    }

    function setCurveSupplyBps(uint256 newBps) external onlyOwner {
        require(newBps > 0 && newBps <= 10_000, "BondingCurveFactory: curveSupplyBps must be in (0, 10000]");
        curveSupplyBps = newBps;
        emit CurveSupplyBpsUpdated(newBps);
    }

    function setVirtualEthReserveDefault(uint256 newDefault) external onlyOwner {
        virtualEthReserveDefault = newDefault;
        emit VirtualEthReserveDefaultUpdated(newDefault);
    }

    function setVirtualTokenReserveBps(uint256 newBps) external onlyOwner {
        require(newBps > 0, "BondingCurveFactory: virtualTokenReserveBps must be > 0");
        virtualTokenReserveBps = newBps;
        emit VirtualTokenReserveBpsUpdated(newBps);
    }

    /// @notice Updates the default real-ETH-raised threshold (in wei) new
    /// curves must cross before they graduate into a pool. Renamed from
    /// setEthGraduationTarget (Finding 6) to match the state variable's own
    /// rename -- only ever affects curves created after this call; a live
    /// curve keeps whatever value it snapshotted at its own creation.
    function setPoolSeedTargetWei(uint256 newTarget) external onlyOwner {
        require(newTarget > 0, "BondingCurveFactory: graduation target must be > 0");
        poolSeedTargetWei = newTarget;
        emit PoolSeedTargetUpdated(newTarget);
    }

    function setCurveLaunchFee(uint256 newFee) external onlyOwner {
        curveLaunchFee = newFee;
        emit CurveLaunchFeeUpdated(newFee);
    }

    function setLpLockDuration(uint256 newDuration) external onlyOwner {
        lpLockDuration = newDuration;
        emit LpLockDurationUpdated(newDuration);
    }

    function setMaxCreatorBuyBps(uint256 newBps) external onlyOwner {
        require(newBps <= 10_000, "BondingCurveFactory: bps cannot exceed 100%");
        maxCreatorBuyBps = newBps;
        emit MaxCreatorBuyBpsUpdated(newBps);
    }

    /// @notice See TokenFactory.setLiquiditySlippageBps -- identical fixed
    /// 5.00%-8.00% band, applied to _doGraduate's own addLiquidityETH call.
    function setLiquiditySlippageBps(uint256 newBps) external onlyOwner {
        require(newBps >= MIN_LIQUIDITY_SLIPPAGE_BPS, "BondingCurveFactory: slippage below 5% floor");
        require(newBps <= MAX_LIQUIDITY_SLIPPAGE_BPS, "BondingCurveFactory: slippage above 8% ceiling");
        liquiditySlippageBps = newBps;
        emit LiquiditySlippageBpsUpdated(newBps);
    }

    function setFeeTreasury(address newTreasury) external onlyOwner {
        require(newTreasury != address(0), "BondingCurveFactory: invalid treasury");
        feeTreasury = newTreasury;
        emit FeeTreasuryUpdated(newTreasury);
    }

    function setRewardsDistributor(address newDistributor) external onlyOwner {
        rewardsDistributor = newDistributor;
        emit RewardsDistributorUpdated(newDistributor);
    }

    function setCreatorRewardsDistributor(address newDistributor) external onlyOwner {
        creatorRewardsDistributor = newDistributor;
        emit CreatorRewardsDistributorUpdated(newDistributor);
    }

    function setFeeWalletDistributor(address newDistributor) external onlyOwner {
        feeWalletDistributor = newDistributor;
        emit FeeWalletDistributorUpdated(newDistributor);
    }

    /// @notice Points relayedCreateCurveToken's onlyRelayer gate at the
    /// platform's relayer hot wallet. See TokenFactory.setRelayer for the
    /// full explanation -- identical convention, including the requirement
    /// that maxRelayerGasReimbursementWei already be set to a real, non-zero
    /// value before a relayer can be enabled. address(0) (the default)
    /// disables gasless relayed curve launches entirely;
    /// depositForRelayedLaunch/reclaimDeposit still work either way.
    function setRelayer(address newRelayer) external onlyOwner {
        if (newRelayer != address(0)) {
            require(
                maxRelayerGasReimbursementWei > 0,
                "BondingCurveFactory: set maxRelayerGasReimbursementWei before enabling a relayer"
            );
        }
        relayer = newRelayer;
        emit RelayerUpdated(newRelayer);
    }

    /// @notice See TokenFactory.setMaxRelayerGasReimbursement -- identical
    /// circuit breaker, applied to relayedCreateCurveToken's own
    /// _settleRelayedFee.
    ///
    /// FIX (this review, same class as TokenFactory's own F-2): setRelayer()
    /// above only checks maxRelayerGasReimbursementWei > 0 at the moment a
    /// relayer is *enabled* -- this setter had no corresponding check, so it
    /// could be called with newCapWei == 0 at any later time, including
    /// while a relayer was already active, silently reopening the circuit
    /// breaker setRelayer() exists to enforce. Now rejects zeroing the cap
    /// while a relayer is configured.
    function setMaxRelayerGasReimbursement(uint256 newCapWei) external onlyOwner {
        require(
            relayer == address(0) || newCapWei > 0,
            "BondingCurveFactory: cannot zero the gas reimbursement cap while a relayer is active"
        );
        maxRelayerGasReimbursementWei = newCapWei;
        emit MaxRelayerGasReimbursementUpdated(newCapWei);
    }

    /// @notice Update the POST-graduation LaunchedToken tax defaults applied
    /// to curves CREATED from this point forward (Finding 4 -- these are
    /// snapshotted per curve at createCurveToken() time, not read live at
    /// graduation, so this never touches an already-existing curve's own
    /// locked-in terms, however long it's been trading). See
    /// TokenFactory.setTaxDefaults for the full explanation of every bound
    /// enforced below -- identical reasoning, identical ceiling.
    function setTaxDefaults(
        address platformFeeWallet_,
        uint256 feeBps_,
        address priceFeed_,
        uint256 graduationTargetUsd_,
        uint256 maxOracleStaleness_,
        uint256 rewardBps_,
        uint256 creatorRewardBps_
    ) external onlyOwner {
        require(feeBps_ <= MAX_FEE_BPS, "BondingCurveFactory: feeBps exceeds MAX_FEE_BPS ceiling");
        require(graduationTargetUsd_ > 0, "BondingCurveFactory: graduation target must be > 0");
        require(maxOracleStaleness_ > 0, "BondingCurveFactory: oracle staleness must be > 0");
        require(rewardBps_ + creatorRewardBps_ <= feeBps_, "BondingCurveFactory: rewardBps+creatorRewardBps cannot exceed feeBps");
        platformFeeWallet = platformFeeWallet_;
        feeBps = feeBps_;
        priceFeed = priceFeed_;
        graduationTargetUsd = graduationTargetUsd_;
        maxOracleStaleness = maxOracleStaleness_;
        rewardBps = rewardBps_;
        creatorRewardBps = creatorRewardBps_;
        emit TaxDefaultsUpdated();
    }

    /// @notice Escape hatch for an already-graduated curve's token whose
    /// price feed has gone permanently stale -- see
    /// TokenFactory.updateTokenPriceFeed / LaunchedToken.updatePriceFeed for
    /// the full explanation; applies identically here. Deliberately calls
    /// into the token directly rather than touching curve.taxPriceFeed
    /// (which stops mattering the moment a curve graduates -- configureTax
    /// already ran, once, with whatever value was snapshotted at that time).
    function updateTokenPriceFeed(address token, address newPriceFeed_, uint256 newMaxOracleStaleness_) external onlyOwner {
        LaunchedToken(token).updatePriceFeed(newPriceFeed_, newMaxOracleStaleness_);
        emit TokenPriceFeedUpdated(token, newPriceFeed_, newMaxOracleStaleness_);
    }

    /// @notice Sweeps ETH that _distributeEthFee couldn't deliver (Finding 1
    /// / strandedFees) to `to`. Deliberately scoped to ONLY the tracked
    /// strandedFees counter -- never address(this).balance directly -- so
    /// this can never touch a live curve's own realEthReserve or a router
    /// refund still earmarked for a specific curve's graduation.
    function rescueStrandedFees(address to, uint256 amount) external onlyOwner {
        require(to != address(0), "BondingCurveFactory: invalid recipient");
        require(amount <= strandedFees, "BondingCurveFactory: exceeds stranded fees");
        strandedFees -= amount;
        (bool sent, ) = payable(to).call{value: amount}("");
        require(sent, "BondingCurveFactory: rescue transfer failed");
        emit StrandedFeesRescued(to, amount);
    }

    /// @notice Rescues an ERC20 mistakenly sent directly to this contract
    /// (Finding 5). Cannot be used on any token this factory itself ever
    /// created as a curve -- live or already graduated -- so this can never
    /// be used to pull a curve's own tracked token balance; it only reaches
    /// a token that has nothing to do with any curve at all.
    function rescueToken(address token, address to, uint256 amount) external onlyOwner {
        require(to != address(0), "BondingCurveFactory: invalid recipient");
        require(creatorOf[token] == address(0), "BondingCurveFactory: cannot rescue a curve's own token");
        bool sent = IERC20(token).transfer(to, amount);
        require(sent, "BondingCurveFactory: token rescue failed");
        emit TokenRescued(token, to, amount);
    }

    /// @notice Circuit breaker on new buy() calls only -- sell() is never
    /// pausable, so a holder can always exit a live curve regardless of
    /// this. See the contract-level note on why this factory (uniquely
    /// among HoodLaunch's contracts so far) needs one at all: it sits on
    /// every live curve's pooled ETH simultaneously, for as long as each one
    /// trades.
    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }
}

contracts/CreatorRewardsDistributor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import "./interfaces/IUniswapV2Router02.sol";
import "./interfaces/IUniswapV2Pair.sol";
import "./interfaces/ICreatorAware.sol";

/// @title CreatorRewardsDistributor
/// @notice Where the creator-reward slice of every taxed buy/sell ends up.
/// LaunchedToken/CustomToken each carve creatorRewardBps (out of their total
/// feeBps/platformFeeBps platform tax — never on top of it, and never
/// overlapping the existing rewardBps carve-out to PlatformRewardsDistributor)
/// off of every taxed transfer and send it here, in-kind, in whatever token
/// that trade was actually taxed in. See LaunchedToken._update /
/// CustomToken._update.
///
/// Unlike PlatformRewardsDistributor — which pools every token's
/// contribution into one shared PlatformToken buyback split across all
/// PlatformToken holders — this keeps every token's creator-reward stream
/// entirely separate and pays out in native ETH, per token, to that
/// specific token's own creator. Closer to how pump.fun's creator-fee-share
/// works than to this platform's own holder-airdrop mechanism.
///
/// Flow, per token:
///  1. In-kind creatorRewardBps accumulates here as an ordinary ERC20
///     balance of that token — no bookkeeping needed for this step, the
///     token's own balanceOf(this) already is the ledger.
///  2. Anyone (typically an off-chain keeper — see scripts/relayer.js's
///     pollCreatorRewardSwaps) calls triggerCreatorSwap(token) once the
///     accumulated balance clears that token's swapThreshold. This swaps
///     the FULL current balance for ETH via the router (using the
///     fee-on-transfer-tolerant variant, since the token being sold here can
///     itself carry a live transfer tax) and credits claimableEth[token].
///  3. Anyone can call claimCreatorRewards(token) — it always pays out to
///     that token's own creator(), regardless of who calls it, so a
///     creator's own "Claim" button on the site, an off-chain keeper, or a
///     direct call from a block explorer all resolve to the exact same
///     recipient.
///
/// claimableEth is keyed by TOKEN, not by creator address, deliberately —
/// per-token claiming is the explicit design here. A creator with several
/// launches gets several independent claimable balances, one per token,
/// matching how a portfolio view naturally lists them — never one pooled
/// balance across everything a wallet has ever launched.
contract CreatorRewardsDistributor is Ownable2Step, ReentrancyGuard {
    IUniswapV2Router02 public immutable router;

    /// @notice ETH owed to a token's creator, credited by
    /// triggerCreatorSwap and zeroed by claimCreatorRewards. Keyed by the
    /// TOKEN address (see contract-level comment for why), not the
    /// creator's own address.
    mapping(address => uint256) public claimableEth;

    /// @notice Minimum balance of `token` this contract must be holding
    /// before triggerCreatorSwap(token) will execute — same anti-dust/
    /// anti-griefing knob as PlatformRewardsDistributor.tokenBuybackThreshold,
    /// and for the same reason a single global threshold wouldn't make sense
    /// (every token has its own supply/decimals scale). Defaults to 0 (any
    /// nonzero balance triggers) until the owner sets one for a given token.
    mapping(address => uint256) public swapThreshold;

    /// @notice Caps how much of `token`'s balance a single
    /// triggerCreatorSwap(token) call is allowed to sell — the anti-dump
    /// knob. Before this existed, an infrequently-triggered token could
    /// accumulate a large balance and then have its *entire* pile sold in
    /// one swap the moment someone finally called triggerCreatorSwap,
    /// showing up as a single visible dump against that token's own pool.
    /// Defaults to 0, meaning "uncapped" (the original all-at-once
    /// behavior) until the owner sets one. Once set, a balance above the
    /// cap is drained across multiple separate calls instead of one — each
    /// individual swap stays small and proportional, at the cost of taking
    /// more calls (and, if swapThreshold is also set, more time re-crossing
    /// it between partial drains) to fully clear a large backlog. See
    /// scripts/relayer.js's creator-rewards sweep loop, which already calls
    /// this on a recurring schedule and so naturally keeps re-draining a
    /// capped balance over successive ticks without any changes needed
    /// there.
    mapping(address => uint256) public maxSwapAmount;

    /// @notice Protective slippage floor applied to triggerCreatorSwap's own
    /// router trade — see Finding CR-2 in the accompanying audit report.
    /// Before this existed, triggerCreatorSwap accepted a purely
    /// caller-supplied minEthOut with no protocol-side floor computed from
    /// the pool's own reserves; since the function is deliberately
    /// permissionless (see its own comment), anyone could call it with
    /// minEthOut == 0 and sandwich their own call for MEV profit at the
    /// creator's expense. Same fixed 5.00%-8.00% band, and the same
    /// "whichever is stricter" combination with the caller's own minEthOut,
    /// already used for CustomToken/CustomTokenFactory's internal swaps.
    uint256 public swapSlippageBps = 600; // 6.00% default
    uint256 public constant MIN_SWAP_SLIPPAGE_BPS = 500; // 5.00%
    uint256 public constant MAX_SWAP_SLIPPAGE_BPS = 800; // 8.00%

    event SwapThresholdUpdated(address indexed token, uint256 newThreshold);
    event MaxSwapAmountUpdated(address indexed token, uint256 newMax);
    event SwapSlippageBpsUpdated(uint256 newBps);
    event CreatorSwapTriggered(address indexed token, address indexed creator, uint256 amountIn, uint256 ethOut);
    event CreatorRewardsClaimed(address indexed token, address indexed creator, address indexed caller, uint256 amount);
    event OrphanedEthRescued(address indexed token, address indexed to, uint256 amount);
    event OrphanedTokensRescued(address indexed token, address indexed to, uint256 amount);

    constructor(address router_, address initialOwner_) Ownable(initialOwner_) {
        require(router_ != address(0), "CreatorRewardsDistributor: invalid router");
        router = IUniswapV2Router02(router_);
    }

    /// @notice Lets this contract receive ETH — its only intended inflow is
    /// the swap output inside triggerCreatorSwap below, but this also covers
    /// any stray dust sent directly.
    receive() external payable {}

    function setSwapThreshold(address token, uint256 newThreshold) external onlyOwner {
        swapThreshold[token] = newThreshold;
        emit SwapThresholdUpdated(token, newThreshold);
    }

    /// @notice See maxSwapAmount's own comment above. 0 means uncapped.
    function setMaxSwapAmount(address token, uint256 newMax) external onlyOwner {
        maxSwapAmount[token] = newMax;
        emit MaxSwapAmountUpdated(token, newMax);
    }

    /// @notice Adjusts the protective slippage floor applied to every
    /// triggerCreatorSwap trade — see swapSlippageBps above and Finding CR-2.
    /// Bounded to the same 5.00%-8.00% band used everywhere else in this
    /// codebase for the identical purpose.
    function setSwapSlippageBps(uint256 newBps) external onlyOwner {
        require(newBps >= MIN_SWAP_SLIPPAGE_BPS, "CreatorRewardsDistributor: slippage below 5% floor");
        require(newBps <= MAX_SWAP_SLIPPAGE_BPS, "CreatorRewardsDistributor: slippage above 8% ceiling");
        swapSlippageBps = newBps;
        emit SwapSlippageBpsUpdated(newBps);
    }

    /// @dev Standard Uniswap V2 constant-product quote (0.30% swap fee baked
    /// into the 997/1000 constants) — used only to derive a protective
    /// slippage floor below, never to execute anything. Same helper as
    /// TokenFactory/CustomToken/CustomTokenFactory's identical utility.
    function _getAmountOut(uint256 amountIn, uint256 reserveIn, uint256 reserveOut) private pure returns (uint256) {
        uint256 amountInWithFee = amountIn * 997;
        uint256 numerator = amountInWithFee * reserveOut;
        uint256 denominator = reserveIn * 1000 + amountInWithFee;
        return numerator / denominator;
    }

    /// @dev Quotes amountIn's expected ETH output off the token/WETH pool's
    /// own live reserves and applies swapSlippageBps — see Finding CR-2.
    /// Returns 0 if no pool is found or either reserve is empty, which
    /// triggerCreatorSwap treats as "can't compute a protocol floor this
    /// time," falling back to the caller's own minEthOut rather than
    /// blocking the swap outright — consistent with how every other
    /// quote-derived floor in this codebase degrades on a missing pool.
    function _protectiveMinOut(address token, uint256 amountIn) private view returns (uint256) {
        address weth = router.WETH();
        address pairAddr = IUniswapV2FactoryMinimal(router.factory()).getPair(token, weth);
        if (pairAddr == address(0)) return 0;

        (uint112 reserve0, uint112 reserve1, ) = IUniswapV2PairMinimal(pairAddr).getReserves();
        address token0 = IUniswapV2PairMinimal(pairAddr).token0();
        uint256 reserveIn = token0 == token ? uint256(reserve0) : uint256(reserve1);
        uint256 reserveOut = token0 == token ? uint256(reserve1) : uint256(reserve0);
        if (reserveIn == 0 || reserveOut == 0) return 0;

        uint256 quoted = _getAmountOut(amountIn, reserveIn, reserveOut);
        return quoted - (quoted * swapSlippageBps) / 10_000;
    }

    /// @notice Swaps up to maxSwapAmount[token] of this contract's balance
    /// of `token` for ETH (the entire balance, if no cap is set — see
    /// maxSwapAmount above), routed straight through WETH
    /// (path = [token, router.WETH()]), and credits the proceeds to that
    /// token's own creator via claimableEth[token]. Permissionless, like
    /// every trigger in PlatformRewardsDistributor — the destination (this
    /// exact token's own creator) never depends on who calls it. Reads
    /// creator() off the token itself at call time (ICreatorAware — both
    /// LaunchedToken and CustomToken expose it as a plain public getter),
    /// so a creator transfer on CustomToken (transferCreator/acceptCreator)
    /// is always reflected in whatever swap happens after it goes through,
    /// never a stale snapshot taken here.
    /// @dev Stack-pressure fix only (no behavior change): groups the loose
    /// uint256 locals this function used to carry (amountIn, protectiveFloor,
    /// effectiveMinOut, before) into a single memory struct. A struct local
    /// is one memory-pointer stack slot regardless of how many fields it
    /// carries, whereas N loose uint256 locals are N separate stack slots —
    /// this function never had a helper split at all, so unlike the other
    /// distributor contracts it was tripping HH600 ("stack too deep") purely
    /// from its own flat local count, not from any later re-inlining.
    struct SwapPlan {
        uint256 amountIn;
        uint256 protectiveFloor;
        uint256 effectiveMinOut;
        uint256 before;
    }

    function triggerCreatorSwap(address token, uint256 minEthOut) external nonReentrant returns (uint256 ethOut) {
        require(token != address(0), "CreatorRewardsDistributor: invalid token");
        uint256 balance = IERC20(token).balanceOf(address(this));
        require(balance > 0 && balance >= swapThreshold[token], "CreatorRewardsDistributor: below threshold");
        uint256 cap = maxSwapAmount[token];

        SwapPlan memory plan;
        plan.amountIn = (cap > 0 && balance > cap) ? cap : balance;

        address creator = ICreatorAware(token).creator();
        require(creator != address(0), "CreatorRewardsDistributor: token has no creator");

        address[] memory path = new address[](2);
        path[0] = token;
        path[1] = router.WETH();

        // Finding CR-2: minEthOut alone was a purely caller-supplied value
        // with no protocol-side floor — since this function is deliberately
        // permissionless, that let anyone call it with minEthOut == 0 and
        // sandwich their own call for MEV profit at the creator's expense.
        // effectiveMinOut is whichever is stricter of the caller's own
        // minEthOut and a floor computed from the pool's own live reserves,
        // same "whichever is stricter" combination CustomTokenFactory uses
        // for its own creator buy-in.
        plan.protectiveFloor = _protectiveMinOut(token, plan.amountIn);
        plan.effectiveMinOut = minEthOut > plan.protectiveFloor ? minEthOut : plan.protectiveFloor;

        plan.before = address(this).balance;
        IERC20(token).approve(address(router), plan.amountIn);
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            plan.amountIn,
            plan.effectiveMinOut,
            path,
            address(this),
            block.timestamp + 15 minutes
        );
        ethOut = address(this).balance - plan.before;

        claimableEth[token] += ethOut;
        emit CreatorSwapTriggered(token, creator, plan.amountIn, ethOut);
    }

    /// @notice Pays out claimableEth[token] to that token's own creator().
    /// Callable by anyone — same permissionless-but-fixed-destination
    /// pattern as triggerCreatorSwap above — so a creator's own claim
    /// button, an off-chain keeper, or a direct block-explorer call all pay
    /// the exact same recipient. Checks-effects-interactions (balance
    /// zeroed before the external call) plus nonReentrant besides.
    function claimCreatorRewards(address token) external nonReentrant returns (uint256 amount) {
        address creator = ICreatorAware(token).creator();
        require(creator != address(0), "CreatorRewardsDistributor: token has no creator");
        amount = claimableEth[token];
        require(amount > 0, "CreatorRewardsDistributor: nothing to claim");
        claimableEth[token] = 0;
        (bool sent, ) = payable(creator).call{value: amount}("");
        require(sent, "CreatorRewardsDistributor: ETH transfer failed");
        emit CreatorRewardsClaimed(token, creator, msg.sender, amount);
    }

    /// @notice Escape hatch for Finding CR-1: once a token's creator has
    /// permanently renounced (LaunchedToken.renounceCreator() /
    /// CustomToken.renounceCreator() — a normal, explicitly supported action
    /// elsewhere in this platform), creator() returns address(0) forever,
    /// which means claimCreatorRewards(token) can never succeed again for
    /// that token. Without this function, any ETH already sitting in
    /// claimableEth[token] at that point — and, before the CR-1 fix,
    /// anything triggerCreatorSwap would have credited afterward — would be
    /// stuck in this contract permanently, with no recovery path anywhere.
    ///
    /// Deliberately narrow, mirroring the rest of this codebase's escape
    /// hatches (e.g. LaunchedToken/CustomToken.updatePriceFeed, which only
    /// works once the current feed has gone stale): only callable once the
    /// token's OWN creator() call reports address(0). The owner can never
    /// redirect a live creator's still-claimable balance this way — doing so
    /// would require the creator to have already, irreversibly, given up the
    /// role that balance was owed to.
    function rescueOrphanedEth(address token, address to) external onlyOwner nonReentrant returns (uint256 amount) {
        require(to != address(0), "CreatorRewardsDistributor: invalid recipient");
        require(ICreatorAware(token).creator() == address(0), "CreatorRewardsDistributor: creator has not renounced");
        amount = claimableEth[token];
        require(amount > 0, "CreatorRewardsDistributor: nothing to rescue");
        claimableEth[token] = 0;
        (bool sent, ) = payable(to).call{value: amount}("");
        require(sent, "CreatorRewardsDistributor: ETH transfer failed");
        emit OrphanedEthRescued(token, to, amount);
    }

    /// @notice Companion to rescueOrphanedEth above, for the in-kind token
    /// side of the same problem: once a token's creator has renounced,
    /// triggerCreatorSwap(token) can never run again either (it requires the
    /// same nonzero creator()), so whatever `token` balance this contract is
    /// still holding — including anything the token's own tax keeps sending
    /// here on every subsequent trade, since LaunchedToken/CustomToken's own
    /// creatorRewardBps carve-out never checks the token's creator status —
    /// would otherwise sit here forever, permanently unswappable and
    /// unclaimable. Same narrow, renounced-only gate as rescueOrphanedEth;
    /// moves the raw token balance rather than swapping it here, so the
    /// owner decides what happens to it next (e.g. route it to the fee
    /// treasury, or to a replacement distributor) rather than this function
    /// making that call unilaterally.
    function rescueOrphanedTokens(address token, address to) external onlyOwner returns (uint256 amount) {
        require(to != address(0), "CreatorRewardsDistributor: invalid recipient");
        require(ICreatorAware(token).creator() == address(0), "CreatorRewardsDistributor: creator has not renounced");
        amount = IERC20(token).balanceOf(address(this));
        require(amount > 0, "CreatorRewardsDistributor: nothing to rescue");
        bool sent = IERC20(token).transfer(to, amount);
        require(sent, "CreatorRewardsDistributor: token transfer failed");
        emit OrphanedTokensRescued(token, to, amount);
    }
}

contracts/CustomBondingCurveFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/proxy/Clones.sol";
import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

import "./CustomToken.sol";
import "./LiquidityLocker.sol";
import "./interfaces/IUniswapV2Router02.sol";

/// @title CustomBondingCurveFactory
/// @notice The "advanced" sibling of BondingCurveFactory: identical bonding-
/// curve mechanics (no upfront ETH, constant-product pricing with virtual
/// reserves, auto-graduation into a real pool once real ETH raised crosses
/// poolSeedTargetWei), but clones CustomToken instead of LaunchedToken, so a
/// creator can configure the same reflections/marketing/auto-liquidity/burn
/// tax CustomTokenFactory already offers -- 0% is simply the all-zero case of
/// the same contract, exactly as it is over there.
///
/// This is deliberately a separate contract from BondingCurveFactory, for
/// exactly the same reason CustomTokenFactory is separate from TokenFactory
/// (see that contract's own header comment): CustomToken is a meaningfully
/// larger, more complex contract than LaunchedToken (reflections,
/// auto-liquidity, auto-burn, its own swap-and-process pipeline), and keeping
/// it fully separate means none of this touches the already-audited-by-tests
/// BondingCurveFactory/LaunchedToken path at all. Every curve-phase mechanic
/// below -- the constant-product math, the fee-then-price / price-then-fee
/// ordering, checks-effects-interactions, the buy-only pause circuit breaker,
/// the balanceOf() invariant checks, per-curve snapshotting of every economic
/// parameter -- is copied byte-for-byte from BondingCurveFactory (see that
/// contract's own header for the full reasoning behind each one); only the
/// token being cloned, and how the curve wires it into a pool at graduation,
/// differ.
///
/// Reuses CustomToken.sol, LiquidityLocker.sol, and the router interfaces --
/// CustomToken.initialize() already accepts an arbitrary mintTo_/factory_
/// pair (see CustomTokenFactory's own two initialize() call sites for
/// precedent: deploy-only mints to the creator with factory_ == the
/// factory; "deploy and add liquidity" mints to the factory itself with
/// factory_ == the factory too). A curve-phase token here always uses the
/// second shape -- mintTo_ == factory_ == address(this) -- for the entire
/// curve phase, which correctly makes CustomToken's `from == factory` guard
/// in _update() skip independent-pool-detection on every curve-phase
/// transfer this factory itself originates (buys paying out from the
/// factory, and the liquidity-seeding transfer inside _doGraduate's
/// addLiquidityETH call).
///
/// FIX (this review, Finding CT-2): that guard alone is NOT sufficient,
/// and CustomToken.sol was not "completely unmodified" as this comment
/// used to claim. `from == factory` only covers transfers the factory
/// itself originates -- it does nothing for an ordinary curve sell()
/// (transferFrom(seller, factory, amount): from == the seller, a trader,
/// not this factory) or a plain wallet-to-wallet transfer of curve tokens,
/// both of which are routine during the genuinely long pre-graduation
/// phase every curve token sits in. Since creating an empty Uniswap-V2-
/// style pair for any token is permissionless and needs no liquidity, an
/// attacker could pre-create a rogue pair for a not-yet-graduated curve
/// token and let the next ordinary sell/transfer permanently lock `pair`
/// to it via CustomToken._activatePoolIfFound() -- causing this factory's
/// own _doGraduate() -> setPair() call below to revert forever on
/// PairAlreadySet(), permanently blocking that token from ever graduating
/// to a real, LP-locked pool. CustomToken.sol now carries a `curveManaged`
/// flag (see its own doc comment) set to `true` by both of this factory's
/// initialize() call sites below, which additionally gates _update()'s
/// auto-activation guard AND activateIndependentPair()'s manual path -- so
/// a curve-managed token never attempts pool auto-detection at all,
/// regardless of what transfer would otherwise trigger it or what rogue
/// pair a third party pre-created. Only this factory's own explicit
/// setPair() call inside _doGraduate() below -- after real liquidity has
/// genuinely been seeded -- can ever set `pair` for these tokens now.
///
/// This factory uses its OWN, freshly-deployed LiquidityLocker instance --
/// never BondingCurveFactory's or CustomTokenFactory's -- because a
/// LiquidityLocker permanently binds itself to exactly one factory address
/// the first time setFactory() is called (see LiquidityLocker.setFactory).
/// Deploy order is therefore: (1) deploy a new LiquidityLocker, (2) deploy
/// this factory passing that locker's address, (3) call
/// locker.setFactory(address(this)) once. Steps (1)-(3) mirror exactly how
/// CustomTokenFactory's own deploy script wires its separate locker instance.
///
/// Post-graduation tax wiring differs from BondingCurveFactory in exactly the
/// way CustomTokenFactory's differs from TokenFactory's: LaunchedToken wires
/// its pair and its platform tax in ONE call (configureTax), while CustomToken
/// splits this into TWO calls -- setPair(pair) followed by
/// configurePlatformTax(...) -- because CustomToken already has its own
/// creator-configured buyFees/sellFees sitting alongside the platform's tax,
/// and configurePlatformTax() needs `pair` to already be set so it can check
/// its own PairNotSet()/PairAlreadySet() invariants (see CustomToken.sol).
/// _doGraduate below makes both calls, in that order, exactly as
/// CustomTokenFactory._seedLiquidityAndBuyIn already does for its own atomic
/// launch path.
///
/// Unlike BondingCurveFactory (which requires platformFeeWallet and priceFeed
/// to already be configured before a curve can even be created -- mirroring
/// TokenFactory's own mandatory launch-time check), createCurveToken here
/// does NOT require either to be set. This mirrors CustomTokenFactory exactly
/// (see that contract's own createCustomToken doc comment): leaving
/// platformFeeWallet/priceFeed unset simply leaves the eventual
/// configurePlatformTax() call recording a permanently-inactive platform tax
/// (feeBps_ == 0 or feeWallet_ == address(0) -- see
/// CustomToken.configurePlatformTax) rather than blocking every curve launch
/// the way BondingCurveFactory's mandatory checks do. The creator's own
/// buyFees_/sellFees_ tax is entirely independent of this and is never
/// affected by it either way.
///
/// Gasless relayed launches, mirroring BondingCurveFactory's own fast-follow
/// (see that contract's own note): a CustomCurveLaunchVoucher extends the
/// plain CurveLaunchVoucher shape with the same buyFees/sellFees FeeSet +
/// reflectionAsset/marketingWallet fields CustomTokenFactory's own
/// CustomLaunchVoucher adds over TokenFactory's plain LaunchVoucher. buy()/
/// sell() remain direct-wallet-only -- only launching a curve is gasless.
contract CustomBondingCurveFactory is Ownable2Step, ReentrancyGuard, Pausable {
    address public immutable tokenImplementation;
    IUniswapV2Router02 public immutable router;
    LiquidityLocker public immutable locker;

    /// @notice See TokenFactory.MAX_FEE_BPS -- identical hard ceiling, same
    /// reasoning, applied here to curveFeeBps and the post-graduation feeBps.
    /// Entirely separate from, and never checked against, CustomToken's own
    /// MAX_TOTAL_BPS (5.00% per side) on the creator's buyFees_/sellFees_ --
    /// that cap is enforced by CustomToken.initialize() itself, not here.
    uint256 public constant MAX_FEE_BPS = 2_000; // 20.00%

    // ---- curve-phase parameters, snapshotted into each curve at creation
    // time (see createCurveToken) -- an owner change here only ever affects
    // curves created after the change, never one already live. Identical
    // defaults and identical reasoning to BondingCurveFactory's own copies. ----

    uint256 public curveLaunchFee; // flat fee to create a curve token -- no pool exists yet
    uint256 public curveFeeBps = 100; // 1.00%, skimmed from the ETH leg of every buy and sell during the curve phase
    uint256 public curveSupplyBps = 8_000; // 80.00% of totalSupply_ tradable on the curve
    uint256 public virtualEthReserveDefault = 3 ether;
    uint256 public virtualTokenReserveBps = 8_000; // 80.00% of totalSupply_
    /// @notice Real ETH (net of curveFeeBps) a curve must accumulate before it
    /// can graduate -- see BondingCurveFactory.poolSeedTargetWei's own doc
    /// comment for the full reasoning; identical default (1.5 ETH) per the
    /// user's requirement that both variants share the same bonding
    /// threshold.
    uint256 public poolSeedTargetWei = 1.5 ether;

    /// @notice See TokenFactory.maxCreatorBuyBps -- identical anti-rug
    /// safeguard, applied to the optional same-transaction creator buy-in at
    /// curve creation, checked against the actual net tokens received.
    uint256 public maxCreatorBuyBps = 500; // 5.00% of totalSupply_ by default

    address public feeTreasury;
    uint256 public lpLockDuration;

    // ---- post-graduation CustomToken platform-tax defaults, PLUS the two
    // reward-diversion addresses/bps below -- identical fields, identical
    // meaning, identical setTaxDefaults() bounds to
    // BondingCurveFactory/CustomTokenFactory's own copies. Entirely separate
    // from, and layered on top of, whatever buyFees_/sellFees_ the creator
    // configured on their own CustomToken at creation -- see
    // CustomToken.configurePlatformTax's own contract-level note on why the
    // two never overlap. Snapshotted into the Curve struct at
    // createCurveToken() time (see the Curve.tax* fields), applied verbatim
    // whenever that curve eventually graduates.
    //
    // --- Post-audit hardening (see AUDIT-CustomBondingCurveFactory.md
    // Finding 1) ---
    // These ten fields used to be individual `public` state variables. That
    // was a genuine vulnerability: their auto-generated getters happened to
    // match ITokenFactoryTaxDefaults's exact eleven-function shape (see
    // ITokenFactoryTaxDefaults.sol), the interface CustomToken._update's own
    // independent-pool auto-detection (`_activatePoolIfFound`,
    // `activateIndependentPair`) calls into via `ITokenFactoryTaxDefaults(
    // factory)` -- and `factory` on every token this contract clones really
    // is this contract's own address. That meant anyone could permanently
    // hijack a curve-phase token's `pair` -- and thus permanently brick its
    // graduation, with no recovery path -- just by getting a real Uniswap
    // pair to exist for (token, WETH) before this factory's own explicit
    // setPair() call runs (as cheap and permissionless as calling the DEX
    // factory's own createPair(), even before the curve is created, since
    // predictTokenAddress() is public). CustomToken's auto-detection is safe
    // against a genuine deploy-only CustomToken (CustomTokenFactory's own
    // use case, where `factory` really is the right source of tax
    // defaults) -- it was never safe against a curve-phase token whose
    // `factory` field happens to satisfy the same interface for an
    // unrelated reason.
    //
    // Making these ten fields private (no individual getters at all) closes
    // this: ITokenFactoryTaxDefaults(factory).feeBps() now hits no matching
    // function on this contract and reverts immediately -- the very first
    // call _activatePoolIfFound() makes after tentatively writing
    // `pair = detectedPair`, so that write rolls back in the same revert.
    // Every value is still fully readable off-chain, just through the one
    // combined taxDefaults() view below instead of ten separate getters --
    // the same shape curveTaxConfig() already uses for the per-curve
    // snapshot. This has zero effect on legitimate post-graduation
    // behavior: once this factory's own setPair() call succeeds, `pair` is
    // permanently non-zero, which already permanently disables
    // _activatePoolIfFound from running again on that token regardless.
    address private platformFeeWallet;
    uint256 private feeBps = 100; // 1.00%
    address private priceFeed;
    uint256 private graduationTargetUsd = 50_000; // whole dollars
    uint256 private maxOracleStaleness = 1 hours;

    /// @notice PlatformRewardsDistributor's address -- see
    /// BondingCurveFactory.rewardsDistributor for the identical dual role
    /// (curve-phase fee revenue split, and the post-graduation tax carve-out
    /// below). address(0) disables both. Private for the same Finding 1
    /// reason as the tax-default fields above -- see taxDefaults() below.
    address private rewardsDistributor;
    // Defaults to 0 by design -- PlatformRewardsDistributor (rewardsDistributor
    // above) is meant to be funded ONLY by the one-time 50% curve-phase fee
    // share it already receives directly, never by the ongoing POST-graduation
    // per-trade tax. See BondingCurveFactory.rewardBps for the full reasoning;
    // behaves identically here. With this at 0, the ongoing slice flows
    // entirely to feeWalletDistributor/feeWallet instead, via the same
    // `fee - rewardCut - creatorCut` remainder computation CustomToken._update
    // already does -- no other code change needed. POST-graduation tax
    // carve-out only -- snapshotted into Curve.taxRewardBps at creation.
    uint256 private rewardBps = 0;

    /// @notice CreatorRewardsDistributor's address -- POST-graduation tax
    /// carve-out only, identical to BondingCurveFactory's own copy.
    address private creatorRewardsDistributor;
    uint256 private creatorRewardBps = 10; // 0.10% -- snapshotted into Curve.taxCreatorRewardBps at creation

    /// @notice FeeWalletDistributor's address -- POST-graduation tax
    /// remainder only, identical to BondingCurveFactory's own copy.
    address private feeWalletDistributor;

    /// @notice The combined replacement for what used to be ten separate
    /// public getters (see the Finding 1 hardening note above) -- the
    /// CURRENT live defaults applied to curves created from this point
    /// forward. For any already-created curve's own locked-in terms, use
    /// curveTaxConfig(token) instead, which is unaffected by this change.
    function taxDefaults()
        external
        view
        returns (
            address platformFeeWallet_,
            uint256 feeBps_,
            address priceFeed_,
            uint256 graduationTargetUsd_,
            uint256 maxOracleStaleness_,
            address rewardsDistributor_,
            uint256 rewardBps_,
            address creatorRewardsDistributor_,
            uint256 creatorRewardBps_,
            address feeWalletDistributor_
        )
    {
        return (
            platformFeeWallet, feeBps, priceFeed, graduationTargetUsd, maxOracleStaleness,
            rewardsDistributor, rewardBps, creatorRewardsDistributor, creatorRewardBps, feeWalletDistributor
        );
    }

    /// @notice Cheap monitoring helper for the exact failure mode Finding 1
    /// describes: true iff this token's own `pair` has been set (by
    /// CustomToken's independent-pool auto-detection, triggered by anyone
    /// once a real Uniswap pair exists for it) while this factory's own
    /// curve still thinks it hasn't graduated. If this is ever true, that
    /// curve's graduate()/buy()-triggered-graduation calls will keep
    /// failing -- surfaced here explicitly rather than left to be
    /// discovered only when graduate() reverts with a generic reason. The
    /// restructuring above prevents this from ever becoming true again for
    /// curves created from this point forward, but this stays in place as a
    /// permanent, cheap tripwire rather than being removed once the root
    /// cause is fixed.
    function isGraduationBlocked(address token) external view returns (bool) {
        Curve storage curve = curves[token];
        if (curve.totalSupply == 0 || curve.graduated) return false;
        return CustomToken(payable(token)).pair() != address(0);
    }

    /// @notice See TokenFactory.liquiditySlippageBps -- identical protection,
    /// applied to _doGraduate's own addLiquidityETH call.
    uint256 public liquiditySlippageBps = 600; // 6.00% default
    uint256 public constant MIN_LIQUIDITY_SLIPPAGE_BPS = 500; // 5.00%
    uint256 public constant MAX_LIQUIDITY_SLIPPAGE_BPS = 800; // 8.00%

    function _minWithSlippage(uint256 amount) private view returns (uint256) {
        return amount - (amount * liquiditySlippageBps) / 10_000;
    }

    struct Curve {
        address creator;
        uint256 totalSupply; // the token's full totalSupply_, snapshotted at creation
        uint256 curveSupply; // portion of totalSupply allocated to the curve at creation
        uint256 tokensRemaining; // curve-held tokens still available to sell
        uint256 virtualEthReserve;
        uint256 virtualTokenReserve;
        uint256 realEthReserve; // real ETH accumulated net of curveFeeBps -- zeroed in _doGraduate once moved to the pool
        uint256 poolSeedTargetWei; // snapshotted at creation
        uint256 curveFeeBps; // snapshotted at creation -- fixed for this curve's lifetime
        bool graduated;
        uint256 createdAt;
        // ---- post-graduation platform-tax terms, snapshotted at creation ----
        address taxPlatformFeeWallet;
        uint256 taxFeeBps;
        address taxPriceFeed;
        uint256 taxGraduationTargetUsd;
        uint256 taxMaxOracleStaleness;
        uint256 taxRewardBps;
        uint256 taxCreatorRewardBps;
    }

    mapping(address => Curve) private curves;
    mapping(address => address) public creatorOf;
    mapping(address => address) public pairOf; // token => its DEX pair once graduated, address(0) before then
    address[] private _tokenList;
    mapping(address => address[]) private _tokensByCreator;

    /// @notice ETH that _distributeEthFee tried to forward to feeTreasury or
    /// rewardsDistributor but couldn't, because the recipient's receive/
    /// fallback reverted. Stays on this contract's own balance, tracked here
    /// rather than lost, until an owner sweeps it via rescueStrandedFees().
    /// Same design as BondingCurveFactory's own post-audit fix (see
    /// AUDIT-BondingCurveFactory.md Finding 1) -- built in from the start
    /// here rather than retrofitted.
    uint256 public strandedFees;

    /// @notice Finding CBCF-2 fix: running total of realEthReserve across
    /// every curve this factory has ever created -- identical convention to
    /// BondingCurveFactory's own totalCurveReserveEth (see that contract's
    /// doc comment for the full reasoning), kept in lockstep with every
    /// place curve.realEthReserve itself changes (_executeBuy, sell(),
    /// _doGraduate). Exists so rescueStrayEth (see below) can identify a
    /// genuine stray ETH transfer in O(1), with no loop over every curve
    /// this factory has ever created.
    uint256 public totalCurveReserveEth;

    event CurveTokenCreated(
        address indexed token,
        address indexed creator,
        string name,
        string symbol,
        uint256 totalSupply,
        uint256 curveSupply,
        uint256 virtualEthReserve,
        uint256 virtualTokenReserve,
        uint256 poolSeedTargetWei,
        address reflectionAsset,
        address marketingWallet
    );
    event CreatorBought(address indexed token, address indexed creator, uint256 ethIn, uint256 tokensOut);
    event CurveBought(address indexed token, address indexed buyer, uint256 ethIn, uint256 feeAmount, uint256 tokensOut, uint256 realEthReserveAfter);
    event CurveSold(address indexed token, address indexed seller, uint256 tokensIn, uint256 feeAmount, uint256 ethOut, uint256 realEthReserveAfter);
    event CurveGraduated(
        address indexed token,
        address indexed pair,
        uint256 ethAdded,
        uint256 tokensAdded,
        uint256 lpAmount,
        uint256 unlockTime,
        uint256 indexed lockId
    );

    event FeeTransferFailed(address indexed recipient, uint256 amount);
    event StrandedFeesRescued(address indexed to, uint256 amount);
    event TokenRescued(address indexed token, address indexed to, uint256 amount);
    /// @notice Finding CBCF-2 fix -- see rescueStrayEth below.
    event StrayEthRescued(address indexed to, uint256 amount);

    event CurveFeeBpsUpdated(uint256 newBps);
    event CurveSupplyBpsUpdated(uint256 newBps);
    event VirtualEthReserveDefaultUpdated(uint256 newDefault);
    event VirtualTokenReserveBpsUpdated(uint256 newBps);
    event PoolSeedTargetUpdated(uint256 newTarget);
    event CurveLaunchFeeUpdated(uint256 newFee);
    event LpLockDurationUpdated(uint256 newDuration);
    event MaxCreatorBuyBpsUpdated(uint256 newBps);
    event LiquiditySlippageBpsUpdated(uint256 newBps);
    event FeeTreasuryUpdated(address newTreasury);
    event TaxDefaultsUpdated();
    event RewardsDistributorUpdated(address newDistributor);
    event CreatorRewardsDistributorUpdated(address newDistributor);
    event FeeWalletDistributorUpdated(address newDistributor);
    event TokenPriceFeedUpdated(address indexed token, address newPriceFeed, uint256 newMaxOracleStaleness);

    // ---- gasless relayed launches -- see BondingCurveFactory's identical
    // section for the full explanation of the deposit/relay/settle flow.
    // Duplicated here rather than shared via a base contract, same
    // reasoning as the rest of this file's deliberate separation from
    // BondingCurveFactory. CustomCurveLaunchVoucher extends the plain
    // CurveLaunchVoucher shape with the same buyFees/sellFees FeeSet +
    // reflectionAsset/marketingWallet fields CustomTokenFactory's own
    // CustomLaunchVoucher adds over TokenFactory's plain LaunchVoucher. ----

    address public relayer;
    uint256 public maxRelayerGasReimbursementWei;
    uint256 public constant RELAY_GAS_OVERHEAD = 60_000;

    struct Deposit {
        uint256 amount;
        uint256 deadline;
        bool settled;
        bool reclaimed;
    }
    mapping(address => mapping(bytes32 => Deposit)) public deposits;

    struct CustomCurveLaunchVoucher {
        address creator;
        string name;
        string symbol;
        uint256 totalSupply;
        CustomToken.FeeSet buyFees;
        CustomToken.FeeSet sellFees;
        address reflectionAsset;
        address marketingWallet;
        uint256 creatorBuyEthAmount;
        uint256 minCreatorTokensOut;
        uint256 fee; // curveLaunchFee the creator locked in and escrowed at deposit time
        // Doubles as the CREATE2 salt relayedCreateCurveToken deploys the
        // clone with -- see TokenFactory.LaunchVoucher.salt for the full
        // explanation, applies identically here.
        uint256 salt;
        uint256 deadline;
    }

    bytes32 private constant FEE_SET_TYPEHASH =
        keccak256("FeeSet(uint16 reflectionBps,uint16 marketingBps,uint16 liquidityBps,uint16 burnBps)");

    bytes32 private constant CUSTOM_CURVE_LAUNCH_VOUCHER_TYPEHASH = keccak256(
        "CustomCurveLaunchVoucher(address creator,string name,string symbol,uint256 totalSupply,FeeSet buyFees,FeeSet sellFees,address reflectionAsset,address marketingWallet,uint256 creatorBuyEthAmount,uint256 minCreatorTokensOut,uint256 fee,uint256 salt,uint256 deadline)FeeSet(uint16 reflectionBps,uint16 marketingBps,uint16 liquidityBps,uint16 burnBps)"
    );

    // Hand-rolled EIP-712 domain separator -- see TokenFactory for why this
    // avoids OpenZeppelin's EIP712 base (mcopy/Cancun dependency).
    bytes32 private constant EIP712_DOMAIN_TYPEHASH = keccak256(
        "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
    );
    bytes32 private immutable _domainSeparator;

    event RelayerUpdated(address newRelayer);
    event MaxRelayerGasReimbursementUpdated(uint256 newCapWei);
    event LaunchDeposited(bytes32 indexed voucherHash, address indexed creator, uint256 amount, uint256 deadline);
    event DepositReclaimed(bytes32 indexed voucherHash, address indexed creator, uint256 amount);
    event RelayedFeeSettled(
        bytes32 indexed voucherHash,
        address indexed token,
        uint256 feeCollected,
        uint256 gasReimbursed,
        uint256 toTreasury,
        uint256 toRewards
    );

    modifier onlyRelayer() {
        require(msg.sender == relayer, "CustomBondingCurveFactory: caller is not the relayer");
        _;
    }

    constructor(
        address tokenImplementation_,
        address router_,
        address locker_,
        uint256 curveLaunchFee_,
        address feeTreasury_,
        uint256 lpLockDuration_,
        address platformFeeWallet_,
        address priceFeed_
    ) Ownable(msg.sender) {
        require(tokenImplementation_ != address(0), "CustomBondingCurveFactory: invalid token implementation");
        require(router_ != address(0), "CustomBondingCurveFactory: invalid router");
        require(locker_ != address(0), "CustomBondingCurveFactory: invalid locker");
        require(feeTreasury_ != address(0), "CustomBondingCurveFactory: invalid treasury");

        tokenImplementation = tokenImplementation_;
        router = IUniswapV2Router02(router_);
        locker = LiquidityLocker(locker_);
        curveLaunchFee = curveLaunchFee_;
        feeTreasury = feeTreasury_;
        lpLockDuration = lpLockDuration_;
        platformFeeWallet = platformFeeWallet_;
        priceFeed = priceFeed_;

        _domainSeparator = keccak256(
            abi.encode(
                EIP712_DOMAIN_TYPEHASH,
                keccak256(bytes("HoodLaunchCustomBondingCurveFactory")),
                keccak256(bytes("1")),
                block.chainid,
                address(this)
            )
        );
    }

    /// @notice Absorbs any ETH the router refunds mid-addLiquidityETH, and any
    /// stray direct transfer.
    ///
    /// FIX (this review, Finding CBCF-2): this comment used to claim a
    /// stray transfer was already recoverable "via rescueStrandedFees()/
    /// rescueToken()" -- identical mistake to BondingCurveFactory's own
    /// BCF-2. rescueStrandedFees() is scoped strictly to the strandedFees
    /// counter (only ever incremented by a failed fee-distribution
    /// transfer, never an ordinary direct send), and rescueToken() only
    /// ever moves ERC20 balances, never ETH. Use rescueStrayEth() instead,
    /// which computes the genuinely unaccounted-for ETH balance directly.
    receive() external payable {}

    /// @dev See TokenFactory._deriveTokenSalt -- binds the actual CREATE2
    /// salt to the creator so a mempool-visible salt can't be front-run.
    function _deriveTokenSalt(address creator_, uint256 salt) private pure returns (bytes32) {
        return keccak256(abi.encode(creator_, salt));
    }

    /// @dev Identical constant-product quote to BondingCurveFactory._quoteBuy
    /// -- fee-first: this curve's own snapshotted curveFeeBps is skimmed off
    /// the incoming ETH before it touches the constant-product formula.
    function _quoteBuy(Curve storage curve, uint256 ethIn) private view returns (uint256 tokensOut, uint256 feeAmount, uint256 netEthIn) {
        feeAmount = (ethIn * curve.curveFeeBps) / 10_000;
        netEthIn = ethIn - feeAmount;
        uint256 effEth = curve.virtualEthReserve + curve.realEthReserve;
        uint256 effToken = curve.virtualTokenReserve + curve.tokensRemaining;
        tokensOut = (netEthIn * effToken) / (effEth + netEthIn);
    }

    /// @dev Grouped return value for _quoteSell -- see the struct-based fix
    /// note on _settleSell below for why this exists: a struct collapses to
    /// one stack slot regardless of how many fields it carries, which is
    /// what actually closes off solc's viaIR/Yul "stack too deep" class of
    /// error for this whole sell path, rather than just moving it from one
    /// function to the next each time one gets split. Identical fix to
    /// BondingCurveFactory's own SellQuote struct.
    struct SellQuote {
        uint256 ethOutGross;
        uint256 feeAmount;
        uint256 netEthOut;
    }

    /// @dev Identical constant-product quote to BondingCurveFactory._quoteSell
    /// -- fee-last: the gross ETH the constant-product formula implies is
    /// computed first, then curveFeeBps is skimmed off that gross amount.
    function _quoteSell(Curve storage curve, uint256 tokenAmountIn) private view returns (SellQuote memory quote) {
        uint256 effEth = curve.virtualEthReserve + curve.realEthReserve;
        uint256 effToken = curve.virtualTokenReserve + curve.tokensRemaining;
        quote.ethOutGross = (tokenAmountIn * effEth) / (effToken + tokenAmountIn);
        quote.feeAmount = (quote.ethOutGross * curve.curveFeeBps) / 10_000;
        quote.netEthOut = quote.ethOutGross - quote.feeAmount;
    }

    /// @dev Identical 50/50 feeTreasury/rewardsDistributor split, and
    /// identical non-reverting-on-failure behavior, to
    /// BondingCurveFactory._distributeEthFee (see that function's own comment
    /// for the full "holders must always be able to exit" reasoning) --
    /// built in from the start here rather than retrofitted.
    function _distributeEthFee(uint256 amount) private {
        if (amount == 0) return;
        if (rewardsDistributor != address(0)) {
            uint256 toRewards = amount / 2;
            uint256 toTreasury = amount - toRewards;
            if (toRewards > 0) {
                (bool sentRewards, ) = rewardsDistributor.call{value: toRewards}("");
                if (!sentRewards) {
                    strandedFees += toRewards;
                    emit FeeTransferFailed(rewardsDistributor, toRewards);
                }
            }
            (bool sent, ) = feeTreasury.call{value: toTreasury}("");
            if (!sent) {
                strandedFees += toTreasury;
                emit FeeTransferFailed(feeTreasury, toTreasury);
            }
        } else {
            (bool sent, ) = feeTreasury.call{value: amount}("");
            if (!sent) {
                strandedFees += amount;
                emit FeeTransferFailed(feeTreasury, amount);
            }
        }
    }

    /// @dev Shared core of a buy -- identical checks-effects-interactions
    /// discipline and identical balanceOf() invariant check to
    /// BondingCurveFactory._executeBuy.
    function _executeBuy(
        address token,
        Curve storage curve,
        address recipient,
        uint256 ethIn,
        uint256 minTokensOut
    ) private returns (uint256 tokensOut, uint256 feeAmount) {
        uint256 netEthIn;
        (tokensOut, feeAmount, netEthIn) = _quoteBuy(curve, ethIn);
        require(tokensOut > 0, "CustomBondingCurveFactory: zero tokens out");
        require(tokensOut <= curve.tokensRemaining, "CustomBondingCurveFactory: exceeds curve supply");
        require(tokensOut >= minTokensOut, "CustomBondingCurveFactory: slippage");

        curve.realEthReserve += netEthIn;
        totalCurveReserveEth += netEthIn; // Finding CBCF-2 -- keep the running total in lockstep with curve.realEthReserve
        curve.tokensRemaining -= tokensOut;

        _distributeEthFee(feeAmount);

        bool sent = IERC20(token).transfer(recipient, tokensOut);
        require(sent, "CustomBondingCurveFactory: token transfer failed");

        require(
            IERC20(token).balanceOf(address(this)) >= curve.tokensRemaining + (curve.totalSupply - curve.curveSupply),
            "CustomBondingCurveFactory: token balance invariant violated"
        );
    }

    /// @notice Deploy a new curve token whose eventual pool will carry a
    /// creator-configured tax (reflections/marketing/auto-liquidity/burn),
    /// exactly like CustomTokenFactory's own CustomToken -- 0% is simply the
    /// all-zero case of buyFees_/sellFees_, same as over there. No ETH from
    /// the creator ever pairs into a pool here; msg.value must equal
    /// curveLaunchFee + creatorBuyEthAmount exactly.
    ///
    /// buyFees_/sellFees_ are each validated against CustomToken's own 5%-
    /// per-side MAX_TOTAL_BPS cap by CustomToken.initialize() itself (this
    /// factory does not duplicate that check, exactly like CustomTokenFactory
    /// doesn't) -- an invalid combination simply reverts the whole
    /// transaction, including the clone deployment. reflectionAsset_ ==
    /// address(0) means reflections pay out in native ETH; marketingWallet_
    /// is required only if either side's marketingBps is nonzero (same rules
    /// as CustomTokenFactory.createCustomToken).
    ///
    /// creatorBuyEthAmount is optional (0 skips it): an ordinary buy against
    /// the freshly-created curve, in this same transaction, capped at
    /// maxCreatorBuyBps of totalSupply_ checked against the actual net tokens
    /// received -- identical anti-rug convention to BondingCurveFactory's own
    /// creator buy-in.
    ///
    /// Snapshots curveFeeBps and the seven post-graduation platform-tax
    /// parameters into this curve at the moment it's created -- an owner
    /// changing any of those afterward only ever affects curves created from
    /// that point forward, never this one. Identical discipline to
    /// BondingCurveFactory.createCurveToken.
    /// @param salt Caller-chosen CREATE2 salt input -- see
    /// TokenFactory.createToken's matching parameter doc; applies identically
    /// here.
    function createCurveToken(
        string calldata name_,
        string calldata symbol_,
        uint256 totalSupply_,
        CustomToken.FeeSet calldata buyFees_,
        CustomToken.FeeSet calldata sellFees_,
        address reflectionAsset_,
        address marketingWallet_,
        uint256 creatorBuyEthAmount,
        uint256 minCreatorTokensOut,
        uint256 salt
    ) external payable nonReentrant returns (address token, uint256 creatorTokensBought) {
        require(bytes(name_).length > 0, "CustomBondingCurveFactory: name required");
        require(bytes(symbol_).length > 0, "CustomBondingCurveFactory: symbol required");
        require(totalSupply_ > 0, "CustomBondingCurveFactory: supply must be > 0");
        require(msg.value == curveLaunchFee + creatorBuyEthAmount, "CustomBondingCurveFactory: incorrect ETH sent");

        token = Clones.cloneDeterministic(tokenImplementation, _deriveTokenSalt(msg.sender, salt));
        // mintTo_ == factory_ == address(this) for the entire curve phase --
        // needed so CustomToken._update's `from == factory` check correctly
        // skips this factory's own internal transfers (curve buy()/sell()
        // pulls tokens through this contract, and graduation's own
        // liquidity-seeding transfer originates here too). This alone is
        // NOT what keeps independent-pool-detection from firing during the
        // curve phase, though -- see curveManaged_ below and CustomToken's
        // own curveManaged doc comment (Finding CT-2) for why.
        CustomToken(payable(token)).initialize(
            name_,
            symbol_,
            totalSupply_,
            msg.sender, // creator_
            address(this), // mintTo_
            address(this), // factory_
            address(router), // router_
            buyFees_,
            sellFees_,
            reflectionAsset_,
            marketingWallet_,
            true // curveManaged_ -- Finding CT-2 fix: this token is cloned by CustomBondingCurveFactory, so it must never auto-detect/auto-activate an independent pool -- only this factory's own setPair() call inside _doGraduate(), after real liquidity has genuinely been seeded, may ever set `pair`
        );

        uint256 curveSupply = (totalSupply_ * curveSupplyBps) / 10_000;
        require(curveSupply > 0, "CustomBondingCurveFactory: curve supply rounds to zero");

        Curve storage curve = curves[token];
        curve.creator = msg.sender;
        curve.totalSupply = totalSupply_;
        curve.curveSupply = curveSupply;
        curve.tokensRemaining = curveSupply;
        curve.virtualEthReserve = virtualEthReserveDefault;
        curve.virtualTokenReserve = (totalSupply_ * virtualTokenReserveBps) / 10_000;
        curve.poolSeedTargetWei = poolSeedTargetWei;
        curve.curveFeeBps = curveFeeBps;
        curve.createdAt = block.timestamp;
        curve.taxPlatformFeeWallet = platformFeeWallet;
        curve.taxFeeBps = feeBps;
        curve.taxPriceFeed = priceFeed;
        curve.taxGraduationTargetUsd = graduationTargetUsd;
        curve.taxMaxOracleStaleness = maxOracleStaleness;
        curve.taxRewardBps = rewardBps;
        curve.taxCreatorRewardBps = creatorRewardBps;

        creatorOf[token] = msg.sender;
        _tokensByCreator[msg.sender].push(token);
        _tokenList.push(token);

        emit CurveTokenCreated(
            token, msg.sender, name_, symbol_, totalSupply_, curveSupply,
            curve.virtualEthReserve, curve.virtualTokenReserve, curve.poolSeedTargetWei,
            reflectionAsset_, marketingWallet_
        );

        if (creatorBuyEthAmount > 0) {
            (uint256 tokensOut, ) = _executeBuy(token, curve, msg.sender, creatorBuyEthAmount, minCreatorTokensOut);
            require(
                tokensOut <= (totalSupply_ * maxCreatorBuyBps) / 10_000,
                "CustomBondingCurveFactory: creator buy-in exceeds max allowed share of supply"
            );
            creatorTokensBought = tokensOut;
            emit CreatorBought(token, msg.sender, creatorBuyEthAmount, tokensOut);

            // Same auto-graduation attempt as buy() -- a creator buy-in large
            // enough to cross poolSeedTargetWei on its own must not leave the
            // curve stuck "crossed but ungraduated".
            if (curve.realEthReserve >= curve.poolSeedTargetWei) {
                try this._attemptGraduate(token) returns (address, uint256, uint256) {} catch {}
            }
        }

        _distributeEthFee(curveLaunchFee);
    }

    function _hashFeeSet(CustomToken.FeeSet calldata f) private pure returns (bytes32) {
        return keccak256(abi.encode(FEE_SET_TYPEHASH, f.reflectionBps, f.marketingBps, f.liquidityBps, f.burnBps));
    }

    /// @notice Computes the exact EIP-712 digest a creator must sign to
    /// authorize a relayed curve launch. See TokenFactory.hashLaunchVoucher
    /// for the full explanation.
    function hashCustomCurveLaunchVoucher(CustomCurveLaunchVoucher calldata voucher) public view returns (bytes32) {
        bytes32 structHash = keccak256(
            abi.encode(
                CUSTOM_CURVE_LAUNCH_VOUCHER_TYPEHASH,
                voucher.creator,
                keccak256(bytes(voucher.name)),
                keccak256(bytes(voucher.symbol)),
                voucher.totalSupply,
                _hashFeeSet(voucher.buyFees),
                _hashFeeSet(voucher.sellFees),
                voucher.reflectionAsset,
                voucher.marketingWallet,
                voucher.creatorBuyEthAmount,
                voucher.minCreatorTokensOut,
                voucher.fee,
                voucher.salt,
                voucher.deadline
            )
        );
        return keccak256(abi.encodePacked("\x19\x01", _domainSeparator, structHash));
    }

    /// @notice Step 2 of a relayed launch -- see BondingCurveFactory.
    /// depositForRelayedLaunch / TokenFactory.depositForRelayedLaunch for
    /// the full explanation; behaves identically here.
    function depositForRelayedLaunch(bytes32 voucherHash, uint256 deadline) external payable nonReentrant {
        require(msg.value > 0, "CustomBondingCurveFactory: no ETH sent");
        require(deadline > block.timestamp, "CustomBondingCurveFactory: deadline already passed");
        Deposit storage d = deposits[msg.sender][voucherHash];
        require(d.amount == 0, "CustomBondingCurveFactory: voucher already funded");
        d.amount = msg.value;
        d.deadline = deadline;
        emit LaunchDeposited(voucherHash, msg.sender, msg.value, deadline);
    }

    /// @notice See TokenFactory.reclaimDeposit.
    function reclaimDeposit(bytes32 voucherHash) external nonReentrant {
        Deposit storage d = deposits[msg.sender][voucherHash];
        require(d.amount > 0, "CustomBondingCurveFactory: no such deposit");
        require(!d.settled, "CustomBondingCurveFactory: voucher already relayed");
        require(!d.reclaimed, "CustomBondingCurveFactory: already reclaimed");
        require(block.timestamp > d.deadline, "CustomBondingCurveFactory: deadline has not passed yet");
        d.reclaimed = true;
        uint256 amount = d.amount;
        (bool sent, ) = payable(msg.sender).call{value: amount}("");
        require(sent, "CustomBondingCurveFactory: refund transfer failed");
        emit DepositReclaimed(voucherHash, msg.sender, amount);
    }

    /// @notice Step 3 of a relayed curve launch, called only by the trusted
    /// relayer -- see BondingCurveFactory.relayedCreateCurveToken for the
    /// full explanation of the verification/deploy/settle steps. Mirrors
    /// createCurveToken() with voucher.creator standing in everywhere
    /// createCurveToken() used msg.sender.
    function relayedCreateCurveToken(
        CustomCurveLaunchVoucher calldata voucher,
        bytes calldata signature
    ) external onlyRelayer nonReentrant returns (address token, uint256 creatorTokensBought) {
        uint256 gasStart = gasleft();

        require(block.timestamp <= voucher.deadline, "CustomBondingCurveFactory: voucher expired");
        require(bytes(voucher.name).length > 0, "CustomBondingCurveFactory: name required");
        require(bytes(voucher.symbol).length > 0, "CustomBondingCurveFactory: symbol required");
        require(voucher.totalSupply > 0, "CustomBondingCurveFactory: supply must be > 0");

        bytes32 voucherHash = hashCustomCurveLaunchVoucher(voucher);
        address signer = ECDSA.recover(voucherHash, signature);
        require(signer == voucher.creator, "CustomBondingCurveFactory: signature does not match voucher creator");

        Deposit storage d = deposits[voucher.creator][voucherHash];
        require(d.amount > 0, "CustomBondingCurveFactory: no matching deposit");
        require(!d.settled, "CustomBondingCurveFactory: voucher already relayed");
        require(!d.reclaimed, "CustomBondingCurveFactory: deposit already reclaimed");
        require(block.timestamp <= d.deadline, "CustomBondingCurveFactory: deposit expired, creator must reclaim");

        uint256 expectedDeposit = voucher.fee + voucher.creatorBuyEthAmount;
        require(d.amount == expectedDeposit, "CustomBondingCurveFactory: deposit does not match voucher amount");

        d.settled = true; // effects before interactions, same discipline as createCurveToken/_executeBuy

        token = Clones.cloneDeterministic(tokenImplementation, _deriveTokenSalt(voucher.creator, voucher.salt));
        // mintTo_ == factory_ == address(this) for the entire curve phase --
        // see createCurveToken()'s own comment on why, and on curveManaged_
        // below (Finding CT-2).
        CustomToken(payable(token)).initialize(
            voucher.name,
            voucher.symbol,
            voucher.totalSupply,
            voucher.creator, // creator_
            address(this), // mintTo_
            address(this), // factory_
            address(router), // router_
            voucher.buyFees,
            voucher.sellFees,
            voucher.reflectionAsset,
            voucher.marketingWallet,
            true // curveManaged_ -- Finding CT-2 fix: see createCurveToken()'s own comment above
        );

        uint256 curveSupply = (voucher.totalSupply * curveSupplyBps) / 10_000;
        require(curveSupply > 0, "CustomBondingCurveFactory: curve supply rounds to zero");

        Curve storage curve = curves[token];
        curve.creator = voucher.creator;
        curve.totalSupply = voucher.totalSupply;
        curve.curveSupply = curveSupply;
        curve.tokensRemaining = curveSupply;
        curve.virtualEthReserve = virtualEthReserveDefault;
        curve.virtualTokenReserve = (voucher.totalSupply * virtualTokenReserveBps) / 10_000;
        curve.poolSeedTargetWei = poolSeedTargetWei;
        curve.curveFeeBps = curveFeeBps;
        curve.createdAt = block.timestamp;
        curve.taxPlatformFeeWallet = platformFeeWallet;
        curve.taxFeeBps = feeBps;
        curve.taxPriceFeed = priceFeed;
        curve.taxGraduationTargetUsd = graduationTargetUsd;
        curve.taxMaxOracleStaleness = maxOracleStaleness;
        curve.taxRewardBps = rewardBps;
        curve.taxCreatorRewardBps = creatorRewardBps;

        creatorOf[token] = voucher.creator;
        _tokensByCreator[voucher.creator].push(token);
        _tokenList.push(token);

        emit CurveTokenCreated(
            token, voucher.creator, voucher.name, voucher.symbol, voucher.totalSupply, curveSupply,
            curve.virtualEthReserve, curve.virtualTokenReserve, curve.poolSeedTargetWei,
            voucher.reflectionAsset, voucher.marketingWallet
        );

        if (voucher.creatorBuyEthAmount > 0) {
            (uint256 tokensOut, ) = _executeBuy(token, curve, voucher.creator, voucher.creatorBuyEthAmount, voucher.minCreatorTokensOut);
            require(
                tokensOut <= (voucher.totalSupply * maxCreatorBuyBps) / 10_000,
                "CustomBondingCurveFactory: creator buy-in exceeds max allowed share of supply"
            );
            creatorTokensBought = tokensOut;
            emit CreatorBought(token, voucher.creator, voucher.creatorBuyEthAmount, tokensOut);

            if (curve.realEthReserve >= curve.poolSeedTargetWei) {
                try this._attemptGraduate(token) returns (address, uint256, uint256) {} catch {}
            }
        }

        _settleRelayedFee(voucherHash, token, voucher.fee, gasStart);
    }

    /// @dev Gas-then-split settlement for a relayed launch -- see
    /// BondingCurveFactory._settleRelayedFee for the full explanation,
    /// including why the treasury/rewards leg is delegated to this
    /// contract's own _distributeEthFee rather than duplicated inline.
    function _settleRelayedFee(bytes32 voucherHash, address token, uint256 feeCollected, uint256 gasStart) private {
        if (feeCollected == 0) return;

        uint256 gasUsed = (gasStart - gasleft()) + RELAY_GAS_OVERHEAD;
        uint256 gasReimbursement = gasUsed * tx.gasprice;
        if (maxRelayerGasReimbursementWei > 0 && gasReimbursement > maxRelayerGasReimbursementWei) {
            gasReimbursement = maxRelayerGasReimbursementWei;
        }
        if (gasReimbursement > feeCollected) {
            gasReimbursement = feeCollected;
        }

        if (gasReimbursement > 0) {
            (bool sentGas, ) = payable(relayer).call{value: gasReimbursement}("");
            require(sentGas, "CustomBondingCurveFactory: relayer gas reimbursement failed");
        }

        uint256 netFee = feeCollected - gasReimbursement;
        uint256 toRewards = (netFee > 0 && rewardsDistributor != address(0)) ? netFee / 2 : 0;
        uint256 toTreasury = netFee - toRewards;
        _distributeEthFee(netFee);

        emit RelayedFeeSettled(voucherHash, token, feeCollected, gasReimbursement, toTreasury, toRewards);
    }

    /// @notice Buy curve tokens with ETH. Identical semantics to
    /// BondingCurveFactory.buy -- reverts if already graduated, auto-attempts
    /// graduation once poolSeedTargetWei is crossed, paused independently of
    /// sell().
    function buy(address token, uint256 minTokensOut) external payable nonReentrant whenNotPaused returns (uint256 tokensOut) {
        Curve storage curve = curves[token];
        require(curve.totalSupply > 0, "CustomBondingCurveFactory: unknown curve");
        require(!curve.graduated, "CustomBondingCurveFactory: already graduated");
        require(msg.value > 0, "CustomBondingCurveFactory: no ETH sent");

        uint256 feeAmount;
        (tokensOut, feeAmount) = _executeBuy(token, curve, msg.sender, msg.value, minTokensOut);

        emit CurveBought(token, msg.sender, msg.value, feeAmount, tokensOut, curve.realEthReserve);

        if (curve.realEthReserve >= curve.poolSeedTargetWei) {
            try this._attemptGraduate(token) returns (address, uint256, uint256) {} catch {}
        }
    }

    /// @notice Sell curve tokens back for ETH. Never pausable -- holders must
    /// always be able to exit a live curve. Identical checks-effects-
    /// interactions discipline to BondingCurveFactory.sell.
    function sell(address token, uint256 tokenAmountIn, uint256 minEthOut) external nonReentrant returns (uint256 ethOut) {
        Curve storage curve = curves[token];
        require(curve.totalSupply > 0, "CustomBondingCurveFactory: unknown curve");
        require(!curve.graduated, "CustomBondingCurveFactory: already graduated");
        require(tokenAmountIn > 0, "CustomBondingCurveFactory: zero amount");

        SellQuote memory quote = _quoteSell(curve, tokenAmountIn);
        require(quote.ethOutGross <= curve.realEthReserve, "CustomBondingCurveFactory: exceeds real ETH reserve");
        require(quote.netEthOut >= minEthOut, "CustomBondingCurveFactory: slippage");

        curve.tokensRemaining += tokenAmountIn;
        curve.realEthReserve -= quote.ethOutGross;
        totalCurveReserveEth -= quote.ethOutGross; // Finding CBCF-2 -- keep the running total in lockstep with curve.realEthReserve

        ethOut = _settleSell(token, curve, tokenAmountIn, quote);
    }

    /// @dev Split out of sell() purely to keep the number of locals live at
    /// once in any single function small enough for solc's viaIR/Yul stack
    /// allocator under real-world optimizer settings -- sell() had grown
    /// enough live variables (curve fields, the quote's three outputs, the
    /// pull/invariant-check/payout machinery) to sit right at that limit
    /// once totalCurveReserveEth bookkeeping was added. No behavior change:
    /// still the same checks-effects-interactions order, called only after
    /// sell() has already applied all storage effects, with sell()'s own
    /// nonReentrant guard covering this call.
    function _settleSell(
        address token,
        Curve storage curve,
        uint256 tokenAmountIn,
        SellQuote memory quote
    ) private returns (uint256 ethOut) {
        bool pulled = IERC20(token).transferFrom(msg.sender, address(this), tokenAmountIn);
        require(pulled, "CustomBondingCurveFactory: token transferFrom failed");
        require(
            IERC20(token).balanceOf(address(this)) >= curve.tokensRemaining + (curve.totalSupply - curve.curveSupply),
            "CustomBondingCurveFactory: token balance invariant violated"
        );

        _distributeEthFee(quote.feeAmount);

        ethOut = quote.netEthOut;
        (bool sentEth, ) = payable(msg.sender).call{value: ethOut}("");
        require(sentEth, "CustomBondingCurveFactory: ETH payout failed");

        emit CurveSold(token, msg.sender, tokenAmountIn, quote.feeAmount, ethOut, curve.realEthReserve);
    }

    /// @notice Permissionless graduation once a curve's realEthReserve has
    /// crossed its own poolSeedTargetWei -- the guaranteed fallback to buy()'s
    /// own best-effort inline attempt.
    function graduate(address token) external nonReentrant returns (address pair, uint256 lpAmount, uint256 lockId) {
        Curve storage curve = curves[token];
        require(curve.totalSupply > 0, "CustomBondingCurveFactory: unknown curve");
        require(!curve.graduated, "CustomBondingCurveFactory: already graduated");
        require(curve.realEthReserve >= curve.poolSeedTargetWei, "CustomBondingCurveFactory: graduation target not met");
        return _doGraduate(token, curve);
    }

    /// @dev External purely so buy() can wrap it in try/catch -- identical
    /// pattern to BondingCurveFactory._attemptGraduate.
    function _attemptGraduate(address token) external returns (address pair, uint256 lpAmount, uint256 lockId) {
        require(msg.sender == address(this), "CustomBondingCurveFactory: internal only");
        Curve storage curve = curves[token];
        if (curve.totalSupply == 0 || curve.graduated || curve.realEthReserve < curve.poolSeedTargetWei) {
            return (address(0), 0, 0);
        }
        return _doGraduate(token, curve);
    }

    /// @dev The actual graduation. Flips `graduated` before any external call
    /// below, zeroes curve.realEthReserve before the pool-seeding call
    /// (identical discipline to BondingCurveFactory._doGraduate, including
    /// its post-audit Finding 2 fix -- built in from the start here). Seeds
    /// the pool with the factory's entire remaining balance of `token` and
    /// this curve's full realEthReserve, locks the resulting LP to the
    /// ORIGINAL creator recorded at curve creation via this factory's OWN
    /// LiquidityLocker instance.
    ///
    /// Wires the token's tax in the two-call shape CustomToken requires --
    /// setPair(pair) first, then configurePlatformTax(...) -- rather than
    /// LaunchedToken's single configureTax() call. See this contract's
    /// header comment for why CustomToken needs both calls. Applies the SAME
    /// post-graduation platform-tax terms that were in effect when this curve
    /// was CREATED (curve.tax* fields, not the live globals) -- identical
    /// snapshotting discipline to BondingCurveFactory. This tax is entirely
    /// independent of, and layered on top of, whatever buyFees_/sellFees_ the
    /// creator configured back at createCurveToken() time.
    function _doGraduate(address token, Curve storage curve) private returns (address pair, uint256 lpAmount, uint256 lockId) {
        curve.graduated = true;

        uint256 tokensForPool = IERC20(token).balanceOf(address(this));
        uint256 ethForPool = curve.realEthReserve;
        curve.realEthReserve = 0;
        totalCurveReserveEth -= ethForPool; // Finding CBCF-2 -- keep the running total in lockstep with curve.realEthReserve
        require(tokensForPool > 0 && ethForPool > 0, "CustomBondingCurveFactory: nothing to graduate");

        IERC20(token).approve(address(router), tokensForPool);
        (, , uint256 lpAmountAdded) = router.addLiquidityETH{value: ethForPool}(
            token,
            tokensForPool,
            _minWithSlippage(tokensForPool),
            _minWithSlippage(ethForPool),
            address(locker), // LP tokens mint straight to this factory's own locker
            block.timestamp + 15 minutes
        );
        lpAmount = lpAmountAdded;

        pair = IUniswapV2FactoryMinimal(router.factory()).getPair(token, router.WETH());
        require(pair != address(0), "CustomBondingCurveFactory: pair not found after addLiquidityETH");
        pairOf[token] = pair;

        CustomToken(payable(token)).setPair(pair);

        uint256 effectiveRewardBps = rewardsDistributor != address(0) ? curve.taxRewardBps : 0;
        uint256 effectiveCreatorRewardBps = creatorRewardsDistributor != address(0) ? curve.taxCreatorRewardBps : 0;
        CustomToken(payable(token)).configurePlatformTax(
            curve.taxPlatformFeeWallet, curve.taxFeeBps, curve.taxPriceFeed, curve.taxGraduationTargetUsd, curve.taxMaxOracleStaleness,
            rewardsDistributor, effectiveRewardBps, creatorRewardsDistributor, effectiveCreatorRewardBps,
            feeWalletDistributor
        );

        uint256 unlockTime = block.timestamp + lpLockDuration;
        lockId = locker.lock(pair, curve.creator, lpAmount, unlockTime);

        emit CurveGraduated(token, pair, ethForPool, tokensForPool, lpAmount, unlockTime, lockId);
    }

    // ---- views ----

    function quoteBuy(address token, uint256 ethIn) external view returns (uint256 tokensOut, uint256 feeAmount) {
        Curve storage curve = curves[token];
        require(curve.totalSupply > 0, "CustomBondingCurveFactory: unknown curve");
        (tokensOut, feeAmount, ) = _quoteBuy(curve, ethIn);
    }

    function quoteSell(address token, uint256 tokenAmountIn) external view returns (uint256 ethOut, uint256 feeAmount) {
        Curve storage curve = curves[token];
        require(curve.totalSupply > 0, "CustomBondingCurveFactory: unknown curve");
        SellQuote memory quote = _quoteSell(curve, tokenAmountIn);
        ethOut = quote.netEthOut;
        feeAmount = quote.feeAmount;
    }

    function curveState(address token)
        external
        view
        returns (
            address creator,
            uint256 totalSupply_,
            uint256 curveSupply,
            uint256 tokensRemaining,
            uint256 virtualEthReserve,
            uint256 virtualTokenReserve,
            uint256 realEthReserve,
            uint256 poolSeedTargetWei_,
            uint256 curveFeeBps_,
            bool graduated,
            uint256 createdAt
        )
    {
        Curve storage curve = curves[token];
        require(curve.totalSupply > 0, "CustomBondingCurveFactory: unknown curve");
        return (
            curve.creator,
            curve.totalSupply,
            curve.curveSupply,
            curve.tokensRemaining,
            curve.virtualEthReserve,
            curve.virtualTokenReserve,
            curve.realEthReserve,
            curve.poolSeedTargetWei,
            curve.curveFeeBps,
            curve.graduated,
            curve.createdAt
        );
    }

    /// @notice The seven post-graduation tax terms this specific curve is
    /// locked into -- snapshotted once, at createCurveToken() time, and
    /// applied verbatim in _doGraduate whenever this curve eventually
    /// graduates, regardless of what setTaxDefaults() has done to the live
    /// globals in the meantime. Identical to
    /// BondingCurveFactory.curveTaxConfig.
    function curveTaxConfig(address token)
        external
        view
        returns (
            address taxPlatformFeeWallet,
            uint256 taxFeeBps,
            address taxPriceFeed,
            uint256 taxGraduationTargetUsd,
            uint256 taxMaxOracleStaleness,
            uint256 taxRewardBps,
            uint256 taxCreatorRewardBps
        )
    {
        Curve storage curve = curves[token];
        require(curve.totalSupply > 0, "CustomBondingCurveFactory: unknown curve");
        return (
            curve.taxPlatformFeeWallet,
            curve.taxFeeBps,
            curve.taxPriceFeed,
            curve.taxGraduationTargetUsd,
            curve.taxMaxOracleStaleness,
            curve.taxRewardBps,
            curve.taxCreatorRewardBps
        );
    }

    function tokensOf(address creator_) external view returns (address[] memory) {
        return _tokensByCreator[creator_];
    }

    function allTokens() external view returns (address[] memory) {
        return _tokenList;
    }

    /// @notice Previews the address createCurveToken() will deploy to for a
    /// given (creator, salt) pair.
    function predictTokenAddress(address creator_, uint256 salt) external view returns (address) {
        return Clones.predictDeterministicAddress(tokenImplementation, _deriveTokenSalt(creator_, salt), address(this));
    }

    // ---- admin ----

    function setCurveFeeBps(uint256 newBps) external onlyOwner {
        require(newBps <= MAX_FEE_BPS, "CustomBondingCurveFactory: feeBps exceeds MAX_FEE_BPS ceiling");
        curveFeeBps = newBps;
        emit CurveFeeBpsUpdated(newBps);
    }

    function setCurveSupplyBps(uint256 newBps) external onlyOwner {
        require(newBps > 0 && newBps <= 10_000, "CustomBondingCurveFactory: curveSupplyBps must be in (0, 10000]");
        curveSupplyBps = newBps;
        emit CurveSupplyBpsUpdated(newBps);
    }

    function setVirtualEthReserveDefault(uint256 newDefault) external onlyOwner {
        virtualEthReserveDefault = newDefault;
        emit VirtualEthReserveDefaultUpdated(newDefault);
    }

    function setVirtualTokenReserveBps(uint256 newBps) external onlyOwner {
        require(newBps > 0, "CustomBondingCurveFactory: virtualTokenReserveBps must be > 0");
        virtualTokenReserveBps = newBps;
        emit VirtualTokenReserveBpsUpdated(newBps);
    }

    /// @notice Updates the default real-ETH-raised threshold (in wei) new
    /// curves must cross before they graduate into a pool -- only ever
    /// affects curves created after this call.
    function setPoolSeedTargetWei(uint256 newTarget) external onlyOwner {
        require(newTarget > 0, "CustomBondingCurveFactory: graduation target must be > 0");
        poolSeedTargetWei = newTarget;
        emit PoolSeedTargetUpdated(newTarget);
    }

    function setCurveLaunchFee(uint256 newFee) external onlyOwner {
        curveLaunchFee = newFee;
        emit CurveLaunchFeeUpdated(newFee);
    }

    function setLpLockDuration(uint256 newDuration) external onlyOwner {
        lpLockDuration = newDuration;
        emit LpLockDurationUpdated(newDuration);
    }

    function setMaxCreatorBuyBps(uint256 newBps) external onlyOwner {
        require(newBps <= 10_000, "CustomBondingCurveFactory: bps cannot exceed 100%");
        maxCreatorBuyBps = newBps;
        emit MaxCreatorBuyBpsUpdated(newBps);
    }

    /// @notice See TokenFactory.setLiquiditySlippageBps -- identical fixed
    /// 5.00%-8.00% band, applied to _doGraduate's own addLiquidityETH call.
    function setLiquiditySlippageBps(uint256 newBps) external onlyOwner {
        require(newBps >= MIN_LIQUIDITY_SLIPPAGE_BPS, "CustomBondingCurveFactory: slippage below 5% floor");
        require(newBps <= MAX_LIQUIDITY_SLIPPAGE_BPS, "CustomBondingCurveFactory: slippage above 8% ceiling");
        liquiditySlippageBps = newBps;
        emit LiquiditySlippageBpsUpdated(newBps);
    }

    function setFeeTreasury(address newTreasury) external onlyOwner {
        require(newTreasury != address(0), "CustomBondingCurveFactory: invalid treasury");
        feeTreasury = newTreasury;
        emit FeeTreasuryUpdated(newTreasury);
    }

    function setRewardsDistributor(address newDistributor) external onlyOwner {
        rewardsDistributor = newDistributor;
        emit RewardsDistributorUpdated(newDistributor);
    }

    function setCreatorRewardsDistributor(address newDistributor) external onlyOwner {
        creatorRewardsDistributor = newDistributor;
        emit CreatorRewardsDistributorUpdated(newDistributor);
    }

    function setFeeWalletDistributor(address newDistributor) external onlyOwner {
        feeWalletDistributor = newDistributor;
        emit FeeWalletDistributorUpdated(newDistributor);
    }

    /// @notice Points relayedCreateCurveToken's onlyRelayer gate at the
    /// platform's relayer hot wallet. See TokenFactory.setRelayer for the
    /// full explanation -- identical convention, including the requirement
    /// that maxRelayerGasReimbursementWei already be set to a real, non-zero
    /// value before a relayer can be enabled.
    function setRelayer(address newRelayer) external onlyOwner {
        if (newRelayer != address(0)) {
            require(
                maxRelayerGasReimbursementWei > 0,
                "CustomBondingCurveFactory: set maxRelayerGasReimbursementWei before enabling a relayer"
            );
        }
        relayer = newRelayer;
        emit RelayerUpdated(newRelayer);
    }

    /// @notice See TokenFactory.setMaxRelayerGasReimbursement -- identical
    /// circuit breaker, applied to relayedCreateCurveToken's own
    /// _settleRelayedFee.
    ///
    /// FIX (this review, same class as TokenFactory's own F-2 and
    /// BondingCurveFactory's own matching fix): setRelayer() above only
    /// checks maxRelayerGasReimbursementWei > 0 at the moment a relayer is
    /// *enabled* -- this setter had no corresponding check, so it could be
    /// called with newCapWei == 0 at any later time, including while a
    /// relayer was already active, silently reopening the circuit breaker
    /// setRelayer() exists to enforce. Now rejects zeroing the cap while a
    /// relayer is configured.
    function setMaxRelayerGasReimbursement(uint256 newCapWei) external onlyOwner {
        require(
            relayer == address(0) || newCapWei > 0,
            "CustomBondingCurveFactory: cannot zero the gas reimbursement cap while a relayer is active"
        );
        maxRelayerGasReimbursementWei = newCapWei;
        emit MaxRelayerGasReimbursementUpdated(newCapWei);
    }

    /// @notice Update the POST-graduation platform-tax defaults applied to
    /// curves CREATED from this point forward -- snapshotted per curve at
    /// createCurveToken() time, so this never touches an already-existing
    /// curve's own locked-in terms. Identical bounds to
    /// BondingCurveFactory/CustomTokenFactory's own setTaxDefaults.
    function setTaxDefaults(
        address platformFeeWallet_,
        uint256 feeBps_,
        address priceFeed_,
        uint256 graduationTargetUsd_,
        uint256 maxOracleStaleness_,
        uint256 rewardBps_,
        uint256 creatorRewardBps_
    ) external onlyOwner {
        require(feeBps_ <= MAX_FEE_BPS, "CustomBondingCurveFactory: feeBps exceeds MAX_FEE_BPS ceiling");
        require(graduationTargetUsd_ > 0, "CustomBondingCurveFactory: graduation target must be > 0");
        require(maxOracleStaleness_ > 0, "CustomBondingCurveFactory: oracle staleness must be > 0");
        require(rewardBps_ + creatorRewardBps_ <= feeBps_, "CustomBondingCurveFactory: rewardBps+creatorRewardBps cannot exceed feeBps");
        platformFeeWallet = platformFeeWallet_;
        feeBps = feeBps_;
        priceFeed = priceFeed_;
        graduationTargetUsd = graduationTargetUsd_;
        maxOracleStaleness = maxOracleStaleness_;
        rewardBps = rewardBps_;
        creatorRewardBps = creatorRewardBps_;
        emit TaxDefaultsUpdated();
    }

    /// @notice Escape hatch for an already-graduated curve's token whose
    /// price feed has gone permanently stale -- calls into the token
    /// directly, same as BondingCurveFactory.updateTokenPriceFeed.
    function updateTokenPriceFeed(address token, address newPriceFeed_, uint256 newMaxOracleStaleness_) external onlyOwner {
        CustomToken(payable(token)).updatePriceFeed(newPriceFeed_, newMaxOracleStaleness_);
        emit TokenPriceFeedUpdated(token, newPriceFeed_, newMaxOracleStaleness_);
    }

    /// @notice Sweeps ETH that _distributeEthFee couldn't deliver to `to`.
    /// Scoped to ONLY the tracked strandedFees counter, never
    /// address(this).balance directly -- identical safeguard to
    /// BondingCurveFactory.rescueStrandedFees.
    function rescueStrandedFees(address to, uint256 amount) external onlyOwner {
        require(to != address(0), "CustomBondingCurveFactory: invalid recipient");
        require(amount <= strandedFees, "CustomBondingCurveFactory: exceeds stranded fees");
        strandedFees -= amount;
        (bool sent, ) = payable(to).call{value: amount}("");
        require(sent, "CustomBondingCurveFactory: rescue transfer failed");
        emit StrandedFeesRescued(to, amount);
    }

    /// @notice Rescues an ERC20 mistakenly sent directly to this contract.
    /// Cannot be used on any token this factory itself ever created as a
    /// curve -- live or already graduated -- identical safeguard to
    /// BondingCurveFactory.rescueToken.
    function rescueToken(address token, address to, uint256 amount) external onlyOwner {
        require(to != address(0), "CustomBondingCurveFactory: invalid recipient");
        require(creatorOf[token] == address(0), "CustomBondingCurveFactory: cannot rescue a curve's own token");
        bool sent = IERC20(token).transfer(to, amount);
        require(sent, "CustomBondingCurveFactory: token rescue failed");
        emit TokenRescued(token, to, amount);
    }

    /// @notice Finding CBCF-2 fix: sweeps ETH that is neither a tracked
    /// strandedFees failure nor any live curve's own realEthReserve --
    /// identical mechanics to BondingCurveFactory.rescueStrayEth (see that
    /// function's own doc comment for the full reasoning).
    function rescueStrayEth(address to) external onlyOwner returns (uint256 amount) {
        require(to != address(0), "CustomBondingCurveFactory: invalid recipient");
        uint256 accountedFor = totalCurveReserveEth + strandedFees;
        uint256 balance = address(this).balance;
        require(balance > accountedFor, "CustomBondingCurveFactory: no stray ETH to rescue");
        amount = balance - accountedFor;
        (bool sent, ) = payable(to).call{value: amount}("");
        require(sent, "CustomBondingCurveFactory: stray ETH rescue failed");
        emit StrayEthRescued(to, amount);
    }

    /// @notice Circuit breaker on new buy() calls only -- sell() is never
    /// pausable. Identical reasoning to BondingCurveFactory.pause.
    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }
}

contracts/CustomToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import "./interfaces/IUniswapV2Router02.sol";
import "./interfaces/IUniswapV2Pair.sol";
import "./interfaces/IAggregatorV3.sol";
import "./interfaces/ITokenFactoryTaxDefaults.sol";

/// @title CustomToken
/// @notice A configurable ERC20 that CustomTokenFactory clones (EIP-1167,
/// same pattern as LaunchedToken) for the "advanced" launch path — a
/// creator picks a tax rate (0% is a valid choice, same contract either
/// way) split across up to four fee types, each independently on or off:
///
///  - reflections: a share of every buy/sell is swapped and distributed to
///    every holder, proportional to their balance, in either the chain's
///    native ETH or a specific ERC20 the creator names at launch. Every
///    holder's claimable balance grows on its own, proportional to their
///    holdings, the moment a distribution happens — no action needed from
///    them at all. Payout itself has two paths, both drawing from the exact
///    same accounting so nobody can ever be paid twice for one
///    distribution: anyone can call pushReflections() to sweep a batch of
///    holders and pay each one directly (this is what makes payout
///    "automatic" — it doesn't require this specific holder to lift a
///    finger, only *someone* to call it, e.g. an off-chain keeper on a
///    schedule — see scripts/pushReflections.js), and a holder who'd rather
///    not wait for the sweep to reach them can still call
///    claimReflections() themselves at any time. Deliberately NOT done by
///    looping over holders inside the transfer itself — that's exactly how
///    fee tokens end up with a transfer that can be gas-griefed into
///    failing, so pushReflections() is a separate, gas-bounded,
///    caller-chosen batch instead (same anti-griefing shape as
///    PlatformRewardsDistributor.processAirdropBatch).
///  - marketing: a share is swapped for ETH and sent to marketingWallet,
///    which the creator (and only the creator) can repoint later via
///    setMarketingWallet().
///  - liquidity: a share is split in half, one half swapped for ETH, and
///    both halves added back into this token's own pool as new liquidity —
///    the resulting LP tokens are sent straight to a burn address, so this
///    stream of liquidity can never be pulled back out by anyone.
///  - burn: a share is destroyed outright via a real burn (totalSupply
///    actually decreases — see _update below), not just moved to a "dead"
///    wallet that still counts toward supply.
///
/// Buy tax and sell tax are set independently, each capped at 5% (see
/// MAX_TOTAL_BPS) — enforced once, at initialize(), and immutable for the
/// life of the token from that point on. Nothing in this contract can
/// ever raise, lower, or otherwise touch buyFees/sellFees or the
/// platform's own platformFeeBps after that point — there is no setter
/// for any of them anywhere below. What CAN change after launch is
/// operational, never the rate itself: the marketing wallet address, the
/// swap-threshold batching knob, the processing-slippage tolerance, the
/// rewards-blocked list, and a tax-exemption whitelist (isTaxExempt /
/// setTaxExempt — bypasses tax entirely for a specific address, but never
/// changes what rate anyone else pays). All of those, plus the creator
/// role itself, go permanently dark the moment the creator calls
/// renounceCreator() — see that function and transferCreator/
/// acceptCreator below. This is deliberate: the classic "creator jacks up
/// the sell tax after launch" rug is closed off at the rate level, not
/// just gated behind a role that could be renounced later.
contract CustomToken is ERC20, ReentrancyGuard {
    bool private _initialized;

    address public creator;
    /// @notice Set by transferCreator(); becomes `creator` once the
    /// proposed address calls acceptCreator() itself. Mirrors the
    /// Ownable2Step pattern already used for every other privileged role
    /// in this codebase (TokenFactory/CustomTokenFactory/LiquidityLocker
    /// owners) so a single mistyped address can never permanently strand
    /// the creator role — see setMarketingWallet, setSwapThreshold,
    /// setRewardsBlocked, activateIndependentPair, and rescueToken/
    /// rescueEth below, all of which become permanently uncallable
    /// without a working creator address.
    address public pendingCreator;
    address public factory;
    address public router;
    address public pair; // set once, by the factory, right after it seeds this token's pool

    /// @notice True for a clone deployed by CustomBondingCurveFactory
    /// (i.e. a "Quick Launch" curve token), false for a clone deployed
    /// directly by CustomTokenFactory ("Deploy Custom Tax Token" /
    /// "Deploy and Add Liquidity"). Set once, at initialize(), and never
    /// changed again.
    ///
    /// @dev Finding CT-2 fix. Mirrors LaunchedToken.curveManaged exactly,
    /// closing the same vulnerability class in this contract:
    /// _activatePoolIfFound()'s auto-activation in _update() below was
    /// originally guarded only by `pair == address(0) && from != factory`,
    /// which correctly excludes CustomTokenFactory's own atomic
    /// "deploy + seed liquidity" internal transfer (from == factory
    /// there) but does NOT exclude a CustomBondingCurveFactory curve
    /// token's ordinary curve sell() (transferFrom(seller, factory,
    /// amount) — from == seller, the trader, not the factory) or any
    /// plain wallet-to-wallet transfer of curve tokens during the
    /// pre-graduation phase. Since creating an empty Uniswap-V2-style
    /// pair for any token is permissionless and requires no liquidity, an
    /// attacker could pre-create a rogue pair for a not-yet-graduated
    /// curve token, and the very next ordinary sell/transfer would
    /// permanently lock `pair` to that rogue shell via
    /// _activatePoolIfFound() — causing CustomBondingCurveFactory's own
    /// _doGraduate() -> setPair() call to revert forever on
    /// PairAlreadySet(), permanently blocking that token from ever
    /// graduating to a real, LP-locked pool. No funds are ever at risk;
    /// this was a permanent, low-cost, permissionless denial-of-service
    /// against the graduation feature specifically. A curve-managed
    /// token (curveManaged == true) now never attempts pool
    /// auto-detection at all — _update()'s guard below additionally
    /// requires `!curveManaged` — so this class of pre-graduation pair
    /// hijack is closed regardless of what transfer would otherwise have
    /// triggered it or what rogue pair a third party pre-created. Only
    /// CustomBondingCurveFactory's own explicit setPair() call (inside
    /// _doGraduate(), after real liquidity has genuinely been seeded)
    /// can ever set `pair` for a curve-managed token.
    bool public curveManaged;
    uint256 public launchedAt;
    string private _tokenName;
    string private _tokenSymbol;

    address private constant BURN_ADDRESS = 0x000000000000000000000000000000000000dEaD;

    /// @notice One side's fee split, all in bps of the transferred amount.
    /// A component at 0 is simply off. reflectionBps+marketingBps+
    /// liquidityBps+burnBps together must be <= MAX_TOTAL_BPS.
    struct FeeSet {
        uint16 reflectionBps;
        uint16 marketingBps;
        uint16 liquidityBps;
        uint16 burnBps;
    }
    uint16 public constant MAX_TOTAL_BPS = 500; // 5.00% per side, hard cap

    /// @dev Scratch struct used only inside _update() to hold one transfer's
    /// computed fee amounts. Purely a stack-pressure fix: with viaIR
    /// enabled, the Yul optimizer still has its own (separate from the EVM's
    /// classic 16-slot limit) ceiling on how many locals can be live at once
    /// in one function, and _update() calling the private _afterBalanceChange
    /// six times across several branches — each with a different subset of
    /// these amounts still live — was landing right at that ceiling ("too
    /// deep in the stack by 1 slots"). A memory struct collapses what used
    /// to be seven separate stack-resident uint256 locals into one memory
    /// pointer, which is what actually fixes it; the arithmetic and control
    /// flow below are otherwise unchanged from before this struct existed.
    struct TransferCuts {
        uint256 reflection;
        uint256 marketing;
        uint256 liquidity;
        uint256 burn;
        uint256 platform;
        uint256 total;
        uint256 toContract;
    }

    FeeSet public buyFees;
    FeeSet public sellFees;

    /// @notice address(0) means reflections pay out in the chain's native
    /// ETH; any other address is the ERC20 reflections pay out in instead
    /// (swapped for via router, routed through WETH). Fixed at launch.
    address public reflectionAsset;

    /// @notice Where the marketing fee's swapped ETH goes. The only
    /// mutable piece of this whole fee configuration — see
    /// setMarketingWallet(). A zero address here simply means the
    /// marketing fee components must be zero too (enforced at
    /// initialize()), since there'd be nowhere for that ETH to go.
    address public marketingWallet;

    // ---- platform-level graduating tax — entirely separate from, and not
    // counted against, the creator's own MAX_TOTAL_BPS cap above. Mirrors
    // LaunchedToken's tax exactly: a flat feeBps skimmed in-kind (no swap,
    // straight token transfer) to platformFeeWallet on every buy and sell,
    // until the pool's live market cap crosses graduationTargetUsd, at
    // which point it permanently disables itself. Wired once by the
    // factory via configurePlatformTax(), immediately after setPair() —
    // passing feeBps_ == 0 or a zero feeWallet_ leaves it permanently
    // inactive. ----
    bool public platformTaxConfigured;
    address public platformFeeWallet;
    uint256 public platformFeeBps; // 100 = 1.00%
    bool public platformTaxActive;
    IAggregatorV3 public priceFeed;
    uint256 public graduationTargetUsd; // whole dollars, e.g. 50000
    uint256 public maxOracleStaleness; // seconds; the tax-disable check is skipped (never reverted) if the feed is older than this

    // ---- reward diversion: carves a slice of the PLATFORM's own
    // platformFeeBps cut off to PlatformRewardsDistributor instead of
    // platformFeeWallet, on every taxed transfer. Never touches
    // reflectionCut/marketingCut/liquidityCut/burnCut above — those are the
    // creator's own separately-capped fee config (buyFees/sellFees) and
    // this feature has nothing to do with them. Snapshotted once, in
    // configurePlatformTax(), same convention as every other platform-tax
    // default here. rewardsDistributor == address(0) (the default) means
    // this is entirely inactive — 100% of platformFeeBps still goes to
    // platformFeeWallet, exactly as before this feature existed. ----
    address public rewardsDistributor;
    uint256 public rewardBps; // absolute bps of transfer value diverted to rewardsDistributor, carved OUT OF platformFeeBps (never on top of it); rewardBps + creatorRewardBps always <= platformFeeBps

    // ---- creator rewards: a second, independent carve-out of the
    // PLATFORM's own platformFeeBps, sent in-kind to
    // CreatorRewardsDistributor on every taxed transfer — never stacked
    // with rewardBps above (rewardBps + creatorRewardBps <= platformFeeBps
    // is enforced once, in configurePlatformTax()), and never touching
    // reflectionCut/marketingCut/liquidityCut/burnCut, which are the
    // creator's own separately-capped fee config and have nothing to do
    // with this feature. CreatorRewardsDistributor later swaps its
    // accumulated balance of this token for ETH and credits this token's
    // own creator, claimable through that contract — see
    // CreatorRewardsDistributor.sol and LaunchedToken's identical mirror of
    // this same feature. Same address(0)-means-inactive convention as
    // rewardsDistributor. ----
    address public creatorRewardsDistributor;
    uint256 public creatorRewardBps; // absolute bps of transfer value diverted to creatorRewardsDistributor, carved OUT OF platformFeeBps (never on top of it, and never overlapping rewardBps)

    // ---- fee-wallet auto-conversion: redirects the REMAINDER of
    // platformFeeBps (cuts.platform - rewardCut - creatorCut, i.e. whatever
    // wasn't already carved off to rewardsDistributor/
    // creatorRewardsDistributor above) to FeeWalletDistributor in-kind,
    // instead of straight to platformFeeWallet. Mirrors LaunchedToken's
    // identical feature exactly — see that contract's comment. No bps of
    // its own; just a different destination for the same remainder.
    // feeWalletDistributor == address(0) (the default) means this is
    // entirely inactive and the remainder still goes straight to
    // platformFeeWallet as a plain token transfer, exactly as it always
    // has. ----
    address public feeWalletDistributor;

    /// @notice Hard ceiling on totalSupply_, enforced once at initialize().
    /// See LaunchedToken.MAX_TOTAL_SUPPLY for the full reasoning — purely
    /// defense-in-depth against currentMarketCapInFeedDecimals()'s own
    /// arithmetic overflowing for an extreme, unrealistic supply.
    uint256 public constant MAX_TOTAL_SUPPLY = 1_000_000_000_000_000 * 1e18; // 1 quadrillion tokens, 18 decimals

    /// @notice Mirrors LaunchedToken.graduationCandidateAt exactly — see
    /// that contract's comment for the full reasoning. 0 means "not
    /// currently a graduation candidate".
    uint256 public graduationCandidateAt;

    /// @notice Mirrors LaunchedToken.GRADUATION_CONFIRMATION_WINDOW.
    uint256 public constant GRADUATION_CONFIRMATION_WINDOW = 30 minutes;

    // ---- fees collected in-kind, awaiting a batched swap-and-process ----
    uint256 public pendingLiquidityTokens;
    uint256 public pendingMarketingTokens;
    uint256 public pendingReflectionTokens;

    /// @notice Total pending tokens (all three streams combined) needed
    /// before a sell or plain transfer will trigger the swap-and-process
    /// step. Defaults to 0.1% of supply; the creator can retune it (never
    /// above 5% of supply, so it can't be set so high it silently never
    /// fires) via setSwapThreshold().
    uint256 public swapThreshold;

    /// @notice Slippage tolerance applied as a protective amountOutMin
    /// floor to every internal swap-and-process trade (marketing's
    /// token-for-ETH swap, half of the liquidity fee's token-for-ETH swap,
    /// and the reflection fee's token-for-ETH-or-token swap), plus the
    /// liquidity-add's own token/ETH minimums — see _quoteOut/
    /// _applySlippage and Finding 2 of AUDIT-CustomToken.md. Before this,
    /// every one of these traded with amountOutMin: 0 (or 0,0), making
    /// them a predictable, repeatable MEV sandwich target since the
    /// trigger condition (pending fees crossing swapThreshold) is public
    /// on-chain state. Same 5.00%-8.00% band as TokenFactory/
    /// CustomTokenFactory's liquiditySlippageBps/buyInSlippageBps, but
    /// creator-adjustable here (via setProcessingSlippageBps) rather than
    /// platform-owned, since these trades only ever affect this specific
    /// token's own marketing/liquidity/reflection proceeds. Set to its
    /// 600 (6.00%) default inside initialize() rather than as an inline
    /// field initializer — this is a clone, and an inline initializer
    /// only ever runs in the implementation contract's own constructor,
    /// never on a clone (see swapThreshold above for the same reasoning).
    uint16 public processingSlippageBps;
    uint16 public constant MIN_PROCESSING_SLIPPAGE_BPS = 500; // 5.00%
    uint16 public constant MAX_PROCESSING_SLIPPAGE_BPS = 800; // 8.00%

    bool private _inSwap;
    modifier lockTheSwap() {
        _inSwap = true;
        _;
        _inSwap = false;
    }

    modifier onlyFactory() {
        if (msg.sender != factory) revert NotFactory();
        _;
    }
    modifier onlyCreator() {
        if (msg.sender != creator) revert NotCreator();
        _;
    }

    // ---- reflection accounting: the standard "magnified dividend per
    // share" pattern (as used by the widely-referenced DividendPayingToken
    // implementations) — O(1) per transfer, no loop over holders. Every
    // balance change (mint, burn, or transfer) adjusts a per-account
    // correction term so that accumulativeDividendOf() stays correct no
    // matter when someone's balance changed relative to past
    // distributions. See _afterBalanceChange / accumulativeDividendOf. ----
    uint256 private constant MAGNITUDE = 2 ** 128;
    uint256 public magnifiedDividendPerShare;
    mapping(address => int256) private _magnifiedDividendCorrections;
    mapping(address => uint256) public withdrawnDividends;
    uint256 public totalDividendsDistributed;
    uint256 public totalDividendsWithdrawn;

    /// @notice Creator-controlled block list: an address with
    /// isBlockedFromRewards[account] == true never shows or accrues any
    /// reflection entitlement, on either claimReflections() or
    /// pushReflections() — see accumulativeDividendOf() and
    /// setRewardsBlocked() below. Meant for the same kind of address the
    /// pair/address(this) exclusion above already covers automatically:
    /// a bot, a known bad actor, or any wallet the creator decides
    /// shouldn't farm reflections — not a way to touch anyone's token
    /// balance, trading ability, or already-claimed history.
    mapping(address => bool) public isBlockedFromRewards;

    /// @notice Creator-controlled tax-exemption whitelist: an address with
    /// isTaxExempt[account] == true pays (and triggers) no tax at all —
    /// neither the creator's own buy/sell fee (reflection/marketing/
    /// liquidity/burn) nor the platform's graduating tax — on any
    /// transfer where it's either side. See setTaxExempt() below for the
    /// full reasoning on why this is safe: it only ever changes WHO pays
    /// the already-fixed rate, never the rate itself.
    mapping(address => bool) public isTaxExempt;

    /// @notice True iff either side's reflectionBps was nonzero at
    /// initialize() — fixed for the token's life, exactly like every other
    /// rate here. Gates whether the holder registry below is maintained at
    /// all: a token that never uses reflections pays zero extra storage
    /// cost for a registry it will never need.
    bool public reflectionsEnabled;

    /// @notice Holder registry for pushReflections() below — same
    /// hand-rolled swap-and-pop array + 1-based index mapping as
    /// PlatformToken.sol (not OpenZeppelin's EnumerableSet, which pulls in
    /// an mcopy-only Arrays.sol incompatible with this project's paris EVM
    /// target). address(this) and `pair` can both end up recorded here as
    /// ordinary side effects of how tokens move during launch/liquidity
    /// seeding — pushReflections() skips both explicitly rather than
    /// trying to keep them out of the array, since `pair` in particular
    /// isn't even known yet at the moment liquidity is first seeded (see
    /// pushReflections' own comment).
    address[] private _reflectionHolders;
    mapping(address => uint256) private _reflectionHolderIndex; // 1-based; 0 = not currently tracked

    /// @notice Round-robin cursor into _reflectionHolders for
    /// pushReflections() — persists across calls so repeated sweeps keep
    /// covering fresh holders instead of always restarting at index 0.
    uint256 public reflectionPushCursor;

    /// @notice Gas forwarded on each native-ETH push in pushReflections()
    /// below — enough for a plain wallet or a simple forwarding contract to
    /// receive it, but capped so one holder's receive()/fallback can't
    /// consume the batch caller's entire remaining gas.
    uint256 public constant PUSH_GAS_STIPEND = 50_000;

    event TokenInitialized(string name, string symbol, uint256 totalSupply, address indexed creator);
    event PairSet(address indexed pair);
    event MarketingWalletUpdated(address indexed newWallet);
    event SwapThresholdUpdated(uint256 newThreshold);
    event RewardsAccessUpdated(address indexed account, bool blocked);
    event DividendsDistributed(uint256 amount);
    event DividendWithdrawn(address indexed to, uint256 amount);
    event ReflectionsPushed(uint256 holdersPaid, uint256 totalPaid, uint256 nextCursor);
    event LiquidityAutoAdded(uint256 tokenAmount, uint256 ethAmount, uint256 lpAmount);
    event MarketingFeeSent(uint256 ethAmount);
    event TokensBurned(uint256 amount);
    event PlatformTaxConfigured(address indexed feeWallet, uint256 feeBps, uint256 graduationTargetUsd);
    event PlatformTaxDisabled(uint256 marketCapInFeedDecimals);
    event GraduationCandidateObserved(uint256 marketCapInFeedDecimals, uint256 confirmEligibleAt);
    event GraduationCandidateReset();
    event PriceFeedUpdated(address indexed newPriceFeed, uint256 newMaxOracleStaleness);
    event ProcessingSlippageBpsUpdated(uint256 newBps);
    event TokenRescued(address indexed token, address indexed to, uint256 amount);
    event EthRescued(address indexed to, uint256 amount);
    event CreatorTransferStarted(address indexed previousCreator, address indexed newCreator);
    event CreatorTransferred(address indexed previousCreator, address indexed newCreator);
    event CreatorRenounced(address indexed previousCreator);
    event TaxExemptionUpdated(address indexed account, bool exempt);

    // ---- custom errors ----
    // Behavior-preserving swap-in for what used to be require(cond, "CustomToken: ...")
    // string-literal reverts throughout this contract: same validation, same
    // order, same revert conditions — only how the revert reason is encoded
    // on-chain changes (a 4-byte selector instead of a stored/ABI-encoded
    // string per call site), which is what keeps this contract's deployed
    // bytecode under the 24,576-byte Spurious Dragon limit. Grouped here the
    // same way the events above are grouped, rather than declared inline at
    // each call site.

    // access control
    error NotFactory(); // caller is not the factory
    error NotCreator(); // caller is not the creator
    error NotPendingCreator(); // caller is not the pending creator
    error InternalOnly(); // callable only via this contract's own external self-call

    // initialize()
    error AlreadyInitialized();
    error SupplyMustBePositive(); // supply must be > 0
    error SupplyTooLarge(); // supply exceeds MAX_TOTAL_SUPPLY
    error InvalidCreator();
    error InvalidMintRecipient();
    error InvalidFactory();
    error InvalidRouter();
    error ReflectionAssetIsSelf(); // reflection asset cannot be this token
    error BuyTaxExceedsLimit(); // buy tax exceeds 5%
    error SellTaxExceedsLimit(); // sell tax exceeds 5%
    error MarketingWalletRequired(); // marketing wallet required when marketing fee is set

    // pair / platform tax wiring
    error PairAlreadySet();
    error InvalidPair();
    error NoPoolFound();
    error PlatformTaxAlreadyConfigured();
    error PairNotSet();
    error RewardBpsExceedsFeeBps(); // rewardBps + creatorRewardBps exceeds feeBps
    error RewardBpsRequiresDistributor();
    error CreatorRewardBpsRequiresDistributor();
    error CombinedTaxExceedsLimit(); // combined platform and creator tax exceeds 100%
    error PlatformTaxNotConfigured();
    error InvalidPriceFeed();
    error InvalidGraduationTarget(); // graduation target must be > 0
    error InvalidOracleStaleness(); // oracle staleness must be > 0
    error PriceFeedStillFresh(); // current price feed is still fresh, cannot be repointed

    // operational setters
    error InvalidWallet();
    error MarketingFeeNotActive(); // marketing fee is 0 on both buy and sell — no wallet to redirect
    error ThresholdOutOfBounds();
    error SlippageBelowFloor(); // slippage below 5% floor
    error SlippageAboveCeiling(); // slippage above 8% ceiling
    error InvalidAccount();

    // creator handoff / rescue
    error InvalidRecipient();
    error AmountExceedsRescuable();
    error RescueTransferFailed();

    // reflections
    error DividendCorrectionOverflow();
    error NothingToClaim();
    error EthClaimTransferFailed();
    error ReflectionTokenClaimTransferFailed();
    error MaxHoldersMustBePositive();

    // swap-and-process
    error MarketingTransferFailed();

    // Runs exactly once, on the implementation contract the factory clones
    // from. Never runs again on any clone.
    constructor() ERC20("", "") {
        _initialized = true;
    }

    receive() external payable {}

    function initialize(
        string memory name_,
        string memory symbol_,
        uint256 totalSupply_,
        address creator_,
        address mintTo_,
        address factory_,
        address router_,
        FeeSet memory buyFees_,
        FeeSet memory sellFees_,
        address reflectionAsset_,
        address marketingWallet_,
        bool curveManaged_
    ) external {
        if (_initialized) revert AlreadyInitialized();
        if (totalSupply_ == 0) revert SupplyMustBePositive();
        if (totalSupply_ > MAX_TOTAL_SUPPLY) revert SupplyTooLarge();
        if (creator_ == address(0)) revert InvalidCreator();
        if (mintTo_ == address(0)) revert InvalidMintRecipient();
        if (factory_ == address(0)) revert InvalidFactory();
        if (router_ == address(0)) revert InvalidRouter();
        if (reflectionAsset_ == address(this)) revert ReflectionAssetIsSelf();

        uint256 buyTotal = uint256(buyFees_.reflectionBps) + buyFees_.marketingBps + buyFees_.liquidityBps + buyFees_.burnBps;
        uint256 sellTotal = uint256(sellFees_.reflectionBps) + sellFees_.marketingBps + sellFees_.liquidityBps + sellFees_.burnBps;
        if (buyTotal > MAX_TOTAL_BPS) revert BuyTaxExceedsLimit();
        if (sellTotal > MAX_TOTAL_BPS) revert SellTaxExceedsLimit();
        if (buyFees_.marketingBps > 0 || sellFees_.marketingBps > 0) {
            if (marketingWallet_ == address(0)) revert MarketingWalletRequired();
        }

        _initialized = true;
        _tokenName = name_;
        _tokenSymbol = symbol_;
        creator = creator_;
        factory = factory_;
        router = router_;
        launchedAt = block.timestamp;
        buyFees = buyFees_;
        sellFees = sellFees_;
        reflectionAsset = reflectionAsset_;
        marketingWallet = marketingWallet_;
        curveManaged = curveManaged_; // Finding CT-2 fix -- see the state variable's own doc comment
        swapThreshold = totalSupply_ / 1000; // 0.1% default; see setSwapThreshold()
        processingSlippageBps = 600; // 6.00% default; see setProcessingSlippageBps()
        reflectionsEnabled = buyFees_.reflectionBps > 0 || sellFees_.reflectionBps > 0;

        _mint(mintTo_, totalSupply_); // "deploy + liquidity": mints to the factory, which pairs it into the pool. "deploy only": mints straight to the creator — see CustomTokenFactory.createCustomToken.

        emit TokenInitialized(name_, symbol_, totalSupply_, creator_);
    }

    /// @notice One-time wiring step, called by the factory immediately
    /// after it seeds this token's pool — mirrors
    /// LaunchedToken.configureTax's role for the simpler contract.
    function setPair(address pair_) external onlyFactory {
        if (pair != address(0)) revert PairAlreadySet();
        if (pair_ == address(0)) revert InvalidPair();
        pair = pair_;
        emit PairSet(pair_);
    }

    /// @notice The shared pool-detection-and-activation core used both by
    /// the fully automatic in-_update() path (see the top of _update()
    /// below) and by activateIndependentPair()'s manual "poke it right
    /// now" convenience below — both produce identical results, since
    /// both funnel through here.
    ///
    /// @dev Both call sites already guarantee `pair == address(0)` before
    /// calling this (see activateIndependentPair()'s own require and
    /// _update()'s `pair == address(0)` guard), so this trusts that
    /// precondition rather than re-checking it — and since
    /// configurePlatformTax() itself requires `pair != address(0)` before
    /// it can ever set platformTaxConfigured, that same precondition also
    /// guarantees platformTaxConfigured is still false here, so
    /// _maybeAutoConfigurePlatformTax() below is likewise called
    /// unconditionally. Does nothing (returns false) if no real pool is
    /// found yet. Otherwise derives the pair the same trustless way
    /// CustomTokenFactory itself does at launch (straight off the DEX
    /// factory's own getPair(token, WETH), so nobody can point `pair` at
    /// an arbitrary address), sets it, emits PairSet — AND, immediately
    /// after, attempts to also auto-configure the platform's own
    /// graduating tax. Before this change, a deploy-only CustomToken's
    /// platformTaxConfigured/platformTaxActive stayed false forever, by
    /// design; this reverses that — see the contract-level rationale
    /// above activateIndependentPair.
    ///
    /// The resulting pool is never LP-locked by this platform regardless
    /// of how it's found — that only ever happens inside the atomic
    /// addLiquidity=true path — so activating here doesn't create or
    /// imply any lock.
    ///
    /// @dev External purely so both call sites can wrap it in try/catch —
    /// same pattern as _computeMarketCapFromPair/_processLiquidity/
    /// _processMarketing/_processReflections elsewhere in this contract
    /// (Solidity's try/catch only guards external calls, never arbitrary
    /// internal logic). Not meant to be called by anything but this
    /// contract itself, hence the msg.sender check. This matters here
    /// specifically because _update() below calls this unconditionally on
    /// every transfer of a still-pool-less token, including the very
    /// first mint inside initialize() — router/factory are ordinarily
    /// real, correctly-implemented contracts, but if either one were ever
    /// misconfigured, temporarily misbehaving, or (as plenty of this
    /// file's own lower-level tests deliberately do) simply not a real
    /// router/factory at all, every external call below would revert;
    /// without try/catch that revert would propagate out of _update() and
    /// brick the mint/transfer that triggered it, instead of just leaving
    /// this detection attempt unable to run this time.
    ///
    /// The platform-tax half (after PairSet is emitted) pulls
    /// CustomTokenFactory's CURRENT tax defaults and self-configures,
    /// mirroring configurePlatformTax()'s own field-by-field assignment
    /// exactly — see LaunchedToken._maybeAutoActivateTax for the
    /// identical reasoning on the simpler token (no "snapshot at deploy
    /// time" exists for a deploy-only token, since none was ever taken;
    /// whatever the platform's config is at the moment the pool is first
    /// found is the only sensible value to use). This runs inside an
    /// arbitrary caller's ordinary transfer (or inside
    /// activateIndependentPair()'s manual call), so it must never revert
    /// over a platform-side misconfiguration: it replicates both of
    /// configurePlatformTax()'s own require() invariants defensively, but
    /// skips configuring instead of reverting if either would fail —
    /// `pair` still gets set either way, so the creator's own
    /// already-configured buy/sell tax, if any, still activates
    /// independently of whether the platform's portion could be safely
    /// added right now. Note this is a one-shot attempt bundled with pool
    /// detection: since `pair` is set unconditionally the moment a pool is
    /// found (whether or not the platform-tax half succeeds), and this
    /// whole function only ever runs while `pair == address(0)`, a
    /// platform-side fix made AFTER the pool was already found has no
    /// later transfer to retry against for that token — platformTaxConfigured
    /// stays permanently false for it. This mirrors configurePlatformTax()
    /// itself, which has always been a single onlyFactory, exactly-once
    /// call with no separate retry entry point either; it isn't a
    /// regression this change introduces. In practice this guard is
    /// unreachable through CustomTokenFactory's own real, live
    /// configuration anyway (its setTaxDefaults()/configurePlatformTax()
    /// already enforce both invariants at the platform level — this is
    /// defense in depth, not a path expected to ever actually trip).
    function _activatePoolIfFound() external returns (bool activated) {
        if (msg.sender != address(this)) revert InternalOnly();
        address dexFactory = IUniswapV2Router02(router).factory();
        address weth = IUniswapV2Router02(router).WETH();
        address detectedPair = IUniswapV2FactoryMinimal(dexFactory).getPair(address(this), weth);
        if (detectedPair == address(0)) return false;

        pair = detectedPair;
        emit PairSet(detectedPair);

        ITokenFactoryTaxDefaults tokenFactory = ITokenFactoryTaxDefaults(factory);
        uint256 feeBps_ = tokenFactory.feeBps();
        address rewardsDistributor_ = tokenFactory.rewardsDistributor();
        address creatorRewardsDistributor_ = tokenFactory.creatorRewardsDistributor();
        // Same "distributor unset -> bps forced to 0" defense
        // CustomTokenFactory._seedLiquidityAndBuyIn applies before calling
        // configurePlatformTax() — replicated here rather than trusting
        // the raw getters directly.
        uint256 rewardBps_ = rewardsDistributor_ != address(0) ? tokenFactory.rewardBps() : 0;
        uint256 creatorRewardBps_ = creatorRewardsDistributor_ != address(0) ? tokenFactory.creatorRewardBps() : 0;

        // Mirrors configurePlatformTax()'s own two requires —
        // rewardBps_ + creatorRewardBps_ <= feeBps_, and the platform's
        // feeBps_ plus this token's already-locked-in creator-side tax
        // (buyFees/sellFees, fixed back at initialize()) not summing past
        // 100% (else _update()'s `value - cuts.total` would underflow and
        // permanently brick every future transfer) — but skip, don't
        // revert, the calling transfer if either would fail.
        if (rewardBps_ + creatorRewardBps_ <= feeBps_ && feeBps_ + _maxCreatorFeeTotal() <= 10_000) {
            _applyPlatformTaxConfig(
                tokenFactory.platformFeeWallet(), feeBps_, tokenFactory.priceFeed(), tokenFactory.graduationTargetUsd(),
                tokenFactory.maxOracleStaleness(), rewardsDistributor_, rewardBps_, creatorRewardsDistributor_,
                creatorRewardBps_, tokenFactory.feeWalletDistributor()
            );
        }
        return true;
    }

    /// @notice Manual "poke it right now" convenience for a "deploy-only"
    /// CustomToken (created via CustomTokenFactory.createCustomToken with
    /// addLiquidity=false): if a creator (or anyone) has added liquidity
    /// for this token directly against the DEX, calling this activates it
    /// immediately instead of waiting for the next ordinary transfer to
    /// trigger the same detection automatically from _update() below —
    /// both paths funnel through the same _activatePoolIfFound() and so
    /// produce identical results.
    ///
    /// @dev Callable by ANYONE, not just the creator — a deliberate
    /// behavior change from this contract's earlier, creator-only
    /// version. The safety property that actually matters here is "a
    /// pool genuinely, verifiably exists on-chain" (still enforced below:
    /// the pair is derived trustlessly off the DEX factory, never taken
    /// as an argument), not who happens to call the function announcing
    /// that fact. Since the automatic in-_update() path is already fully
    /// permissionless by construction — any ordinary transfer, by
    /// anyone, can trigger the exact same activation — gating only this
    /// manual convenience version behind onlyCreator no longer served a
    /// real purpose and was merely inconsistent with the automatic path.
    function activateIndependentPair() external {
        if (pair != address(0)) revert PairAlreadySet();
        // Finding CT-2 fix: this manual convenience path funnels through
        // the exact same _activatePoolIfFound() as _update()'s automatic
        // detection, and is callable by literally anyone -- so leaving it
        // ungated here would let an attacker trigger the same rogue-pair
        // hijack on a curve-managed token directly, on demand, without
        // even waiting for an ordinary sell/transfer to trip the
        // _update() guard. See curveManaged's own doc comment for the
        // full writeup of the vulnerability this closes.
        if (curveManaged) revert NoPoolFound();
        bool activated = this._activatePoolIfFound();
        if (!activated) revert NoPoolFound();
    }

    /// @notice One-time wiring step, called by the factory immediately
    /// after setPair() — mirrors LaunchedToken.configureTax, but for a
    /// platform-level fee stream that sits entirely apart from the
    /// creator's own buyFees/sellFees above (it isn't counted against
    /// MAX_TOTAL_BPS, and it's skimmed in-kind rather than batched through
    /// the swap-and-process pipeline). Passing feeBps_ == 0 or a zero
    /// feeWallet_ records the settings but leaves the tax permanently
    /// inactive — e.g. for a deployment where the platform takes no cut.
    function configurePlatformTax(
        address feeWallet_,
        uint256 feeBps_,
        address priceFeed_,
        uint256 graduationTargetUsd_,
        uint256 maxOracleStaleness_,
        address rewardsDistributor_,
        uint256 rewardBps_,
        address creatorRewardsDistributor_,
        uint256 creatorRewardBps_,
        address feeWalletDistributor_
    ) external onlyFactory {
        if (platformTaxConfigured) revert PlatformTaxAlreadyConfigured();
        if (pair == address(0)) revert PairNotSet();
        if (rewardBps_ + creatorRewardBps_ > feeBps_) revert RewardBpsExceedsFeeBps();
        if (rewardsDistributor_ == address(0) && rewardBps_ != 0) revert RewardBpsRequiresDistributor();
        if (creatorRewardsDistributor_ == address(0) && creatorRewardBps_ != 0) {
            revert CreatorRewardBpsRequiresDistributor();
        }
        // Finding CT-3 fix (mirrors LaunchedToken Finding F-3/TF-2):
        // CustomTokenFactory.setTaxDefaults already requires
        // graduationTargetUsd_ > 0 and maxOracleStaleness_ > 0 before
        // either value can be set at the platform level, so under normal
        // operation this pair always arrives here already validated. But
        // nothing about this function's own signature enforces that --
        // _activatePoolIfFound()'s auto-configure path reads both values
        // fresh off the factory on every call, and a graduationTargetUsd
        // of 0 would make currentMarketCapInFeedDecimals()'s very first
        // observation "confirm" graduation immediately (permanently
        // disabling the platform's tax before it ever collected anything
        // meaningful), while a maxOracleStaleness of 0 would make every
        // price-feed read treat the feed as stale, permanently disabling
        // _maybeDisablePlatformTax()'s ability to ever graduate the token
        // at all. Bounding both here too costs nothing and removes the
        // dependency on the caller (whether the factory or a future
        // integration) always getting this right upstream.
        if (graduationTargetUsd_ == 0) revert InvalidGraduationTarget();
        if (maxOracleStaleness_ == 0) revert InvalidOracleStaleness();
        // Defends against the platform's own feeBps_ and this token's
        // already-locked-in creator-side tax (buyFees/sellFees, set back
        // at initialize()) summing past 100%. If they ever did,
        // _update()'s `value - totalCut` would underflow and revert on
        // every single taxed transfer of this token, permanently, since
        // neither side's fee rate can change after this point — see
        // Finding 3 of AUDIT-CustomToken.md. Not exploitable under any
        // config shipped today (platform defaults are far below this),
        // but this closes the combination off at configuration time
        // rather than relying on the platform owner never raising feeBps_
        // without checking.
        if (feeBps_ + _maxCreatorFeeTotal() > 10_000) revert CombinedTaxExceedsLimit();

        _applyPlatformTaxConfig(
            feeWallet_, feeBps_, priceFeed_, graduationTargetUsd_, maxOracleStaleness_,
            rewardsDistributor_, rewardBps_, creatorRewardsDistributor_, creatorRewardBps_, feeWalletDistributor_
        );
    }

    /// @dev The larger of buyFees'/sellFees' own combined bps totals —
    /// shared by configurePlatformTax()'s require and
    /// _maybeAutoConfigurePlatformTax()'s identical defensive check, so
    /// the computation exists exactly once in the compiled contract
    /// rather than twice.
    function _maxCreatorFeeTotal() private view returns (uint256) {
        uint256 buyTotal = uint256(buyFees.reflectionBps) + buyFees.marketingBps + buyFees.liquidityBps + buyFees.burnBps;
        uint256 sellTotal = uint256(sellFees.reflectionBps) + sellFees.marketingBps + sellFees.liquidityBps + sellFees.burnBps;
        return buyTotal > sellTotal ? buyTotal : sellTotal;
    }

    /// @dev The actual field-by-field write configurePlatformTax() and
    /// _maybeAutoConfigurePlatformTax() both need, factored out so it
    /// exists exactly once in the compiled contract rather than twice —
    /// callers are responsible for validating everything first (this
    /// performs no checks of its own).
    function _applyPlatformTaxConfig(
        address feeWallet_,
        uint256 feeBps_,
        address priceFeed_,
        uint256 graduationTargetUsd_,
        uint256 maxOracleStaleness_,
        address rewardsDistributor_,
        uint256 rewardBps_,
        address creatorRewardsDistributor_,
        uint256 creatorRewardBps_,
        address feeWalletDistributor_
    ) private {
        platformTaxConfigured = true;
        platformFeeWallet = feeWallet_;
        platformFeeBps = feeBps_;
        priceFeed = IAggregatorV3(priceFeed_);
        graduationTargetUsd = graduationTargetUsd_;
        maxOracleStaleness = maxOracleStaleness_;
        platformTaxActive = feeBps_ > 0 && feeWallet_ != address(0);
        rewardsDistributor = rewardsDistributor_;
        rewardBps = rewardBps_;
        creatorRewardsDistributor = creatorRewardsDistributor_;
        creatorRewardBps = creatorRewardBps_;
        feeWalletDistributor = feeWalletDistributor_;

        emit PlatformTaxConfigured(feeWallet_, feeBps_, graduationTargetUsd_);
    }

    /// @notice Escape hatch for a platform price feed that's gone
    /// permanently stale or was never a real, maintained feed to begin
    /// with — mirrors LaunchedToken.updatePriceFeed exactly. Callable only
    /// by the factory (which gates it behind its own owner — see
    /// CustomTokenFactory.updateTokenPriceFeed), never by the creator.
    /// Repoints only the oracle inputs the platform-tax graduation check
    /// reads; touches nothing about platformFeeBps, platformFeeWallet,
    /// pair, or platformTaxActive directly.
    /// See LaunchedToken.updatePriceFeed's own freshness guard for why this
    /// reverts if the current feed can still report a fresh price: without
    /// it, the owner could repoint a healthy, currently-live token's oracle
    /// inputs at any time for any reason.
    function updatePriceFeed(address newPriceFeed_, uint256 newMaxOracleStaleness_) external onlyFactory {
        if (!platformTaxConfigured) revert PlatformTaxNotConfigured();
        if (newPriceFeed_ == address(0)) revert InvalidPriceFeed();
        if (newMaxOracleStaleness_ == 0) revert InvalidOracleStaleness();
        (, bool feedIsFresh) = currentMarketCapInFeedDecimals();
        if (feedIsFresh) revert PriceFeedStillFresh();
        priceFeed = IAggregatorV3(newPriceFeed_);
        maxOracleStaleness = newMaxOracleStaleness_;
        emit PriceFeedUpdated(newPriceFeed_, newMaxOracleStaleness_);
    }

    function name() public view override returns (string memory) { return _tokenName; }
    function symbol() public view override returns (string memory) { return _tokenSymbol; }

    /// @notice The one piece of this token's fee configuration that can
    /// change after launch, exactly as requested — everyone can see a
    /// wallet change happen (event below), but nobody, including this
    /// contract's own code, can touch the tax rates themselves again.
    /// Only callable while the marketing fee is actually active (nonzero on
    /// buyFees or sellFees, locked in permanently at initialize()) — a
    /// token launched with marketingBps == 0 on both sides never routes
    /// anything to marketingWallet, so there's nothing meaningful to
    /// redirect. onlyCreator already means this becomes permanently
    /// uncallable the moment renounceCreator() is called (msg.sender can
    /// never equal address(0)), same as every other creator-gated setter
    /// here.
    function setMarketingWallet(address newWallet) external onlyCreator {
        if (newWallet == address(0)) revert InvalidWallet();
        if (buyFees.marketingBps == 0 && sellFees.marketingBps == 0) revert MarketingFeeNotActive();
        marketingWallet = newWallet;
        emit MarketingWalletUpdated(newWallet);
    }

    /// @notice Retune how much pending fee-tokens must build up before a
    /// sell/transfer triggers the next swap-and-process batch. Bounded so
    /// it can't be set so high it never fires (rewards/liquidity/marketing
    /// would just sit uncollected forever) — a purely operational knob,
    /// not a fee rate, so letting the creator tune it doesn't reopen the
    /// "rates are locked forever" guarantee above.
    function setSwapThreshold(uint256 newThreshold) external onlyCreator {
        if (newThreshold == 0 || newThreshold > totalSupply() / 20) revert ThresholdOutOfBounds();
        swapThreshold = newThreshold;
        emit SwapThresholdUpdated(newThreshold);
    }

    /// @notice Retune the protective slippage floor applied to every
    /// internal swap-and-process trade — see processingSlippageBps above.
    /// Bounded to the same 5.00%-8.00% band already used elsewhere in this
    /// codebase for the identical purpose.
    function setProcessingSlippageBps(uint256 newBps) external onlyCreator {
        if (newBps < MIN_PROCESSING_SLIPPAGE_BPS) revert SlippageBelowFloor();
        if (newBps > MAX_PROCESSING_SLIPPAGE_BPS) revert SlippageAboveCeiling();
        processingSlippageBps = uint16(newBps);
        emit ProcessingSlippageBpsUpdated(newBps);
    }

    /// @notice Step 1 of a two-step creator handoff — see pendingCreator
    /// above and Finding 5 of AUDIT-CustomToken.md. Does nothing to the
    /// live `creator` role until the proposed address calls
    /// acceptCreator() itself.
    function transferCreator(address newCreator) external onlyCreator {
        if (newCreator == address(0)) revert InvalidCreator();
        pendingCreator = newCreator;
        emit CreatorTransferStarted(creator, newCreator);
    }

    /// @notice Step 2: only the proposed address can complete the
    /// handoff, proving it controls that address before every
    /// onlyCreator-gated function (setMarketingWallet, setSwapThreshold,
    /// setRewardsBlocked, activateIndependentPair, setProcessingSlippageBps,
    /// rescueToken, rescueEth) starts listening to it instead of the old
    /// creator.
    function acceptCreator() external {
        if (msg.sender != pendingCreator) revert NotPendingCreator();
        address previousCreator = creator;
        creator = pendingCreator;
        pendingCreator = address(0);
        emit CreatorTransferred(previousCreator, creator);
    }

    /// @notice Permanently renounces the creator role — the standard
    /// "renounce ownership" assurance a token's own buyers can go verify
    /// on-chain. Sets `creator` (and any in-flight `pendingCreator`) to
    /// address(0) forever, with no recovery path by design. The instant
    /// this is called, every onlyCreator-gated function on this contract
    /// — setMarketingWallet, setSwapThreshold, setRewardsBlocked,
    /// activateIndependentPair, setProcessingSlippageBps, setTaxExempt,
    /// rescueToken, rescueEth, transferCreator — becomes permanently
    /// uncallable by anyone, including the address that just called this.
    /// Note what this does NOT touch: buyFees, sellFees, and
    /// platformFeeBps were never mutable in the first place (no function
    /// anywhere sets them after initialize()/configurePlatformTax()), so
    /// renouncing doesn't "lock in" the tax rate — it was already locked
    /// in at launch. What renouncing removes is every remaining
    /// *operational* lever, including the tax-exemption whitelist below.
    function renounceCreator() external onlyCreator {
        address previousCreator = creator;
        creator = address(0);
        pendingCreator = address(0);
        emit CreatorRenounced(previousCreator);
    }

    /// @notice Recovers ERC20 tokens sitting on this contract that aren't
    /// owed to anyone — e.g. dust left over from an imperfect-ratio
    /// addLiquidityETH call inside _processLiquidity, or a token sent
    /// here directly by mistake. See Finding 4 of AUDIT-CustomToken.md.
    /// Structurally cannot reach into anything this contract still owes:
    /// when `token` is this token itself, the rescuable amount excludes
    /// every pending fee stream (pendingLiquidityTokens/
    /// pendingMarketingTokens/pendingReflectionTokens); when `token` is
    /// reflectionAsset, it excludes every holder's still-unclaimed
    /// reflection entitlement (totalDividendsDistributed minus
    /// totalDividendsWithdrawn) — for any other token, the full balance
    /// is rescuable since this contract never intentionally holds one.
    function rescueToken(address token, address to, uint256 amount) external onlyCreator {
        if (to == address(0)) revert InvalidRecipient();
        uint256 balance = IERC20(token).balanceOf(address(this));
        uint256 reserved;
        if (token == address(this)) {
            reserved = pendingLiquidityTokens + pendingMarketingTokens + pendingReflectionTokens;
        }
        if (reflectionAsset != address(0) && token == reflectionAsset) {
            reserved += totalDividendsDistributed - totalDividendsWithdrawn;
        }
        uint256 rescuable = balance > reserved ? balance - reserved : 0;
        if (amount > rescuable) revert AmountExceedsRescuable();

        bool sent = IERC20(token).transfer(to, amount);
        if (!sent) revert RescueTransferFailed();
        emit TokenRescued(token, to, amount);
    }

    /// @notice Recovers stray native ETH sitting on this contract —
    /// direct donations to receive(), or dust left over from an
    /// imperfect-ratio addLiquidityETH call. Never touches ETH owed to
    /// holders: when reflectionAsset == address(0) (native-ETH
    /// reflections), the rescuable amount excludes every holder's
    /// still-unclaimed dividend balance the same way rescueToken does
    /// above.
    function rescueEth(address to, uint256 amount) external onlyCreator {
        if (to == address(0)) revert InvalidRecipient();
        uint256 reserved = reflectionAsset == address(0) ? (totalDividendsDistributed - totalDividendsWithdrawn) : 0;
        uint256 balance = address(this).balance;
        uint256 rescuable = balance > reserved ? balance - reserved : 0;
        if (amount > rescuable) revert AmountExceedsRescuable();

        (bool sent, ) = payable(to).call{value: amount}("");
        if (!sent) revert RescueTransferFailed();
        emit EthRescued(to, amount);
    }

    /// @notice Blocks (or unblocks) `account` from ever showing or
    /// accruing a reflection entitlement — see accumulativeDividendOf()
    /// and isBlockedFromRewards above. Only affects reflections: a blocked
    /// account can still hold, send, and receive the token normally, and
    /// still pays/receives the same transfer tax as anyone else.
    ///
    /// While blocked, every distribution that happens is simply never
    /// payable to this account — not deferred, not redirected to other
    /// holders (same "safe over maximal" tradeoff as the pair exclusion
    /// above; see the README for why). If later unblocked, the account's
    /// entitlement resumes from the same magnified-dividend-per-share
    /// bookkeeping every other holder uses, which was never paused while
    /// they were blocked — so anything distributed during the blocked
    /// window becomes claimable again once unblocked, exactly as if they'd
    /// simply not gotten around to claiming it yet. Treat blocking as
    /// meant to be permanent for an address you actually want to exclude;
    /// toggling it on and off is not a way to selectively skip specific
    /// distributions.
    function setRewardsBlocked(address account, bool blocked) external onlyCreator {
        if (account == address(0)) revert InvalidAccount();
        isBlockedFromRewards[account] = blocked;
        emit RewardsAccessUpdated(account, blocked);
    }

    /// @notice Whitelists (or un-whitelists) `account` to bypass ALL tax —
    /// both the creator's own buy/sell fee (reflection/marketing/
    /// liquidity/burn) and the platform's graduating tax — on any
    /// transfer where it's either side (see _update's `exempt` check).
    /// Does NOT touch buyFees/sellFees/platformFeeBps themselves, which
    /// stay exactly as fixed at launch — this only ever changes WHO pays
    /// the already-fixed rate, never the rate itself, so it can't be used
    /// to reintroduce the "creator jacks up the tax" rug this contract's
    /// immutable fee rates are built to prevent. Meant for addresses that
    /// legitimately shouldn't be taxed on their own token movements —
    /// e.g. the LiquidityLocker holding the locked LP, a vesting or
    /// airdrop-distribution contract, or a CEX deposit wallet the creator
    /// has arranged a listing with.
    function setTaxExempt(address account, bool exempt) external onlyCreator {
        if (account == address(0)) revert InvalidAccount();
        isTaxExempt[account] = exempt;
        emit TaxExemptionUpdated(account, exempt);
    }

    // ---------------------------------------------------------------
    // Transfer tax + reflection bookkeeping
    // ---------------------------------------------------------------

    /// @dev Buy = from the pair; sell = to the pair; anything else
    /// (including every leg of our own swap-and-process batch, guarded by
    /// _inSwap) is untaxed, same convention LaunchedToken already uses.
    function _update(address from, address to, uint256 value) internal override {
        // Auto-detect an independently-created pool before anything else
        // below runs — see _activatePoolIfFound()/
        // _maybeAutoConfigurePlatformTax(). Skipped once `pair` is set
        // (the common case after the first pool-detecting transfer, or
        // for the entire life of an addLiquidity=true token, which starts
        // out with `pair` already set) and skipped whenever
        // `from == factory`: that's specifically CustomTokenFactory's own
        // internal liquidity-seeding transfer inside its atomic
        // addLiquidity=true flow (see
        // CustomTokenFactory._seedLiquidityAndBuyIn/
        // _relayedSeedLiquidityAndBuyIn, both of which mint the full
        // supply to `address(this)` and then transfer it into the
        // freshly-created pair via addLiquidityETH, strictly BEFORE
        // calling setPair()/configurePlatformTax() themselves). Without
        // this guard, that same internal transfer would race ahead and
        // set `pair` here first, and the factory's own explicit
        // setPair() call right after would then revert on
        // `require(pair == address(0))`, permanently breaking every
        // atomic launch. A deploy-only token's creator can never trip
        // this guard by accident: the factory never holds any of a
        // deploy-only token's supply (100% mints straight to the
        // creator), so `from` can never equal `factory` for that token's
        // own, later, independent liquidity add.
        //
        // Deliberate, disclosed gas tradeoff, same as LaunchedToken's
        // identical mechanism: until a pool is found, EVERY transfer of
        // an otherwise-untaxed deploy-only token pays the extra gas of
        // this detection attempt. Wrapped in try/catch (see
        // _activatePoolIfFound's own doc comment for why) so a
        // misbehaving/incomplete router or factory can never brick this
        // transfer — it just leaves `pair` unset for now, retried on a
        // later one.
        bool justActivated = false;
        if (pair == address(0) && !curveManaged && from != factory) {
            try this._activatePoolIfFound() returns (bool activated) {
                justActivated = activated;
            } catch {
                justActivated = false;
            }
        }

        if (_inSwap || from == address(0) || value == 0) {
            super._update(from, to, value);
            _afterBalanceChange(from, to, value);
            return;
        }

        // `justActivated` forces this exact transfer down the untaxed
        // passthrough branch below even though `to` now equals the pair
        // that was just set moments ago in this same call — by neither
        // the creator's own buy/sell fee nor the platform's cut. Mirrors
        // the existing, always-untaxed factory-seeded liquidity transfer
        // (there, `pair`/platform tax are wired strictly after
        // addLiquidityETH returns). Taxation begins with the next
        // transfer that touches the pool, not this one.
        bool isBuy = !justActivated && pair != address(0) && from == pair;
        bool isSell = !justActivated && pair != address(0) && to == pair;

        if (!isBuy && !isSell) {
            super._update(from, to, value);
            _afterBalanceChange(from, to, value);
            _maybeSwapAndProcess();
            return;
        }

        // Tax-exemption whitelist (see setTaxExempt above): bypasses BOTH
        // the creator's own fee and the platform's cut for this specific
        // transfer, but every other side effect of a buy/sell still runs
        // exactly as normal — the pending-fee batch can still be
        // triggered by an exempt seller (it's about the token's overall
        // backlog, not this trade), and the graduation check still runs
        // (it's about market cap, not this trade's tax). Only the fee
        // computation itself is skipped.
        if (isTaxExempt[from] || isTaxExempt[to]) {
            super._update(from, to, value);
            _afterBalanceChange(from, to, value);
            if (isSell) _maybeSwapAndProcess();
            if (platformTaxActive) _maybeDisablePlatformTax();
            return;
        }

        FeeSet memory fees = isBuy ? buyFees : sellFees;
        TransferCuts memory cuts;
        cuts.reflection = (value * fees.reflectionBps) / 10_000;
        cuts.marketing = (value * fees.marketingBps) / 10_000;
        cuts.liquidity = (value * fees.liquidityBps) / 10_000;
        cuts.burn = (value * fees.burnBps) / 10_000;
        // Platform cut is independent of the creator's own fee config above
        // (not part of `fees`/MAX_TOTAL_BPS) — same flat rate on both buy
        // and sell, exactly like LaunchedToken's tax.
        cuts.platform = platformTaxActive ? (value * platformFeeBps) / 10_000 : 0;
        cuts.total = cuts.reflection + cuts.marketing + cuts.liquidity + cuts.burn + cuts.platform;

        cuts.toContract = cuts.reflection + cuts.marketing + cuts.liquidity;
        if (cuts.toContract > 0) {
            super._update(from, address(this), cuts.toContract);
            _afterBalanceChange(from, address(this), cuts.toContract);
            pendingReflectionTokens += cuts.reflection;
            pendingMarketingTokens += cuts.marketing;
            pendingLiquidityTokens += cuts.liquidity;
        }
        if (cuts.burn > 0) {
            super._update(from, address(0), cuts.burn); // true burn — totalSupply actually decreases
            _afterBalanceChange(from, address(0), cuts.burn);
            emit TokensBurned(cuts.burn);
        }
        if (cuts.platform > 0) {
            // rewardCut and creatorCut are both carved OUT OF cuts.platform,
            // never added on top of it — the platform's total cut on this
            // transfer stays exactly platformFeeBps. Neither touches
            // cuts.reflection/marketing/liquidity/burn above, which are the
            // creator's own separately-capped fee config and have nothing
            // to do with this feature. rewardBps + creatorRewardBps <=
            // platformFeeBps is enforced once, at configurePlatformTax(),
            // so this can never underflow.
            uint256 rewardCut = (rewardsDistributor != address(0) && rewardBps > 0) ? (value * rewardBps) / 10_000 : 0;
            uint256 creatorCut = (creatorRewardsDistributor != address(0) && creatorRewardBps > 0) ? (value * creatorRewardBps) / 10_000 : 0;
            uint256 toFeeWallet = cuts.platform - rewardCut - creatorCut;
            if (rewardCut > 0) {
                // In-kind, straight to the rewards contract — no swap, same
                // as the rest of the platform tax.
                super._update(from, rewardsDistributor, rewardCut);
                _afterBalanceChange(from, rewardsDistributor, rewardCut);
            }
            if (creatorCut > 0) {
                super._update(from, creatorRewardsDistributor, creatorCut);
                _afterBalanceChange(from, creatorRewardsDistributor, creatorCut);
            }
            if (toFeeWallet > 0) {
                // Routes to FeeWalletDistributor in-kind when set, for later
                // automatic ETH conversion (see FeeWalletDistributor.sol);
                // otherwise falls straight to platformFeeWallet exactly as
                // before this feature existed.
                address toFeeWalletRecipient = feeWalletDistributor != address(0) ? feeWalletDistributor : platformFeeWallet;
                super._update(from, toFeeWalletRecipient, toFeeWallet);
                _afterBalanceChange(from, toFeeWalletRecipient, toFeeWallet);
            }
        }
        super._update(from, to, value - cuts.total);
        _afterBalanceChange(from, to, value - cuts.total);

        // Never trigger a swap mid-buy (avoids selling against the pool's
        // reserves while a buy against those same reserves is still being
        // priced) — only a sell or an ordinary transfer can kick it off.
        if (isSell) _maybeSwapAndProcess();
        // The graduation check, by contrast, runs after either a buy or a
        // sell — same as LaunchedToken, which checks after any transfer
        // that touches the pool.
        if (platformTaxActive) _maybeDisablePlatformTax();
    }

    // ---------------------------------------------------------------
    // Burn: a true burn, callable directly by any holder at any time — on
    // top of (and completely independent from) the tax-triggered burnBps
    // component above. A voluntary burn's `to` is address(0), which is
    // never `pair`, so it takes the plain untaxed path through _update()
    // above (the `!isBuy && !isSell` branch) exactly like an ordinary
    // wallet-to-wallet transfer — no tax is ever skimmed off a holder
    // choosing to destroy their own tokens. "True burn" means totalSupply
    // actually decreases (OpenZeppelin's ERC20._burn, routed through the
    // same _update() override every other transfer uses), same as the
    // existing tax burn already does — not a transfer to a dead address.
    // ---------------------------------------------------------------

    /// @notice Permanently destroys `amount` of the caller's own tokens.
    function burn(uint256 amount) external {
        _burn(msg.sender, amount);
        emit TokensBurned(amount);
    }

    /// @notice Same as burn(), but spends `account`'s allowance to the
    /// caller first — standard OpenZeppelin ERC20Burnable behavior, so a
    /// third-party contract a holder has approved can burn on their behalf
    /// without ever taking custody of the tokens first.
    function burnFrom(address account, uint256 amount) external {
        _spendAllowance(account, msg.sender, amount);
        _burn(account, amount);
        emit TokensBurned(amount);
    }

    function _afterBalanceChange(address from, address to, uint256 value) private {
        if (value == 0) return;

        if (magnifiedDividendPerShare != 0) {
            int256 magCorrection = _toInt256Safe(magnifiedDividendPerShare * value);
            if (from != address(0)) _magnifiedDividendCorrections[from] += magCorrection;
            if (to != address(0)) _magnifiedDividendCorrections[to] -= magCorrection;
        }

        // Holder-registry maintenance for pushReflections() — independent
        // of the dividend-correction block above (it must keep running
        // even before any distribution has ever happened, i.e. while
        // magnifiedDividendPerShare is still 0) and skipped entirely for a
        // token that never turned reflections on.
        if (reflectionsEnabled) {
            if (from != address(0) && balanceOf(from) == 0) _removeReflectionHolder(from);
            if (to != address(0) && balanceOf(to) > 0) _addReflectionHolder(to);
        }
    }

    function _addReflectionHolder(address account) private {
        if (_reflectionHolderIndex[account] != 0) return;
        _reflectionHolders.push(account);
        _reflectionHolderIndex[account] = _reflectionHolders.length;
    }

    function _removeReflectionHolder(address account) private {
        uint256 idx = _reflectionHolderIndex[account];
        if (idx == 0) return;
        uint256 lastIndex = _reflectionHolders.length;
        if (idx != lastIndex) {
            address lastAccount = _reflectionHolders[lastIndex - 1];
            _reflectionHolders[idx - 1] = lastAccount;
            _reflectionHolderIndex[lastAccount] = idx;
        }
        _reflectionHolders.pop();
        delete _reflectionHolderIndex[account];
    }

    function reflectionHolderCount() external view returns (uint256) {
        return _reflectionHolders.length;
    }

    function reflectionHolderAt(uint256 index) external view returns (address) {
        return _reflectionHolders[index];
    }

    function _toInt256Safe(uint256 a) private pure returns (int256) {
        if (a > uint256(type(int256).max)) revert DividendCorrectionOverflow();
        return int256(a);
    }

    // ---------------------------------------------------------------
    // Reflections: view + claim
    // ---------------------------------------------------------------

    function accumulativeDividendOf(address account) public view returns (uint256) {
        // The pair (and the token contract itself) never has a real "holder"
        // entitled to reflections — its balance is pool liquidity, not a
        // position — and a creator-blocked address (see
        // isBlockedFromRewards/setRewardsBlocked above) is excluded the
        // same way. Block both here so withdrawableDividendOf() and
        // claimReflections() both automatically inherit the exclusion,
        // without touching the correction bookkeeping that every other
        // (real, unblocked) holder relies on for correct accounting.
        if (account == pair || account == address(this) || isBlockedFromRewards[account]) return 0;
        int256 total = int256(magnifiedDividendPerShare * balanceOf(account)) + _magnifiedDividendCorrections[account];
        if (total < 0) return 0; // defensive only — correct bookkeeping never produces a negative total
        return uint256(total) / MAGNITUDE;
    }

    function withdrawableDividendOf(address account) public view returns (uint256) {
        uint256 total = accumulativeDividendOf(account);
        uint256 withdrawn = withdrawnDividends[account];
        // Guards against underflow for an account that had already claimed
        // before being blocked (accumulativeDividendOf forces `total` to 0
        // the moment they're blocked, which would otherwise be less than
        // their pre-existing withdrawnDividends) — correctly reads as
        // "nothing withdrawable" rather than reverting.
        return total > withdrawn ? total - withdrawn : 0;
    }

    /// @notice Pull your accumulated share of whatever's been distributed so
    /// far (native ETH, or reflectionAsset if one was set) straight to your
    /// wallet right now, rather than waiting for pushReflections() below to
    /// sweep around to you. Both paths read and write the exact same
    /// accounting (withdrawableDividendOf / withdrawnDividends), so there is
    /// no way to be paid twice for one distribution regardless of which
    /// path — or both, at different times — a given holder ends up using.
    /// nonReentrant alongside pushReflections(), sharing the same guard: see
    /// pushReflections' own comment for exactly what that closes off.
    function claimReflections() external nonReentrant returns (uint256 amount) {
        amount = withdrawableDividendOf(msg.sender);
        if (amount == 0) revert NothingToClaim();
        withdrawnDividends[msg.sender] += amount;
        totalDividendsWithdrawn += amount;

        if (reflectionAsset == address(0)) {
            (bool sent, ) = payable(msg.sender).call{value: amount}("");
            if (!sent) revert EthClaimTransferFailed();
        } else {
            bool sent = IERC20(reflectionAsset).transfer(msg.sender, amount);
            if (!sent) revert ReflectionTokenClaimTransferFailed();
        }
        emit DividendWithdrawn(msg.sender, amount);
    }

    /// @notice Permissionlessly pushes a batch of holders' currently
    /// withdrawable reflection share directly to their wallets — the
    /// "holders don't have to do anything" counterpart to claimReflections()
    /// above. Anyone can call this (the creator, an off-chain keeper on a
    /// schedule, this platform's own front end, a curious holder) — it
    /// takes no special permission because it can only ever pay people
    /// exactly what they're already owed, to their own recorded address,
    /// never anywhere else.
    ///
    /// Gas-bounded by maxHolders, walking the holder registry starting from
    /// reflectionPushCursor and wrapping back to the start once it reaches
    /// the end, so repeated calls keep covering fresh holders rather than
    /// always restarting at index 0. This function's own gas cost depends
    /// only on maxHolders, never on the total holder count — the same
    /// anti-griefing shape as PlatformRewardsDistributor.processAirdropBatch,
    /// and exactly why this is a standalone call rather than something
    /// triggered automatically inside a transfer: looping over an
    /// unbounded holder list inside `_update` is exactly the failure mode
    /// this design avoids (see the reflections NatSpec at the top of this
    /// file).
    ///
    /// address(this) and `pair` are always skipped, whether or not they
    /// happen to appear in the registry (see its own comment for why they
    /// can end up there) — paying either would either pay the contract's
    /// own temporarily-held, not-yet-swapped fee balance to itself, or
    /// donate real funds to the AMM pool, which is a real, irreversible
    /// loss (recoverable by anyone via a plain skim() call), not a
    /// bookkeeping quirk.
    ///
    /// A single holder's payment failing — a smart-contract wallet that
    /// reverts on receiving ETH, or one that's simply out of gas at that
    /// moment — never blocks the rest of the batch and never costs that
    /// holder their entitlement: this function only marks a holder's
    /// dividend withdrawn AFTER their transfer actually succeeds, so a
    /// failed push leaves their balance exactly as claimable as it was
    /// before, fully available via claimReflections() whenever they like.
    /// Sending is capped at PUSH_GAS_STIPEND gas specifically so one
    /// holder's receive()/fallback can't consume the batch caller's entire
    /// remaining gas — plenty for a plain wallet or a simple forwarding
    /// contract, but bounded rather than open-ended.
    ///
    /// nonReentrant is required, not just defense in depth, given the
    /// send-then-record ordering above: it's what stops a malicious
    /// holder's receive() from calling back into this function or
    /// claimReflections() and being paid twice for the same distribution
    /// before this call gets to record it as withdrawn. Both functions
    /// share one OpenZeppelin ReentrancyGuard status, so the guard blocks
    /// cross-function reentrancy between them, not only self-recursion.

    function pushReflections(uint256 maxHolders) external nonReentrant returns (uint256 holdersPaid, uint256 totalPaid) {
        if (maxHolders == 0) revert MaxHoldersMustBePositive();
        uint256 cursor = reflectionPushCursor;

        // Re-reads `_reflectionHolders.length` on every iteration (a single
        // warm SLOAD) rather than caching it once before the loop. The ETH
        // send below is an arbitrary external call to `holder` — gas-capped
        // at PUSH_GAS_STIPEND specifically so a hostile receive() can't
        // complete a further token transfer of its own (confirmed by a
        // dedicated test: within that stipend, a nested transfer that would
        // shrink this registry via swap-and-pop reliably runs out of gas
        // and reverts harmlessly before it can mutate anything) — but this
        // loop no longer *depends* on that margin for safety. A stale
        // `total` combined with a swap-and-pop that shrank the array mid-loop
        // would otherwise let `_reflectionHolders[cursor]` read out of
        // bounds and panic-revert the entire batch; re-checking the current
        // length here removes that possibility even if PUSH_GAS_STIPEND, the
        // registry-mutation cost, or the EVM's own gas schedule ever change.
        uint256 steps = maxHolders;
        for (uint256 visited = 0; visited < steps; visited++) {
            uint256 total = _reflectionHolders.length;
            if (total == 0) break;
            if (cursor >= total) cursor = 0;

            address holder = _reflectionHolders[cursor];
            cursor = cursor + 1 == total ? 0 : cursor + 1;

            if (holder == address(this) || holder == pair || isBlockedFromRewards[holder]) continue;
            uint256 amount = withdrawableDividendOf(holder);
            if (amount == 0) continue;

            bool sent;
            if (reflectionAsset == address(0)) {
                (sent, ) = payable(holder).call{value: amount, gas: PUSH_GAS_STIPEND}("");
            } else {
                // A standard ERC20 transfer() never invokes recipient code
                // the way a native ETH send can, so this branch doesn't
                // carry the same griefing/reentrancy exposure — but it's
                // still wrapped defensively in case reflectionAsset turns
                // out to be a nonstandard token whose transfer() reverts
                // instead of returning false.
                try IERC20(reflectionAsset).transfer(holder, amount) returns (bool ok) {
                    sent = ok;
                } catch {
                    sent = false;
                }
            }

            if (sent) {
                withdrawnDividends[holder] += amount;
                totalDividendsWithdrawn += amount;
                holdersPaid++;
                totalPaid += amount;
                emit DividendWithdrawn(holder, amount);
            }
            // A failed send leaves this holder's entitlement completely
            // untouched — not marked withdrawn, not lost — so
            // claimReflections() will report exactly the same amount as
            // still due if they come claim it themselves.
        }

        reflectionPushCursor = cursor;
        emit ReflectionsPushed(holdersPaid, totalPaid, cursor);
    }

    function _distributeDividends(uint256 amount) private {
        if (amount == 0 || totalSupply() == 0) return;
        magnifiedDividendPerShare += (amount * MAGNITUDE) / totalSupply();
        totalDividendsDistributed += amount;
        emit DividendsDistributed(amount);
    }

    // ---------------------------------------------------------------
    // Platform tax: graduation check (identical approach to LaunchedToken)
    // ---------------------------------------------------------------

    /// @notice Current market cap in the price feed's own decimals (e.g. 8
    /// for a typical Chainlink USD feed), or (0, false) if there's no pool
    /// yet, the feed can't be read, or its data is stale beyond
    /// maxOracleStaleness. A stale/broken feed never blocks trading — it
    /// only means the tax-disable check can't run until the feed recovers.
    ///
    /// The pool-reads-and-arithmetic half of this (everything past the
    /// oracle call) is delegated to _computeMarketCapFromPair() through an
    /// external self-call specifically so it can sit behind its own
    /// try/catch — see LaunchedToken.currentMarketCapInFeedDecimals for why
    /// this matters: without it, a revert from a misbehaving pair or from
    /// arithmetic overflow would propagate out and revert the entire
    /// transfer instead of just leaving this check unable to run.
    function currentMarketCapInFeedDecimals() public view returns (uint256 marketCap, bool feedIsFresh) {
        if (pair == address(0)) return (0, false);
        try priceFeed.latestRoundData() returns (uint80, int256 answer, uint256, uint256 updatedAt, uint80) {
            if (answer <= 0) return (0, false);
            // See LaunchedToken.currentMarketCapInFeedDecimals for why this
            // guards against updatedAt > block.timestamp explicitly: a
            // try/catch only catches a revert from the external call
            // itself, not from this line, so an unguarded underflow here
            // (a future-dated oracle round) would revert every future
            // taxed transfer instead of just skipping this check.
            if (updatedAt > block.timestamp || block.timestamp - updatedAt > maxOracleStaleness) return (0, false);

            try this._computeMarketCapFromPair(uint256(answer)) returns (uint256 mc, bool ok) {
                if (!ok) return (0, false);
                return (mc, true);
            } catch {
                return (0, false);
            }
        } catch {
            return (0, false);
        }
    }

    /// @dev External purely so currentMarketCapInFeedDecimals() can wrap it
    /// in try/catch — see LaunchedToken._computeMarketCapFromPair, which
    /// this mirrors exactly. Not meant to be called by anything but this
    /// contract itself.
    function _computeMarketCapFromPair(uint256 ethUsd) external view returns (uint256 marketCap, bool ok) {
        if (msg.sender != address(this)) revert InternalOnly();
        (uint112 reserve0, uint112 reserve1, ) = IUniswapV2PairMinimal(pair).getReserves();
        address token0 = IUniswapV2PairMinimal(pair).token0();
        uint256 tokenReserve = token0 == address(this) ? uint256(reserve0) : uint256(reserve1);
        uint256 ethReserve = token0 == address(this) ? uint256(reserve1) : uint256(reserve0);
        if (tokenReserve == 0) return (0, false);

        uint256 pricePerTokenWei = (ethReserve * 1e18) / tokenReserve;
        uint256 usdPerToken = (pricePerTokenWei * ethUsd) / 1e18;
        marketCap = (usdPerToken * totalSupply()) / 1e18;
        ok = true;
    }

    /// @notice Mirrors LaunchedToken._maybeDisableTax exactly — see that
    /// contract's comment for the full reasoning on why graduation now
    /// requires two separate observations at least
    /// GRADUATION_CONFIRMATION_WINDOW apart, rather than disabling the tax
    /// off one instantaneous spot-price read.
    function _maybeDisablePlatformTax() internal {
        if (!platformTaxActive) return;
        (uint256 marketCap, bool feedIsFresh) = currentMarketCapInFeedDecimals();
        if (!feedIsFresh) return; // oracle hiccup: leave any in-progress candidacy exactly as it was

        // Finding CT-1 (mirrors LaunchedToken Finding F-1): priceFeed.decimals()
        // is an external call just like latestRoundData() above, and every
        // other price-feed call in this function's own call chain
        // (latestRoundData() itself, and the _computeMarketCapFromPair self-call)
        // is already wrapped in try/catch specifically so a misbehaving feed
        // can never brick a taxed transfer. This one line was the sole
        // exception: if decimals() ever reverted on a feed that still answers
        // latestRoundData() successfully, that revert would propagate out of
        // _maybeDisablePlatformTax() and out of _update(), permanently
        // reverting every single taxed buy/sell of this token — not just
        // blocking graduation, but bricking ordinary trading entirely, with no
        // admin override anywhere in this contract. Guarding it closes that
        // gap and keeps this function consistent with its own stated
        // defensive philosophy.
        uint8 feedDecimals;
        try priceFeed.decimals() returns (uint8 d) {
            feedDecimals = d;
        } catch {
            return;
        }
        uint256 targetInFeedDecimals = graduationTargetUsd * (10 ** feedDecimals);
        if (marketCap < targetInFeedDecimals) {
            if (graduationCandidateAt != 0) {
                graduationCandidateAt = 0;
                emit GraduationCandidateReset();
            }
            return;
        }

        if (graduationCandidateAt == 0) {
            graduationCandidateAt = block.timestamp;
            emit GraduationCandidateObserved(marketCap, block.timestamp + GRADUATION_CONFIRMATION_WINDOW);
            return;
        }

        if (block.timestamp < graduationCandidateAt + GRADUATION_CONFIRMATION_WINDOW) {
            return; // still within the confirmation window; needs a later transfer to confirm
        }

        platformTaxActive = false;
        emit PlatformTaxDisabled(marketCap);
    }

    // ---------------------------------------------------------------
    // Swap-and-process: turns collected in-kind fees into their real
    // outcomes (auto-liquidity, marketing ETH, reflection payouts)
    // ---------------------------------------------------------------

    function _maybeSwapAndProcess() private {
        if (_inSwap || pair == address(0)) return;
        uint256 pending = pendingLiquidityTokens + pendingMarketingTokens + pendingReflectionTokens;
        if (pending < swapThreshold) return;
        _swapAndProcess();
    }

    /// @dev Each of the three _process* steps below is called through an
    /// external self-call wrapped in its own try/catch — the same pattern
    /// _computeMarketCapFromPair already uses for the graduation math (try/
    /// catch only wraps external calls, never arbitrary internal logic).
    /// Before this fix, a revert in any one step — a marketingWallet that
    /// rejects ETH, a reflectionAsset pool that's been drained, an
    /// addLiquidityETH call that reverts for an ordinary router-level
    /// reason — propagated straight out of _swapAndProcess and reverted
    /// the entire outer transfer that happened to trigger this batch.
    /// Since this runs on every sell/plain-transfer once pending fees
    /// cross swapThreshold, that meant one broken step could permanently
    /// brick all trading and transfers for the token, with no admin
    /// override anywhere in the contract. See Finding 1 of
    /// AUDIT-CustomToken.md. A failed step's tokens are added straight
    /// back to the relevant pending counter — nothing is silently
    /// forfeited, it just waits for whatever was broken to get fixed
    /// (e.g. via setMarketingWallet()) and gets retried on a later batch.
    function _swapAndProcess() private lockTheSwap {
        uint256 liquidityTokens = pendingLiquidityTokens;
        uint256 marketingTokens = pendingMarketingTokens;
        uint256 reflectionTokens = pendingReflectionTokens;
        pendingLiquidityTokens = 0;
        pendingMarketingTokens = 0;
        pendingReflectionTokens = 0;

        if (liquidityTokens > 0) {
            try this._processLiquidity(liquidityTokens) {
                // succeeded — nothing left to do
            } catch {
                pendingLiquidityTokens += liquidityTokens;
            }
        }
        if (marketingTokens > 0 && marketingWallet != address(0)) {
            try this._processMarketing(marketingTokens) {
            } catch {
                pendingMarketingTokens += marketingTokens;
            }
        }
        if (reflectionTokens > 0) {
            try this._processReflections(reflectionTokens) {
            } catch {
                pendingReflectionTokens += reflectionTokens;
            }
        }
    }

    /// @dev Half swapped for ETH, the other half paired with that ETH as
    /// fresh liquidity — the resulting LP tokens go straight to a burn
    /// address, so this stream of liquidity can never be withdrawn by
    /// anyone, ever, including the creator. External purely so
    /// _swapAndProcess can wrap it in try/catch — see that function's own
    /// comment; not meant to be called by anything but this contract
    /// itself.
    function _processLiquidity(uint256 amount) external {
        if (msg.sender != address(this)) revert InternalOnly();
        uint256 half = amount / 2;
        uint256 otherHalf = amount - half;
        if (half == 0 || otherHalf == 0) return;

        uint256 ethBefore = address(this).balance;
        _swapTokensForEth(half);
        uint256 ethForLiquidity = address(this).balance - ethBefore;
        if (ethForLiquidity == 0) return;

        _approve(address(this), router, otherHalf);
        (, , uint256 lpAmount) = IUniswapV2Router02(router).addLiquidityETH{value: ethForLiquidity}(
            address(this),
            otherHalf,
            _applySlippage(otherHalf),
            _applySlippage(ethForLiquidity),
            BURN_ADDRESS,
            block.timestamp + 15 minutes
        );
        emit LiquidityAutoAdded(otherHalf, ethForLiquidity, lpAmount);
    }

    /// @dev External purely so _swapAndProcess can wrap it in try/catch —
    /// see that function's own comment; not meant to be called by
    /// anything but this contract itself.
    function _processMarketing(uint256 amount) external {
        if (msg.sender != address(this)) revert InternalOnly();
        uint256 ethBefore = address(this).balance;
        _swapTokensForEth(amount);
        uint256 ethOut = address(this).balance - ethBefore;
        if (ethOut == 0) return;
        (bool sent, ) = payable(marketingWallet).call{value: ethOut}("");
        if (!sent) revert MarketingTransferFailed();
        emit MarketingFeeSent(ethOut);
    }

    /// @dev External purely so _swapAndProcess can wrap it in try/catch —
    /// see that function's own comment; not meant to be called by
    /// anything but this contract itself.
    function _processReflections(uint256 amount) external {
        if (msg.sender != address(this)) revert InternalOnly();
        if (reflectionAsset == address(0)) {
            uint256 ethBefore = address(this).balance;
            _swapTokensForEth(amount);
            uint256 ethOut = address(this).balance - ethBefore;
            _distributeDividends(ethOut);
        } else {
            uint256 balBefore = IERC20(reflectionAsset).balanceOf(address(this));
            _swapTokensForToken(amount, reflectionAsset);
            uint256 received = IERC20(reflectionAsset).balanceOf(address(this)) - balBefore;
            _distributeDividends(received);
        }
    }

    /// @dev Standard Uniswap V2 constant-product quote (0.30% swap fee
    /// baked into the 997/1000 constants) — used only to derive a
    /// protective slippage floor below, never to execute anything, same
    /// convention as TokenFactory/CustomTokenFactory's identical helper.
    function _getAmountOut(uint256 amountIn, uint256 reserveIn, uint256 reserveOut) private pure returns (uint256) {
        uint256 amountInWithFee = amountIn * 997;
        uint256 numerator = amountInWithFee * reserveOut;
        uint256 denominator = reserveIn * 1000 + amountInWithFee;
        return numerator / denominator;
    }

    /// @dev Quotes amountIn's expected output in tokenOut off the
    /// relevant pool's own live reserves — the token/WETH leg always
    /// reads `pair` directly (already known, no lookup needed); any other
    /// leg (e.g. WETH/reflectionAsset) is looked up off the DEX factory.
    /// Returns 0 if no pool exists yet or either reserve is empty, which
    /// callers treat as "can't protect this trade" rather than blocking
    /// it — a missing quote must never be able to revert or brick a
    /// transfer (see Finding 1's reasoning, which this is deliberately
    /// consistent with).
    function _quoteOut(uint256 amountIn, address tokenIn, address tokenOut) private view returns (uint256) {
        address pairAddr;
        if (tokenIn == address(this) || tokenOut == address(this)) {
            pairAddr = pair;
        } else {
            address dexFactory = IUniswapV2Router02(router).factory();
            pairAddr = IUniswapV2FactoryMinimal(dexFactory).getPair(tokenIn, tokenOut);
        }
        if (pairAddr == address(0)) return 0;

        (uint112 reserve0, uint112 reserve1, ) = IUniswapV2PairMinimal(pairAddr).getReserves();
        address token0 = IUniswapV2PairMinimal(pairAddr).token0();
        uint256 reserveIn = token0 == tokenIn ? uint256(reserve0) : uint256(reserve1);
        uint256 reserveOut = token0 == tokenIn ? uint256(reserve1) : uint256(reserve0);
        if (reserveIn == 0 || reserveOut == 0) return 0;

        return _getAmountOut(amountIn, reserveIn, reserveOut);
    }

    /// @dev floor = amount minus processingSlippageBps of it.
    function _applySlippage(uint256 amount) private view returns (uint256) {
        return amount - (amount * processingSlippageBps) / 10_000;
    }

    function _swapTokensForEth(uint256 amount) private {
        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = IUniswapV2Router02(router).WETH();
        uint256 quoted = _quoteOut(amount, path[0], path[1]);
        uint256 minOut = quoted > 0 ? _applySlippage(quoted) : 0;
        _approve(address(this), router, amount);
        IUniswapV2Router02(router).swapExactTokensForETHSupportingFeeOnTransferTokens(
            amount, minOut, path, address(this), block.timestamp + 15 minutes
        );
    }

    function _swapTokensForToken(uint256 amount, address outputToken) private {
        address weth = IUniswapV2Router02(router).WETH();
        address[] memory path = new address[](3);
        path[0] = address(this);
        path[1] = weth;
        path[2] = outputToken;

        // Two-hop quote: estimate the WETH leg first, then use that
        // estimate as the input to quote the second leg — an
        // approximation (the real swap's first leg may land slightly
        // differently), but one that only ever sets a protective floor,
        // never the trade itself, same as every other quote helper in
        // this codebase.
        uint256 wethQuoted = _quoteOut(amount, path[0], path[1]);
        uint256 minOut = 0;
        if (wethQuoted > 0) {
            uint256 finalQuoted = _quoteOut(wethQuoted, path[1], path[2]);
            if (finalQuoted > 0) minOut = _applySlippage(finalQuoted);
        }

        _approve(address(this), router, amount);
        IUniswapV2Router02(router).swapExactTokensForTokensSupportingFeeOnTransferTokens(
            amount, minOut, path, address(this), block.timestamp + 15 minutes
        );
    }
}

contracts/CustomTokenFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/proxy/Clones.sol";
import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

import "./CustomToken.sol";
import "./LiquidityLocker.sol";
import "./interfaces/IUniswapV2Router02.sol";

/// @title CustomTokenFactory
/// @notice The entry point for the "advanced" launch path: creates a
/// CustomToken (EIP-1167 clone, same approach as TokenFactory/LaunchedToken)
/// with whatever fee configuration the creator chose — 0% tax is just the
/// all-zero case of the same contract — and seeds it with liquidity in the
/// same transaction, since none of a CustomToken's fee machinery (buy/sell
/// detection, auto-liquidity, reflections) means anything without a live
/// pool to trade against.
///
/// Deliberately a separate contract from TokenFactory rather than a third
/// mode bolted onto it — CustomToken is a meaningfully larger, more
/// complex contract (reflections, auto-liquidity, auto-burn) than
/// LaunchedToken, and keeping it fully separate means none of this touches
/// the already-audited-by-tests TokenFactory/LaunchedToken/LiquidityLocker
/// path at all. This factory uses its own LiquidityLocker instance (a
/// second deployment of the same, unmodified locker contract) rather than
/// sharing TokenFactory's, since a LiquidityLocker only ever accepts
/// lock() calls from the one factory address it was wired to.
///
/// The initial liquidity a creator provides at launch is locked to them
/// (same anti-rug protection as the main launch flow) — it's only the
/// *ongoing* auto-liquidity generated by the liquidity fee, after launch,
/// that gets burned outright (see CustomToken._processLiquidity).
contract CustomTokenFactory is Ownable2Step, ReentrancyGuard {
    address public immutable tokenImplementation;
    IUniswapV2Router02 public immutable router;
    LiquidityLocker public immutable locker;

    uint256 public deployFee; // "Deploy Custom Tax Token" — create + verify only, no liquidity, no tax of any kind
    uint256 public launchFee; // "Deploy and Add Liquidity (Live)" — atomic creation + pool + creator tax + platform tax
    address public feeTreasury;
    uint256 public lpLockDuration;

    // ---- platform-level graduating tax defaults, applied to every
    // CustomToken created after a change (existing tokens keep whatever
    // they were configured with — see CustomToken.configurePlatformTax).
    // This is entirely separate from, and on top of, whatever buy/sell tax
    // the creator themselves configured — same "platform always takes its
    // 1.00% until graduation" behavior TokenFactory already has for its
    // simpler token, now available here too. ----
    /// @notice See TokenFactory.MAX_FEE_BPS — identical hard ceiling on
    /// feeBps_ in setTaxDefaults here, for the same reasoning.
    uint256 public constant MAX_FEE_BPS = 2_000; // 20.00%

    address public platformFeeWallet;
    uint256 public feeBps = 100; // 1.00%
    address public priceFeed;
    uint256 public graduationTargetUsd = 50_000; // whole dollars; tax permanently disables once a pool's live market cap crosses this
    uint256 public maxOracleStaleness = 1 hours;

    /// @notice PlatformRewardsDistributor's address — see
    /// TokenFactory.rewardsDistributor for the full explanation; behaves
    /// identically here. address(0) (the default) disables the feature
    /// entirely: deployFee/launchFee stay 100% feeTreasury, and every
    /// CustomToken launched from here on gets no reward diversion at all.
    address public rewardsDistributor;

    /// @notice Out of feeBps (the platform's own graduating tax on a
    /// CustomToken — entirely separate from the creator's own buyFees/
    /// sellFees), how much (absolute bps) gets diverted to
    /// rewardsDistributor instead of platformFeeWallet. See
    /// TokenFactory.rewardBps for the full explanation, including why this
    /// now defaults to 0 (PlatformRewardsDistributor is one-time,
    /// launch-fee-only by design — see that comment for the full
    /// reasoning); behaves identically here.
    uint256 public rewardBps = 0;

    /// @notice CreatorRewardsDistributor's address — see
    /// TokenFactory.creatorRewardsDistributor for the full explanation;
    /// behaves identically here.
    address public creatorRewardsDistributor;

    /// @notice Out of feeBps, how much (absolute bps) gets diverted to
    /// creatorRewardsDistributor instead of platformFeeWallet — carved OUT
    /// OF feeBps, never added on top of it, and never overlapping
    /// rewardBps above. See TokenFactory.creatorRewardBps for the full
    /// explanation; behaves identically here.
    uint256 public creatorRewardBps = 10; // 0.10%

    /// @notice FeeWalletDistributor's address — see
    /// TokenFactory.feeWalletDistributor for the full explanation; behaves
    /// identically here. address(0) (the default) disables it entirely, and
    /// the platform-fee remainder goes straight to platformFeeWallet exactly
    /// as it always has.
    address public feeWalletDistributor;

    /// @notice Anti-rug ceiling on a creator's own same-transaction buy-in,
    /// in bps of totalSupply_ — identical safeguard to TokenFactory's
    /// maxCreatorBuyBps, checked against the actual net tokens received
    /// (post buy-tax), not an estimate.
    uint256 public maxCreatorBuyBps = 500; // 5.00% by default

    /// @notice Slippage tolerance applied to addLiquidityETH()'s own
    /// amountTokenMin/amountETHMin — identical safeguard to TokenFactory's
    /// liquiditySlippageBps, protecting the initial liquidity seed against
    /// a bot manipulating the pair's reserves between submission and
    /// confirmation. The whole launch (liquidity add included) reverts if
    /// the actual amounts land outside this band. Owner-adjustable within a
    /// fixed 5.00%–8.00% band (see setLiquiditySlippageBps).
    uint256 public liquiditySlippageBps = 600; // 6.00% default, i.e. the midpoint of the allowed band
    uint256 public constant MIN_LIQUIDITY_SLIPPAGE_BPS = 500; // 5.00%
    uint256 public constant MAX_LIQUIDITY_SLIPPAGE_BPS = 800; // 8.00%

    /// @dev floor = amount minus liquiditySlippageBps of it.
    function _minWithSlippage(uint256 amount) private view returns (uint256) {
        return amount - (amount * liquiditySlippageBps) / 10_000;
    }

    /// @notice Same protection as liquiditySlippageBps, applied to the
    /// creator's own same-transaction buy-in instead of the liquidity add —
    /// see TokenFactory.buyInSlippageBps for the full reasoning, identical
    /// here. Owner-adjustable within the same fixed 5.00%–8.00% band.
    uint256 public buyInSlippageBps = 600; // 6.00% default, i.e. the midpoint of the allowed band

    /// @dev Standard Uniswap V2 constant-product quote — see
    /// TokenFactory._getAmountOut for the full reasoning, identical here.
    function _getAmountOut(uint256 amountIn, uint256 reserveIn, uint256 reserveOut) private pure returns (uint256) {
        uint256 amountInWithFee = amountIn * 997;
        uint256 numerator = amountInWithFee * reserveOut;
        uint256 denominator = reserveIn * 1000 + amountInWithFee;
        return numerator / denominator;
    }

    /// @dev Computes the buy-in's protective floor from the pool's own
    /// just-added reserves, netting out the tax this exact trade will pay
    /// FIRST (the creator's own configured buyFees, already recorded on
    /// `token` by initialize(), plus the platform's own tax if it ended up
    /// active — both read straight off the token's own getters rather than
    /// recomputed here, so this can never drift from what _update() will
    /// actually deduct), then applying buyInSlippageBps — returns whichever
    /// is stricter, that floor or the caller's own minCreatorTokensOut.
    function _effectiveMinBuyOut(
        address token,
        uint256 creatorBuyEthAmount,
        uint256 ethReserve,
        uint256 tokenReserve,
        uint256 callerMinOut
    ) private view returns (uint256) {
        (uint16 rBps, uint16 mBps, uint16 lBps, uint16 bBps) = CustomToken(payable(token)).buyFees();
        uint256 buyTaxBps = uint256(rBps) + mBps + lBps + bBps;
        if (CustomToken(payable(token)).platformTaxActive()) {
            buyTaxBps += CustomToken(payable(token)).platformFeeBps();
        }
        uint256 grossOut = _getAmountOut(creatorBuyEthAmount, ethReserve, tokenReserve);
        uint256 expectedNetOut = grossOut - (grossOut * buyTaxBps) / 10_000;
        uint256 floor = expectedNetOut - (expectedNetOut * buyInSlippageBps) / 10_000;
        return callerMinOut > floor ? callerMinOut : floor;
    }

    mapping(address => address) public creatorOf;
    mapping(address => address) public pairOf;
    address[] private _tokenList;
    mapping(address => address[]) private _tokensByCreator;

    // ---- gasless relayed launches — see TokenFactory's identical section
    // for the full explanation of the deposit/relay/settle flow and why
    // deposits are keyed by (depositor address, voucher hash). Duplicated
    // here rather than shared via a base contract, same reasoning as the
    // rest of this file's deliberate separation from TokenFactory. ----

    address public relayer;
    uint256 public maxRelayerGasReimbursementWei;
    uint256 public constant RELAY_GAS_OVERHEAD = 60_000;

    struct Deposit {
        uint256 amount;
        uint256 deadline;
        bool settled;
        bool reclaimed;
    }
    mapping(address => mapping(bytes32 => Deposit)) public deposits;

    struct CustomLaunchVoucher {
        address creator;
        string name;
        string symbol;
        uint256 totalSupply;
        bool addLiquidity;
        uint256 liquidityEthAmount;
        CustomToken.FeeSet buyFees;
        CustomToken.FeeSet sellFees;
        address reflectionAsset;
        address marketingWallet;
        uint256 creatorBuyEthAmount;
        uint256 minCreatorTokensOut;
        uint256 fee; // deployFee or launchFee the creator locked in and escrowed at deposit time
        // Doubles as the CREATE2 salt relayedCreateCustomToken deploys the
        // clone with (see Clones.cloneDeterministic there) — see
        // TokenFactory.LaunchVoucher.salt for the full explanation, applies
        // identically here.
        uint256 salt;
        uint256 deadline;
    }

    bytes32 private constant FEE_SET_TYPEHASH =
        keccak256("FeeSet(uint16 reflectionBps,uint16 marketingBps,uint16 liquidityBps,uint16 burnBps)");

    bytes32 private constant CUSTOM_LAUNCH_VOUCHER_TYPEHASH = keccak256(
        "CustomLaunchVoucher(address creator,string name,string symbol,uint256 totalSupply,bool addLiquidity,uint256 liquidityEthAmount,FeeSet buyFees,FeeSet sellFees,address reflectionAsset,address marketingWallet,uint256 creatorBuyEthAmount,uint256 minCreatorTokensOut,uint256 fee,uint256 salt,uint256 deadline)FeeSet(uint16 reflectionBps,uint16 marketingBps,uint16 liquidityBps,uint16 burnBps)"
    );

    // Hand-rolled EIP-712 domain separator — see TokenFactory for why this
    // avoids OpenZeppelin's EIP712 base (mcopy/Cancun dependency).
    bytes32 private constant EIP712_DOMAIN_TYPEHASH = keccak256(
        "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
    );
    bytes32 private immutable _domainSeparator;

    event RelayerUpdated(address newRelayer);
    event MaxRelayerGasReimbursementUpdated(uint256 newCapWei);
    event LaunchDeposited(bytes32 indexed voucherHash, address indexed creator, uint256 amount, uint256 deadline);
    event DepositReclaimed(bytes32 indexed voucherHash, address indexed creator, uint256 amount);
    event RelayedFeeSettled(
        bytes32 indexed voucherHash,
        address indexed token,
        uint256 feeCollected,
        uint256 gasReimbursed,
        uint256 toTreasury,
        uint256 toRewards
    );

    modifier onlyRelayer() {
        require(msg.sender == relayer, "CustomTokenFactory: caller is not the relayer");
        _;
    }

    event CustomTokenCreated(
        address indexed token,
        address indexed creator,
        string name,
        string symbol,
        uint256 totalSupply,
        address pair,
        address reflectionAsset,
        address marketingWallet
    );
    event InitialLiquidityLocked(address indexed token, uint256 lpAmount, uint256 unlockTime, uint256 indexed lockId);
    event CreatorBought(address indexed token, address indexed creator, uint256 ethIn, uint256 tokensOut);
    event DeployFeeUpdated(uint256 newFee);
    event LaunchFeeUpdated(uint256 newFee);
    event FeeTreasuryUpdated(address newTreasury);
    event LpLockDurationUpdated(uint256 newDuration);
    event MaxCreatorBuyBpsUpdated(uint256 newBps);
    event LiquiditySlippageBpsUpdated(uint256 newBps);
    event BuyInSlippageBpsUpdated(uint256 newBps);
    event TaxDefaultsUpdated();
    event RewardsDistributorUpdated(address newDistributor);
    event CreatorRewardsDistributorUpdated(address newDistributor);
    event FeeWalletDistributorUpdated(address newDistributor);
    event TokenPriceFeedUpdated(address indexed token, address newPriceFeed, uint256 newMaxOracleStaleness);

    constructor(
        address tokenImplementation_,
        address router_,
        address locker_,
        uint256 deployFee_,
        uint256 launchFee_,
        address feeTreasury_,
        uint256 lpLockDuration_,
        address platformFeeWallet_,
        address priceFeed_
    ) Ownable(msg.sender) {
        require(tokenImplementation_ != address(0), "CustomTokenFactory: invalid implementation");
        require(router_ != address(0), "CustomTokenFactory: invalid router");
        require(locker_ != address(0), "CustomTokenFactory: invalid locker");
        require(feeTreasury_ != address(0), "CustomTokenFactory: invalid treasury");

        tokenImplementation = tokenImplementation_;
        router = IUniswapV2Router02(router_);
        locker = LiquidityLocker(locker_);
        deployFee = deployFee_;
        launchFee = launchFee_;
        feeTreasury = feeTreasury_;
        lpLockDuration = lpLockDuration_;
        platformFeeWallet = platformFeeWallet_;
        priceFeed = priceFeed_;

        _domainSeparator = keccak256(
            abi.encode(
                EIP712_DOMAIN_TYPEHASH,
                keccak256(bytes("HoodLaunchCustomTokenFactory")),
                keccak256(bytes("1")),
                block.chainid,
                address(this)
            )
        );
    }

    function _hashTypedDataV4(bytes32 structHash) private view returns (bytes32) {
        return keccak256(abi.encodePacked("\x19\x01", _domainSeparator, structHash));
    }

    function _hashFeeSet(CustomToken.FeeSet calldata f) private pure returns (bytes32) {
        return keccak256(abi.encode(FEE_SET_TYPEHASH, f.reflectionBps, f.marketingBps, f.liquidityBps, f.burnBps));
    }

    /// @notice Computes the exact EIP-712 digest a creator must sign to
    /// authorize a relayed CustomToken launch. See TokenFactory.
    /// hashLaunchVoucher for the full explanation.
    function hashCustomLaunchVoucher(CustomLaunchVoucher calldata voucher) public view returns (bytes32) {
        bytes32 structHash = keccak256(
            abi.encode(
                CUSTOM_LAUNCH_VOUCHER_TYPEHASH,
                voucher.creator,
                keccak256(bytes(voucher.name)),
                keccak256(bytes(voucher.symbol)),
                voucher.totalSupply,
                voucher.addLiquidity,
                voucher.liquidityEthAmount,
                _hashFeeSet(voucher.buyFees),
                _hashFeeSet(voucher.sellFees),
                voucher.reflectionAsset,
                voucher.marketingWallet,
                voucher.creatorBuyEthAmount,
                voucher.minCreatorTokensOut,
                voucher.fee,
                voucher.salt,
                voucher.deadline
            )
        );
        return _hashTypedDataV4(structHash);
    }

    /// @notice Step 2 of a relayed launch — see TokenFactory.
    /// depositForRelayedLaunch for the full explanation; behaves
    /// identically here.
    function depositForRelayedLaunch(bytes32 voucherHash, uint256 deadline) external payable nonReentrant {
        require(msg.value > 0, "CustomTokenFactory: no ETH sent");
        require(deadline > block.timestamp, "CustomTokenFactory: deadline already passed");
        Deposit storage d = deposits[msg.sender][voucherHash];
        require(d.amount == 0, "CustomTokenFactory: voucher already funded");
        d.amount = msg.value;
        d.deadline = deadline;
        emit LaunchDeposited(voucherHash, msg.sender, msg.value, deadline);
    }

    /// @notice See TokenFactory.reclaimDeposit.
    function reclaimDeposit(bytes32 voucherHash) external nonReentrant {
        Deposit storage d = deposits[msg.sender][voucherHash];
        require(d.amount > 0, "CustomTokenFactory: no such deposit");
        require(!d.settled, "CustomTokenFactory: voucher already relayed");
        require(!d.reclaimed, "CustomTokenFactory: already reclaimed");
        require(block.timestamp > d.deadline, "CustomTokenFactory: deadline has not passed yet");
        d.reclaimed = true;
        uint256 amount = d.amount;
        (bool sent, ) = payable(msg.sender).call{value: amount}("");
        require(sent, "CustomTokenFactory: refund transfer failed");
        emit DepositReclaimed(voucherHash, msg.sender, amount);
    }

    /// @notice Step 3 of a relayed launch, called only by the trusted
    /// relayer — see TokenFactory.relayedCreateToken for the full
    /// explanation of the verification, deploy, and gas-then-split
    /// settlement steps. Mirrors createCustomToken()'s two modes with
    /// voucher.creator standing in everywhere createCustomToken() used
    /// msg.sender.
    function relayedCreateCustomToken(
        CustomLaunchVoucher calldata voucher,
        bytes calldata signature
    )
        external
        onlyRelayer
        nonReentrant
        returns (address token, address pair, uint256 lpAmount, uint256 lockId, uint256 creatorTokensBought)
    {
        uint256 gasStart = gasleft();

        require(block.timestamp <= voucher.deadline, "CustomTokenFactory: voucher expired");
        require(bytes(voucher.name).length > 0, "CustomTokenFactory: name required");
        require(bytes(voucher.symbol).length > 0, "CustomTokenFactory: symbol required");
        require(voucher.totalSupply > 0, "CustomTokenFactory: supply must be > 0");

        bytes32 voucherHash = hashCustomLaunchVoucher(voucher);
        address signer = ECDSA.recover(voucherHash, signature);
        require(signer == voucher.creator, "CustomTokenFactory: signature does not match voucher creator");

        Deposit storage d = deposits[voucher.creator][voucherHash];
        require(d.amount > 0, "CustomTokenFactory: no matching deposit");
        require(!d.settled, "CustomTokenFactory: voucher already relayed");
        require(!d.reclaimed, "CustomTokenFactory: deposit already reclaimed");
        require(block.timestamp <= d.deadline, "CustomTokenFactory: deposit expired, creator must reclaim");

        uint256 expectedDeposit = voucher.fee +
            (voucher.addLiquidity ? voucher.liquidityEthAmount + voucher.creatorBuyEthAmount : 0);
        require(d.amount == expectedDeposit, "CustomTokenFactory: deposit does not match voucher amount");

        d.settled = true; // effects before interactions

        token = Clones.cloneDeterministic(tokenImplementation, _deriveTokenSalt(voucher.creator, voucher.salt));

        if (!voucher.addLiquidity) {
            require(
                voucher.liquidityEthAmount == 0 && voucher.creatorBuyEthAmount == 0,
                "CustomTokenFactory: no liquidity/buy-in in deploy-only mode"
            );
            CustomToken(payable(token)).initialize(
                voucher.name,
                voucher.symbol,
                voucher.totalSupply,
                voucher.creator,
                voucher.creator,
                address(this),
                address(router),
                voucher.buyFees,
                voucher.sellFees,
                voucher.reflectionAsset,
                voucher.marketingWallet,
                false // curveManaged_ -- Finding CT-2 fix: this token is launched directly by CustomTokenFactory, not cloned by CustomBondingCurveFactory
            );
        } else {
            require(voucher.liquidityEthAmount > 0, "CustomTokenFactory: no ETH sent for liquidity");
            CustomToken(payable(token)).initialize(
                voucher.name,
                voucher.symbol,
                voucher.totalSupply,
                voucher.creator,
                address(this),
                address(this),
                address(router),
                voucher.buyFees,
                voucher.sellFees,
                voucher.reflectionAsset,
                voucher.marketingWallet,
                false // curveManaged_ -- Finding CT-2 fix: see the other call site's comment above
            );

            (pair, lpAmount, lockId, creatorTokensBought) = _relayedSeedLiquidityAndBuyIn(
                token,
                voucher.creator,
                voucher.totalSupply,
                voucher.liquidityEthAmount,
                voucher.creatorBuyEthAmount,
                voucher.minCreatorTokensOut
            );
            pairOf[token] = pair;
        }

        creatorOf[token] = voucher.creator;
        _tokensByCreator[voucher.creator].push(token);
        _tokenList.push(token);

        emit CustomTokenCreated(
            token, voucher.creator, voucher.name, voucher.symbol, voucher.totalSupply, pair, voucher.reflectionAsset, voucher.marketingWallet
        );

        _settleRelayedFee(voucherHash, token, voucher.fee, gasStart);
    }

    /// @dev Relayed counterpart to _seedLiquidityAndBuyIn — identical
    /// behavior, parameterized on an explicit `creator_` everywhere the
    /// original used msg.sender.
    function _relayedSeedLiquidityAndBuyIn(
        address token,
        address creator_,
        uint256 totalSupply_,
        uint256 liquidityEthAmount,
        uint256 creatorBuyEthAmount,
        uint256 minCreatorTokensOut
    ) internal returns (address pair, uint256 lpAmount, uint256 lockId, uint256 creatorTokensBought) {
        IERC20(token).approve(address(router), totalSupply_);
        (uint256 amountTokenUsed, uint256 amountETHUsed, uint256 lpAmountAdded) = router.addLiquidityETH{value: liquidityEthAmount}(
            token,
            totalSupply_,
            _minWithSlippage(totalSupply_),
            _minWithSlippage(liquidityEthAmount),
            address(locker),
            block.timestamp + 15 minutes
        );
        lpAmount = lpAmountAdded;

        pair = IUniswapV2FactoryMinimal(router.factory()).getPair(token, router.WETH());
        require(pair != address(0), "CustomTokenFactory: pair not found after addLiquidityETH");
        CustomToken(payable(token)).setPair(pair);

        uint256 effectiveRewardBps = rewardsDistributor != address(0) ? rewardBps : 0;
        uint256 effectiveCreatorRewardBps = creatorRewardsDistributor != address(0) ? creatorRewardBps : 0;
        CustomToken(payable(token)).configurePlatformTax(
            platformFeeWallet, feeBps, priceFeed, graduationTargetUsd, maxOracleStaleness,
            rewardsDistributor, effectiveRewardBps, creatorRewardsDistributor, effectiveCreatorRewardBps,
            feeWalletDistributor
        );

        uint256 unlockTime = block.timestamp + lpLockDuration;
        lockId = locker.lock(pair, creator_, lpAmount, unlockTime);
        emit InitialLiquidityLocked(token, lpAmount, unlockTime, lockId);

        if (creatorBuyEthAmount > 0) {
            address[] memory path = new address[](2);
            path[0] = router.WETH();
            path[1] = token;
            uint256 effectiveMinOut = _effectiveMinBuyOut(token, creatorBuyEthAmount, amountETHUsed, amountTokenUsed, minCreatorTokensOut);
            uint256 balBefore = IERC20(token).balanceOf(creator_);
            router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: creatorBuyEthAmount}(
                effectiveMinOut,
                path,
                creator_,
                block.timestamp + 15 minutes
            );
            creatorTokensBought = IERC20(token).balanceOf(creator_) - balBefore;
            require(
                creatorTokensBought <= (totalSupply_ * maxCreatorBuyBps) / 10_000,
                "CustomTokenFactory: creator buy-in exceeds max allowed share of supply"
            );
            emit CreatorBought(token, creator_, creatorBuyEthAmount, creatorTokensBought);
        }
    }

    /// @dev Gas-then-split settlement for a relayed launch — see
    /// TokenFactory._settleRelayedFee for the full explanation.
    function _settleRelayedFee(bytes32 voucherHash, address token, uint256 feeCollected, uint256 gasStart) internal {
        if (feeCollected == 0) return;

        uint256 gasUsed = (gasStart - gasleft()) + RELAY_GAS_OVERHEAD;
        uint256 gasReimbursement = gasUsed * tx.gasprice;
        if (maxRelayerGasReimbursementWei > 0 && gasReimbursement > maxRelayerGasReimbursementWei) {
            gasReimbursement = maxRelayerGasReimbursementWei;
        }
        if (gasReimbursement > feeCollected) {
            gasReimbursement = feeCollected;
        }

        if (gasReimbursement > 0) {
            (bool sentGas, ) = payable(relayer).call{value: gasReimbursement}("");
            require(sentGas, "CustomTokenFactory: relayer gas reimbursement failed");
        }

        uint256 netFee = feeCollected - gasReimbursement;
        uint256 toRewards;
        uint256 toTreasury;
        if (netFee > 0) {
            if (rewardsDistributor != address(0)) {
                toRewards = netFee / 2;
                toTreasury = netFee - toRewards;
                if (toRewards > 0) {
                    (bool sentRewards, ) = rewardsDistributor.call{value: toRewards}("");
                    require(sentRewards, "CustomTokenFactory: rewards transfer failed");
                }
                (bool sent, ) = feeTreasury.call{value: toTreasury}("");
                require(sent, "CustomTokenFactory: fee transfer failed");
            } else {
                toTreasury = netFee;
                (bool sent, ) = feeTreasury.call{value: netFee}("");
                require(sent, "CustomTokenFactory: fee transfer failed");
            }
        }

        emit RelayedFeeSettled(voucherHash, token, feeCollected, gasReimbursement, toTreasury, toRewards);
    }

    /// @notice Deploy a new CustomToken and seed its pool, atomically.
    /// msg.value must equal deployFee + liquidityEthAmount +
    /// creatorBuyEthAmount exactly. buyFees_/sellFees_ are each capped at
    /// 5% total (see CustomToken.MAX_TOTAL_BPS) — passing all-zero fees is
    /// exactly how you get a 0%-tax token through this same path.
    /// reflectionAsset_ == address(0) means reflections pay out in native
    /// ETH; any other address is the ERC20 they pay out in instead.
    /// marketingWallet_ is required only if either side's marketingBps is
    /// nonzero. creatorBuyEthAmount is optional (0 skips it entirely) — an
    /// ordinary swap against the pool just created, in this same
    /// transaction, guaranteed to be its first trade, but capped at
    /// maxCreatorBuyBps of totalSupply_ (checked against what actually
    /// lands net of buy tax) as an anti-rug safeguard: exceeding it reverts
    /// the whole launch rather than partially executing.
    /// @param salt Caller-chosen CREATE2 salt input for the clone's address
    /// — see the matching parameter doc on TokenFactory.createToken for the
    /// full explanation; applies identically here (predictTokenAddress
    /// below previews the resulting address, and the actual salt used is
    /// derived from (msg.sender, salt) via _deriveTokenSalt so it's bound
    /// to the caller and can't be front-run — see TokenFactory's own
    /// _deriveTokenSalt for the reasoning).
    function createCustomToken(
        string calldata name_,
        string calldata symbol_,
        uint256 totalSupply_,
        bool addLiquidity,
        uint256 liquidityEthAmount,
        CustomToken.FeeSet calldata buyFees_,
        CustomToken.FeeSet calldata sellFees_,
        address reflectionAsset_,
        address marketingWallet_,
        uint256 creatorBuyEthAmount,
        uint256 minCreatorTokensOut,
        uint256 salt
    ) external payable nonReentrant returns (address token, address pair, uint256 lpAmount, uint256 lockId, uint256 creatorTokensBought) {
        require(bytes(name_).length > 0, "CustomTokenFactory: name required");
        require(bytes(symbol_).length > 0, "CustomTokenFactory: symbol required");
        require(totalSupply_ > 0, "CustomTokenFactory: supply must be > 0");

        token = Clones.cloneDeterministic(tokenImplementation, _deriveTokenSalt(msg.sender, salt));
        uint256 feeCollected;

        if (!addLiquidity) {
            // "Deploy Custom Tax Token": create + verify only, no pool ever
            // gets seeded — pair stays address(0) forever, so neither the
            // creator's own configured tax nor the platform's graduating
            // tax can ever activate (both gate on _update() seeing a
            // nonzero pair). Whatever buyFees_/sellFees_ the creator chose
            // are recorded on-chain for transparency, but are inert unless
            // this token is later paired manually — entirely the creator's
            // own responsibility from here, same as TokenFactory's plain
            // "Deploy Token" mode.
            require(msg.value == deployFee, "CustomTokenFactory: incorrect ETH sent for Deploy Custom Tax Token");
            require(liquidityEthAmount == 0 && creatorBuyEthAmount == 0, "CustomTokenFactory: no liquidity/buy-in in deploy-only mode");
            feeCollected = deployFee;
            CustomToken(payable(token)).initialize(
                name_,
                symbol_,
                totalSupply_,
                msg.sender,
                msg.sender,
                address(this),
                address(router),
                buyFees_,
                sellFees_,
                reflectionAsset_,
                marketingWallet_,
                false // curveManaged_ -- Finding CT-2 fix: this token is launched directly by CustomTokenFactory, not cloned by CustomBondingCurveFactory
            );
        } else {
            // "Deploy and Add Liquidity (Live)": the only path where either
            // the creator's own tax or the platform's 1.00%-until-
            // graduation tax can ever apply — both require a live pair,
            // which only this branch creates.
            require(msg.value >= launchFee, "CustomTokenFactory: launch fee not met");
            require(
                msg.value - launchFee == liquidityEthAmount + creatorBuyEthAmount,
                "CustomTokenFactory: msg.value doesn't match fee + liquidity + buy-in"
            );
            require(liquidityEthAmount > 0, "CustomTokenFactory: no ETH sent for liquidity");
            feeCollected = launchFee;
            CustomToken(payable(token)).initialize(
                name_,
                symbol_,
                totalSupply_,
                msg.sender,
                address(this),
                address(this),
                address(router),
                buyFees_,
                sellFees_,
                reflectionAsset_,
                marketingWallet_,
                false // curveManaged_ -- Finding CT-2 fix: see the other call site's comment above
            );

            (pair, lpAmount, lockId, creatorTokensBought) = _seedLiquidityAndBuyIn(
                token,
                totalSupply_,
                liquidityEthAmount,
                creatorBuyEthAmount,
                minCreatorTokensOut
            );
            pairOf[token] = pair;
        }

        // Effects before interactions: every piece of this factory's own
        // state for `token` is finalized before the external fee-transfer
        // call below, so a reentrant call during it (e.g. a malicious or
        // buggy feeTreasury) can never observe this launch half-recorded.
        creatorOf[token] = msg.sender;
        _tokensByCreator[msg.sender].push(token);
        _tokenList.push(token);

        if (feeCollected > 0) {
            // 50% of every deployFee/launchFee stays platform profit exactly
            // as before; the other 50% funds the platform's own buyback/
            // burn/holder-rewards contract, once one is configured — see
            // TokenFactory._finalizeLaunch for the identical logic on the
            // simpler token path. While rewardsDistributor is unset, this
            // is 100% feeTreasury, byte-for-byte the same behavior this
            // contract has always had.
            if (rewardsDistributor != address(0)) {
                uint256 toRewards = feeCollected / 2;
                uint256 toTreasury = feeCollected - toRewards;
                if (toRewards > 0) {
                    (bool sentRewards, ) = rewardsDistributor.call{value: toRewards}("");
                    require(sentRewards, "CustomTokenFactory: rewards transfer failed");
                }
                (bool sent, ) = feeTreasury.call{value: toTreasury}("");
                require(sent, "CustomTokenFactory: fee transfer failed");
            } else {
                (bool sent, ) = feeTreasury.call{value: feeCollected}("");
                require(sent, "CustomTokenFactory: fee transfer failed");
            }
        }

        emit CustomTokenCreated(token, msg.sender, name_, symbol_, totalSupply_, pair, reflectionAsset_, marketingWallet_);
    }

    /// @dev Everything specific to seeding the pool and the optional
    /// buy-in, split out of createCustomToken() to keep its stack shallow
    /// enough to compile — same reason TokenFactory splits
    /// _launchWithLiquidity out of createToken(). Only ever called from the
    /// addLiquidity branch above.
    function _seedLiquidityAndBuyIn(
        address token,
        uint256 totalSupply_,
        uint256 liquidityEthAmount,
        uint256 creatorBuyEthAmount,
        uint256 minCreatorTokensOut
    ) internal returns (address pair, uint256 lpAmount, uint256 lockId, uint256 creatorTokensBought) {
        IERC20(token).approve(address(router), totalSupply_);
        (uint256 amountTokenUsed, uint256 amountETHUsed, uint256 lpAmountAdded) = router.addLiquidityETH{value: liquidityEthAmount}(
            token,
            totalSupply_,
            _minWithSlippage(totalSupply_), // 5–8% slippage tolerance — see liquiditySlippageBps
            _minWithSlippage(liquidityEthAmount),
            address(locker), // LP tokens mint straight to the locker — never pass through this factory
            block.timestamp + 15 minutes
        );
        lpAmount = lpAmountAdded;

        pair = IUniswapV2FactoryMinimal(router.factory()).getPair(token, router.WETH());
        require(pair != address(0), "CustomTokenFactory: pair not found after addLiquidityETH");
        CustomToken(payable(token)).setPair(pair);

        // Wire the platform's own graduating tax on top of whatever the
        // creator configured — same 1.00%-until-graduation behavior as
        // TokenFactory's simpler token, just skimmed in-kind rather than
        // batched. Leaving platformFeeWallet/priceFeed unset simply leaves
        // this permanently inactive (see CustomToken.configurePlatformTax);
        // it never blocks a launch the way TokenFactory's mandatory
        // platform fee wallet/price feed checks do.
        // rewardBps only ever actually applies once rewardsDistributor is
        // set — see TokenFactory._launchWithLiquidity for the identical
        // reasoning on the simpler token path.
        uint256 effectiveRewardBps = rewardsDistributor != address(0) ? rewardBps : 0;
        uint256 effectiveCreatorRewardBps = creatorRewardsDistributor != address(0) ? creatorRewardBps : 0;
        CustomToken(payable(token)).configurePlatformTax(
            platformFeeWallet, feeBps, priceFeed, graduationTargetUsd, maxOracleStaleness,
            rewardsDistributor, effectiveRewardBps, creatorRewardsDistributor, effectiveCreatorRewardBps,
            feeWalletDistributor
        );

        uint256 unlockTime = block.timestamp + lpLockDuration;
        lockId = locker.lock(pair, msg.sender, lpAmount, unlockTime);
        emit InitialLiquidityLocked(token, lpAmount, unlockTime, lockId);

        if (creatorBuyEthAmount > 0) {
            address[] memory path = new address[](2);
            path[0] = router.WETH();
            path[1] = token;
            uint256 effectiveMinOut = _effectiveMinBuyOut(token, creatorBuyEthAmount, amountETHUsed, amountTokenUsed, minCreatorTokensOut);
            uint256 balBefore = IERC20(token).balanceOf(msg.sender);
            router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: creatorBuyEthAmount}(
                effectiveMinOut,
                path,
                msg.sender,
                block.timestamp + 15 minutes
            );
            creatorTokensBought = IERC20(token).balanceOf(msg.sender) - balBefore;
            require(
                creatorTokensBought <= (totalSupply_ * maxCreatorBuyBps) / 10_000,
                "CustomTokenFactory: creator buy-in exceeds max allowed share of supply"
            );
            emit CreatorBought(token, msg.sender, creatorBuyEthAmount, creatorTokensBought);
        }
    }

    function tokensOf(address creator_) external view returns (address[] memory) {
        return _tokensByCreator[creator_];
    }

    function allTokens() external view returns (address[] memory) {
        return _tokenList;
    }

    /// @notice Previews the address createCustomToken()/
    /// relayedCreateCustomToken() will deploy to for a given (creator, salt)
    /// pair — see TokenFactory.predictTokenAddress for the full
    /// explanation; applies identically here.
    function predictTokenAddress(address creator_, uint256 salt) external view returns (address) {
        return Clones.predictDeterministicAddress(tokenImplementation, _deriveTokenSalt(creator_, salt), address(this));
    }

    /// @dev See TokenFactory._deriveTokenSalt for the full reasoning — binds
    /// the actual CREATE2 salt to the creator so a mempool-visible salt
    /// can't be copied and front-run by a third party.
    function _deriveTokenSalt(address creator_, uint256 salt) private pure returns (bytes32) {
        return keccak256(abi.encode(creator_, salt));
    }

    // ---- admin ----

    /// @notice Updates the flat fee for "Deploy Custom Tax Token" (no
    /// liquidity, no tax of any kind). See TokenFactory.setDeployFee for
    /// why this is a fixed wei amount rather than USD-denominated.
    function setDeployFee(uint256 newFee) external onlyOwner {
        deployFee = newFee;
        emit DeployFeeUpdated(newFee);
    }

    /// @notice Updates the flat fee for "Deploy and Add Liquidity (Live)",
    /// charged on top of the liquidity/buy-in ETH.
    function setLaunchFee(uint256 newFee) external onlyOwner {
        launchFee = newFee;
        emit LaunchFeeUpdated(newFee);
    }

    function setFeeTreasury(address newTreasury) external onlyOwner {
        require(newTreasury != address(0), "CustomTokenFactory: invalid treasury");
        feeTreasury = newTreasury;
        emit FeeTreasuryUpdated(newTreasury);
    }

    function setLpLockDuration(uint256 newDuration) external onlyOwner {
        lpLockDuration = newDuration;
        emit LpLockDurationUpdated(newDuration);
    }

    /// @notice Updates the anti-rug ceiling on a creator's own
    /// same-transaction buy-in, in bps of totalSupply_ (500 = 5.00%).
    /// Applies to launches from this point forward.
    function setMaxCreatorBuyBps(uint256 newBps) external onlyOwner {
        require(newBps <= 10_000, "CustomTokenFactory: bps cannot exceed 100%");
        maxCreatorBuyBps = newBps;
        emit MaxCreatorBuyBpsUpdated(newBps);
    }

    /// @notice Adjusts the addLiquidityETH slippage tolerance, kept to a
    /// fixed 5.00%–8.00% band — see TokenFactory.setLiquiditySlippageBps for
    /// the full reasoning, identical here.
    function setLiquiditySlippageBps(uint256 newBps) external onlyOwner {
        require(newBps >= MIN_LIQUIDITY_SLIPPAGE_BPS, "CustomTokenFactory: slippage below 5% floor");
        require(newBps <= MAX_LIQUIDITY_SLIPPAGE_BPS, "CustomTokenFactory: slippage above 8% ceiling");
        liquiditySlippageBps = newBps;
        emit LiquiditySlippageBpsUpdated(newBps);
    }

    /// @notice Adjusts the creator buy-in's slippage tolerance, same fixed
    /// 5.00%–8.00% band as setLiquiditySlippageBps, for the same reasons.
    function setBuyInSlippageBps(uint256 newBps) external onlyOwner {
        require(newBps >= MIN_LIQUIDITY_SLIPPAGE_BPS, "CustomTokenFactory: slippage below 5% floor");
        require(newBps <= MAX_LIQUIDITY_SLIPPAGE_BPS, "CustomTokenFactory: slippage above 8% ceiling");
        buyInSlippageBps = newBps;
        emit BuyInSlippageBpsUpdated(newBps);
    }

    /// @notice Points deployFee/launchFee's 50% rewards share, and every
    /// future CustomToken's per-token reward diversion, at a
    /// PlatformRewardsDistributor. See TokenFactory.setRewardsDistributor —
    /// behaves identically here. address(0) disables the entire feature,
    /// fully reversibly, and never touches a token or launch that already
    /// happened.
    function setRewardsDistributor(address newDistributor) external onlyOwner {
        rewardsDistributor = newDistributor;
        emit RewardsDistributorUpdated(newDistributor);
    }

    /// @notice See TokenFactory.setCreatorRewardsDistributor — identical
    /// behavior here.
    function setCreatorRewardsDistributor(address newDistributor) external onlyOwner {
        creatorRewardsDistributor = newDistributor;
        emit CreatorRewardsDistributorUpdated(newDistributor);
    }

    /// @notice See TokenFactory.setFeeWalletDistributor — identical
    /// behavior here.
    function setFeeWalletDistributor(address newDistributor) external onlyOwner {
        feeWalletDistributor = newDistributor;
        emit FeeWalletDistributorUpdated(newDistributor);
    }

    /// @notice See TokenFactory.setRelayer — identical behavior here,
    /// including the requirement that maxRelayerGasReimbursementWei already
    /// be set to a non-zero value before a relayer can be enabled.
    function setRelayer(address newRelayer) external onlyOwner {
        if (newRelayer != address(0)) {
            require(
                maxRelayerGasReimbursementWei > 0,
                "CustomTokenFactory: set maxRelayerGasReimbursementWei before enabling a relayer"
            );
        }
        relayer = newRelayer;
        emit RelayerUpdated(newRelayer);
    }

    /// @notice See TokenFactory.setMaxRelayerGasReimbursement — identical
    /// behavior here, including Finding CTF-1 (mirrors TokenFactory Finding
    /// F-2): setRelayer() above refuses to enable a relayer until this cap is
    /// nonzero, specifically so a relayer can never be left with an
    /// unreimbursable, unbounded gas exposure. Before this fix, this setter
    /// could silently zero the cap right back out afterward while a relayer
    /// stayed configured, reopening the exact gap setRelayer()'s own check
    /// exists to close. Now the cap can only go to zero once no relayer is
    /// enabled.
    function setMaxRelayerGasReimbursement(uint256 newCapWei) external onlyOwner {
        require(
            newCapWei > 0 || relayer == address(0),
            "CustomTokenFactory: cannot zero the cap while a relayer is enabled"
        );
        maxRelayerGasReimbursementWei = newCapWei;
        emit MaxRelayerGasReimbursementUpdated(newCapWei);
    }

    /// @notice Update the platform tax defaults applied to CustomTokens
    /// created from this point forward. Existing tokens are unaffected —
    /// each one snapshots these values into its own storage the moment
    /// configurePlatformTax() runs during its own launch.
    /// platformFeeWallet_ and priceFeed_ may still be set to address(0)
    /// deliberately — that's the documented way to leave the platform tax
    /// permanently inactive for launches going forward (configurePlatformTax
    /// treats a zero feeWallet/feeBps as "record it, but never activate it";
    /// unlike TokenFactory, this never blocks a launch). feeBps_,
    /// graduationTargetUsd_, and maxOracleStaleness_ get real bounds below
    /// so a mistyped value can't silently brick every future launch's
    /// transfers (feeBps_ above 10,000) or defeat the tax from block one
    /// (graduationTargetUsd_ == 0) — mirrors the same bound already
    /// enforced on setMaxCreatorBuyBps, and the identical fix applied to
    /// TokenFactory.setTaxDefaults. rewardBps_ is the new addition: how
    /// much of feeBps_ gets carved off to rewardsDistributor going
    /// forward — must never exceed feeBps_ itself.
    function setTaxDefaults(
        address platformFeeWallet_,
        uint256 feeBps_,
        address priceFeed_,
        uint256 graduationTargetUsd_,
        uint256 maxOracleStaleness_,
        uint256 rewardBps_,
        uint256 creatorRewardBps_
    ) external onlyOwner {
        require(feeBps_ <= MAX_FEE_BPS, "CustomTokenFactory: feeBps exceeds MAX_FEE_BPS ceiling");
        require(graduationTargetUsd_ > 0, "CustomTokenFactory: graduation target must be > 0");
        require(maxOracleStaleness_ > 0, "CustomTokenFactory: oracle staleness must be > 0");
        require(rewardBps_ + creatorRewardBps_ <= feeBps_, "CustomTokenFactory: rewardBps+creatorRewardBps cannot exceed feeBps");
        platformFeeWallet = platformFeeWallet_;
        feeBps = feeBps_;
        priceFeed = priceFeed_;
        graduationTargetUsd = graduationTargetUsd_;
        maxOracleStaleness = maxOracleStaleness_;
        rewardBps = rewardBps_;
        creatorRewardBps = creatorRewardBps_;
        emit TaxDefaultsUpdated();
    }

    /// @notice Escape hatch for an already-launched CustomToken whose
    /// platform price feed has gone permanently stale or was never a real,
    /// maintained feed — see CustomToken.updatePriceFeed /
    /// TokenFactory.updateTokenPriceFeed (identical pattern). Owner-only,
    /// and deliberately narrow: repoints only that token's oracle inputs,
    /// never its fee rates, fee wallet, pair, or platformTaxActive
    /// directly.
    function updateTokenPriceFeed(address token, address newPriceFeed_, uint256 newMaxOracleStaleness_) external onlyOwner {
        CustomToken(payable(token)).updatePriceFeed(newPriceFeed_, newMaxOracleStaleness_);
        emit TokenPriceFeedUpdated(token, newPriceFeed_, newMaxOracleStaleness_);
    }
}

contracts/FeeWalletDistributor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import "./interfaces/IUniswapV2Router02.sol";
import "./interfaces/IUniswapV2Pair.sol";
import "./interfaces/IPlatformToken.sol";

/// @title FeeWalletDistributor
/// @notice Where the platform-fee-wallet slice of every taxed buy/sell ends
/// up, once a token's feeWalletDistributor is set. LaunchedToken/CustomToken
/// each carve `toFeeWallet` (whatever's left of their feeBps/platformFeeBps
/// cut after rewardBps/creatorRewardBps are carved out) off of every taxed
/// transfer and send it here in-kind, instead of straight to a plain wallet
/// address.
///
/// --- Buyback + burn + holder-airdrop (this version) ---
/// Per the platform's confirmed design, this slice is no longer paid out to
/// feeWallet in full. Once platformToken is configured (see
/// setPlatformToken), every amount this contract pulls in `token` is split
/// 50/50 at the top of triggerFeeWalletSwap:
///  - 50% swaps to ETH exactly as this contract always did, credited to
///    claimableEth[token] and paid out via claimFeeWalletRewards — this half
///    is unchanged in every respect from the original version of this file.
///  - 50% swaps to platformToken and is immediately split again, 50/50, into
///    an outright burn and pendingAirdropTokens — the accumulate-and-batch-
///    trigger buyback/burn/push-airdrop machinery below
///    (setPlatformToken/_splitAndProcess/startAirdropRound/
///    processAirdropBatch/_sendPlatformToken) is ported directly from
///    PlatformRewardsDistributor, at the platform's explicit request, so the
///    two contracts behave identically for this piece: same fixed 50/50
///    burn/airdrop split, same push-based holder payout walking
///    PlatformToken's own holder registry in gas-bounded batches, same
///    try/catch-and-requeue protection against a single reverting holder
///    bricking a round (mirroring Finding PR-1's fix), same
///    approve-to-zero-then-approve pattern for non-standard ERC20 allowances
///    (mirroring Finding PR-3's fix).
///
/// Net effect once platformToken is configured: of every unit of platform
/// tax that reaches this contract, 50% ends up as ETH at feeWallet, 25%
/// worth of platformToken is burned, and 25% worth of platformToken is
/// pushed out to platformToken's own holders.
///
/// --- Security review (this file) ---
/// One finding from the accompanying audit report is fixed directly in this
/// version:
///  - Finding FWD-1 (Medium): the buyback leg originally had no
///    caller-supplied slippage floor of its own — only the ETH leg did — so
///    a caller wanting extra protection beyond the protocol default had no
///    way to provide it for that leg. Fixed by adding a second
///    triggerFeeWalletSwap(token, minEthOut, minPlatformTokensOut) overload;
///    the original 2-argument overload is unchanged and simply forwards
///    minPlatformTokensOut = 0.
/// Four additional informational notes (FWD-2..FWD-5) are documented in the
/// accompanying report and require no code change.
///
/// Before platformToken is configured, this contract behaves exactly as it
/// always did: the entire pulled amount converts to ETH for feeWallet, and
/// nothing is held back — same "inert until configured" pattern documented
/// on PlatformRewardsDistributor.platformToken, so enabling this later never
/// requires touching any already-launched token or factory again.
///
/// Flow, per token, once configured:
///  1. In-kind fee-wallet remainder accumulates here as an ordinary ERC20
///     balance of that token — no bookkeeping needed for this step, the
///     token's own balanceOf(this) already is the ledger.
///  2. Anyone (typically an off-chain keeper — see scripts/relayer.js's
///     feeWalletPollLoop) calls triggerFeeWalletSwap(token, minEthOut) once
///     the accumulated balance clears that token's swapThreshold. This pulls
///     up to maxSwapAmount[token] of the current balance (the full balance,
///     if no cap is set), splits it 50/50, and:
///       a. swaps the ETH-leg half for ETH via the router (fee-on-transfer-
///          tolerant, since `token` can itself carry a live transfer tax)
///          and credits claimableEth[token] — minEthOut applies only to this
///          leg, so existing callers (including scripts/relayer.js, which
///          predicts and supplies minEthOut for the historically-full
///          amount) keep working unchanged; the protocol-side protective
///          floor (see _protectiveMinOut/swapSlippageBps) is recomputed
///          against whatever the actual half-sized leg is.
///       b. swaps the buyback-leg half for platformToken (routed through
///          WETH) and splits the proceeds 50% burn / 50% into
///          pendingAirdropTokens, purely against the protocol's own
///          protective floor (no caller-supplied override for this leg,
///          since triggerFeeWalletSwap's external signature is unchanged).
///  3. Anyone can call claimFeeWalletRewards(token) — it always pays out to
///     whatever this contract's feeWallet is set to AT CLAIM TIME, never a
///     stale snapshot, so a single setFeeWallet() call repoints every
///     token's next claim at once. Unchanged from the original version.
///  4. Anyone can call startAirdropRound() once pendingAirdropTokens is
///     nonzero, and processAirdropBatch(maxHolders) to walk PlatformToken's
///     holder registry in bounded batches, paying each holder their
///     proportional share of the frozen round amount — identical mechanics
///     to PlatformRewardsDistributor's own airdrop rounds.
contract FeeWalletDistributor is Ownable2Step, ReentrancyGuard {
    IUniswapV2Router02 public immutable router;

    /// @notice The single recipient every token's fee-wallet slice
    /// ultimately pays out to. Owner-settable (see setFeeWallet) — read
    /// live at claim time, never snapshotted per token. address(0) simply
    /// leaves claimFeeWalletRewards permanently reverting until set; it
    /// never blocks triggerFeeWalletSwap, since accumulating and swapping
    /// don't depend on who the eventual recipient is.
    address public feeWallet;

    /// @notice The token every buyback leg converts into, and every airdrop
    /// pays out in. address(0) (the default) means "not configured yet" —
    /// see the contract-level comment above for how triggerFeeWalletSwap
    /// behaves in that state (100% ETH leg, no buyback, unchanged from the
    /// original version of this contract). ETH and tokens continue to
    /// accumulate normally in the meantime. See setPlatformToken.
    IPlatformToken public platformToken;

    /// @notice ETH owed to feeWallet, accrued from a given token's swapped
    /// balance. Credited by triggerFeeWalletSwap's ETH leg and zeroed by
    /// claimFeeWalletRewards. Keyed by TOKEN — see the contract-level
    /// comment for why — not by feeWallet itself (there's only ever one).
    mapping(address => uint256) public claimableEth;

    /// @notice Minimum balance of `token` this contract must be holding
    /// before triggerFeeWalletSwap(token) will execute — identical
    /// anti-dust/anti-griefing knob as
    /// CreatorRewardsDistributor.swapThreshold, for the same reason a single
    /// global threshold wouldn't make sense (every token has its own
    /// supply/decimals scale). Defaults to 0 (any nonzero balance triggers)
    /// until the owner sets one for a given token. Applies to the total
    /// amount pulled, before the 50/50 ETH-leg/buyback-leg split.
    mapping(address => uint256) public swapThreshold;

    /// @notice Caps how much of `token`'s balance a single
    /// triggerFeeWalletSwap(token) call is allowed to pull — identical
    /// anti-dump knob as CreatorRewardsDistributor.maxSwapAmount, and for
    /// the same reason: without it, an infrequently-triggered token could
    /// accumulate a large balance and have its entire pile sold in one call,
    /// showing up as a single visible dump against that token's own pool.
    /// Defaults to 0, meaning "uncapped", until the owner sets one — once
    /// set, a balance above the cap drains across multiple separate calls
    /// instead of one. Applies to the total amount pulled, before the 50/50
    /// ETH-leg/buyback-leg split — each leg trades half of whatever this cap
    /// allows through in a given call.
    mapping(address => uint256) public maxSwapAmount;

    /// @notice Protective slippage floor applied to every swap this contract
    /// executes — both triggerFeeWalletSwap's ETH leg (see the accompanying
    /// audit report's Finding FW-1) and its platformToken buyback leg.
    /// Before FW-1 was fixed, triggerFeeWalletSwap accepted a purely
    /// caller-supplied minEthOut with no protocol-side floor computed from
    /// the pool's own reserves; since the function is deliberately
    /// permissionless (see its own comment), anyone could call it with
    /// minEthOut == 0 and sandwich their own call for MEV profit, reducing
    /// what the platform's own fee wallet ultimately collects. Identical
    /// fix, same fixed 5.00%-8.00% band, as the one already applied to
    /// CreatorRewardsDistributor.triggerCreatorSwap and
    /// PlatformRewardsDistributor's own buyback triggers — reused here
    /// unchanged for the new buyback leg rather than introducing a second,
    /// separately-tunable knob for the same purpose.
    uint256 public swapSlippageBps = 600; // 6.00% default
    uint256 public constant MIN_SWAP_SLIPPAGE_BPS = 500; // 5.00%
    uint256 public constant MAX_SWAP_SLIPPAGE_BPS = 800; // 8.00%

    /// @notice PlatformToken sitting here, already bought back by the
    /// buyback leg and already split, awaiting its turn in the next airdrop
    /// round. Frozen into roundAmount the moment startAirdropRound() runs.
    /// Identical role to PlatformRewardsDistributor.pendingAirdropTokens.
    uint256 public pendingAirdropTokens;

    bool public roundActive;
    uint256 public roundAmount; // total PlatformToken being paid out this round, frozen at round start
    uint256 public roundSupplySnapshot; // denominator: eligible supply frozen at round start (see startAirdropRound)
    uint256 public roundCursor; // next holder-registry index processAirdropBatch will start from

    event FeeWalletUpdated(address indexed oldWallet, address indexed newWallet);
    event PlatformTokenSet(address indexed newToken);
    event SwapThresholdUpdated(address indexed token, uint256 newThreshold);
    event MaxSwapAmountUpdated(address indexed token, uint256 newMax);
    event SwapSlippageBpsUpdated(uint256 newBps);
    event FeeWalletSwapTriggered(address indexed token, uint256 amountIn, uint256 ethOut);
    event FeeWalletRewardsClaimed(address indexed token, address indexed feeWallet, address indexed caller, uint256 amount);
    event PlatformTokenBuybackTriggered(address indexed token, uint256 amountIn, uint256 tokensOut, uint256 burned, uint256 toAirdrop);
    event DirectPlatformTokensProcessed(address indexed token, uint256 amountIn, uint256 burned, uint256 toAirdrop);
    event AirdropRoundStarted(uint256 amount, uint256 supplySnapshot, uint256 holderCountAtStart);
    event AirdropBatchProcessed(uint256 fromIndex, uint256 toIndex, uint256 amountDistributed);
    event AirdropPayoutSkipped(address indexed holder, uint256 amount);
    event AirdropRoundCompleted(uint256 totalDistributed);

    constructor(address router_, address initialOwner_, address feeWallet_) Ownable(initialOwner_) {
        require(router_ != address(0), "FeeWalletDistributor: invalid router");
        router = IUniswapV2Router02(router_);
        feeWallet = feeWallet_;
        emit FeeWalletUpdated(address(0), feeWallet_);
    }

    /// @notice Lets this contract receive ETH — its only intended inflow is
    /// the swap output inside triggerFeeWalletSwap's ETH leg below, but this
    /// also covers any stray dust sent directly.
    receive() external payable {}

    // ---------------------------------------------------------------
    // Admin
    // ---------------------------------------------------------------

    /// @notice Repoints where every token's next claimFeeWalletRewards call
    /// sends its ETH. Takes effect on the next claim for every token at
    /// once — never retroactive to ETH already paid out, and never touches
    /// claimableEth balances themselves.
    function setFeeWallet(address newWallet) external onlyOwner {
        emit FeeWalletUpdated(feeWallet, newWallet);
        feeWallet = newWallet;
    }

    /// @notice Wires up the token the buyback leg converts into and every
    /// airdrop pays out in. Deliberately blocked while a round is active or
    /// while platformToken is already sitting in pendingAirdropTokens —
    /// changing the token out from under either would orphan that balance
    /// in a token nobody can query it under anymore. Same guard as
    /// PlatformRewardsDistributor.setPlatformToken, for the identical
    /// reason. Before this is called, triggerFeeWalletSwap runs exactly as
    /// it always did (100% ETH leg) — see the contract-level comment.
    function setPlatformToken(address newToken) external onlyOwner {
        require(!roundActive, "FeeWalletDistributor: round in progress");
        require(pendingAirdropTokens == 0, "FeeWalletDistributor: pending airdrop must clear first");
        platformToken = IPlatformToken(newToken);
        emit PlatformTokenSet(newToken);
    }

    function setSwapThreshold(address token, uint256 newThreshold) external onlyOwner {
        swapThreshold[token] = newThreshold;
        emit SwapThresholdUpdated(token, newThreshold);
    }

    /// @notice See maxSwapAmount's own comment above. 0 means uncapped.
    function setMaxSwapAmount(address token, uint256 newMax) external onlyOwner {
        maxSwapAmount[token] = newMax;
        emit MaxSwapAmountUpdated(token, newMax);
    }

    /// @notice Adjusts the protective slippage floor applied to every swap
    /// this contract executes — see swapSlippageBps above and Finding FW-1.
    /// Bounded to the same 5.00%-8.00% band used everywhere else in this
    /// codebase for the identical purpose.
    function setSwapSlippageBps(uint256 newBps) external onlyOwner {
        require(newBps >= MIN_SWAP_SLIPPAGE_BPS, "FeeWalletDistributor: slippage below 5% floor");
        require(newBps <= MAX_SWAP_SLIPPAGE_BPS, "FeeWalletDistributor: slippage above 8% ceiling");
        swapSlippageBps = newBps;
        emit SwapSlippageBpsUpdated(newBps);
    }

    // ---------------------------------------------------------------
    // Quoting helpers
    // ---------------------------------------------------------------

    /// @dev Standard Uniswap V2 constant-product quote (0.30% swap fee baked
    /// into the 997/1000 constants) — used only to derive a protective
    /// slippage floor below, never to execute anything. Same helper as
    /// CreatorRewardsDistributor/PlatformRewardsDistributor/CustomToken/
    /// CustomTokenFactory's identical utility.
    function _getAmountOut(uint256 amountIn, uint256 reserveIn, uint256 reserveOut) private pure returns (uint256) {
        uint256 amountInWithFee = amountIn * 997;
        uint256 numerator = amountInWithFee * reserveOut;
        uint256 denominator = reserveIn * 1000 + amountInWithFee;
        return numerator / denominator;
    }

    /// @dev Quotes amountIn's expected ETH output off the token/WETH pool's
    /// own live reserves and applies swapSlippageBps — see Finding FW-1.
    /// Returns 0 if no pool is found or either reserve is empty, which the
    /// ETH leg treats as "can't compute a protocol floor this time," falling
    /// back to the caller's own minEthOut rather than blocking the swap
    /// outright. Single-hop, used only for the ETH leg (token -> WETH).
    function _protectiveMinOut(address token, uint256 amountIn) private view returns (uint256) {
        address weth = router.WETH();
        address pairAddr = IUniswapV2FactoryMinimal(router.factory()).getPair(token, weth);
        if (pairAddr == address(0)) return 0;

        (uint112 reserve0, uint112 reserve1, ) = IUniswapV2PairMinimal(pairAddr).getReserves();
        address token0 = IUniswapV2PairMinimal(pairAddr).token0();
        uint256 reserveIn = token0 == token ? uint256(reserve0) : uint256(reserve1);
        uint256 reserveOut = token0 == token ? uint256(reserve1) : uint256(reserve0);
        if (reserveIn == 0 || reserveOut == 0) return 0;

        uint256 quoted = _getAmountOut(amountIn, reserveIn, reserveOut);
        return quoted - (quoted * swapSlippageBps) / 10_000;
    }

    /// @dev Quotes amountIn's expected output at the END of a multi-hop path
    /// off each hop's own live pool reserves, chaining the output of one hop
    /// into the input of the next, then applies swapSlippageBps to the final
    /// figure — see Finding PR-2 in the PlatformRewardsDistributor audit,
    /// whose identical helper this is ported from. Used only for the
    /// buyback leg's [token, WETH, platformToken] path. Returns 0 if any hop's
    /// pool doesn't exist or has an empty reserve, which the buyback leg
    /// treats as "can't compute a protocol floor this time" — see
    /// _executePlatformTokenBuyback below for how that's handled.
    function _protectiveMinOut(address[] memory path, uint256 amountIn) private view returns (uint256) {
        address factory = router.factory();
        uint256 amount = amountIn;
        for (uint256 i = 0; i + 1 < path.length; i++) {
            address pairAddr = IUniswapV2FactoryMinimal(factory).getPair(path[i], path[i + 1]);
            if (pairAddr == address(0)) return 0;

            (uint112 reserve0, uint112 reserve1, ) = IUniswapV2PairMinimal(pairAddr).getReserves();
            address token0 = IUniswapV2PairMinimal(pairAddr).token0();
            uint256 reserveIn = token0 == path[i] ? uint256(reserve0) : uint256(reserve1);
            uint256 reserveOut = token0 == path[i] ? uint256(reserve1) : uint256(reserve0);
            if (reserveIn == 0 || reserveOut == 0) return 0;

            amount = _getAmountOut(amount, reserveIn, reserveOut);
        }
        return amount - (amount * swapSlippageBps) / 10_000;
    }

    // ---------------------------------------------------------------
    // Main trigger — splits 50/50 between the ETH leg and the buyback leg
    // ---------------------------------------------------------------

    /// @notice Pulls up to maxSwapAmount[token] of this contract's balance
    /// of `token` (the entire balance, if no cap is set), and:
    ///   - if platformToken is NOT configured, swaps 100% of it for ETH,
    ///     credited to claimableEth[token] — byte-for-byte the original
    ///     behavior of this contract.
    ///   - if platformToken IS configured, splits it 50/50: half runs
    ///     through the same ETH-leg logic as above; half runs through the
    ///     new buyback leg (see _executePlatformTokenBuyback).
    /// Permissionless, like every trigger in
    /// CreatorRewardsDistributor/PlatformRewardsDistributor — the
    /// destination of the ETH leg (this contract's own feeWallet, read at
    /// claim time) never depends on who calls it, and neither does the
    /// buyback leg's fixed 50/50 burn/airdrop split.
    /// @param minEthOut Caller-supplied minimum-out floor for the ETH leg
    /// (unchanged meaning from the original contract) — combined with the
    /// protocol's own protective floor computed against the ETH leg's
    /// actual (possibly halved) size. The buyback leg gets no caller-
    /// supplied floor from this overload (it relies solely on the
    /// protocol's own protective floor) — this overload's signature is
    /// kept byte-for-byte unchanged from the original contract for
    /// backward compatibility with existing callers (see
    /// scripts/relayer.js's feeWalletPollLoop). Callers that also want to
    /// supply a floor for the buyback leg should use the 3-argument
    /// overload below instead — see Finding FWD-1.
    /// @dev Stack-pressure fix only (no behavior change): groups each
    /// private helper's loose uint256 locals into a single memory struct.
    /// A struct local is one memory-pointer stack slot regardless of how
    /// many fields it carries, whereas N loose uint256 locals are N stack
    /// slots — under viaIR, solc's Yul optimizer can inline a private
    /// function back into its single call site regardless of `runs`, which
    /// re-merges every inlined function's locals onto one combined stack
    /// frame. _executeFeeWalletLeg and _executePlatformTokenBuyback are
    /// each called from exactly one place (inside _triggerFeeWalletSwap),
    /// so without this they're exactly the shape the compiler is free to
    /// re-merge, which is what kept tripping HH600 ("stack too deep") here
    /// even after splitting the logic into separate functions.
    struct SplitPlan {
        uint256 amountIn;
        uint256 buybackAmount;
        uint256 ethLegAmount;
    }

    struct SwapPlan {
        uint256 protectiveFloor;
        uint256 effectiveMinOut;
        uint256 before;
    }

    struct BuybackPlan {
        uint256 protectiveFloor;
        uint256 effectiveMinOut;
        uint256 before;
        uint256 tokensOut;
    }

    function triggerFeeWalletSwap(address token, uint256 minEthOut) external nonReentrant returns (uint256 ethOut) {
        return _triggerFeeWalletSwap(token, minEthOut, 0);
    }

    /// @notice Same as triggerFeeWalletSwap(token, minEthOut) above, but
    /// additionally lets the caller supply `minPlatformTokensOut` — a
    /// caller-side minimum-out floor for the buyback leg specifically,
    /// combined with the protocol's own protective floor the same
    /// "whichever is stricter" way minEthOut already is for the ETH leg,
    /// and the same way PlatformRewardsDistributor.triggerTokenBuyback's
    /// own minTokensOut already works. Added to fix Finding FWD-1: before
    /// this overload existed, the buyback leg had no way for a caller
    /// (e.g. an off-chain keeper quoting this leg's expected output in
    /// real time, the same way scripts/relayer.js already does for the
    /// ETH leg) to add protection beyond the protocol default — a real,
    /// if narrower, gap next to the ETH leg's existing caller-supplied
    /// floor. Existing callers that only know about the 2-argument
    /// overload are entirely unaffected — that overload now simply calls
    /// this one with minPlatformTokensOut = 0.
    function triggerFeeWalletSwap(address token, uint256 minEthOut, uint256 minPlatformTokensOut)
        external
        nonReentrant
        returns (uint256 ethOut)
    {
        return _triggerFeeWalletSwap(token, minEthOut, minPlatformTokensOut);
    }

    /// @dev Shared implementation for both triggerFeeWalletSwap overloads.
    /// Not itself nonReentrant (both external overloads already are) —
    /// applying the modifier here too would make one overload's call into
    /// this function revert as a false-positive reentrant call.
    function _triggerFeeWalletSwap(address token, uint256 minEthOut, uint256 minPlatformTokensOut)
        private
        returns (uint256 ethOut)
    {
        require(token != address(0), "FeeWalletDistributor: invalid token");
        uint256 balance = IERC20(token).balanceOf(address(this));
        require(balance > 0 && balance >= swapThreshold[token], "FeeWalletDistributor: below threshold");
        uint256 cap = maxSwapAmount[token];

        SplitPlan memory split;
        split.amountIn = (cap > 0 && balance > cap) ? cap : balance;
        split.buybackAmount = address(platformToken) != address(0) ? split.amountIn / 2 : 0;
        split.ethLegAmount = split.amountIn - split.buybackAmount;

        if (split.ethLegAmount > 0) {
            ethOut = _executeFeeWalletLeg(token, split.ethLegAmount, minEthOut);
        }
        if (split.buybackAmount > 0) {
            _executePlatformTokenBuyback(token, split.buybackAmount, minPlatformTokensOut);
        }
    }

    /// @dev The ETH leg: swaps `amountIn` of `token` for ETH via the router
    /// (fee-on-transfer-tolerant) and credits the proceeds to
    /// claimableEth[token]. Identical mechanics to the original contract's
    /// triggerFeeWalletSwap body, factored out so triggerFeeWalletSwap can
    /// call it on either the full balance (platformToken unset) or half of
    /// it (platformToken set). Adds the approve-to-zero-then-approve pattern
    /// (mirroring Finding PR-3's fix in PlatformRewardsDistributor) that the
    /// original version of this leg didn't have, for the same non-standard-
    /// ERC20-allowance safety.
    function _executeFeeWalletLeg(address token, uint256 amountIn, uint256 minEthOut) private returns (uint256 ethOut) {
        address[] memory path = new address[](2);
        path[0] = token;
        path[1] = router.WETH();

        // Finding FW-1: minEthOut alone was a purely caller-supplied value
        // with no protocol-side floor — since this function is deliberately
        // permissionless, that let anyone call it with minEthOut == 0 and
        // sandwich their own call for MEV profit. effectiveMinOut is
        // whichever is stricter of the caller's own minEthOut and a floor
        // computed from the pool's own live reserves, against this leg's
        // actual amountIn.
        SwapPlan memory plan;
        plan.protectiveFloor = _protectiveMinOut(token, amountIn);
        plan.effectiveMinOut = minEthOut > plan.protectiveFloor ? minEthOut : plan.protectiveFloor;

        plan.before = address(this).balance;
        IERC20(token).approve(address(router), 0);
        IERC20(token).approve(address(router), amountIn);
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            amountIn,
            plan.effectiveMinOut,
            path,
            address(this),
            block.timestamp + 15 minutes
        );
        ethOut = address(this).balance - plan.before;

        claimableEth[token] += ethOut;
        emit FeeWalletSwapTriggered(token, amountIn, ethOut);
    }

    /// @dev The buyback leg: swaps `amountIn` of `token` for platformToken
    /// (routed through WETH) and splits the proceeds 50% burned / 50% into
    /// pendingAirdropTokens via _splitAndProcess — ported directly from
    /// PlatformRewardsDistributor.triggerTokenBuyback, including its direct-
    /// token shortcut (if `token` already IS platformToken, no swap is
    /// needed) and its Finding PR-2/PR-3 fixes.
    /// @param minPlatformTokensOut Caller-supplied minimum-out floor for
    /// this leg (see Finding FWD-1) — combined with the protocol's own
    /// protective floor the same "whichever is stricter" way minEthOut
    /// already is for the ETH leg. Callers that only use the 2-argument
    /// triggerFeeWalletSwap overload pass 0 here, so this degrades to
    /// relying solely on the protocol's own protective floor for them,
    /// exactly as before FWD-1 was fixed. That protocol floor itself still
    /// degrades to 0 (no floor at all) if the [token, WETH, platformToken]
    /// path's pools can't be quoted, consistent with how every other
    /// quote-derived floor in this codebase degrades on a missing pool —
    /// callers who want a hard guarantee in that situation should supply
    /// their own minPlatformTokensOut via the 3-argument overload.
    function _executePlatformTokenBuyback(address token, uint256 amountIn, uint256 minPlatformTokensOut) private {
        if (token == address(platformToken)) {
            (uint256 burnedDirect, uint256 toAirdropDirect) = _splitAndProcess(amountIn);
            emit DirectPlatformTokensProcessed(token, amountIn, burnedDirect, toAirdropDirect);
            return;
        }

        address[] memory path = new address[](3);
        path[0] = token;
        path[1] = router.WETH();
        path[2] = address(platformToken);

        // Finding FWD-1 (fixed): effectiveMinOut is whichever is stricter of
        // the caller's own minPlatformTokensOut and the protocol's own
        // reserve-derived floor — same combination already used for the ETH
        // leg's minEthOut and for every buyback trigger in
        // PlatformRewardsDistributor.
        BuybackPlan memory plan;
        plan.protectiveFloor = _protectiveMinOut(path, amountIn);
        plan.effectiveMinOut = minPlatformTokensOut > plan.protectiveFloor ? minPlatformTokensOut : plan.protectiveFloor;

        // Finding PR-3 (ported): approving `amountIn` directly on top of any
        // existing allowance breaks against ERC20s (e.g. USDT and tokens
        // that copy its guard) that revert on changing a nonzero allowance
        // straight to another nonzero value. Resetting to zero first makes
        // this safe regardless of whatever allowance, if any, is already
        // outstanding.
        IERC20(token).approve(address(router), 0);
        IERC20(token).approve(address(router), amountIn);
        plan.before = platformToken.balanceOf(address(this));
        router.swapExactTokensForTokensSupportingFeeOnTransferTokens(
            amountIn,
            plan.effectiveMinOut,
            path,
            address(this),
            block.timestamp + 15 minutes
        );
        plan.tokensOut = platformToken.balanceOf(address(this)) - plan.before;

        (uint256 burned, uint256 toAirdrop) = _splitAndProcess(plan.tokensOut);
        emit PlatformTokenBuybackTriggered(token, amountIn, plan.tokensOut, burned, toAirdrop);
    }

    /// @dev Fixed 50/50 split, shared by every path that produces fresh
    /// platformToken here (the buyback leg, plus its direct-token
    /// shortcut). Burns immediately; the airdrop half just accumulates
    /// until startAirdropRound() is next called. Identical to
    /// PlatformRewardsDistributor._splitAndProcess.
    function _splitAndProcess(uint256 amount) private returns (uint256 burned, uint256 toAirdrop) {
        if (amount == 0) return (0, 0);
        burned = amount / 2;
        toAirdrop = amount - burned;
        if (burned > 0) platformToken.burn(burned);
        pendingAirdropTokens += toAirdrop;
    }

    /// @notice Pays out claimableEth[token] to feeWallet, read live at call
    /// time (see setFeeWallet) — never a stale snapshot. Callable by
    /// anyone — same permissionless-but-fixed-destination pattern as
    /// triggerFeeWalletSwap above. Checks-effects-interactions (balance
    /// zeroed before the external call) plus nonReentrant besides.
    /// Unchanged from the original version of this contract.
    function claimFeeWalletRewards(address token) external nonReentrant returns (uint256 amount) {
        address recipient = feeWallet;
        require(recipient != address(0), "FeeWalletDistributor: fee wallet not set");
        amount = claimableEth[token];
        require(amount > 0, "FeeWalletDistributor: nothing to claim");
        claimableEth[token] = 0;
        (bool sent, ) = payable(recipient).call{value: amount}("");
        require(sent, "FeeWalletDistributor: ETH transfer failed");
        emit FeeWalletRewardsClaimed(token, recipient, msg.sender, amount);
    }

    // ---------------------------------------------------------------
    // Airdrop rounds — accumulate-and-batch-trigger, ported directly from
    // PlatformRewardsDistributor's identical mechanism
    // ---------------------------------------------------------------

    /// @notice Freezes whatever's accumulated in pendingAirdropTokens into
    /// a new round: the amount being paid out, and the eligible supply
    /// (PlatformToken's total supply minus whatever this contract itself
    /// is currently holding, since this contract is never a payee of its
    /// own airdrop) it's divided by. Permissionless, like the triggers
    /// above — anyone can kick a round off once there's something to
    /// distribute. Identical to PlatformRewardsDistributor.startAirdropRound.
    function startAirdropRound() external nonReentrant {
        require(!roundActive, "FeeWalletDistributor: round already active");
        require(address(platformToken) != address(0), "FeeWalletDistributor: platform token not set");
        require(pendingAirdropTokens > 0, "FeeWalletDistributor: nothing to distribute");

        uint256 ownBalance = platformToken.balanceOf(address(this));
        uint256 supply = platformToken.totalSupply();
        uint256 supplySnapshot = supply > ownBalance ? supply - ownBalance : 0;
        require(supplySnapshot > 0, "FeeWalletDistributor: no eligible holders");

        roundAmount = pendingAirdropTokens;
        pendingAirdropTokens = 0;
        roundSupplySnapshot = supplySnapshot;
        roundCursor = 0;
        roundActive = true;

        emit AirdropRoundStarted(roundAmount, roundSupplySnapshot, platformToken.holderCount());
    }

    /// @dev Wraps the actual token transfer in try/catch so a single
    /// reverting recipient (a blocklist, a max-wallet cap on PlatformToken,
    /// or any other transfer-blocking condition) can never take down the
    /// whole batch — mirrors Finding PR-1's fix in PlatformRewardsDistributor.
    /// `platformToken.transfer(...)` is already an external call
    /// (platformToken is a separately-deployed contract), so it can be
    /// try/catched directly with no extra self-call needed.
    function _sendPlatformToken(address to, uint256 amount) private returns (bool) {
        try platformToken.transfer(to, amount) returns (bool ok) {
            return ok;
        } catch {
            return false;
        }
    }

    /// @notice Pushes up to `maxHolders` holders' proportional share of the
    /// active round, resuming from wherever the last call left off, and
    /// closes the round out once every holder's been reached. Anyone can
    /// call this (e.g. a keeper looping until the round completes) — it's
    /// the only way round funds ever actually move. Identical mechanics,
    /// including the same disclosed live-balance and shrinking-registry
    /// approximations, as PlatformRewardsDistributor.processAirdropBatch —
    /// see that contract's own comment for the full rationale.
    function processAirdropBatch(uint256 maxHolders) external nonReentrant {
        require(roundActive, "FeeWalletDistributor: no active round");
        require(maxHolders > 0, "FeeWalletDistributor: maxHolders must be > 0");

        uint256 total = platformToken.holderCount();
        uint256 from = roundCursor;
        uint256 to = from + maxHolders;
        if (to > total) to = total;

        uint256 distributed;
        for (uint256 i = from; i < to; i++) {
            address holder = platformToken.holderAt(i);
            if (holder == address(this)) continue;
            uint256 share = (roundAmount * platformToken.balanceOf(holder)) / roundSupplySnapshot;
            if (share == 0) continue;
            if (_sendPlatformToken(holder, share)) {
                distributed += share;
            } else {
                // Mirrors Finding PR-1's fix: don't lose the share — requeue
                // it for the next round instead of leaving it stranded,
                // unaccounted, in this contract's own balance forever.
                pendingAirdropTokens += share;
                emit AirdropPayoutSkipped(holder, share);
            }
        }

        roundCursor = to;
        emit AirdropBatchProcessed(from, to, distributed);

        if (roundCursor >= total) {
            roundActive = false;
            emit AirdropRoundCompleted(roundAmount);
        }
    }
}

contracts/interfaces/IAggregatorV3.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @notice The slice of Chainlink's AggregatorV3Interface BondingCurve
/// actually needs. Matches the real interface exactly, so a real Chainlink
/// ETH/USD feed address can be dropped in directly — e.g. on most EVM
/// chains a feed like this is called "ETH / USD". Robinhood Chain being a
/// very new network, confirm a feed actually exists there (or that a
/// third-party oracle provider supports it) before relying on this in
/// production; there is no guarantee one does yet.
interface IAggregatorV3 {
    function decimals() external view returns (uint8);

    function latestRoundData()
        external
        view
        returns (
            uint80 roundId,
            int256 answer,
            uint256 startedAt,
            uint256 updatedAt,
            uint80 answeredInRound
        );
}

contracts/interfaces/ICreatorAware.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @notice The one thing CreatorRewardsDistributor needs from a token it
/// holds creator-reward tokens for: who its creator is. Both LaunchedToken
/// and CustomToken already expose this as a public state variable (an
/// implicit getter) — no changes were needed on either contract beyond this
/// interface declaring the same shape, so a creator transfer on CustomToken
/// (transferCreator/acceptCreator) is always reflected here automatically,
/// never a stale snapshot. Same "depend on the minimal shape, not the
/// concrete contract" approach as IPlatformToken.
interface ICreatorAware {
    function creator() external view returns (address);
}

contracts/interfaces/IPlatformToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/// @notice The minimal slice of PlatformToken that PlatformRewardsDistributor
/// actually needs: the standard ERC20 surface, plus burn() (from
/// ERC20Burnable), the enumerable holder registry (holderCount()/
/// holderAt()), and the per-holder generation stamps (holderGeneration()/
/// holderGenerationCounter()) PlatformToken adds on top. Declared as its
/// own interface, rather than importing the concrete PlatformToken
/// contract, so the distributor only ever depends on this exact shape —
/// including in tests, where a much simpler mock can stand in for it.
interface IPlatformToken is IERC20 {
    function burn(uint256 amount) external;
    function holderCount() external view returns (uint256);
    function holderAt(uint256 index) external view returns (address);
    /// @notice The generation `holder` was most recently (re-)added to the
    /// registry under — see PlatformToken.holderGeneration's own comment.
    /// 0 means the address has never been a holder.
    function holderGeneration(address holder) external view returns (uint256);
    /// @notice The current, live value of PlatformToken's own monotonically
    /// increasing holder-registry-entry counter — see
    /// PlatformToken.holderGenerationCounter's own comment.
    function holderGenerationCounter() external view returns (uint256);
}

contracts/interfaces/ITokenFactoryTaxDef.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./IUniswapV2Router02.sol";

/// @notice The minimal slice of TokenFactory's/CustomTokenFactory's own
/// public tax-default getters that a "deploy only" LaunchedToken/
/// CustomToken needs when it automatically detects, on an ordinary
/// transfer, that a real DEX pool now exists for it — see
/// LaunchedToken._maybeAutoActivateTax and
/// CustomToken._maybeAutoConfigurePlatformTax. TokenFactory and
/// CustomTokenFactory expose an identical set of tax-default getters
/// (same names, same types — confirmed field-by-field against both
/// contracts), so this one interface serves both call sites: router() is
/// only ever called through it from LaunchedToken (CustomToken already
/// has its own `router` state variable and never needs this factory's).
/// Every function here is already a plain public state-variable getter on
/// both factories today — neither factory needed any code change to
/// support this.
interface ITokenFactoryTaxDefaults {
    function router() external view returns (IUniswapV2Router02);
    function feeBps() external view returns (uint256);
    function platformFeeWallet() external view returns (address);
    function priceFeed() external view returns (address);
    function graduationTargetUsd() external view returns (uint256);
    function maxOracleStaleness() external view returns (uint256);
    function rewardsDistributor() external view returns (address);
    function rewardBps() external view returns (uint256);
    function creatorRewardsDistributor() external view returns (address);
    function creatorRewardBps() external view returns (uint256);
    function feeWalletDistributor() external view returns (address);
}

contracts/interfaces/IUniswapV2Pair.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @notice The minimal slice of a real Uniswap V2 pair contract that
/// LaunchedToken needs to read its own live pool reserves for the market
/// cap check that decides when its transfer tax permanently disables.
/// Matches the real interface exactly, so a real pair address drops in
/// without any code change here.
interface IUniswapV2PairMinimal {
    function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast);
    function token0() external view returns (address);
}

contracts/interfaces/IUniswapV2Router02..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @notice The minimal slice of the Uniswap V2 Router interface TokenFactory
/// actually needs. Point this at whatever Uniswap V2-style router Robinhood
/// Chain's DEX exposes — the interface is the de facto standard across V2
/// forks (Uniswap, Sushiswap, Camelot's V2 mode, etc.), so no code change
/// should be needed beyond the deployed address.
interface IUniswapV2Router02 {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);

    function addLiquidityETH(
        address token,
        uint256 amountTokenDesired,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    )
        external
        payable
        returns (uint256 amountToken, uint256 amountETH, uint256 liquidity);

    /// @notice Buy variant that tolerates a fee-on-transfer token on the
    /// output side — required here because LaunchedToken can carry a live
    /// transfer tax. Unlike the plain swapExactETHForTokens, this never
    /// returns a pre-computed amounts array (that array would be wrong for
    /// a taxed token); callers must measure what actually landed via a
    /// before/after balance diff on `to`, same as the router itself does
    /// internally.
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external payable;

    /// @notice Sell variant that tolerates a fee-on-transfer token on the
    /// input side, for the same reason as above.
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external;

    /// @notice Token-for-token variant, same fee-on-transfer tolerance as
    /// above. CustomToken uses this to swap collected fee tokens for
    /// whatever ERC20 a creator picked as their reflection asset, routed
    /// through WETH (path = [ourToken, WETH, reflectionAsset]) since a
    /// direct pair against an arbitrary token isn't something this project
    /// can assume exists.
    function swapExactTokensForTokensSupportingFeeOnTransferTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external;
}

/// @notice The one function TokenFactory needs from the paired Uniswap V2
/// Factory contract, to look up the pair address created for a token so its
/// LP tokens can be locked and its tax can be pointed at the right pool.
interface IUniswapV2FactoryMinimal {
    function getPair(address tokenA, address tokenB) external view returns (address pair);
}

contracts/LaunchedToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";

import "./interfaces/IAggregatorV3.sol";
import "./interfaces/IUniswapV2Pair.sol";
import "./interfaces/IUniswapV2Router02.sol";
import "./interfaces/ITokenFactoryTaxDefaults.sol";

/// @title LaunchedToken
/// @notice The ERC20 every launch deploys as an EIP-1167 clone of this
/// implementation. What happens next depends entirely on which mode
/// TokenFactory launched it under:
///
///  - "Just Launch": the full supply mints straight to the creator's own
///    wallet. configureTax() is never called for this token, so it behaves
///    as a completely ordinary, untaxed ERC20 for its entire life —
///    creating a pool and adding liquidity anywhere, any time, by whatever
///    means, is entirely the creator's own responsibility from here.
///
///  - "Launch + Add Liquidity": the full supply mints to TokenFactory,
///    which immediately pairs it into a real DEX pool and then calls
///    configureTax() exactly once, pointing this token at that pool. From
///    that moment on, every transfer that touches the pool (a buy or a
///    sell) has feeBps skimmed to feeWallet — this is the only way to
///    collect a fee against a real Uniswap V2-style pool, since those
///    pools have no transaction hooks of their own. After every taxed
///    transfer this token checks the pool's live market cap (via a
///    Chainlink-style price feed) and permanently disables the tax,
///    forever, the moment that market cap crosses graduationTargetUsd.
contract LaunchedToken is ERC20 {
    bool private _initialized;

    address public creator;
    address public factory;
    uint256 public launchedAt;
    string private _tokenName;
    string private _tokenSymbol;

    /// @notice FIX (this review, Finding TF-1): true for a token cloned and
    /// initialized by a bonding-curve factory (currently BondingCurveFactory
    /// — every "Quick Launch" curve token), false for a token cloned by
    /// TokenFactory (both "Deploy Token" and "Deploy and Add Liquidity").
    /// Set once, at initialize() time, and never changed afterward — same
    /// "immutable after init" convention as `factory` itself.
    ///
    /// The ONLY thing this flag does is gate _maybeAutoActivateTax() in
    /// _update() below (see that function's own doc comment for the full
    /// vulnerability this closes): a curve-managed token never runs that
    /// auto-detection at all, no matter what transfer triggers it or what
    /// pool a third party may have pre-created for its address, because a
    /// curve-managed token's tax is only ever meant to activate through its
    /// factory's own explicit graduation call (see
    /// BondingCurveFactory._doGraduate -> configureTax()). It has no other
    /// effect anywhere in this contract — feeBps, feeWallet, pair,
    /// taxActive, and every reward-diversion field still only ever get set
    /// by configureTax() itself for either kind of token.
    bool public curveManaged;

    // ---- tax state, set once via configureTax(). Everything below stays
    // zero/false/unset for a "Just Launch" token, which never calls
    // configureTax() at all. ----
    bool public taxConfigured;
    address public pair;
    address public feeWallet;
    uint256 public feeBps; // 100 = 1.00%
    bool public taxActive;
    IAggregatorV3 public priceFeed;
    uint256 public graduationTargetUsd; // whole dollars, e.g. 50000
    uint256 public maxOracleStaleness; // seconds; the tax-disable check is skipped (never reverted) if the feed is older than this

    // ---- reward diversion: carves a slice of the platform's own feeBps
    // cut off to PlatformRewardsDistributor instead of feeWallet, on every
    // taxed transfer. Snapshotted once, in configureTax(), same "applies
    // going forward only" convention as every other tax default here.
    // rewardsDistributor == address(0) (the default) means this is
    // entirely inactive and every taxed transfer behaves exactly as it did
    // before this feature existed — 100% of feeBps still goes to
    // feeWallet. ----
    address public rewardsDistributor;
    uint256 public rewardBps; // absolute bps of transfer value diverted to rewardsDistributor, carved OUT OF feeBps (never on top of it); rewardBps + creatorRewardBps always <= feeBps

    // ---- creator rewards: a second, independent carve-out of feeBps, sent
    // in-kind to CreatorRewardsDistributor on every taxed transfer — never
    // stacked with rewardBps above (rewardBps + creatorRewardBps <= feeBps
    // is enforced once, in configureTax()). CreatorRewardsDistributor later
    // swaps its accumulated balance of this token for ETH and credits this
    // token's own creator, claimable through that contract (see
    // CreatorRewardsDistributor.sol). Same address(0)-means-inactive
    // convention as rewardsDistributor: creatorRewardsDistributor ==
    // address(0) (the default) means this is entirely inactive and
    // whatever feeBps isn't already carved to rewardsDistributor still
    // goes to feeWallet in full. ----
    address public creatorRewardsDistributor;
    uint256 public creatorRewardBps; // absolute bps of transfer value diverted to creatorRewardsDistributor, carved OUT OF feeBps (never on top of it, and never overlapping rewardBps)

    // ---- fee-wallet auto-conversion: redirects the REMAINDER of feeBps
    // (fee - rewardCut - creatorCut, i.e. whatever wasn't already carved off
    // to rewardsDistributor/creatorRewardsDistributor above) to
    // FeeWalletDistributor in-kind, instead of straight to feeWallet.
    // Unlike rewardBps/creatorRewardBps this has no bps of its own to
    // configure — it's just a different destination for the same
    // remainder — so it's a single address, snapshotted once in
    // configureTax() like every other distributor here.
    // feeWalletDistributor == address(0) (the default) means this is
    // entirely inactive and the remainder still goes straight to feeWallet
    // as a plain token transfer, exactly as it always has. ----
    address public feeWalletDistributor;

    /// @notice Hard ceiling on totalSupply_, enforced once at initialize().
    /// Purely defense-in-depth: currentMarketCapInFeedDecimals()'s own
    /// arithmetic (usdPerToken * totalSupply()) would need a totalSupply in
    /// the neighborhood of 1e44 tokens to have any realistic path to
    /// overflowing a uint256 at ordinary prices — utterly outside anything
    /// a real launch would ever use — but capping it here at 1 quadrillion
    /// tokens (comfortably above real-world outliers like PEPE's ~420
    /// trillion or SHIB's ~589 trillion supply) removes that edge case
    /// entirely rather than relying on it staying implausible. See
    /// _computeMarketCapFromPair for the other half of this hardening (a
    /// revert in the graduation math is caught, not left to brick trading).
    uint256 public constant MAX_TOTAL_SUPPLY = 1_000_000_000_000_000 * 1e18; // 1 quadrillion tokens, 18 decimals

    /// @notice Once a taxed transfer first observes the pool's market cap at
    /// or above graduationTargetUsd, this records when — rather than
    /// disabling the tax immediately off that one instantaneous reading.
    /// 0 means "not currently a graduation candidate". See
    /// _maybeDisableTax() for why: a single spot-price read is cheap to
    /// manipulate temporarily (a large trade against a pool whose totalSupply
    /// dwarfs its real liquidity can imply a market cap far beyond the
    /// pool's actual ETH value for exactly one instant), so graduation now
    /// requires the target to still be met on a later transfer, at least
    /// GRADUATION_CONFIRMATION_WINDOW after the first qualifying
    /// observation — and any transfer that observes the target no longer
    /// met in between resets this back to 0, so unwinding a manipulated
    /// position (itself a transfer against the pool) undoes the candidate
    /// window instead of letting it quietly finish counting down.
    uint256 public graduationCandidateAt;

    /// @notice Minimum time a pool's market cap must stay at or above
    /// graduationTargetUsd, confirmed across at least two separate
    /// pair-touching transfers, before the tax actually disables. Fixed
    /// rather than owner-configurable — this is a security property of
    /// every launch, not a tunable default.
    uint256 public constant GRADUATION_CONFIRMATION_WINDOW = 30 minutes;

    event TokenInitialized(string name, string symbol, uint256 totalSupply, address indexed creator);
    event TaxConfigured(address indexed pair, address indexed feeWallet, uint256 feeBps, uint256 graduationTargetUsd);
    event TaxDisabled(uint256 marketCapInFeedDecimals);
    event GraduationCandidateObserved(uint256 marketCapInFeedDecimals, uint256 confirmEligibleAt);
    event GraduationCandidateReset();
    event PriceFeedUpdated(address indexed newPriceFeed, uint256 newMaxOracleStaleness);

    modifier onlyFactory() {
        require(msg.sender == factory, "LaunchedToken: caller is not the factory");
        _;
    }

    // Runs exactly once, on the implementation contract TokenFactory clones
    // from. Never runs again on any clone.
    constructor() ERC20("", "") {
        _initialized = true;
    }

    /// @param curveManaged_ FIX (this review, Finding TF-1): true only when
    /// the caller is a bonding-curve factory (BondingCurveFactory today)
    /// cloning this token for curve trading; false for every TokenFactory
    /// launch ("Deploy Token" or "Deploy and Add Liquidity"). See the
    /// curveManaged state variable's own doc comment above for exactly what
    /// this does and why it's needed.
    function initialize(
        string memory name_,
        string memory symbol_,
        uint256 totalSupply_,
        address creator_,
        address mintTo_,
        address factory_,
        bool curveManaged_
    ) external {
        require(!_initialized, "LaunchedToken: already initialized");
        require(totalSupply_ > 0, "LaunchedToken: supply must be > 0");
        require(totalSupply_ <= MAX_TOTAL_SUPPLY, "LaunchedToken: supply too large");
        require(creator_ != address(0), "LaunchedToken: invalid creator");
        require(mintTo_ != address(0), "LaunchedToken: invalid mint recipient");
        require(factory_ != address(0), "LaunchedToken: invalid factory");

        _initialized = true;
        _tokenName = name_;
        _tokenSymbol = symbol_;
        creator = creator_;
        factory = factory_;
        curveManaged = curveManaged_;
        launchedAt = block.timestamp;

        _mint(mintTo_, totalSupply_);

        emit TokenInitialized(name_, symbol_, totalSupply_, creator_);
    }

    /// @notice One-time wiring step, called by TokenFactory immediately
    /// after it seeds this token's DEX pool (see
    /// TokenFactory._launchWithLiquidity) — never called at all for a
    /// "Just Launch" token. Passing feeBps_ == 0 or a zero feeWallet_
    /// records the pair but leaves the tax permanently inactive.
    function configureTax(
        address pair_,
        address feeWallet_,
        uint256 feeBps_,
        address priceFeed_,
        uint256 graduationTargetUsd_,
        uint256 maxOracleStaleness_,
        address rewardsDistributor_,
        uint256 rewardBps_,
        address creatorRewardsDistributor_,
        uint256 creatorRewardBps_,
        address feeWalletDistributor_
    ) external onlyFactory {
        require(!taxConfigured, "LaunchedToken: tax already configured");
        require(pair_ != address(0), "LaunchedToken: invalid pair");
        // FIX (post-audit, HoodLaunch_TokenFactory_LaunchedToken_Audit —
        // Finding F-3, hardening): configureTax() is onlyFactory, so feeBps_
        // is only ever attacker-controlled if the factory itself is
        // compromised or misconfigured — but at that point this was the only
        // remaining place a fee above TokenFactory's own MAX_FEE_BPS ceiling
        // could reach a live token with no local check of its own. Bounding
        // it here too costs nothing and removes the dependency on the
        // caller always doing so correctly.
        require(feeBps_ <= 2_000, "LaunchedToken: feeBps exceeds 20% ceiling");
        // FIX (this review, hardening — same rationale as Finding F-3 above):
        // TokenFactory.setTaxDefaults already requires graduationTargetUsd_ > 0
        // and maxOracleStaleness_ > 0 unconditionally before either value is
        // ever stored, so in TokenFactory's own normal flow these can never
        // reach this function as 0 in the first place. But exactly like
        // feeBps_ above, configureTax() is the last line of defense if the
        // factory itself is ever compromised or misconfigured — and unlike
        // feeBps_, neither value had a local backstop here. A 0
        // graduationTargetUsd_ would make _maybeDisableTaxWithDecimals treat
        // any nonzero market cap as already past graduation, disabling the
        // tax on the very next confirmed transfer; a 0 maxOracleStaleness_
        // makes currentMarketCapInFeedDecimals's own freshness check
        // (block.timestamp - updatedAt > maxOracleStaleness) fail almost
        // immediately for any real oracle round, permanently treating the
        // feed as stale and leaving the tax stuck on forever instead of ever
        // gracefully disabling. Bounding both here too costs nothing and
        // removes the dependency on the caller always doing so correctly.
        require(graduationTargetUsd_ > 0, "LaunchedToken: graduation target must be > 0");
        require(maxOracleStaleness_ > 0, "LaunchedToken: oracle staleness must be > 0");
        require(rewardBps_ + creatorRewardBps_ <= feeBps_, "LaunchedToken: rewardBps+creatorRewardBps exceeds feeBps");
        require(rewardsDistributor_ != address(0) || rewardBps_ == 0, "LaunchedToken: rewardBps requires a distributor");
        require(
            creatorRewardsDistributor_ != address(0) || creatorRewardBps_ == 0,
            "LaunchedToken: creatorRewardBps requires a distributor"
        );

        taxConfigured = true;
        pair = pair_;
        feeWallet = feeWallet_;
        feeBps = feeBps_;
        priceFeed = IAggregatorV3(priceFeed_);
        graduationTargetUsd = graduationTargetUsd_;
        maxOracleStaleness = maxOracleStaleness_;
        taxActive = feeBps_ > 0 && feeWallet_ != address(0);
        rewardsDistributor = rewardsDistributor_;
        rewardBps = rewardBps_;
        creatorRewardsDistributor = creatorRewardsDistributor_;
        creatorRewardBps = creatorRewardBps_;
        feeWalletDistributor = feeWalletDistributor_;

        emit TaxConfigured(pair_, feeWallet_, feeBps_, graduationTargetUsd_);
    }

    /// @notice Escape hatch for a price feed that's gone permanently stale
    /// or was never a real, maintained feed to begin with (a real risk on a
    /// young chain — see the comment on IAggregatorV3). Callable only by
    /// the factory, which gates it behind its own owner (see
    /// TokenFactory.updateTokenPriceFeed) — never by the creator or anyone
    /// else. Deliberately narrow: it repoints the oracle inputs the
    /// graduation check reads, and nothing else. It cannot touch feeBps,
    /// feeWallet, pair, or taxActive directly, and disabling the tax still
    /// requires the same currentMarketCapInFeedDecimals()/confirmation-
    /// window path as ever — this only unblocks that path when it would
    /// otherwise be stuck forever behind a dead oracle, it doesn't grant a
    /// shortcut around it.
    ///
    /// This also only WORKS when the current feed is actually the dead-
    /// oracle case it's meant for: the require below reuses this contract's
    /// own currentMarketCapInFeedDecimals() freshness check and reverts if
    /// the existing feed can still report a fresh price. Without this
    /// guard the owner could repoint a perfectly healthy, currently-live
    /// token's oracle inputs at any time for any reason — an ongoing lever
    /// over whether/when that token's tax ever turns off. With it, the
    /// owner can only act once the current feed has genuinely stopped
    /// delivering fresh data (dead/reverting, stale beyond
    /// maxOracleStaleness, or returning a non-positive/future-dated round),
    /// matching the escape-hatch use case this function documents rather
    /// than an unrestricted standing power.
    function updatePriceFeed(address newPriceFeed_, uint256 newMaxOracleStaleness_) external onlyFactory {
        require(taxConfigured, "LaunchedToken: tax not configured");
        require(newPriceFeed_ != address(0), "LaunchedToken: invalid price feed");
        require(newMaxOracleStaleness_ > 0, "LaunchedToken: oracle staleness must be > 0");
        (, bool feedIsFresh) = currentMarketCapInFeedDecimals();
        require(!feedIsFresh, "LaunchedToken: current price feed is still fresh, cannot be repointed");
        priceFeed = IAggregatorV3(newPriceFeed_);
        maxOracleStaleness = newMaxOracleStaleness_;
        emit PriceFeedUpdated(newPriceFeed_, newMaxOracleStaleness_);
    }

    function name() public view override returns (string memory) { return _tokenName; }
    function symbol() public view override returns (string memory) { return _tokenSymbol; }

    /// @notice Permissionless, automatic activation of the platform's tax
    /// for a "Just Launch" token (100% minted straight to the creator, no
    /// pool, configureTax() never called) the moment a real DEX pool for
    /// it is first detected on-chain — closes the gap where a creator who
    /// deploys "Just Launch" and later adds liquidity entirely on their
    /// own, outside this platform, would otherwise leave the platform's
    /// tax permanently unreachable even though a real, tradeable pool now
    /// exists. See the contract-level doc comment above.
    ///
    /// Called from the very top of _update(), gated there on
    /// `!taxConfigured` — once taxConfigured is true (whether because a
    /// pool was found this way, or because this is actually a "Launch +
    /// Add Liquidity" token that had configureTax() called on it back at
    /// launch) this function is never even invoked again, so the overhead
    /// below disappears forever. Until then, this is a deliberate,
    /// disclosed tradeoff: EVERY transfer of a still-pool-less token pays
    /// the extra gas of this detection attempt (a couple of staticcalls),
    /// in exchange for activation needing no explicit call from anyone,
    /// ever.
    ///
    /// FIX (this review, Finding TF-1): _update() now also gates this call
    /// on `!curveManaged`, so a bonding-curve token (BondingCurveFactory)
    /// never reaches this function at all, no matter what transfer would
    /// otherwise trigger it. Before this fix, this same detection ran on
    /// any curve-token transfer where `from` wasn't the factory — which
    /// includes an ordinary curve sell() (transferFrom(seller, factory,
    /// amount)) and any plain wallet-to-wallet transfer of already-bought
    /// curve tokens, both routine actions any holder takes well before a
    /// curve ever graduates. Since creating an empty (zero-reserve)
    /// Uniswap pair for an arbitrary token address is permissionless and
    /// nearly free, anyone could pre-create one for a brand-new curve
    /// token, then simply wait for the next ordinary sell/transfer to
    /// silently flip taxConfigured to true against that empty shell —
    /// after which BondingCurveFactory._doGraduate()'s own configureTax()
    /// call would revert forever on `require(!taxConfigured)`, permanently
    /// and irreversibly blocking that token from ever graduating to a real,
    /// LP-locked pool. A curve-managed token's tax is only ever meant to
    /// activate through its own factory's explicit graduation call, never
    /// through this auto-detection path, which exists purely for
    /// TokenFactory's "Just Launch" mode.
    ///
    /// Returns true only if THIS call is the one that just flipped
    /// taxConfigured on, so _update() can make sure the exact transfer
    /// that seeds the newly-found pool is never itself taxed — see
    /// _update()'s use of the return value below.
    ///
    /// @dev External purely so _update() can wrap it in try/catch (see
    /// _computeMarketCapFromPair below for the same pattern already used
    /// in this contract — Solidity's try/catch only guards external
    /// calls, never arbitrary internal logic). Not meant to be called by
    /// anything but this contract itself, hence the msg.sender check.
    /// This matters here specifically because _update() calls this
    /// unconditionally on every transfer of a still-pool-less token,
    /// including the very first mint inside initialize() — factory/router
    /// are ordinarily real, correctly-implemented contracts, but if
    /// either one were ever misconfigured, temporarily misbehaving, or
    /// simply not a real factory/router at all, every external call below
    /// would revert; without try/catch that revert would propagate out of
    /// _update() and brick the mint/transfer that triggered it, instead
    /// of just leaving this detection attempt unable to run this time.
    function _maybeAutoActivateTax() external returns (bool justActivated) {
        require(msg.sender == address(this), "LaunchedToken: internal only");
        if (taxConfigured) return false;

        ITokenFactoryTaxDefaults tokenFactory = ITokenFactoryTaxDefaults(factory);
        IUniswapV2Router02 factoryRouter = tokenFactory.router();
        address dexFactory = factoryRouter.factory();
        address weth = factoryRouter.WETH();
        address detectedPair = IUniswapV2FactoryMinimal(dexFactory).getPair(address(this), weth);
        if (detectedPair == address(0)) return false; // no pool yet — the common case for most transfers

        // No "snapshot at deploy time" exists for a Just Launch token,
        // since none was ever taken — the platform's tax defaults in
        // effect at the moment a pool is first detected are the only
        // sensible ones to apply, read straight off TokenFactory's
        // current storage exactly like TokenFactory._launchWithLiquidity
        // reads its own storage when it seeds a pool itself.
        uint256 feeBps_ = tokenFactory.feeBps();
        address platformFeeWallet_ = tokenFactory.platformFeeWallet();
        address priceFeed_ = tokenFactory.priceFeed();
        uint256 graduationTargetUsd_ = tokenFactory.graduationTargetUsd();
        uint256 maxOracleStaleness_ = tokenFactory.maxOracleStaleness();
        address rewardsDistributor_ = tokenFactory.rewardsDistributor();
        address creatorRewardsDistributor_ = tokenFactory.creatorRewardsDistributor();
        address feeWalletDistributor_ = tokenFactory.feeWalletDistributor();

        // Same "distributor unset -> bps forced to 0" defense
        // TokenFactory._launchWithLiquidity applies before calling
        // configureTax() — replicated here rather than trusting the raw
        // getters directly, even though TokenFactory's own invariants
        // should already guarantee this.
        uint256 rewardBps_ = rewardsDistributor_ != address(0) ? tokenFactory.rewardBps() : 0;
        uint256 creatorRewardBps_ = creatorRewardsDistributor_ != address(0) ? tokenFactory.creatorRewardBps() : 0;

        // Same invariant configureTax() itself enforces via require —
        // but this runs inside an arbitrary caller's ordinary transfer,
        // so a platform-side misconfiguration must never revert (brick)
        // that unrelated transfer. Skip activation this time instead;
        // taxConfigured stays false, so a later transfer can retry once/
        // if the platform's own config is fixed.
        if (rewardBps_ + creatorRewardBps_ > feeBps_) return false;

        taxConfigured = true;
        pair = detectedPair;
        feeWallet = platformFeeWallet_;
        feeBps = feeBps_;
        priceFeed = IAggregatorV3(priceFeed_);
        graduationTargetUsd = graduationTargetUsd_;
        maxOracleStaleness = maxOracleStaleness_;
        taxActive = feeBps_ > 0 && platformFeeWallet_ != address(0);
        rewardsDistributor = rewardsDistributor_;
        rewardBps = rewardBps_;
        creatorRewardsDistributor = creatorRewardsDistributor_;
        creatorRewardBps = creatorRewardBps_;
        feeWalletDistributor = feeWalletDistributor_;

        emit TaxConfigured(detectedPair, platformFeeWallet_, feeBps_, graduationTargetUsd_);
        return true;
    }

    /// @dev The tax itself. Skims feeBps to feeWallet on any transfer that
    /// touches the pool directly (a buy sends pair -> someone; a sell sends
    /// someone -> pair). Every other transfer — the factory's own seeding
    /// transfer into the pair inside addLiquidityETH (taxActive is still
    /// false at that point, since configureTax runs right after), the
    /// initial mint, and any ordinary wallet-to-wallet transfer (neither
    /// side is ever the pool) — passes through untaxed automatically,
    /// since none of those match `from == pair || to == pair` while taxed.
    function _update(address from, address to, uint256 value) internal override {
        // Auto-detect an independently-created pool before anything else
        // below runs — see _maybeAutoActivateTax(). Skipped once
        // taxConfigured (the common case after the first pool-detecting
        // transfer, or for the entire life of a "Launch + Add Liquidity"
        // token, which starts out with taxConfigured already true) and
        // skipped whenever `from == factory`: that's specifically
        // TokenFactory's own internal liquidity-seeding transfer inside
        // its atomic "Launch + Add Liquidity" flow (see
        // TokenFactory._launchWithLiquidity/_relayedLaunchWithLiquidity,
        // both of which mint the full supply to `address(this)` and then
        // transfer it into the freshly-created pair via addLiquidityETH,
        // strictly BEFORE calling configureTax() themselves). Without this
        // guard, that same internal transfer would race ahead and
        // self-configure the tax here first, and TokenFactory's own
        // explicit configureTax() call right after would then revert on
        // `require(!taxConfigured)`, permanently breaking every atomic
        // launch. A "Just Launch" token's creator can never trip this
        // guard by accident: TokenFactory never holds any of a
        // deploy-only token's supply (100% mints straight to the
        // creator), so `from` can never equal `factory` for that token's
        // own, later, independent liquidity add.
        // Wrapped in try/catch (see _maybeAutoActivateTax's own doc
        // comment for why) so a misbehaving/incomplete factory or router
        // can never brick this transfer — it just leaves taxConfigured
        // false for now, retried on a later one.
        //
        // FIX (this review, Finding TF-1): also gated on `!curveManaged`.
        // A bonding-curve token's `factory` field points at its curve
        // factory (BondingCurveFactory), which is never the sender on a
        // curve sell() (that's a transferFrom FROM the seller) or on any
        // ordinary wallet-to-wallet transfer of curve tokens — both are
        // routine, unprivileged actions that would otherwise satisfy
        // `from != factory` well before graduation. Without this guard, a
        // third party could permissionlessly pre-create an empty DEX pair
        // for the token's address and let the very next such transfer
        // auto-activate the tax against it, permanently blocking
        // BondingCurveFactory._doGraduate()'s own configureTax() call
        // (`require(!taxConfigured)`) from ever succeeding again — see
        // _maybeAutoActivateTax's own doc comment for the full writeup.
        // curveManaged is false for every TokenFactory-launched token, so
        // this changes nothing about that existing, intended feature.
        bool justActivated = false;
        if (!taxConfigured && !curveManaged && from != factory) {
            try this._maybeAutoActivateTax() returns (bool activated) {
                justActivated = activated;
            } catch {
                justActivated = false;
            }
        }

        // `justActivated` forces this exact transfer down the untaxed
        // passthrough branch below even though `to` (or `from`) now
        // equals the pair that was just set moments ago in this same
        // call — mirrors the existing, always-untaxed factory-launched
        // seeding transfer (there, taxActive is still false at that
        // point since configureTax() runs strictly after addLiquidityETH
        // returns). Taxation begins with the next transfer that touches
        // the pool, not this one.
        if (!justActivated && taxActive && value > 0 && (from == pair || to == pair)) {
            uint256 fee = (value * feeBps) / 10_000;
            if (fee > 0) {
                // rewardCut and creatorCut are both carved OUT OF fee, never
                // added on top of it — the platform's total take on this
                // transfer stays exactly feeBps, same as before either
                // feature existed. rewardBps + creatorRewardBps <= feeBps is
                // enforced once, at configureTax(), so this can never
                // underflow.
                uint256 rewardCut = (rewardsDistributor != address(0) && rewardBps > 0) ? (value * rewardBps) / 10_000 : 0;
                uint256 creatorCut = (creatorRewardsDistributor != address(0) && creatorRewardBps > 0) ? (value * creatorRewardBps) / 10_000 : 0;
                uint256 toFeeWallet = fee - rewardCut - creatorCut;
                if (rewardCut > 0) super._update(from, rewardsDistributor, rewardCut);
                if (creatorCut > 0) super._update(from, creatorRewardsDistributor, creatorCut);
                // Routes to FeeWalletDistributor in-kind when set, for later
                // automatic ETH conversion (see FeeWalletDistributor.sol);
                // otherwise falls straight to feeWallet exactly as before
                // this feature existed.
                if (toFeeWallet > 0) {
                    super._update(from, feeWalletDistributor != address(0) ? feeWalletDistributor : feeWallet, toFeeWallet);
                }
                super._update(from, to, value - fee);
            } else {
                super._update(from, to, value);
            }
            _maybeDisableTax();
        } else {
            super._update(from, to, value);
        }
    }

    /// @notice Current market cap in the price feed's own decimals (e.g. 8
    /// for a typical Chainlink USD feed), or (0, false) if there's no pool
    /// yet, the feed can't be read, or its data is stale beyond
    /// maxOracleStaleness. A stale/broken feed never blocks trading — it
    /// only means the tax-disable check can't run until the feed recovers.
    ///
    /// The pool-reads-and-arithmetic half of this (everything past the
    /// oracle call) is delegated to _computeMarketCapFromPair() through an
    /// external self-call specifically so it can sit behind its own
    /// try/catch: unlike the oracle call, that inner computation was
    /// previously unguarded, so any revert from it (a misbehaving pair, or
    /// arithmetic overflow) would have propagated out of here, out of
    /// _maybeDisableTax(), and reverted the entire transfer instead of just
    /// leaving the tax-disable check unable to run this time.
    function currentMarketCapInFeedDecimals() public view returns (uint256 marketCap, bool feedIsFresh) {
        if (pair == address(0)) return (0, false);
        try priceFeed.latestRoundData() returns (uint80, int256 answer, uint256, uint256 updatedAt, uint80) {
            if (answer <= 0) return (0, false);
            // updatedAt > block.timestamp (a future-dated round — a
            // misbehaving, misconfigured, or compromised feed) is checked
            // explicitly before the subtraction below. Solidity's try/catch
            // only guards a revert thrown by the external call itself
            // (priceFeed.latestRoundData()); a revert thrown by code here,
            // after that call already succeeded — such as an underflow
            // panic from block.timestamp - updatedAt when updatedAt is in
            // the future — is NOT caught, and would otherwise propagate all
            // the way out of _maybeDisableTax() and revert the entire
            // transfer, permanently bricking trading against this token
            // until the owner intervenes. Treating a future-dated round the
            // same as a stale one (fail open: skip the check, never revert)
            // keeps this function's own documented contract ("a stale/
            // broken feed never blocks trading").
            if (updatedAt > block.timestamp || block.timestamp - updatedAt > maxOracleStaleness) return (0, false);

            try this._computeMarketCapFromPair(uint256(answer)) returns (uint256 mc, bool ok) {
                if (!ok) return (0, false);
                return (mc, true);
            } catch {
                return (0, false);
            }
        } catch {
            return (0, false);
        }
    }

    /// @dev External purely so currentMarketCapInFeedDecimals() can wrap it
    /// in try/catch (Solidity's try/catch only guards external calls) —
    /// this is not meant to be called by anything other than this contract
    /// itself, hence the msg.sender check. Contains everything that reads
    /// the pair and derives a USD market cap from it; isolated here so a
    /// revert anywhere in this block degrades to "can't confirm graduation
    /// right now" instead of bricking the transfer that triggered it.
    function _computeMarketCapFromPair(uint256 ethUsd) external view returns (uint256 marketCap, bool ok) {
        require(msg.sender == address(this), "LaunchedToken: internal only");
        (uint112 reserve0, uint112 reserve1, ) = IUniswapV2PairMinimal(pair).getReserves();
        address token0 = IUniswapV2PairMinimal(pair).token0();
        uint256 tokenReserve = token0 == address(this) ? uint256(reserve0) : uint256(reserve1);
        uint256 ethReserve = token0 == address(this) ? uint256(reserve1) : uint256(reserve0);
        if (tokenReserve == 0) return (0, false);

        uint256 pricePerTokenWei = (ethReserve * 1e18) / tokenReserve;
        uint256 usdPerToken = (pricePerTokenWei * ethUsd) / 1e18;
        marketCap = (usdPerToken * totalSupply()) / 1e18;
        ok = true;
    }

    /// @notice Graduation requires the market cap target to be met on TWO
    /// separate observations, at least GRADUATION_CONFIRMATION_WINDOW apart,
    /// rather than disabling the tax off a single instantaneous reading.
    ///
    /// Why: a pool's spot price is cheap to move temporarily, and because
    /// marketCap here is spot price * totalSupply(), a typical launch's
    /// enormous totalSupply relative to its actual (thin, freshly-seeded)
    /// liquidity means a comparatively small, temporary trade can imply a
    /// market cap far beyond the pool's real ETH value for exactly one
    /// instant — see the audit note in the repo. Requiring the target to
    /// still hold on a later, separate transfer means unwinding the
    /// manipulating position — itself a transfer against this same pool —
    /// resets graduationCandidateAt back to 0 before confirmation can ever
    /// complete, so an attacker has to keep real capital committed and the
    /// price genuinely elevated for the entire window, not just for one
    /// instant.
    function _maybeDisableTax() internal {
        if (!taxActive) return;
        (uint256 marketCap, bool feedIsFresh) = currentMarketCapInFeedDecimals();
        if (!feedIsFresh) return; // oracle hiccup: leave any in-progress candidacy exactly as it was

        // FIX (post-audit, HoodLaunch_TokenFactory_LaunchedToken_Audit —
        // Finding F-1): priceFeed.decimals() was called here unguarded,
        // immediately after the freshness check above. A price feed that
        // returns a fresh round from latestRoundData() but reverts (or runs
        // out of gas) on decimals() — plausible for a non-standard or buggy
        // aggregator — would propagate that revert straight out of
        // _maybeDisableTax() and out of _update(), bricking the ENTIRE taxed
        // transfer for as long as the feed stays in that state. Wrapped in
        // its own try/catch so a failure here degrades to "can't confirm
        // graduation right now" (identical to the existing feedIsFresh
        // fallback above) instead of blocking ordinary trading.
        try priceFeed.decimals() returns (uint8 feedDecimals) {
            _maybeDisableTaxWithDecimals(marketCap, feedDecimals);
        } catch {
            return;
        }
    }

    /// @dev Split out of _maybeDisableTax() so the try/catch above only
    /// wraps the one call that can revert (priceFeed.decimals()) — the rest
    /// of the original logic is unchanged.
    function _maybeDisableTaxWithDecimals(uint256 marketCap, uint8 feedDecimals) private {
        uint256 targetInFeedDecimals = graduationTargetUsd * (10 ** feedDecimals);
        if (marketCap < targetInFeedDecimals) {
            if (graduationCandidateAt != 0) {
                graduationCandidateAt = 0;
                emit GraduationCandidateReset();
            }
            return;
        }

        if (graduationCandidateAt == 0) {
            graduationCandidateAt = block.timestamp;
            emit GraduationCandidateObserved(marketCap, block.timestamp + GRADUATION_CONFIRMATION_WINDOW);
            return;
        }

        if (block.timestamp < graduationCandidateAt + GRADUATION_CONFIRMATION_WINDOW) {
            return; // still within the confirmation window; needs a later transfer to confirm
        }

        taxActive = false;
        emit TaxDisabled(marketCap);
    }

    // ---------------------------------------------------------------
    // Burn: a true burn, callable directly by any holder at any time —
    // unlike the transfer tax above, this has nothing to do with a pool and
    // is never taxed (a burn's `to` is address(0), never `pair`, so the tax
    // branch in _update() above never applies to it). "True burn" means
    // totalSupply actually decreases (OpenZeppelin's ERC20._burn, which
    // routes through the same _update() override as every other transfer)
    // — not a transfer to a dead address that a holder or explorer could
    // mistake for real supply still existing somewhere.
    // ---------------------------------------------------------------

    event TokensBurned(uint256 amount);

    /// @notice Permanently destroys `amount` of the caller's own tokens.
    function burn(uint256 amount) external {
        _burn(msg.sender, amount);
        emit TokensBurned(amount);
    }

    /// @notice Same as burn(), but spends `account`'s allowance to the
    /// caller first — standard OpenZeppelin ERC20Burnable behavior, so a
    /// third-party contract a holder has approved can burn on their behalf
    /// without ever taking custody of the tokens first.
    function burnFrom(address account, uint256 amount) external {
        _spendAllowance(account, msg.sender, amount);
        _burn(account, amount);
        emit TokensBurned(amount);
    }
}

contracts/LiquidityLocker.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable2Step.sol";

/// @title LiquidityLocker
/// @notice Holds LP tokens on a creator's behalf for a fixed period after
/// TokenFactory.addLiquidity() runs, so a creator cannot add liquidity and
/// immediately pull it back out. This is the mechanism that makes
/// "creator-funded liquidity" meaningfully different from an outright rug
/// pull: the creator still chooses the amount, but not when they can
/// withdraw it once it's in.
///
/// This contract intentionally knows nothing about tokenomics or bonding
/// curves — it is a generic timelock for ERC20 balances, keyed by an
/// incrementing lock id, and only TokenFactory is allowed to create new
/// locks.
contract LiquidityLocker is Ownable2Step {
    struct Lock {
        address lpToken;
        address owner;
        uint256 amount;
        uint256 unlockTime;
        bool withdrawn;
    }

    /// @notice The only address allowed to call lock(). Set once, after
    /// deployment, to the TokenFactory address (see deploy script) — kept
    /// as a separate step rather than a constructor argument because
    /// TokenFactory's own constructor needs this locker's address first.
    address public factory;

    Lock[] public locks;
    mapping(address => uint256[]) public locksByOwner;

    /// @notice Running sum of every non-withdrawn lock's amount, per LP
    /// token. Purely a bookkeeping/safety total — lock() checks this
    /// against the token's real balanceOf(this) before recording a new
    /// lock, so a factory bug that tries to over-record a lock beyond what
    /// was actually transferred in gets rejected here rather than silently
    /// accepted. Also what rescueToken() below is not allowed to touch.
    mapping(address => uint256) public totalLocked;

    event FactorySet(address indexed factory);
    event Locked(uint256 indexed lockId, address indexed lpToken, address indexed owner, uint256 amount, uint256 unlockTime);
    event Withdrawn(uint256 indexed lockId, address indexed owner, uint256 amount);
    event TokenRescued(address indexed token, address indexed to, uint256 amount);

    modifier onlyFactory() {
        require(msg.sender == factory, "LiquidityLocker: caller is not the factory");
        _;
    }

    constructor() Ownable(msg.sender) {}

    /// @notice One-time wiring step: point this locker at the TokenFactory
    /// that's allowed to create locks in it. Callable once by the deployer.
    function setFactory(address factory_) external onlyOwner {
        require(factory == address(0), "LiquidityLocker: factory already set");
        require(factory_ != address(0), "LiquidityLocker: invalid factory");
        factory = factory_;
        emit FactorySet(factory_);
    }

    /// @notice Blocked until a factory is wired, so an out-of-order deploy
    /// mistake (renouncing before setFactory() ever runs) can't strand this
    /// instance permanently — with no owner left, factory would be stuck at
    /// address(0) forever and this locker could never hold anything.
    function renounceOwnership() public virtual override onlyOwner {
        require(factory != address(0), "LiquidityLocker: cannot renounce before a factory is wired");
        super.renounceOwnership();
    }

    function lock(
        address lpToken,
        address owner_,
        uint256 amount,
        uint256 unlockTime
    ) external onlyFactory returns (uint256 lockId) {
        require(lpToken != address(0), "LiquidityLocker: invalid lpToken");
        require(owner_ != address(0), "LiquidityLocker: invalid owner");
        require(amount > 0, "LiquidityLocker: amount must be > 0");
        require(unlockTime > block.timestamp, "LiquidityLocker: unlock time must be in the future");

        // Sanity guard, not a substitute for the factory's own correctness:
        // this contract must actually already hold enough of lpToken to
        // back every outstanding lock plus this new one. The real transfer
        // always happens before lock() is called (LP mints straight here
        // via addLiquidityETH's `to` parameter), so this should never fire
        // in normal operation — it exists purely to reject a miscounted or
        // duplicated lock() call rather than silently recording a claim
        // nothing backs.
        uint256 newTotalLocked = totalLocked[lpToken] + amount;
        require(
            IERC20(lpToken).balanceOf(address(this)) >= newTotalLocked,
            "LiquidityLocker: amount exceeds tokens actually held"
        );
        totalLocked[lpToken] = newTotalLocked;

        lockId = locks.length;
        locks.push(Lock({lpToken: lpToken, owner: owner_, amount: amount, unlockTime: unlockTime, withdrawn: false}));
        locksByOwner[owner_].push(lockId);
        emit Locked(lockId, lpToken, owner_, amount, unlockTime);
    }

    /// @notice Claim back LP tokens from a matured lock. Only the original
    /// creator (recorded at lock time) can call this, and only after
    /// unlockTime has passed.
    function withdraw(uint256 lockId) external {
        Lock storage l = locks[lockId];
        require(msg.sender == l.owner, "LiquidityLocker: not lock owner");
        require(block.timestamp >= l.unlockTime, "LiquidityLocker: still locked");
        require(!l.withdrawn, "LiquidityLocker: already withdrawn");

        l.withdrawn = true;
        totalLocked[l.lpToken] -= l.amount;
        bool sent = IERC20(l.lpToken).transfer(msg.sender, l.amount);
        require(sent, "LiquidityLocker: LP transfer failed");

        emit Withdrawn(lockId, msg.sender, l.amount);
    }

    /// @notice Recovers tokens sitting on this contract that were never
    /// claimed by a real lock() call — e.g. sent here directly by mistake
    /// instead of arriving as the `to` recipient of addLiquidityETH.
    /// Structurally cannot reach into anyone's locked LP: the rescuable
    /// amount is capped at this contract's actual balance minus
    /// totalLocked[token], which only ever covers real, outstanding locks.
    function rescueToken(address token, address to, uint256 amount) external onlyOwner {
        require(to != address(0), "LiquidityLocker: invalid recipient");
        uint256 rescuable = IERC20(token).balanceOf(address(this)) - totalLocked[token];
        require(amount <= rescuable, "LiquidityLocker: amount exceeds rescuable balance");

        bool sent = IERC20(token).transfer(to, amount);
        require(sent, "LiquidityLocker: rescue transfer failed");

        emit TokenRescued(token, to, amount);
    }

    function locksOf(address owner_) external view returns (uint256[] memory) {
        return locksByOwner[owner_];
    }

    function lockCount() external view returns (uint256) {
        return locks.length;
    }
}

