// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @notice A minimal contract that reverts on receiving plain ETH -- used to
/// simulate a misbehaving feeTreasury/rewardsDistributor for
/// BondingCurveFactory's fee-distribution isolation tests. See
/// AUDIT-BondingCurveFactory.md Finding 1: before the fix, a fee recipient
/// like this one could block every buy()/sell()/createCurveToken() call --
/// most seriously sell(), trapping every holder's ability to exit.
contract RevertingReceiver {
    receive() external payable {
        revert("RevertingReceiver: nope");
    }
}

contracts/PlatformRewardsDistributor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import "./interfaces/IUniswapV2Router02.sol";
import "./interfaces/IUniswapV2Pair.sol";
import "./interfaces/IPlatformToken.sol";

/// @title PlatformRewardsDistributor
/// @notice Where every "kickback to holders" fee stream on Hood Launch
/// ends up, and the one place that turns it into buyback + burn + holder
/// airdrops of PlatformToken. Two completely separate flows feed it:
///
///  1. Launch-fee revenue: TokenFactory/CustomTokenFactory each send this
///     contract 50% of every deployFee/launchFee collected, in native ETH,
///     the moment a launch finalizes — see
///     TokenFactory._finalizeLaunch / CustomTokenFactory.createCustomToken.
///     The other 50% keeps going to feeTreasury exactly as before.
///  2. Ongoing trading tax: LaunchedToken/CustomToken each carve
///     rewardBps (out of their total feeBps/platformFeeBps platform tax)
///     off of every taxed buy/sell and send it here in-kind — i.e. in
///     whatever token that trade was actually taxed in, not ETH. See
///     LaunchedToken._update / CustomToken._update.
///
/// Both flows are inert until platformToken is configured (see
/// setPlatformToken) — before that, ETH and tokens simply accumulate on
/// this contract's own balance, exactly as documented on every factory's
/// rewardsDistributor field: "prior to that it will be the original
/// system." Nothing about enabling this feature later requires touching
/// any already-launched token or factory again.
///
/// Buyback execution is accumulate-and-batch-trigger, not live-per-trade —
/// the same pattern CustomToken already uses for its own liquidity/
/// marketing/reflection fees (see CustomToken._maybeSwapAndProcess). Both
/// trigger functions are permissionless: anyone (typically an off-chain
/// keeper) can fire one once its threshold is met, but nothing about who
/// calls it changes where the funds go — the split is always the same
/// fixed 50% burn / 50% holder-airdrop-pool.
///
/// Holder payouts are pushed, not claimed: PlatformToken tracks its own
/// live holder set on-chain (see PlatformToken.holderCount/holderAt), and
/// startAirdropRound()/processAirdropBatch() walk it in gas-bounded
/// batches so it stays permissionless and affordable no matter how many
/// holders PlatformToken eventually has.
///
/// --- Security review (this file) ---
/// Two findings from the accompanying audit report are fixed directly in
/// this version — see the inline comments at each site for the mechanics:
///  - Finding PR-1 (Critical): processAirdropBatch could be permanently
///    bricked by a single reverting holder payout.
///  - Finding PR-2 (High): triggerEthBuyback/triggerTokenBuyback had no
///    protocol-side slippage floor, making every permissionless call
///    sandwich-able for MEV profit at the community's expense.
///  - Finding PR-3 (Medium): triggerTokenBuyback's approve() call could
///    permanently revert against non-standard ERC20s (USDT-style) that
///    reject changing a nonzero allowance directly to another nonzero
///    value.
///  - Finding PR-4 (Informational, fixed at the platform owner's explicit
///    request): there was no rescue path for ETH or an ERC20 balance that
///    never clears its own buyback threshold (or, for platformToken
///    specifically, a balance left behind after setPlatformToken() moves
///    on to a different token). rescueEth()/rescueToken() below close this
///    — see each function's own comment for how they avoid the
///    centralization risk a fully unrestricted rescue would otherwise
///    carry: rescueToken() can never touch platformToken's own
///    pendingAirdropTokens or an active round's roundAmount, so holder
///    funds already earmarked for a payout can never be diverted by this.
contract PlatformRewardsDistributor is Ownable2Step, ReentrancyGuard {
    IUniswapV2Router02 public immutable router;

    /// @notice The token every buyback converts into, and every airdrop
    /// pays out in. address(0) (the default) means "not configured yet" —
    /// every trigger/round function below refuses to run until this is
    /// set, but ETH and tokens can still accumulate here harmlessly in the
    /// meantime. See setPlatformToken.
    IPlatformToken public platformToken;

    /// @notice Minimum ETH balance this contract must be holding before
    /// triggerEthBuyback will execute. Purely an anti-dust/anti-griefing
    /// knob (a buyback below this just isn't worth the gas) — owner-tunable,
    /// defaults to 0 (any nonzero balance triggers) until set otherwise.
    uint256 public ethBuybackThreshold;

    /// @notice Same idea as ethBuybackThreshold, but per input token, for
    /// triggerTokenBuyback. Defaults to 0 for every token until the owner
    /// sets one.
    mapping(address => uint256) public tokenBuybackThreshold;

    /// @notice Caps how much of this contract's ETH balance a single
    /// triggerEthBuyback call is allowed to spend — same anti-dump purpose
    /// as CreatorRewardsDistributor.maxSwapAmount, applied to the buy side
    /// here (a large single buy is a visible pump on platformToken's own
    /// chart, the mirror image of a large single sell dumping a launched
    /// token's chart). Defaults to 0, meaning "uncapped" (the original
    /// spend-it-all behavior). Once set, a balance above the cap is spent
    /// down across multiple separate calls instead of one.
    uint256 public maxEthBuybackAmount;

    /// @notice Same as maxEthBuybackAmount, but per input token, for
    /// triggerTokenBuyback — the sell-side counterpart (selling `token` for
    /// platformToken is a sell against `token`'s own pool, same dump risk
    /// CreatorRewardsDistributor.maxSwapAmount exists to bound). Defaults to
    /// 0 (uncapped) per token until the owner sets one.
    mapping(address => uint256) public maxTokenBuybackAmount;

    /// @notice Protective slippage floor applied to every buyback swap in
    /// this contract — see Finding PR-2 in the accompanying audit report.
    /// Before this existed, triggerEthBuyback/triggerTokenBuyback accepted
    /// a purely caller-supplied minTokensOut with no protocol-side floor
    /// computed from the pool(s)' own reserves; since both functions are
    /// deliberately permissionless, that let anyone call them with
    /// minTokensOut == 0 and sandwich their own call for MEV profit at the
    /// expense of the burn/airdrop pool. Same fixed 5.00%-8.00% band, and
    /// the same "whichever is stricter" combination with the caller's own
    /// minTokensOut, already used for CreatorRewardsDistributor's and
    /// FeeWalletDistributor's own swap triggers.
    uint256 public swapSlippageBps = 600; // 6.00% default
    uint256 public constant MIN_SWAP_SLIPPAGE_BPS = 500; // 5.00%
    uint256 public constant MAX_SWAP_SLIPPAGE_BPS = 800; // 8.00%

    /// @notice PlatformToken sitting here, already bought back and already
    /// split, awaiting its turn in the next airdrop round. Frozen into
    /// roundAmount the moment startAirdropRound() runs.
    uint256 public pendingAirdropTokens;

    bool public roundActive;
    uint256 public roundAmount; // total PlatformToken being paid out this round, frozen at round start
    uint256 public roundSupplySnapshot; // denominator: eligible supply frozen at round start (see startAirdropRound)
    uint256 public roundCursor; // next holder-registry index processAirdropBatch will start from

    /// @notice Finding PR-5 fix, layer 1 of 2: platformToken.holderCount()
    /// at the exact moment startAirdropRound() froze roundSupplySnapshot --
    /// the round's own "finish line," frozen the same way its payout pool
    /// and denominator already are. Before this existed, processAirdropBatch()
    /// capped its own walk using a LIVE, freshly re-read holderCount() on
    /// every single call, which let an address that first became a holder
    /// AFTER the round had already started still be walked (if its
    /// registry index fell inside a not-yet-processed batch) and assigned a
    /// share of roundAmount/roundSupplySnapshot -- a pool it was never part
    /// of when the denominator was computed. processAirdropBatch() caps its
    /// walk at whichever is SMALLER of the live holderCount() and this
    /// value, so the round can still tolerate the registry SHRINKING
    /// mid-round (an existing holder's balance dropping to zero, removed via
    /// swap-and-pop, exactly as before) but can never walk past whoever
    /// existed when the round actually started. Every genuine round-start
    /// holder is guaranteed to stay at SOME index below this bound for the
    /// round's entire lifetime (PlatformToken's swap-and-pop only ever moves
    /// an existing entry to a LOWER index, filling a vacated slot -- it never
    /// pushes one higher), so this bound alone never excludes a legitimate
    /// holder. It is not, on its own, enough to EXCLUDE every impostor,
    /// though: that same swap-and-pop mechanic can also hand a freshly
    /// vacated LOW index (still under this bound) to a brand-new holder who
    /// only entered after the round started -- see roundGenerationAtStart
    /// below, layer 2, for how that residual case is closed.
    uint256 public roundHolderCountAtStart;

    /// @notice Finding PR-5 fix, layer 2 of 2: platformToken's own
    /// holderGenerationCounter() at the exact moment startAirdropRound() ran
    /// (captured in the same call already reading holderCount() above, so no
    /// extra external call is introduced). Every address PlatformToken has
    /// ever added to its registry is stamped with the generation counter's
    /// value at the moment of that addition (or re-addition, if it had
    /// previously dropped to zero and left the registry) -- see
    /// PlatformToken.holderGeneration's own comment. processAirdropBatch()
    /// skips any holder whose OWN generation is strictly newer than this
    /// value, regardless of what index it's sitting at -- this is what
    /// actually closes the residual gap layer 1 above cannot: a holder that
    /// recycles a vacated low index via swap-and-pop after the round already
    /// started is correctly identified as ineligible by its generation stamp
    /// alone, independent of the index it happens to occupy.
    uint256 public roundGenerationAtStart;

    event PlatformTokenSet(address indexed newToken);
    event EthBuybackThresholdUpdated(uint256 newThreshold);
    event TokenBuybackThresholdUpdated(address indexed token, uint256 newThreshold);
    event MaxEthBuybackAmountUpdated(uint256 newMax);
    event MaxTokenBuybackAmountUpdated(address indexed token, uint256 newMax);
    event SwapSlippageBpsUpdated(uint256 newBps);
    event EthBuybackTriggered(uint256 ethIn, uint256 tokensOut, uint256 burned, uint256 toAirdrop);
    event TokenBuybackTriggered(address indexed token, uint256 amountIn, uint256 tokensOut, uint256 burned, uint256 toAirdrop);
    event DirectPlatformTokensProcessed(uint256 amountIn, uint256 burned, uint256 toAirdrop);
    event AirdropRoundStarted(uint256 amount, uint256 supplySnapshot, uint256 holderCountAtStart);
    event AirdropBatchProcessed(uint256 fromIndex, uint256 toIndex, uint256 amountDistributed);
    event AirdropPayoutSkipped(address indexed holder, uint256 amount);
    event AirdropRoundCompleted(uint256 totalDistributed);
    /// @notice Finding PR-5 fix, layer 2: fired instead of AirdropPayoutSkipped
    /// when a walked holder is excluded because it entered (or re-entered)
    /// PlatformToken's registry after this round already started -- as
    /// opposed to AirdropPayoutSkipped, which fires for a genuinely eligible
    /// holder whose payout transfer itself failed. No share is computed or
    /// requeued for an ineligible holder here, since it was never part of
    /// roundSupplySnapshot's denominator in the first place.
    event AirdropHolderIneligibleThisRound(address indexed holder, uint256 holderGeneration, uint256 roundGeneration);
    /// @notice Finding PR-4 fix -- see rescueEth/rescueToken below.
    event EthRescued(address indexed to, uint256 amount);
    event TokenRescued(address indexed token, address indexed to, uint256 amount);

    constructor(address router_, address initialOwner_) Ownable(initialOwner_) {
        require(router_ != address(0), "PlatformRewardsDistributor: invalid router");
        router = IUniswapV2Router02(router_);
    }

    /// @notice Where TokenFactory/CustomTokenFactory send their 50% launch-
    /// fee share, and the only way ETH ever lands here.
    receive() external payable {}

    // ---------------------------------------------------------------
    // Admin
    // ---------------------------------------------------------------

    /// @notice Wires up the token every buyback/burn/airdrop from here on
    /// operates on. Deliberately blocked while a round is active or while
    /// PlatformToken is already sitting in pendingAirdropTokens — changing
    /// the token out from under either would orphan that balance in a
    /// token nobody can query it under anymore. Safe to call exactly once,
    /// right when PlatformToken itself launches, per the owner's own plan
    /// ("i would launch the token in conjunction with the launch of the
    /// platform... prior to that it will be the original system").
    function setPlatformToken(address newToken) external onlyOwner {
        require(!roundActive, "PlatformRewardsDistributor: round in progress");
        require(pendingAirdropTokens == 0, "PlatformRewardsDistributor: pending airdrop must clear first");
        platformToken = IPlatformToken(newToken);
        emit PlatformTokenSet(newToken);
    }

    function setEthBuybackThreshold(uint256 newThreshold) external onlyOwner {
        ethBuybackThreshold = newThreshold;
        emit EthBuybackThresholdUpdated(newThreshold);
    }

    function setTokenBuybackThreshold(address token, uint256 newThreshold) external onlyOwner {
        tokenBuybackThreshold[token] = newThreshold;
        emit TokenBuybackThresholdUpdated(token, newThreshold);
    }

    /// @notice See maxEthBuybackAmount's own comment above. 0 means uncapped.
    function setMaxEthBuybackAmount(uint256 newMax) external onlyOwner {
        maxEthBuybackAmount = newMax;
        emit MaxEthBuybackAmountUpdated(newMax);
    }

    /// @notice See maxTokenBuybackAmount's own comment above. 0 means uncapped.
    function setMaxTokenBuybackAmount(address token, uint256 newMax) external onlyOwner {
        maxTokenBuybackAmount[token] = newMax;
        emit MaxTokenBuybackAmountUpdated(token, newMax);
    }

    /// @notice Adjusts the protective slippage floor applied to every
    /// buyback trade — see swapSlippageBps above and Finding PR-2. Bounded
    /// to the same 5.00%-8.00% band used everywhere else in this codebase
    /// for the identical purpose.
    function setSwapSlippageBps(uint256 newBps) external onlyOwner {
        require(newBps >= MIN_SWAP_SLIPPAGE_BPS, "PlatformRewardsDistributor: slippage below 5% floor");
        require(newBps <= MAX_SWAP_SLIPPAGE_BPS, "PlatformRewardsDistributor: slippage above 8% ceiling");
        swapSlippageBps = newBps;
        emit SwapSlippageBpsUpdated(newBps);
    }

    // ---------------------------------------------------------------
    // Buyback triggers — permissionless once the relevant threshold is met
    // ---------------------------------------------------------------

    /// @dev Standard Uniswap V2 constant-product quote (0.30% swap fee baked
    /// into the 997/1000 constants) — used only to derive a protective
    /// slippage floor below, never to execute anything. Same helper as
    /// CreatorRewardsDistributor/FeeWalletDistributor/CustomToken/
    /// CustomTokenFactory's identical utility.
    function _getAmountOut(uint256 amountIn, uint256 reserveIn, uint256 reserveOut) private pure returns (uint256) {
        uint256 amountInWithFee = amountIn * 997;
        uint256 numerator = amountInWithFee * reserveOut;
        uint256 denominator = reserveIn * 1000 + amountInWithFee;
        return numerator / denominator;
    }

    /// @dev Quotes amountIn's expected output at the END of a (possibly
    /// multi-hop) path off each hop's own live pool reserves, chaining the
    /// output of one hop into the input of the next, then applies
    /// swapSlippageBps to the final figure — see Finding PR-2. Generalizes
    /// CreatorRewardsDistributor's/FeeWalletDistributor's single-hop
    /// _protectiveMinOut to the two-hop [token, WETH, platformToken] path
    /// triggerTokenBuyback needs (triggerEthBuyback's own
    /// [WETH, platformToken] path is just the one-hop case of the same
    /// loop). Returns 0 if any hop's pool doesn't exist or has an empty
    /// reserve, which callers treat as "can't compute a protocol floor this
    /// time," falling back to the caller's own minTokensOut rather than
    /// blocking the swap outright — consistent with how every other
    /// quote-derived floor in this codebase degrades on a missing pool.
    function _protectiveMinOut(address[] memory path, uint256 amountIn) private view returns (uint256) {
        address factory = router.factory();
        uint256 amount = amountIn;
        for (uint256 i = 0; i + 1 < path.length; i++) {
            address pairAddr = IUniswapV2FactoryMinimal(factory).getPair(path[i], path[i + 1]);
            if (pairAddr == address(0)) return 0;

            (uint112 reserve0, uint112 reserve1, ) = IUniswapV2PairMinimal(pairAddr).getReserves();
            address token0 = IUniswapV2PairMinimal(pairAddr).token0();
            uint256 reserveIn = token0 == path[i] ? uint256(reserve0) : uint256(reserve1);
            uint256 reserveOut = token0 == path[i] ? uint256(reserve1) : uint256(reserve0);
            if (reserveIn == 0 || reserveOut == 0) return 0;

            amount = _getAmountOut(amount, reserveIn, reserveOut);
        }
        return amount - (amount * swapSlippageBps) / 10_000;
    }

    /// @notice Swaps up to maxEthBuybackAmount of this contract's ETH
    /// balance for platformToken (the entire balance, if no cap is set) and
    /// splits the result 50% burned / 50% into the airdrop pool. Anyone can
    /// call this (e.g. a scheduled keeper) — the destination of the funds
    /// never depends on who calls it.
    function triggerEthBuyback(uint256 minTokensOut) external nonReentrant returns (uint256 tokensOut) {
        require(address(platformToken) != address(0), "PlatformRewardsDistributor: platform token not set");
        uint256 balance = address(this).balance;
        require(balance > 0 && balance >= ethBuybackThreshold, "PlatformRewardsDistributor: below threshold");
        uint256 cap = maxEthBuybackAmount;
        uint256 ethIn = (cap > 0 && balance > cap) ? cap : balance;

        address[] memory path = new address[](2);
        path[0] = router.WETH();
        path[1] = address(platformToken);

        // Finding PR-2: minTokensOut alone was a purely caller-supplied
        // value with no protocol-side floor — since this function is
        // deliberately permissionless, that let anyone call it with
        // minTokensOut == 0 and sandwich their own call for MEV profit at
        // the burn/airdrop pool's expense. effectiveMinOut is whichever is
        // stricter of the caller's own minTokensOut and a floor computed
        // from the pool's own live reserves.
        uint256 protectiveFloor = _protectiveMinOut(path, ethIn);
        uint256 effectiveMinOut = minTokensOut > protectiveFloor ? minTokensOut : protectiveFloor;

        uint256 before = platformToken.balanceOf(address(this));
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: ethIn}(
            effectiveMinOut,
            path,
            address(this),
            block.timestamp + 15 minutes
        );
        tokensOut = platformToken.balanceOf(address(this)) - before;

        (uint256 burned, uint256 toAirdrop) = _splitAndProcess(tokensOut);
        emit EthBuybackTriggered(ethIn, tokensOut, burned, toAirdrop);
    }

    /// @notice Swaps up to maxTokenBuybackAmount[token] of this contract's
    /// balance of `token` for platformToken (the entire balance, if no cap
    /// is set — routed through WETH, see
    /// IUniswapV2Router02.swapExactTokensForTokensSupportingFeeOnTransferTokens)
    /// and splits the result 50/50, same as triggerEthBuyback. If `token`
    /// happens to already be platformToken itself, no swap is needed — it's
    /// processed directly, uncapped (a burn/airdrop-pool credit isn't a
    /// trade, so it carries none of the price-impact risk the cap exists
    /// for). Anyone can call this once the token's balance clears its
    /// configured threshold.
    function triggerTokenBuyback(address token, uint256 minTokensOut) external nonReentrant returns (uint256 tokensOut) {
        require(address(platformToken) != address(0), "PlatformRewardsDistributor: platform token not set");
        require(token != address(0), "PlatformRewardsDistributor: invalid token");

        uint256 balance = IERC20(token).balanceOf(address(this));
        require(balance > 0 && balance >= tokenBuybackThreshold[token], "PlatformRewardsDistributor: below threshold");

        if (token == address(platformToken)) {
            (uint256 burnedDirect, uint256 toAirdropDirect) = _splitAndProcess(balance);
            emit DirectPlatformTokensProcessed(balance, burnedDirect, toAirdropDirect);
            return balance;
        }

        uint256 cap = maxTokenBuybackAmount[token];
        uint256 amountIn = (cap > 0 && balance > cap) ? cap : balance;

        address[] memory path = new address[](3);
        path[0] = token;
        path[1] = router.WETH();
        path[2] = address(platformToken);

        // Finding PR-2 (see triggerEthBuyback above for the full
        // rationale) — applied here via the same _protectiveMinOut helper,
        // generalized to walk both hops of this path.
        uint256 protectiveFloor = _protectiveMinOut(path, amountIn);
        uint256 effectiveMinOut = minTokensOut > protectiveFloor ? minTokensOut : protectiveFloor;

        // Finding PR-3: approving `amountIn` directly on top of any
        // existing allowance breaks against ERC20s (e.g. USDT and tokens
        // that copy its guard) that revert on changing a nonzero allowance
        // straight to another nonzero value. Resetting to zero first makes
        // this safe regardless of whatever allowance, if any, is already
        // outstanding — including the case where a prior call here left a
        // residual allowance because `token` took a transfer fee and the
        // router pulled less than the full approved amount.
        IERC20(token).approve(address(router), 0);
        IERC20(token).approve(address(router), amountIn);
        uint256 before = platformToken.balanceOf(address(this));
        router.swapExactTokensForTokensSupportingFeeOnTransferTokens(
            amountIn,
            effectiveMinOut,
            path,
            address(this),
            block.timestamp + 15 minutes
        );
        tokensOut = platformToken.balanceOf(address(this)) - before;

        (uint256 burned, uint256 toAirdrop) = _splitAndProcess(tokensOut);
        emit TokenBuybackTriggered(token, amountIn, tokensOut, burned, toAirdrop);
    }

    /// @dev Fixed 50/50 split, shared by every path that produces fresh
    /// platformToken here (both buyback triggers, plus the direct-token
    /// shortcut above). Burns immediately; the airdrop half just
    /// accumulates until startAirdropRound() is next called.
    function _splitAndProcess(uint256 amount) private returns (uint256 burned, uint256 toAirdrop) {
        if (amount == 0) return (0, 0);
        burned = amount / 2;
        toAirdrop = amount - burned;
        if (burned > 0) platformToken.burn(burned);
        pendingAirdropTokens += toAirdrop;
    }

    // ---------------------------------------------------------------
    // Airdrop rounds — accumulate-and-batch-trigger, mirroring
    // CustomToken's own swapThreshold/_maybeSwapAndProcess pattern
    // ---------------------------------------------------------------

    /// @notice Freezes whatever's accumulated in pendingAirdropTokens into
    /// a new round: the amount being paid out, and the eligible supply
    /// (PlatformToken's total supply minus whatever this contract itself
    /// is currently holding, since this contract is never a payee of its
    /// own airdrop) it's divided by. Permissionless, like the triggers
    /// above — anyone can kick a round off once there's something to
    /// distribute.
    function startAirdropRound() external nonReentrant {
        require(!roundActive, "PlatformRewardsDistributor: round already active");
        require(address(platformToken) != address(0), "PlatformRewardsDistributor: platform token not set");
        require(pendingAirdropTokens > 0, "PlatformRewardsDistributor: nothing to distribute");

        uint256 ownBalance = platformToken.balanceOf(address(this));
        uint256 supply = platformToken.totalSupply();
        uint256 supplySnapshot = supply > ownBalance ? supply - ownBalance : 0;
        require(supplySnapshot > 0, "PlatformRewardsDistributor: no eligible holders");

        roundAmount = pendingAirdropTokens;
        pendingAirdropTokens = 0;
        roundSupplySnapshot = supplySnapshot;
        roundCursor = 0;
        roundActive = true;

        // Finding PR-5 fix (layer 1): freeze the round's own finish line
        // here, the same moment roundSupplySnapshot itself is frozen -- see
        // roundHolderCountAtStart's own comment above for why a live-only
        // holderCount() check in processAirdropBatch() let a holder from
        // OUTSIDE this snapshot draw against it. Captured once into a local
        // so the value backing the event and the value stored as state are
        // guaranteed identical (rather than two separate external calls
        // that could theoretically observe different results).
        uint256 holderCountAtStart = platformToken.holderCount();
        roundHolderCountAtStart = holderCountAtStart;

        // Finding PR-5 fix (layer 2): freeze PlatformToken's own
        // holderGenerationCounter() too -- see roundGenerationAtStart's own
        // comment above for why layer 1's count bound alone isn't enough to
        // exclude a holder that recycles a vacated low index via
        // swap-and-pop after this round has already started.
        roundGenerationAtStart = platformToken.holderGenerationCounter();

        emit AirdropRoundStarted(roundAmount, roundSupplySnapshot, holderCountAtStart);
    }

    /// @dev Finding PR-1 fix: wraps the actual token transfer in try/catch
    /// so a single reverting recipient (a blocklist, a max-wallet cap on
    /// PlatformToken, or any other transfer-blocking condition) can never
    /// take down the whole batch. `platformToken.transfer(...)` is already
    /// an external call (platformToken is a separately-deployed contract),
    /// so it can be try/catched directly with no extra self-call needed.
    function _sendPlatformToken(address to, uint256 amount) private returns (bool) {
        try platformToken.transfer(to, amount) returns (bool ok) {
            return ok;
        } catch {
            return false;
        }
    }

    /// @notice Pushes up to `maxHolders` holders' proportional share of the
    /// active round, resuming from wherever the last call left off, and
    /// closes the round out once every holder's been reached. Anyone can
    /// call this (e.g. a keeper looping until the round completes) — it's
    /// the only way round funds ever actually move.
    ///
    /// Finding PR-1 (fixed here): before this fix, a single holder whose
    /// transfer reverted — for example because PlatformToken itself
    /// enforces a blocklist, a max-wallet cap that this payout would cross,
    /// or any other transfer-blocking condition — would revert this whole
    /// call. Since `from` always starts at `roundCursor`, which only
    /// advances on a SUCCESSFUL call, every subsequent call would begin at
    /// that exact same holder and revert identically, permanently freezing
    /// the round (and, with it, roundAmount of PlatformToken, and every
    /// future round behind it, since startAirdropRound() refuses to run
    /// while roundActive is true). _sendPlatformToken now catches a failed
    /// transfer instead of letting it propagate: the batch keeps moving,
    /// the failed share is added back to pendingAirdropTokens so it isn't
    /// silently lost (it simply becomes eligible for the NEXT round,
    /// recomputed against balances at that time), and an
    /// AirdropPayoutSkipped event records exactly which holder and how
    /// much, for anyone auditing a round afterward.
    ///
    /// Two other, disclosed and deliberate approximations keep this
    /// affordable and gas-bounded rather than paying for a fully-frozen
    /// per-holder snapshot:
    ///  - Each holder's share is computed from their LIVE balance at the
    ///    moment they're processed, not a balance frozen at round start —
    ///    someone who buys or sells between startAirdropRound() and their
    ///    turn in the loop is paid on whatever they're holding right then.
    ///  - PlatformToken's holder registry can itself shrink mid-round (a
    ///    holder's balance hits zero elsewhere and they're removed via the
    ///    registry's swap-and-pop set), which can shift which address sits
    ///    at a given index for the remainder of the round. In the rare
    ///    case this causes an address to be skipped, their share simply
    ///    stays unpaid this round rather than the whole round reverting.
    function processAirdropBatch(uint256 maxHolders) external nonReentrant {
        require(roundActive, "PlatformRewardsDistributor: no active round");
        require(maxHolders > 0, "PlatformRewardsDistributor: maxHolders must be > 0");

        // Finding PR-5 fix: bound this round's walk at whichever is SMALLER
        // of the live holderCount() and roundHolderCountAtStart (frozen in
        // startAirdropRound()) -- never the live value alone. See that
        // field's own comment for the full reasoning; in short, capping at
        // the smaller of the two still lets the registry shrink mid-round
        // (an existing holder emptying their balance, removed via
        // swap-and-pop) exactly as before, while guaranteeing this round
        // never walks an address that only became a holder after
        // roundSupplySnapshot was already frozen.
        uint256 liveHolderCount = platformToken.holderCount();
        uint256 total = liveHolderCount < roundHolderCountAtStart ? liveHolderCount : roundHolderCountAtStart;
        uint256 from = roundCursor;
        uint256 to = from + maxHolders;
        if (to > total) to = total;

        uint256 distributed;
        for (uint256 i = from; i < to; i++) {
            address holder = platformToken.holderAt(i);
            if (holder == address(this)) continue;
            // Finding PR-5 fix (layer 2): a holder whose registry generation
            // is NEWER than roundGenerationAtStart entered (or re-entered)
            // PlatformToken's registry after this round already started --
            // regardless of which index it's sitting at, including one
            // recycled from an existing holder draining to zero, which layer
            // 1's count bound alone cannot tell apart from a genuine
            // round-start holder. No share is computed or requeued for it:
            // it was never part of roundSupplySnapshot's denominator, so it
            // has no legitimate claim on this round's pool at all -- it will
            // be included fairly by whichever LATER round's own fresh
            // snapshot it's actually a holder at the start of.
            if (platformToken.holderGeneration(holder) > roundGenerationAtStart) {
                emit AirdropHolderIneligibleThisRound(holder, platformToken.holderGeneration(holder), roundGenerationAtStart);
                continue;
            }
            uint256 share = (roundAmount * platformToken.balanceOf(holder)) / roundSupplySnapshot;
            if (share == 0) continue;
            if (_sendPlatformToken(holder, share)) {
                distributed += share;
            } else {
                // Finding PR-1: don't lose the share — requeue it for the
                // next round instead of leaving it stranded, unaccounted,
                // in this contract's own balance forever.
                pendingAirdropTokens += share;
                emit AirdropPayoutSkipped(holder, share);
            }
        }

        roundCursor = to;
        emit AirdropBatchProcessed(from, to, distributed);

        if (roundCursor >= total) {
            roundActive = false;
            emit AirdropRoundCompleted(roundAmount);
        }
    }

    // ---------------------------------------------------------------
    // Rescue — Finding PR-4, fixed at the platform owner's explicit
    // request. See the contract-level "Security review" note above for
    // why an earlier revision of this file left this deliberately unfixed,
    // and why the scoping below is what makes it safe to add now.
    // ---------------------------------------------------------------

    /// @notice Sweeps this contract's ETH balance to `to`. ETH here is
    /// always just platform revenue waiting for triggerEthBuyback() —
    /// unlike platformToken (see rescueToken below), no ETH balance is ever
    /// earmarked for a specific holder, so this is a plain, unrestricted
    /// sweep, gated only by onlyOwner. Exists for exactly the gap Finding
    /// PR-4 described: a balance sitting below ethBuybackThreshold (or one
    /// that accumulated before platformToken was ever configured) had no
    /// way to move at all.
    function rescueEth(address to) external onlyOwner nonReentrant returns (uint256 amount) {
        require(to != address(0), "PlatformRewardsDistributor: invalid recipient");
        amount = address(this).balance;
        require(amount > 0, "PlatformRewardsDistributor: nothing to rescue");
        (bool sent, ) = payable(to).call{value: amount}("");
        require(sent, "PlatformRewardsDistributor: ETH rescue failed");
        emit EthRescued(to, amount);
    }

    /// @notice Sweeps an ERC20 balance this contract is holding to `to`.
    ///
    /// For any token OTHER than the currently-configured platformToken,
    /// this is unrestricted: an input token stuck below its own
    /// tokenBuybackThreshold (or one whose pool no longer exists to swap
    /// against) carries no per-holder claim — it's simply platform revenue
    /// awaiting a buyback that may never come, the exact gap Finding PR-4
    /// described. This also reaches a PREVIOUS platformToken instance's
    /// leftover balance after setPlatformToken() has since moved on to a
    /// new one — that old instance's IPlatformToken reference is gone from
    /// storage, but any balance of it sitting here can never be the
    /// CURRENT platformToken's pendingAirdropTokens/roundAmount (those are
    /// only ever denominated in whatever `platformToken` points to right
    /// now), so it is always fully rescuable under the same check below.
    ///
    /// For platformToken itself, this is deliberately NOT unrestricted:
    /// pendingAirdropTokens (and, while a round is active, roundAmount) are
    /// holder funds already earmarked for a specific payout, computed
    /// against a live balance the airdrop machinery expects to still be
    /// here. Rescuing those out from under it would either brick
    /// processAirdropBatch (insufficient balance for _sendPlatformToken) or
    /// let an owner unilaterally divert funds holders already have a claim
    /// on — exactly the "worse centralization risk" an earlier revision of
    /// this file traded the availability gap for. The rescuable amount is
    /// therefore capped at whatever balance remains ABOVE both
    /// commitments — e.g. burn()'s own truncation dust, or a stray direct
    /// transfer of platformToken to this address outside the buyback flow.
    function rescueToken(address token, address to, uint256 amount) external onlyOwner nonReentrant {
        require(to != address(0), "PlatformRewardsDistributor: invalid recipient");
        uint256 balance = IERC20(token).balanceOf(address(this));
        if (token == address(platformToken)) {
            uint256 committed = pendingAirdropTokens + (roundActive ? roundAmount : 0);
            uint256 rescuable = balance > committed ? balance - committed : 0;
            require(amount <= rescuable, "PlatformRewardsDistributor: exceeds rescuable balance");
        } else {
            require(amount <= balance, "PlatformRewardsDistributor: exceeds balance");
        }
        bool sent = IERC20(token).transfer(to, amount);
        require(sent, "PlatformRewardsDistributor: token rescue failed");
        emit TokenRescued(token, to, amount);
    }
}

contracts/PlatformTaxDistributor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/// @notice Minimal Uniswap V2-style router surface this contract needs —
/// declared locally rather than imported from HoodLaunch's own contracts,
/// since this contract is intentionally standalone (see the contract-level
/// comment below): it has no dependency on anything else in that codebase.
interface IRouterMinimal {
    function WETH() external pure returns (address);
    function getAmountsOut(uint256 amountIn, address[] calldata path) external view returns (uint256[] memory amounts);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external payable;
}

/// @notice The minimal slice of the platform token this contract needs to
/// disburse proportionally to every holder — an enumerable ERC20
/// (holderCount/holderAt on top of the ordinary ERC20 surface). Declared
/// locally, not imported, for the same standalone reason as IRouterMinimal
/// above.
interface IPlatformTokenMinimal {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function holderCount() external view returns (uint256);
    function holderAt(uint256 index) external view returns (address);
}

/// @title PlatformTaxDistributor
/// @notice A fully standalone contract: it is NOT part of HoodLaunch's own
/// deployment, is never read or written by that platform's relayer or admin
/// panel, and is not controlled by that platform's own owner/admin wallet in
/// any way. It is deployed and owned independently by whoever deploys it —
/// see Ownable2Step below, where the deploying wallet becomes the initial
/// owner exactly like any other Ownable contract, with no special tie-in to
/// HoodLaunch's own access control.
///
/// HoodLaunch's own front end (public/index.html) only ever needs this
/// contract's ADDRESS: it sends this contract a flat 0.30% of every buy,
/// sell, curve buy, and curve sell it executes, as an ordinary extra ETH
/// transfer alongside the trade itself (see PLATFORM_TAX_DISTRIBUTOR in that
/// file). Nothing about what happens to that ETH once it arrives here is
/// visible to or controlled by HoodLaunch's own contracts, its relayer, or
/// its admin wallet — this contract's owner is the only one who can change
/// any setting below.
///
/// Automation: every ETH transfer this contract receives (see receive()
/// below) simply accumulates in its own balance — there is no per-sender
/// bookkeeping, since the tax has no notion of "whose" it is once paid. The
/// moment that balance reaches disburseThreshold, receive() itself
/// automatically triggers the split: half straight to feeWallet in plain
/// ETH, half swapped for platformToken (using a live on-chain quote — see
/// triggerDistributionAuto()) and queued for pro-rata disbursement to every
/// platform token holder, which then starts paying itself out too — see
/// autoProcessBatchSize below. No keeper, relayer, or manual call is needed
/// for any of this — it all happens as a side effect of ordinary trade-tax
/// transfers arriving. A smart contract can never run code on its own
/// timer, only when some transaction calls it, so this contract uses the
/// one thing that reliably calls it on an ongoing basis — HoodLaunch's own
/// traders paying their 0.30% tax — as its "heartbeat": each such transfer
/// also nudges an in-progress holder-payout round forward by a small,
/// bounded batch. The tradeoff is real and disclosed: whoever's transfer
/// happens to trigger a batch pays that batch's extra gas alongside their
/// own transaction. autoProcessBatchSize is kept small by default and can
/// be set to 0 to disable this piggybacking, falling back to
/// processDisburseRound() only ever being called manually or by an
/// external script the owner runs entirely outside this contract.
///
/// --- Security review (this file) ---
/// Finding PTD-4 (Informational, fixed at the deploying owner's explicit
/// request): this contract originally had no rescue path for a stray ETH
/// or token balance — the same gap disclosed and, at the time, left
/// unfixed on PlatformRewardsDistributor.sol's own Finding PR-4, for the
/// same centralization-risk reasoning. rescueEth()/rescueToken() below
/// close it using the identical scoping PR-4's own fix uses: rescueToken()
/// can never touch platformToken's own pendingDisburseTokens or an active
/// round's roundAmount, so holder funds already earmarked for a
/// disbursement can never be diverted by this.
contract PlatformTaxDistributor is Ownable2Step, ReentrancyGuard {
    IRouterMinimal public immutable router;

    /// @notice The token bought back and disbursed to holders. Changeable
    /// by the owner (see setPlatformToken) as long as no disburse round is
    /// currently in progress and no bought-back tokens are still waiting
    /// to be disbursed under the OLD token — never lets a swap-out happen
    /// out from under an in-flight round or a pending balance.
    IPlatformTokenMinimal public platformToken;

    /// @notice Where half of every collected tax goes, in plain ETH.
    address public feeWallet;

    /// @notice ETH balance this contract must reach before it automatically
    /// (or manually, via triggerDistribution/triggerDistributionAuto) splits
    /// and disburses. Owner-adjustable, with no externally enforced ceiling
    /// beyond > 0 — this is the deployer's own contract to tune as they see
    /// fit. Starts at 0.25 ETH.
    uint256 public disburseThreshold = 0.25 ether;

    /// @notice Slippage floor applied to the ETH -> platformToken buyback
    /// leg whenever it's computed automatically from a live on-chain quote
    /// (see triggerDistributionAuto() and receive() below) — e.g. 500 =
    /// 5.00% tolerance under the router's own getAmountsOut() quote at the
    /// moment the trade executes. Has no effect on triggerDistribution(),
    /// which takes its own caller-supplied floor instead.
    uint256 public buybackSlippageBps = 500; // 5.00%

    /// @notice Running, all-time total of every wei this contract has ever
    /// received (see receive() below) — never decremented, purely a
    /// transparency counter. Independent of the current balance, which
    /// drops back toward zero every time a distribution runs.
    uint256 public totalEthCollected;

    /// @notice All-time totals of what's actually been done with the ETH
    /// collected above, split the same way every distribution is split —
    /// plain running counters, same purpose as totalEthCollected.
    uint256 public totalDistributedToFeeWallet;
    uint256 public totalDistributedToBuyback;

    /// @notice How many holders receive() automatically pays out (see
    /// below) on top of whatever else it does, whenever a disburse round is
    /// already active — the only way to make holder payout fully
    /// self-driving with no external keeper: a smart contract can't run on
    /// its own timer, so ongoing trade-tax payments are used as the
    /// "heartbeat" that nudges an in-progress round forward. Kept
    /// deliberately small and owner-adjustable, since whoever's incoming
    /// transfer happens to trigger a batch pays that batch's extra gas on
    /// top of their own transaction — a real cost shifted onto an
    /// unrelated trader, not free automation. Set to 0 to disable this
    /// piggybacking entirely and rely only on manual/external
    /// processDisburseRound() calls instead.
    uint256 public autoProcessBatchSize = 5;

    // ---- disburse-round bookkeeping: an accumulate-then-batch pattern so
    // paying out every platform token holder never risks looping over an
    // unbounded list in one transaction. Tokens bought back by a
    // distribution accumulate in pendingDisburseTokens; the moment that's
    // nonzero and no round is already active, a new round auto-starts
    // (see _startRoundIfNeeded, called right after every successful
    // buyback) — snapshotting both the amount and the CURRENT
    // totalSupply() so a token minted/burned mid-round, or more tax bought
    // back mid-round, doesn't retroactively change what's already being
    // paid out. processDisburseRound() then pays batches of holders out of
    // that snapshot, proportional to their holdings AT THE TIME EACH BATCH
    // ACTUALLY RUNS (not a true historical snapshot of every balance — see
    // that function's own comment for why that tradeoff is deliberate and
    // disclosed, the same running-total approach reflection/dividend
    // mechanisms elsewhere use rather than a per-block snapshot of every
    // holder). ----
    uint256 public pendingDisburseTokens;
    bool public roundActive;
    uint256 public roundAmount; // total platformToken being paid out this round
    uint256 public roundSupplyAtStart; // totalSupply() read once, at round start — the denominator every batch divides against
    uint256 public roundCursor; // holderAt() index the next processDisburseRound() batch resumes from

    event TaxReceived(address indexed from, uint256 amount, uint256 totalEthCollected);
    event PlatformTokenUpdated(address indexed newPlatformToken);
    event FeeWalletUpdated(address indexed newFeeWallet);
    event DisburseThresholdUpdated(uint256 newThreshold);
    event BuybackSlippageBpsUpdated(uint256 newBps);
    event DistributionTriggered(uint256 totalAmount, uint256 toFeeWallet, uint256 toBuyback, uint256 platformTokensBought);
    event DisburseRoundStarted(uint256 amount, uint256 supplyAtStart);
    event DisburseRoundProgress(uint256 nextCursor, uint256 paidThisBatch);
    event DisburseRoundFinished(uint256 totalAmount);
    event AutoProcessBatchSizeUpdated(uint256 newBatchSize);
    event DisbursePayoutSkipped(address indexed holder, uint256 amount);
    /// @notice Finding PTD-4 fix -- see rescueEth/rescueToken below.
    event EthRescued(address indexed to, uint256 amount);
    event TokenRescued(address indexed token, address indexed to, uint256 amount);

    constructor(address router_, address platformToken_, address feeWallet_) Ownable(msg.sender) {
        require(router_ != address(0), "PlatformTaxDistributor: invalid router");
        router = IRouterMinimal(router_);
        platformToken = IPlatformTokenMinimal(platformToken_);
        feeWallet = feeWallet_;
    }

    /// @notice Every trade's 0.30% tax lands here as a plain ETH transfer —
    /// see HoodLaunch's own public/index.html, the only piece of that
    /// platform that knows this address exists. Logs the transfer, adds it
    /// to the all-time totalEthCollected counter, and drives BOTH pieces of
    /// this contract's automation as side effects:
    ///
    ///  1. If a disburse round is already active, piggybacks a small,
    ///     bounded batch of holder payouts onto THIS transfer (see
    ///     autoProcessBatchSize above) — the only way to make holder payout
    ///     fully self-driving without an external keeper, since ongoing
    ///     trade-tax payments are the only thing that calls this contract
    ///     on any regular cadence.
    ///  2. If the balance is now at or above disburseThreshold, immediately
    ///     attempts a full distribution (see triggerDistributionAuto()).
    ///
    /// Both attempts are wrapped in try/catch specifically so NEITHER can
    /// ever cause this function to revert: if feeWallet/platformToken
    /// aren't configured yet, if the router can't quote or swap right now,
    /// if a holder's token transfer reverts, or if anything else about
    /// either automatic attempt fails, this transfer still succeeds — a
    /// misconfigured setting or misbehaving dependency on THIS contract
    /// must never be able to cause a trade on HoodLaunch's own platform to
    /// fail.
    receive() external payable {
        totalEthCollected += msg.value;
        emit TaxReceived(msg.sender, msg.value, totalEthCollected);

        if (roundActive && autoProcessBatchSize > 0) {
            try this.processDisburseRound(autoProcessBatchSize) {} catch {}
        }
        if (address(this).balance >= disburseThreshold) {
            try this.triggerDistributionAuto() {} catch {}
        }
    }

    function setPlatformToken(address newPlatformToken) external onlyOwner {
        require(!roundActive, "PlatformTaxDistributor: a disburse round is active");
        require(pendingDisburseTokens == 0, "PlatformTaxDistributor: tokens are pending disbursement under the current platform token");
        platformToken = IPlatformTokenMinimal(newPlatformToken);
        emit PlatformTokenUpdated(newPlatformToken);
    }

    function setFeeWallet(address newFeeWallet) external onlyOwner {
        feeWallet = newFeeWallet;
        emit FeeWalletUpdated(newFeeWallet);
    }

    function setDisburseThreshold(uint256 newThreshold) external onlyOwner {
        require(newThreshold > 0, "PlatformTaxDistributor: threshold must be > 0");
        disburseThreshold = newThreshold;
        emit DisburseThresholdUpdated(newThreshold);
    }

    function setBuybackSlippageBps(uint256 newBps) external onlyOwner {
        require(newBps <= 2_000, "PlatformTaxDistributor: slippage above 20% ceiling");
        buybackSlippageBps = newBps;
        emit BuybackSlippageBpsUpdated(newBps);
    }

    /// @notice Tunes how many holders each incoming tax payment automatically
    /// pays out of an in-progress round (see receive() and
    /// autoProcessBatchSize above). Capped at 50 — this runs inside an
    /// ordinary trader's own transaction, so it must stay small enough that
    /// it can never plausibly push that transaction over a block's gas
    /// limit on its own. 0 disables the piggyback entirely.
    function setAutoProcessBatchSize(uint256 newBatchSize) external onlyOwner {
        require(newBatchSize <= 50, "PlatformTaxDistributor: batch size above 50 ceiling");
        autoProcessBatchSize = newBatchSize;
        emit AutoProcessBatchSizeUpdated(newBatchSize);
    }

    /// @notice Manual, permissionless fallback for whenever the balance is
    /// already at or above disburseThreshold but, for whatever reason, no
    /// distribution has happened yet (e.g. the automatic attempt inside
    /// receive() failed and was silently swallowed — see that function's
    /// own comment). Uses a live on-chain quote off the router's own
    /// getAmountsOut(), same as the fully automatic path, with
    /// buybackSlippageBps as the tolerance — exactly what receive() itself
    /// calls, just also directly callable by anyone at any time.
    function triggerDistributionAuto() external nonReentrant {
        uint256 balance = address(this).balance;
        require(balance >= disburseThreshold, "PlatformTaxDistributor: balance below disburseThreshold");
        require(feeWallet != address(0), "PlatformTaxDistributor: feeWallet not set");
        require(address(platformToken) != address(0), "PlatformTaxDistributor: platformToken not set");

        uint256 toBuyback = balance - balance / 2;
        address[] memory path = new address[](2);
        path[0] = router.WETH();
        path[1] = address(platformToken);
        uint256[] memory amountsOut = router.getAmountsOut(toBuyback, path);
        uint256 quoted = amountsOut[amountsOut.length - 1];
        uint256 minOut = (quoted * (10_000 - buybackSlippageBps)) / 10_000;

        _distribute(minOut);
    }

    /// @notice Same as triggerDistributionAuto(), but with a caller-supplied
    /// slippage floor — for anyone who wants TIGHTER control over the
    /// buyback leg than the automatic quote (e.g. someone who suspects the
    /// pool is being manipulated right now and wants a stricter floor than
    /// buybackSlippageBps would compute).
    ///
    /// FIX (this review): this function used to take minPlatformTokenOut
    /// straight from the caller with no protocol-side floor at all — unlike
    /// triggerDistributionAuto(), which always computes one from a live
    /// quote. Since this function is just as permissionless as that one,
    /// anyone could call this instead with minPlatformTokenOut = 0 to get
    /// the exact unprotected swap the automatic path exists specifically to
    /// prevent — sandwich the buyback, extract the difference, at the direct
    /// expense of the burn/holder-disbursement split. Now computes the same
    /// live-quote floor triggerDistributionAuto() does and takes whichever
    /// of that floor or the caller's own value is stricter (higher), so the
    /// caller-supplied value can only ever tighten the protection, never
    /// remove it.
    function triggerDistribution(uint256 minPlatformTokenOut) external nonReentrant {
        uint256 balance = address(this).balance;
        require(balance >= disburseThreshold, "PlatformTaxDistributor: balance below disburseThreshold");
        require(feeWallet != address(0), "PlatformTaxDistributor: feeWallet not set");
        require(address(platformToken) != address(0), "PlatformTaxDistributor: platformToken not set");

        uint256 toBuyback = balance - balance / 2;
        address[] memory path = new address[](2);
        path[0] = router.WETH();
        path[1] = address(platformToken);
        uint256[] memory amountsOut = router.getAmountsOut(toBuyback, path);
        uint256 quoted = amountsOut[amountsOut.length - 1];
        uint256 protocolFloor = (quoted * (10_000 - buybackSlippageBps)) / 10_000;
        uint256 effectiveMinOut = minPlatformTokenOut > protocolFloor ? minPlatformTokenOut : protocolFloor;

        _distribute(effectiveMinOut);
    }

    /// @dev Shared core of both trigger paths above: splits the CURRENT ETH
    /// balance 50/50 — half straight to feeWallet, half swapped for
    /// platformToken and added to pendingDisburseTokens — then auto-starts
    /// a disburse round over that pending balance if none is already
    /// active (see _startRoundIfNeeded). Both callers have already checked
    /// disburseThreshold/feeWallet/platformToken before reaching here.
    function _distribute(uint256 minPlatformTokenOut) private {
        uint256 balance = address(this).balance;
        uint256 toFeeWallet = balance / 2;
        uint256 toBuyback = balance - toFeeWallet;

        (bool sent, ) = feeWallet.call{value: toFeeWallet}("");
        require(sent, "PlatformTaxDistributor: feeWallet transfer failed");
        totalDistributedToFeeWallet += toFeeWallet;

        address[] memory path = new address[](2);
        path[0] = router.WETH();
        path[1] = address(platformToken);
        uint256 boughtBefore = platformToken.balanceOf(address(this));
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: toBuyback}(
            minPlatformTokenOut, path, address(this), block.timestamp + 15 minutes
        );
        uint256 bought = platformToken.balanceOf(address(this)) - boughtBefore;
        pendingDisburseTokens += bought;
        totalDistributedToBuyback += toBuyback;

        emit DistributionTriggered(balance, toFeeWallet, toBuyback, bought);

        _startRoundIfNeeded();
    }

    /// @dev Auto-starts a new disburse round the moment there's something
    /// pending and no round is already active — called right after every
    /// successful buyback above, so in the common case nobody ever needs to
    /// call startDisburseRound() manually at all. Snapshots
    /// pendingDisburseTokens and platformToken.totalSupply() once, for the
    /// same reasons documented on the contract-level comment above.
    function _startRoundIfNeeded() private {
        if (roundActive || pendingDisburseTokens == 0) return;
        roundActive = true;
        roundAmount = pendingDisburseTokens;
        roundSupplyAtStart = platformToken.totalSupply();
        roundCursor = 0;
        pendingDisburseTokens = 0;
        emit DisburseRoundStarted(roundAmount, roundSupplyAtStart);
    }

    /// @notice Manual fallback for _startRoundIfNeeded() above — covers the
    /// rare case where pendingDisburseTokens is nonzero but no round is
    /// active and nothing has triggered a new distribution since (e.g. the
    /// owner sent platformToken to this contract directly, outside the
    /// normal buyback path). Reverts if a round is already active or if
    /// there's nothing pending; ordinarily unnecessary, since every
    /// successful distribution starts a round on its own.
    function startDisburseRound() external {
        require(!roundActive, "PlatformTaxDistributor: a disburse round is already active");
        require(pendingDisburseTokens > 0, "PlatformTaxDistributor: nothing pending to disburse");
        require(address(platformToken) != address(0), "PlatformTaxDistributor: platformToken not set");
        _startRoundIfNeeded();
    }

    /// @notice Pays out up to `batchSize` more holders from the active
    /// round, resuming from roundCursor — callable repeatedly by anyone
    /// until it reports the round finished (roundActive flips back to
    /// false). Looping over ALL holders in one transaction risks running
    /// out of gas, which is why this is batched at all — receive() already
    /// calls this automatically, in small pieces, every time a new tax
    /// payment arrives (see autoProcessBatchSize), so in ordinary operation
    /// with regular trading activity nobody needs to call this directly.
    /// It remains callable by anyone at any time regardless — the owner, a
    /// holder impatient for their share, or a script/cron the owner sets up
    /// entirely outside this contract — as a faster or more reliable way to
    /// finish a round than waiting on trading activity alone.
    ///
    /// A holder with a zero balance, a zero computed share, or a transfer
    /// that reverts (e.g. a blocklist-style token) is simply skipped rather
    /// than reverting the whole batch — see _sendPlatformToken.
    ///
    /// FIX (this review, same class as the already-fixed PlatformRewards-
    /// Distributor Finding PR-1): a skipped holder's share used to be
    /// silently dropped — never added back to pendingDisburseTokens, never
    /// reflected in roundAmount, and no code path ever revisited it, despite
    /// this function's own comment previously (incorrectly) claiming it
    /// would become "available to whatever the NEXT distribution adds to
    /// pendingDisburseTokens." In reality, since pendingDisburseTokens is
    /// only ever incremented by a fresh buyback's own `bought` amount (see
    /// _distribute), a skipped share just sat in this contract's raw
    /// platformToken balance forever, uncounted by any tracking variable.
    /// Skipped shares are now re-added to pendingDisburseTokens so they
    /// actually get folded into the NEXT round once one starts, and a
    /// DisbursePayoutSkipped event makes every skip independently
    /// auditable.
    function processDisburseRound(uint256 batchSize) external nonReentrant {
        require(roundActive, "PlatformTaxDistributor: no disburse round is active");
        require(batchSize > 0, "PlatformTaxDistributor: batchSize must be > 0");

        uint256 holders = platformToken.holderCount();
        uint256 cursor = roundCursor;
        uint256 end = cursor + batchSize;
        if (end > holders) end = holders;

        uint256 paidThisBatch;
        for (uint256 i = cursor; i < end; i++) {
            address holder = platformToken.holderAt(i);
            uint256 bal = platformToken.balanceOf(holder);
            if (bal == 0) continue;
            uint256 share = (roundAmount * bal) / roundSupplyAtStart;
            if (share == 0) continue;
            if (_sendPlatformToken(holder, share)) {
                paidThisBatch += share;
            } else {
                pendingDisburseTokens += share;
                emit DisbursePayoutSkipped(holder, share);
            }
        }

        roundCursor = end;
        emit DisburseRoundProgress(end, paidThisBatch);

        if (end >= holders) {
            roundActive = false;
            emit DisburseRoundFinished(roundAmount);
        }
    }

    /// @dev Isolated purely so a misbehaving platformToken (e.g. a
    /// blocklist-style token that reverts transfers to certain addresses)
    /// can't brick the entire batch — a failed send to one holder is
    /// skipped, never retried automatically and never a reason to revert
    /// everyone else's already-successful payouts in the same batch. See
    /// processDisburseRound's own doc comment.
    function _sendPlatformToken(address to, uint256 amount) private returns (bool) {
        try platformToken.transfer(to, amount) returns (bool ok) {
            return ok;
        } catch {
            return false;
        }
    }

    // ---------------------------------------------------------------
    // Rescue — Finding PTD-4, fixed at the deploying owner's explicit
    // request. See the contract-level "Security review" note above.
    // ---------------------------------------------------------------

    /// @notice Sweeps this contract's ETH balance to `to`. ETH here is
    /// never earmarked for a specific holder — it's simply tax revenue
    /// waiting for disburseThreshold to trigger a split — so this is a
    /// plain, unrestricted sweep, gated only by onlyOwner. Closes the gap
    /// Finding PTD-4 described: a balance that never reaches
    /// disburseThreshold (or that accumulates before feeWallet/
    /// platformToken are configured) previously had no way to move at all.
    function rescueEth(address to) external onlyOwner nonReentrant returns (uint256 amount) {
        require(to != address(0), "PlatformTaxDistributor: invalid recipient");
        amount = address(this).balance;
        require(amount > 0, "PlatformTaxDistributor: nothing to rescue");
        (bool sent, ) = payable(to).call{value: amount}("");
        require(sent, "PlatformTaxDistributor: ETH rescue failed");
        emit EthRescued(to, amount);
    }

    /// @notice Sweeps an ERC20 balance this contract is holding to `to`.
    ///
    /// For any token OTHER than the currently-configured platformToken,
    /// this is unrestricted — it carries no per-holder claim, exactly the
    /// gap Finding PTD-4 described. This also reaches a PREVIOUS
    /// platformToken instance's leftover balance after setPlatformToken()
    /// has since moved on to a new one, for the identical reason
    /// PlatformRewardsDistributor's own rescueToken() does.
    ///
    /// For platformToken itself, this is deliberately NOT unrestricted:
    /// pendingDisburseTokens (and, while a round is active, roundAmount)
    /// are holder funds already earmarked for a specific disbursement,
    /// computed against a live balance the disburse machinery expects to
    /// still be here. The rescuable amount is capped at whatever balance
    /// remains ABOVE both commitments — e.g. a stray direct transfer of
    /// platformToken to this address outside the buyback flow.
    function rescueToken(address token, address to, uint256 amount) external onlyOwner nonReentrant {
        require(to != address(0), "PlatformTaxDistributor: invalid recipient");
        uint256 balance = IPlatformTokenMinimal(token).balanceOf(address(this));
        if (token == address(platformToken)) {
            uint256 committed = pendingDisburseTokens + (roundActive ? roundAmount : 0);
            uint256 rescuable = balance > committed ? balance - committed : 0;
            require(amount <= rescuable, "PlatformTaxDistributor: exceeds rescuable balance");
        } else {
            require(amount <= balance, "PlatformTaxDistributor: exceeds balance");
        }
        bool sent = IPlatformTokenMinimal(token).transfer(to, amount);
        require(sent, "PlatformTaxDistributor: token rescue failed");
        emit TokenRescued(token, to, amount);
    }
}

contracts/PlatformToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/access/Ownable2Step.sol";

/// @title PlatformToken
/// @notice Hood Launch's own token — the one the platform itself launches
/// "in conjunction with the launch of the platform" (the owner's own
/// words). A plain, fixed-supply, ordinary ERC20 in every way a holder or
/// a DEX ever sees it — no tax, no transfer restrictions, nothing that
/// makes it behave differently from any other token someone could launch
/// through this same platform.
///
/// The one thing it adds on top of a stock ERC20Burnable is a live,
/// enumerable holder registry, maintained automatically in _update below,
/// because PlatformRewardsDistributor needs to be able to walk "every
/// current holder" on-chain, in a deterministic order, to push out batched
/// airdrops — see PlatformRewardsDistributor.processAirdropBatch. Nothing
/// about the registry affects transfers, balances, or supply; it's pure
/// bookkeeping alongside the ERC20 state OpenZeppelin already tracks.
///
/// The registry is a small hand-rolled swap-and-pop set (an address array
/// plus a 1-based index mapping) rather than OpenZeppelin's own
/// EnumerableSet.AddressSet — deliberately: the version of EnumerableSet
/// this project's pinned OpenZeppelin release resolves to pulls in
/// Arrays.sol helpers that use the `mcopy` opcode, which isn't available
/// under this project's target EVM version (hardhat.config.js's
/// solidity.settings leaves evmVersion at its pre-Cancun default, matching
/// Robinhood Chain's own EVM support). Avoiding the import sidesteps that
/// entirely; the logic below (append on add, swap-last-into-slot on
/// remove) is the exact same approach EnumerableSet itself uses
/// internally.
///
/// burn()/burnFrom() (via ERC20Burnable) are what PlatformRewardsDistributor
/// calls on its own balance after every buyback, to actually destroy the
/// "burn" half of each round — see PlatformRewardsDistributor._splitAndProcess.
///
/// Alongside the registry itself, holderGeneration/holderGenerationCounter
/// stamp each holder with WHEN it most recently entered the registry. This
/// exists purely so PlatformRewardsDistributor's airdrop rounds can tell a
/// genuine round-start holder apart from one that entered (or re-entered)
/// after a round had already started, even when that address happens to
/// land at a registry index the round would otherwise have treated as
/// "safe" — see holderGenerationCounter's own comment and
/// PlatformRewardsDistributor.processAirdropBatch for the full mechanics.
contract PlatformToken is ERC20, ERC20Burnable, Ownable2Step {
    address[] private _holderList;
    mapping(address => uint256) private _holderIndex; // 1-based index into _holderList; 0 means "not currently a holder"

    /// @notice Monotonically increasing counter, bumped once every time an
    /// address transitions from a zero balance to a nonzero one (i.e. every
    /// time _addHolder actually registers someone new, whether for the
    /// first time ever or re-entering after a previous exit) — see
    /// holderGeneration below and _addHolder. Added specifically so
    /// PlatformRewardsDistributor's airdrop rounds can tell a genuine
    /// round-start holder apart from an address that only entered (or
    /// re-entered) the registry after a round had already started, even
    /// when that address happens to land at a registry INDEX that existed
    /// at round start (which can happen because _removeHolder's swap-and-pop
    /// can hand a freshly-vacated low index to a brand-new holder — see
    /// PlatformRewardsDistributor.processAirdropBatch's own comment on
    /// roundGenerationAtStart for the full reasoning). Starts at 0 (no
    /// holder has ever been registered); the first holder ever added gets
    /// generation 1, matching this file's own existing 1-based
    /// _holderIndex convention.
    uint256 public holderGenerationCounter;

    /// @notice The generation stamped on `account` the most recent time it
    /// was added to the holder registry (see holderGenerationCounter
    /// above). 0 means the address has never been a holder. An address that
    /// drains to zero and is later re-added gets a NEW, higher generation —
    /// deliberately: whatever balance it holds after re-entering has no
    /// relationship to any round's supply snapshot computed before that
    /// re-entry, so it must be treated as a brand-new entrant, not as
    /// continuously eligible since its original, long-ago first entry.
    mapping(address => uint256) public holderGeneration;

    /// @param name_ Token name.
    /// @param symbol_ Token symbol.
    /// @param totalSupply_ The entire, fixed supply — minted once, here,
    /// and never again. There is no mint() function anywhere in this
    /// contract.
    /// @param initialHolder_ Where the full supply lands at construction —
    /// expected to be the deployer/admin wallet, who from there seeds
    /// liquidity (via this same platform's own launch flow or directly
    /// against the DEX router) exactly like any other token's creator
    /// would, entirely as a separate, later step from this deployment.
    constructor(
        string memory name_,
        string memory symbol_,
        uint256 totalSupply_,
        address initialHolder_
    ) ERC20(name_, symbol_) Ownable(msg.sender) {
        require(totalSupply_ > 0, "PlatformToken: supply must be > 0");
        require(initialHolder_ != address(0), "PlatformToken: invalid initial holder");
        _mint(initialHolder_, totalSupply_);
    }

    /// @notice How many distinct addresses currently hold a nonzero
    /// balance. Grows/shrinks automatically as balances cross zero — see
    /// _update below.
    function holderCount() external view returns (uint256) {
        return _holderList.length;
    }

    /// @notice The holder address at a given registry index. Indices are
    /// NOT stable across calls that change the registry (removal is
    /// swap-and-pop, same as OpenZeppelin's EnumerableSet) — callers that
    /// need to walk the whole set across multiple transactions, like
    /// PlatformRewardsDistributor's batched airdrop, must tolerate that a
    /// holder's index can shift if someone else's balance hits zero in
    /// between. See PlatformRewardsDistributor.processAirdropBatch for how
    /// that tradeoff is handled.
    function holderAt(uint256 index) external view returns (address) {
        return _holderList[index];
    }

    /// @dev Maintains the holder registry alongside every mint, burn, and
    /// transfer. Runs after the balance change itself (super._update), so
    /// balanceOf(from)/balanceOf(to) below already reflect the new
    /// balances. Adding an address that's already present, or removing one
    /// that's already absent, is a harmless no-op.
    function _update(address from, address to, uint256 value) internal override(ERC20) {
        super._update(from, to, value);

        if (from != address(0) && balanceOf(from) == 0) {
            _removeHolder(from);
        }
        if (to != address(0) && balanceOf(to) > 0) {
            _addHolder(to);
        }
    }

    function _addHolder(address account) private {
        if (_holderIndex[account] != 0) return; // already registered
        _holderList.push(account);
        _holderIndex[account] = _holderList.length; // 1-based
        holderGenerationCounter += 1;
        holderGeneration[account] = holderGenerationCounter;
    }

    function _removeHolder(address account) private {
        uint256 idx = _holderIndex[account]; // 1-based
        if (idx == 0) return; // not registered

        uint256 lastIndex = _holderList.length; // also 1-based, since length == count
        if (idx != lastIndex) {
            address lastAccount = _holderList[lastIndex - 1];
            _holderList[idx - 1] = lastAccount;
            _holderIndex[lastAccount] = idx;
        }
        _holderList.pop();
        delete _holderIndex[account];
    }
}

contracts/TokenFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/proxy/Clones.sol";
import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

import "./LaunchedToken.sol";
import "./LiquidityLocker.sol";
import "./interfaces/IUniswapV2Router02.sol";

/// @title TokenFactory
/// @notice The entry point for a launch. Every launch starts with
/// createToken(), which picks one of two completely different paths:
///
///  - addLiquidityAtLaunch = false ("Deploy Token"): create + verify only.
///    100% of the supply mints straight into msg.sender's own wallet. No
///    pool, no tax, no further on-chain involvement from this contract at
///    all — the transaction is over the moment it confirms. Adding
///    liquidity anywhere, any time, by whatever means, is entirely the
///    creator's own responsibility from here. Costs a flat deployFee.
///
///  - addLiquidityAtLaunch = true ("Deploy and Add Liquidity (Launch)"):
///    token creation and liquidity provisioning happen atomically, in this
///    same transaction. 100% of the supply is minted to this factory,
///    paired against the creator's ETH into a real DEX pool, and the
///    resulting LP tokens are locked to the creator for lpLockDuration
///    starting right now (see LiquidityLocker) — the creator can never pull
///    it back out early. The token also gets a feeBps transfer tax on
///    trades against that pool, routed to platformFeeWallet, until the
///    pool's live market cap crosses graduationTargetUsd, at which point
///    the tax permanently disables itself (see LaunchedToken). An optional
///    creatorBuyEthAmount, on top of the liquidity, executes an ordinary
///    buy against the pool in this same transaction — guaranteed to be the
///    first trade against it, but capped at maxCreatorBuyBps of totalSupply
///    (default 5%) as an anti-rug safeguard: a buy-in that would land above
///    the cap reverts the whole launch instead of partially executing.
///    Costs a flat launchFee, separate from (and normally higher than)
///    deployFee, on top of the liquidity/buy-in ETH.
///
/// deployFee and launchFee are each a fixed wei amount set by the owner
/// (see setDeployFee/setLaunchFee) — this contract has no live USD/ETH
/// price awareness of its own, so keeping them tracking a USD target (e.g.
/// $50 / $100) as ETH's price moves is an off-chain job: the front end
/// reads these values live before building a transaction, and the owner
/// (or a scheduled script — see scripts/updateFees.js) is expected to
/// update them periodically against a live ETH/USD price.
contract TokenFactory is Ownable2Step, ReentrancyGuard {
    address public immutable tokenImplementation;
    IUniswapV2Router02 public immutable router;
    LiquidityLocker public immutable locker;

    uint256 public deployFee; // "Deploy Token" — create + verify only, no liquidity
    uint256 public launchFee; // "Deploy and Add Liquidity (Launch)" — atomic creation + pool
    address public feeTreasury;
    uint256 public lpLockDuration;

    // ---- transfer-tax defaults, applied to every "Launch + Add Liquidity"
    // pool created after a change (existing pools keep whatever they were
    // created with — see LaunchedToken.configureTax) ----
    /// @notice Hard ceiling on feeBps_ in setTaxDefaults, well below the
    /// mathematical 100% limit. Bounds how punishing a future launch's
    /// transfer tax can ever be set, even by a fully trusted owner acting
    /// in good faith by mistake or a compromised owner key acting in bad
    /// faith — 2,000 bps (20%) is intentionally generous relative to the
    /// 1.00% default so it never gets in the way of a legitimate tax
    /// change, while still ruling out a tax so high it's effectively
    /// confiscatory or makes a token untradeable. Adjust this constant if a
    /// different ceiling fits the platform's actual policy.
    uint256 public constant MAX_FEE_BPS = 2_000; // 20.00%

    address public platformFeeWallet;
    // Aligned to 100 (1.00%) to match every other launch mode's default
    // (CustomTokenFactory, BondingCurveFactory, CustomBondingCurveFactory all
    // default feeBps to 1.00%) — previously 25 (0.25%) here only, which left
    // this one launch mode's ongoing trading tax at a different rate than
    // the other three for no documented reason.
    uint256 public feeBps = 100; // 1.00%
    address public priceFeed;
    // Aligned to 50_000 to match every other launch mode's default
    // (CustomTokenFactory, BondingCurveFactory, CustomBondingCurveFactory all
    // graduate their transfer tax at the same $50,000 live-market-cap target)
    // — previously 80_000 here only, which left this one launch mode's tax
    // running longer than the other three for no documented reason.
    uint256 public graduationTargetUsd = 50_000; // whole dollars; tax permanently disables once a pool's live market cap crosses this
    uint256 public maxOracleStaleness = 1 hours;

    /// @notice PlatformRewardsDistributor's address — the platform's own
    /// buyback/burn/holder-airdrop contract. address(0) (the default)
    /// disables this entirely: every deployFee/launchFee stays 100%
    /// feeTreasury (see _finalizeLaunch below), and every launch from here
    /// on configures its token with no reward diversion at all (see
    /// LaunchedToken.configureTax). Set once, via setRewardsDistributor,
    /// whenever the platform token itself launches — nothing about
    /// flipping this on ever touches a token or launch that already
    /// happened.
    address public rewardsDistributor;

    /// @notice Out of feeBps (the platform's ongoing 1.00% trading tax),
    /// how much (in absolute bps, e.g. 10 = 0.10%) gets diverted to
    /// rewardsDistributor instead of platformFeeWallet — carved OUT OF
    /// feeBps, never added on top of it. Must stay <= feeBps (enforced in
    /// setTaxDefaults); has no effect at all while rewardsDistributor is
    /// unset. Snapshotted per-token at launch, same as every other tax
    /// default here.
    ///
    /// Defaults to 0 by design: PlatformRewardsDistributor (rewardsDistributor
    /// above) is meant to be funded ONLY by the one-time 50% launch/deploy-fee
    /// share it already receives directly in _finalizeLaunch — never by the
    /// ongoing per-trade tax. With rewardBps at 0, no per-trade tax is ever
    /// diverted to rewardsDistributor; the full remainder (feeBps minus
    /// creatorRewardBps) flows entirely to feeWalletDistributor/feeWallet
    /// instead (see toFeeWallet in LaunchedToken._update — it's computed as
    /// `fee - rewardCut - creatorCut`, so a zero rewardCut requires no other
    /// code change for feeWalletDistributor to receive that share). Owner can
    /// still turn ongoing rewardsDistributor funding back on via
    /// setTaxDefaults for future launches, but that is a deliberate
    /// exception, not the shipped default.
    uint256 public rewardBps = 0;

    /// @notice CreatorRewardsDistributor's address — pays a slice of the
    /// ongoing trading tax back to each token's own creator, in native ETH,
    /// claimable per token (see CreatorRewardsDistributor.sol). address(0)
    /// (the default) disables this entirely: every launch from here on
    /// configures its token with no creator-reward diversion at all. Set
    /// once, via setCreatorRewardsDistributor — nothing about flipping this
    /// on ever touches a token or launch that already happened, same
    /// convention as rewardsDistributor above.
    address public creatorRewardsDistributor;

    /// @notice Out of feeBps, how much (absolute bps) gets diverted to
    /// creatorRewardsDistributor instead of platformFeeWallet — carved OUT
    /// OF feeBps, never added on top of it, and never overlapping
    /// rewardBps above (rewardBps + creatorRewardBps must stay <= feeBps,
    /// enforced in setTaxDefaults). Has no effect at all while
    /// creatorRewardsDistributor is unset. Snapshotted per-token at launch,
    /// same as every other tax default here.
    ///
    /// Aligned to 10 (0.10%) to match every other launch mode's default
    /// (CustomTokenFactory, BondingCurveFactory, CustomBondingCurveFactory
    /// all default creatorRewardBps to 0.10%) — previously 5 (0.05%) here
    /// only.
    uint256 public creatorRewardBps = 10; // 0.10%

    /// @notice FeeWalletDistributor's address — automatically converts the
    /// remainder of feeBps that would otherwise sit at platformFeeWallet as
    /// a plain token balance into ETH instead (see FeeWalletDistributor.sol
    /// and LaunchedToken.configureTax). address(0) (the default) disables
    /// this entirely: every launch from here on configures its token with
    /// no fee-wallet diversion at all, and that remainder goes straight to
    /// platformFeeWallet exactly as it always has. Set once, via
    /// setFeeWalletDistributor — nothing about flipping this on ever
    /// touches a token or launch that already happened, same convention as
    /// rewardsDistributor/creatorRewardsDistributor above. Unlike those two,
    /// there's no companion bps to configure here — the amount routed is
    /// simply whatever's left of feeBps after rewardBps/creatorRewardBps,
    /// so there's nothing for setTaxDefaults to validate a bound on.
    address public feeWalletDistributor;

    // ---- anti-rug safeguard on the creator's own same-transaction buy-in
    // (see _launchWithLiquidity) ----
    uint256 public maxCreatorBuyBps = 500; // 5.00% of totalSupply_ by default

    /// @notice Slippage tolerance applied to addLiquidityETH()'s own
    /// amountTokenMin/amountETHMin — protects the initial liquidity seed
    /// against a bot that manipulates the pair's reserves between when this
    /// transaction is submitted and when it actually lands (e.g. donating
    /// tokens/ETH straight to the pair, or racing another swap into the
    /// same block), which would otherwise let the router accept a far worse
    /// price than the creator intended with the old amountTokenMin=0/
    /// amountETHMin=0. Router itself still reverts the whole launch
    /// (liquidity add included) if the actual amounts land outside this
    /// band, rather than silently accepting a bad fill. Owner-adjustable
    /// within a fixed 5.00%–8.00% band (see setLiquiditySlippageBps) — wide
    /// enough to absorb ordinary reserve noise, never so wide it stops
    /// meaning anything.
    uint256 public liquiditySlippageBps = 600; // 6.00% default, i.e. the midpoint of the allowed band
    uint256 public constant MIN_LIQUIDITY_SLIPPAGE_BPS = 500; // 5.00%
    uint256 public constant MAX_LIQUIDITY_SLIPPAGE_BPS = 800; // 8.00%

    /// @dev floor = amount minus liquiditySlippageBps of it, i.e. the
    /// smallest amount addLiquidityETH is allowed to actually use.
    function _minWithSlippage(uint256 amount) private view returns (uint256) {
        return amount - (amount * liquiditySlippageBps) / 10_000;
    }

    /// @notice Same protection as liquiditySlippageBps, applied to the
    /// creator's own same-transaction buy-in instead of the liquidity add —
    /// that swap trades against a pool that now genuinely has reserves, so
    /// unlike a virgin addLiquidityETH call, it's a real, sandwichable
    /// trade. Owner-adjustable within the same fixed 5.00%–8.00% band (see
    /// setBuyInSlippageBps). This is a FLOOR only: the caller-supplied
    /// minCreatorTokensOut still applies too, whichever is stricter wins
    /// (see _effectiveMinBuyOut) — this never loosens a caller's own tighter
    /// request, only backstops a missing or lazy one (the front end
    /// currently always sends 0).
    uint256 public buyInSlippageBps = 600; // 6.00% default, i.e. the midpoint of the allowed band

    /// @dev Standard Uniswap V2 constant-product quote (0.30% swap fee
    /// baked into the 997/1000 constants — the near-universal fee for a
    /// V2-style router, which is what this contract's IUniswapV2Router02
    /// interface targets). Used only to derive a slippage floor below,
    /// never to execute anything — a router charging a different fee makes
    /// this an approximation of the real quote, which is fine since it only
    /// ever sets a protective floor, not the trade itself.
    function _getAmountOut(uint256 amountIn, uint256 reserveIn, uint256 reserveOut) private pure returns (uint256) {
        uint256 amountInWithFee = amountIn * 997;
        uint256 numerator = amountInWithFee * reserveOut;
        uint256 denominator = reserveIn * 1000 + amountInWithFee;
        return numerator / denominator;
    }

    /// @dev Computes the buy-in's protective floor from the pool's own
    /// just-added reserves (known exactly — this is always that pool's
    /// first-ever liquidity), nets out feeBps first (the tax this exact
    /// trade will pay, so the tax itself is never mistaken for hostile
    /// slippage), then applies buyInSlippageBps — and returns whichever is
    /// stricter, that floor or the caller's own minCreatorTokensOut.
    function _effectiveMinBuyOut(
        uint256 creatorBuyEthAmount,
        uint256 ethReserve,
        uint256 tokenReserve,
        uint256 callerMinOut
    ) private view returns (uint256) {
        uint256 grossOut = _getAmountOut(creatorBuyEthAmount, ethReserve, tokenReserve);
        uint256 expectedNetOut = grossOut - (grossOut * feeBps) / 10_000;
        uint256 floor = expectedNetOut - (expectedNetOut * buyInSlippageBps) / 10_000;
        return callerMinOut > floor ? callerMinOut : floor;
    }

    mapping(address => address) public creatorOf;
    mapping(address => address) public pairOf; // token => its DEX pair, or address(0) for a "Just Launch" token
    address[] private _tokenList;
    mapping(address => address[]) private _tokensByCreator;

    // ---- gasless relayed launches ----
    //
    // Normal flow (createToken above): the creator's own wallet submits the
    // deploy transaction directly and pays its gas out of pocket, same as
    // any blockchain transaction — that gas is separate from and in
    // addition to deployFee/launchFee.
    //
    // Relayed flow (below): the creator instead (1) signs a LaunchVoucher
    // off-chain — free, no gas, an EIP-712 typed message committing to the
    // exact launch parameters — then (2) sends ONE plain ETH transfer into
    // escrow via depositForRelayedLaunch (a cheap, simple deposit, NOT the
    // expensive deploy/liquidity transaction). A trusted `relayer` address
    // (a platform-operated hot wallet, see setRelayer) then calls
    // relayedCreateToken, paying gas out of ITS OWN balance to actually
    // perform the deploy (and, for the liquidity path, the pool seeding).
    // In that same transaction, the contract measures the gas the relayer
    // just spent, reimburses exactly that (capped — see
    // maxRelayerGasReimbursementWei) back to the relayer out of the
    // escrowed fee, and only THEN splits the true remainder 50/50 between
    // feeTreasury and rewardsDistributor (or 100% feeTreasury if
    // rewardsDistributor is unset) — identical payout rule to
    // _finalizeLaunch, just applied to what's left after gas rather than
    // the raw fee.
    //
    // If the relayer never processes a deposit before its own deadline
    // (e.g. the relayer service is down), the depositor — and only the
    // depositor — can pull their full escrowed ETH back via
    // reclaimDeposit(). Deposits are keyed by (depositor address, voucher
    // hash) specifically so no one else can ever front-run or squat a
    // voucher hash that isn't theirs — a deposit under any other address
    // simply lives in a different storage slot and can never collide with
    // or block the real creator's own deposit.

    /// @notice The platform's relayer hot wallet — the only address allowed
    /// to call relayedCreateToken. address(0) (the default) disables the
    /// entire relayed-launch feature; depositForRelayedLaunch/
    /// reclaimDeposit still work either way, so a deposit made while no
    /// relayer is configured can simply be reclaimed once its deadline
    /// passes.
    address public relayer;

    /// @notice Safety cap, in wei, on how much gas reimbursement a single
    /// relayedCreateToken call can pay itself out of one voucher's fee — a
    /// circuit breaker against a compromised or malfunctioning relayer key
    /// inflating tx.gasprice to drain more than a real deploy could ever
    /// cost. 0 (the default) means no cap — but setRelayer refuses to
    /// enable a relayer while this is still 0, so a real value must be
    /// chosen (via setMaxRelayerGasReimbursement) before the relayed-launch
    /// feature can actually be used; this variable can only ever be 0 while
    /// there is also no relayer configured to spend it.
    uint256 public maxRelayerGasReimbursementWei;

    /// @dev Flat gas-unit buffer added on top of the gas actually measured
    /// via gasleft() inside relayedCreateToken, to account for the
    /// intrinsic per-transaction cost (base 21,000 + calldata) that isn't
    /// visible to gasleft() diffing from inside the call itself.
    uint256 public constant RELAY_GAS_OVERHEAD = 60_000;

    struct Deposit {
        uint256 amount;
        uint256 deadline;
        bool settled;
        bool reclaimed;
    }

    /// @notice creator => voucher hash => their escrowed deposit. Keying by
    /// creator address (rather than a flat hash => Deposit map) is what
    /// makes the whole scheme front-running-proof: depositing under someone
    /// else's address is impossible, so no one can ever claim or block a
    /// voucher hash that isn't rightfully theirs.
    mapping(address => mapping(bytes32 => Deposit)) public deposits;

    struct LaunchVoucher {
        address creator;
        string name;
        string symbol;
        uint256 totalSupply;
        bool addLiquidityAtLaunch;
        uint256 liquidityEthAmount;
        uint256 creatorBuyEthAmount;
        uint256 minCreatorTokensOut;
        uint256 fee; // deployFee or launchFee the creator locked in and escrowed at deposit time
        // Doubles as the CREATE2 salt relayedCreateToken deploys the clone
        // with (see Clones.cloneDeterministic there) — originally just
        // "front-end-generated randomness to keep two otherwise-identical
        // vouchers from hashing the same," which a mined-for-a-chosen-
        // address-suffix value still satisfies (each mined salt is
        // effectively unique), so no new voucher field or signature format
        // was needed to add vanity addresses to the relayed path.
        uint256 salt;
        uint256 deadline; // both the voucher's and the matching deposit's expiry
    }

    bytes32 private constant LAUNCH_VOUCHER_TYPEHASH = keccak256(
        "LaunchVoucher(address creator,string name,string symbol,uint256 totalSupply,bool addLiquidityAtLaunch,uint256 liquidityEthAmount,uint256 creatorBuyEthAmount,uint256 minCreatorTokensOut,uint256 fee,uint256 salt,uint256 deadline)"
    );

    // Hand-rolled EIP-712 domain separator rather than pulling in
    // OpenZeppelin's EIP712 base: that base (via MessageHashUtils ->
    // Strings -> Bytes) uses the `mcopy` opcode, which only exists from the
    // Cancun hardfork on — a hard, silent requirement this contract has no
    // business imposing on whichever EVM Robinhood Chain actually runs.
    // This does the identical ERC-5267 domain-separator construction with
    // nothing but keccak256/abi.encode, which every EVM version supports.
    bytes32 private constant EIP712_DOMAIN_TYPEHASH = keccak256(
        "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
    );
    bytes32 private immutable _domainSeparator;

    event RelayerUpdated(address newRelayer);
    event MaxRelayerGasReimbursementUpdated(uint256 newCapWei);
    event LaunchDeposited(bytes32 indexed voucherHash, address indexed creator, uint256 amount, uint256 deadline);
    event DepositReclaimed(bytes32 indexed voucherHash, address indexed creator, uint256 amount);
    event RelayedFeeSettled(
        bytes32 indexed voucherHash,
        address indexed token,
        uint256 feeCollected,
        uint256 gasReimbursed,
        uint256 toTreasury,
        uint256 toRewards
    );

    modifier onlyRelayer() {
        require(msg.sender == relayer, "TokenFactory: caller is not the relayer");
        _;
    }

    event TokenCreated(
        address indexed token,
        address indexed creator,
        string name,
        string symbol,
        uint256 totalSupply,
        bool launchedWithLiquidity,
        address pair
    );
    event LiquidityAdded(
        address indexed token,
        address indexed creator,
        uint256 ethAmount,
        uint256 tokenAmount,
        uint256 lpAmount,
        uint256 unlockTime,
        uint256 indexed lockId,
        address pair
    );
    event CreatorBought(address indexed token, address indexed creator, uint256 ethIn, uint256 tokensOut);
    event DeployFeeUpdated(uint256 newFee);
    event LaunchFeeUpdated(uint256 newFee);
    event LpLockDurationUpdated(uint256 newDuration);
    event FeeTreasuryUpdated(address newTreasury);
    event TaxDefaultsUpdated();
    event MaxCreatorBuyBpsUpdated(uint256 newBps);
    event LiquiditySlippageBpsUpdated(uint256 newBps);
    event BuyInSlippageBpsUpdated(uint256 newBps);
    event RewardsDistributorUpdated(address newDistributor);
    event CreatorRewardsDistributorUpdated(address newDistributor);
    event FeeWalletDistributorUpdated(address newDistributor);
    event TokenPriceFeedUpdated(address indexed token, address newPriceFeed, uint256 newMaxOracleStaleness);

    constructor(
        address tokenImplementation_,
        address router_,
        address locker_,
        uint256 deployFee_,
        uint256 launchFee_,
        address feeTreasury_,
        uint256 lpLockDuration_,
        address platformFeeWallet_,
        address priceFeed_
    ) Ownable(msg.sender) {
        require(tokenImplementation_ != address(0), "TokenFactory: invalid token implementation");
        require(router_ != address(0), "TokenFactory: invalid router");
        require(locker_ != address(0), "TokenFactory: invalid locker");
        require(feeTreasury_ != address(0), "TokenFactory: invalid treasury");

        tokenImplementation = tokenImplementation_;
        router = IUniswapV2Router02(router_);
        locker = LiquidityLocker(locker_);
        deployFee = deployFee_;
        launchFee = launchFee_;
        feeTreasury = feeTreasury_;
        lpLockDuration = lpLockDuration_;
        platformFeeWallet = platformFeeWallet_;
        priceFeed = priceFeed_;

        _domainSeparator = keccak256(
            abi.encode(
                EIP712_DOMAIN_TYPEHASH,
                keccak256(bytes("HoodLaunchTokenFactory")),
                keccak256(bytes("1")),
                block.chainid,
                address(this)
            )
        );
    }

    /// @dev See the comment on _domainSeparator for why this is hand-rolled
    /// instead of OpenZeppelin's EIP712._hashTypedDataV4.
    function _hashTypedDataV4(bytes32 structHash) private view returns (bytes32) {
        return keccak256(abi.encodePacked("\x19\x01", _domainSeparator, structHash));
    }

    /// @dev The actual CREATE2 salt used for a given (creator, caller-chosen
    /// salt) pair is keccak256(abi.encode(creator_, salt)) rather than the
    /// raw salt value — this binds the resulting clone address to the
    /// creator who mined it. Without this binding, a salt (and the exact
    /// calldata carrying it) sitting in the public mempool could be copied
    /// verbatim by a third party and resubmitted with higher gas, landing
    /// their transaction first and permanently claiming that address for a
    /// token of their own choosing, while the original submitter's
    /// transaction reverts (CREATE2 to an already-deployed address always
    /// does). Binding the salt to the creator's address makes the resulting
    /// address unreproducible by anyone else, closing that front-running
    /// window while preserving the ability to mine a salt for a chosen
    /// address suffix (the miner just needs to include its own address in
    /// the off-chain search).
    function _deriveTokenSalt(address creator_, uint256 salt) private pure returns (bytes32) {
        return keccak256(abi.encode(creator_, salt));
    }

    /// @notice Deploy a new token, in either mode. msg.value must equal
    /// deployFee exactly for "Deploy Token", or launchFee +
    /// liquidityEthAmount + creatorBuyEthAmount for "Deploy and Add
    /// Liquidity (Launch)" — liquidityEthAmount and creatorBuyEthAmount are
    /// both ignored (and must be 0) in "Deploy Token" mode.
    ///
    /// @param salt Caller-chosen CREATE2 salt input for the clone's address
    /// (see predictTokenAddress below to preview the resulting address
    /// before sending this transaction). Deployed via
    /// Clones.cloneDeterministic rather than the old plain Clones.clone
    /// specifically so the front end can pick a salt that lands on a chosen
    /// address suffix (the platform mines one ending in its own chain ID) —
    /// any salt works, including 0; this contract places no meaning on the
    /// value itself, only on the address it produces. The actual CREATE2
    /// salt used is derived from (msg.sender, salt) — see _deriveTokenSalt —
    /// so the resulting address is bound to the caller and cannot be
    /// reproduced or front-run by anyone else. Reusing a salt already used
    /// by this same caller with this same implementation simply reverts
    /// (CREATE2 to an already-deployed address always does), so a caller
    /// that wants a specific suffix picks a fresh salt and tries again
    /// rather than resubmitting the same one.
    function createToken(
        string calldata name_,
        string calldata symbol_,
        uint256 totalSupply_,
        bool addLiquidityAtLaunch,
        uint256 liquidityEthAmount,
        uint256 creatorBuyEthAmount,
        uint256 minCreatorTokensOut,
        uint256 salt
    ) external payable nonReentrant returns (address token, uint256 lpAmount, uint256 lockId, uint256 creatorTokensBought) {
        require(bytes(name_).length > 0, "TokenFactory: name required");
        require(bytes(symbol_).length > 0, "TokenFactory: symbol required");
        require(totalSupply_ > 0, "TokenFactory: supply must be > 0");

        token = Clones.cloneDeterministic(tokenImplementation, _deriveTokenSalt(msg.sender, salt));
        address pair;
        uint256 feeCollected;

        if (!addLiquidityAtLaunch) {
            require(msg.value == deployFee, "TokenFactory: incorrect ETH sent for Deploy Token");
            feeCollected = deployFee;
            LaunchedToken(token).initialize(name_, symbol_, totalSupply_, msg.sender, msg.sender, address(this), false);
        } else {
            (lpAmount, lockId, creatorTokensBought, pair) = _createWithLiquidity(
                token,
                name_,
                symbol_,
                totalSupply_,
                liquidityEthAmount,
                creatorBuyEthAmount,
                minCreatorTokensOut
            );
            pairOf[token] = pair;
            feeCollected = launchFee;
        }

        _finalizeLaunch(token, feeCollected);

        emit TokenCreated(token, msg.sender, name_, symbol_, totalSupply_, addLiquidityAtLaunch, pair);
    }

    /// @dev Validates the ETH split and runs LaunchedToken.initialize() for
    /// the "Deploy and Add Liquidity (Launch)" path, then hands off to
    /// _launchWithLiquidity() for the rest. Split out purely to keep
    /// createToken()'s own stack shallow enough to compile.
    function _createWithLiquidity(
        address token,
        string calldata name_,
        string calldata symbol_,
        uint256 totalSupply_,
        uint256 liquidityEthAmount,
        uint256 creatorBuyEthAmount,
        uint256 minCreatorTokensOut
    ) internal returns (uint256 lpAmount, uint256 lockId, uint256 creatorTokensBought, address pair) {
        require(msg.value >= launchFee, "TokenFactory: launch fee not met");
        require(
            msg.value - launchFee == liquidityEthAmount + creatorBuyEthAmount,
            "TokenFactory: msg.value doesn't match liquidity + buy-in"
        );
        LaunchedToken(token).initialize(name_, symbol_, totalSupply_, msg.sender, address(this), address(this), false);
        (lpAmount, lockId, creatorTokensBought, pair) = _launchWithLiquidity(
            token,
            totalSupply_,
            liquidityEthAmount,
            creatorBuyEthAmount,
            minCreatorTokensOut
        );
    }

    function _finalizeLaunch(address token, uint256 feeCollected) internal {
        // Effects before interactions: every piece of this factory's own
        // state for `token` is finalized before the external call(s)
        // below, so a reentrant call during a fee transfer (e.g. a
        // malicious or buggy feeTreasury/rewardsDistributor) can never
        // observe this launch half-recorded.
        creatorOf[token] = msg.sender;
        _tokensByCreator[msg.sender].push(token);
        _tokenList.push(token);

        if (feeCollected == 0) return;

        // 50% of every deployFee/launchFee stays platform profit exactly as
        // before; the other 50% funds the platform's own buyback/burn/
        // holder-rewards contract, once one is configured. While
        // rewardsDistributor is unset, this is 100% feeTreasury, byte-for-
        // byte the same behavior this contract has always had.
        if (rewardsDistributor != address(0)) {
            uint256 toRewards = feeCollected / 2;
            uint256 toTreasury = feeCollected - toRewards;
            if (toRewards > 0) {
                (bool sentRewards, ) = rewardsDistributor.call{value: toRewards}("");
                require(sentRewards, "TokenFactory: rewards transfer failed");
            }
            (bool sent, ) = feeTreasury.call{value: toTreasury}("");
            require(sent, "TokenFactory: fee transfer failed");
        } else {
            (bool sent, ) = feeTreasury.call{value: feeCollected}("");
            require(sent, "TokenFactory: fee transfer failed");
        }
    }

    /// @notice Computes the exact EIP-712 digest a creator must sign to
    /// authorize a relayed launch. Front ends call this (or reproduce it
    /// off-chain with an identical typed-data structure) to build the
    /// eth_signTypedData_v4 payload, and it's recomputed here again inside
    /// relayedCreateToken to check the relayer-submitted voucher against
    /// that signature.
    function hashLaunchVoucher(LaunchVoucher calldata voucher) public view returns (bytes32) {
        bytes32 structHash = keccak256(
            abi.encode(
                LAUNCH_VOUCHER_TYPEHASH,
                voucher.creator,
                keccak256(bytes(voucher.name)),
                keccak256(bytes(voucher.symbol)),
                voucher.totalSupply,
                voucher.addLiquidityAtLaunch,
                voucher.liquidityEthAmount,
                voucher.creatorBuyEthAmount,
                voucher.minCreatorTokensOut,
                voucher.fee,
                voucher.salt,
                voucher.deadline
            )
        );
        return _hashTypedDataV4(structHash);
    }

    /// @notice Step 2 of a relayed launch (step 1 is signing the voucher
    /// off-chain, for free): the creator sends exactly
    /// voucher.fee + (liquidity + buy-in, if addLiquidityAtLaunch) as a
    /// plain ETH transfer, keyed by their own address and this exact
    /// voucher's hash. Cheap — an ordinary transfer plus one storage write,
    /// nowhere near the gas a real deploy (let alone deploy + seed
    /// liquidity) costs. msg.sender is always the escrow's owner for this
    /// hash: depositing under someone else's address is impossible, so a
    /// deposit here can never be front-run or squatted by anyone but the
    /// creator themselves.
    function depositForRelayedLaunch(bytes32 voucherHash, uint256 deadline) external payable nonReentrant {
        require(msg.value > 0, "TokenFactory: no ETH sent");
        require(deadline > block.timestamp, "TokenFactory: deadline already passed");
        Deposit storage d = deposits[msg.sender][voucherHash];
        require(d.amount == 0, "TokenFactory: voucher already funded");
        d.amount = msg.value;
        d.deadline = deadline;
        emit LaunchDeposited(voucherHash, msg.sender, msg.value, deadline);
    }

    /// @notice Lets a depositor pull their full escrowed ETH back once its
    /// deadline has passed without being relayed — the safety valve if the
    /// relayer service never picks up a deposit (down, misconfigured, or
    /// simply never launched because relayer is unset).
    function reclaimDeposit(bytes32 voucherHash) external nonReentrant {
        Deposit storage d = deposits[msg.sender][voucherHash];
        require(d.amount > 0, "TokenFactory: no such deposit");
        require(!d.settled, "TokenFactory: voucher already relayed");
        require(!d.reclaimed, "TokenFactory: already reclaimed");
        require(block.timestamp > d.deadline, "TokenFactory: deadline has not passed yet");
        d.reclaimed = true;
        uint256 amount = d.amount;
        (bool sent, ) = payable(msg.sender).call{value: amount}("");
        require(sent, "TokenFactory: refund transfer failed");
        emit DepositReclaimed(voucherHash, msg.sender, amount);
    }

    /// @notice Step 3 of a relayed launch, called only by the trusted
    /// relayer: verifies the creator's signature over `voucher` and that a
    /// matching, unexpired, unsettled deposit of exactly the right amount
    /// exists, then performs the identical deploy (and, for the liquidity
    /// path, pool-seeding) logic createToken() runs — with `voucher.creator`
    /// standing in everywhere createToken() would otherwise have used
    /// msg.sender, since here msg.sender is the relayer, not the creator.
    /// Ends by reimbursing the relayer's own gas cost out of the escrowed
    /// fee and splitting the true remainder exactly as _finalizeLaunch
    /// does. The relayer pays this call's gas from its own wallet; the
    /// creator touches no gas at any point in a relayed launch.
    function relayedCreateToken(
        LaunchVoucher calldata voucher,
        bytes calldata signature
    ) external onlyRelayer nonReentrant returns (address token, uint256 lpAmount, uint256 lockId, uint256 creatorTokensBought) {
        uint256 gasStart = gasleft();

        require(block.timestamp <= voucher.deadline, "TokenFactory: voucher expired");
        require(bytes(voucher.name).length > 0, "TokenFactory: name required");
        require(bytes(voucher.symbol).length > 0, "TokenFactory: symbol required");
        require(voucher.totalSupply > 0, "TokenFactory: supply must be > 0");

        bytes32 voucherHash = hashLaunchVoucher(voucher);
        address signer = ECDSA.recover(voucherHash, signature);
        require(signer == voucher.creator, "TokenFactory: signature does not match voucher creator");

        Deposit storage d = deposits[voucher.creator][voucherHash];
        require(d.amount > 0, "TokenFactory: no matching deposit");
        require(!d.settled, "TokenFactory: voucher already relayed");
        require(!d.reclaimed, "TokenFactory: deposit already reclaimed");
        require(block.timestamp <= d.deadline, "TokenFactory: deposit expired, creator must reclaim");

        uint256 expectedDeposit = voucher.fee +
            (voucher.addLiquidityAtLaunch ? voucher.liquidityEthAmount + voucher.creatorBuyEthAmount : 0);
        require(d.amount == expectedDeposit, "TokenFactory: deposit does not match voucher amount");

        d.settled = true; // effects before interactions, same discipline as _finalizeLaunch

        token = Clones.cloneDeterministic(tokenImplementation, _deriveTokenSalt(voucher.creator, voucher.salt));
        address pair;

        if (!voucher.addLiquidityAtLaunch) {
            LaunchedToken(token).initialize(
                voucher.name, voucher.symbol, voucher.totalSupply, voucher.creator, voucher.creator, address(this), false
            );
        } else {
            LaunchedToken(token).initialize(
                voucher.name, voucher.symbol, voucher.totalSupply, voucher.creator, address(this), address(this), false
            );
            (lpAmount, lockId, creatorTokensBought, pair) = _relayedLaunchWithLiquidity(
                token,
                voucher.creator,
                voucher.totalSupply,
                voucher.liquidityEthAmount,
                voucher.creatorBuyEthAmount,
                voucher.minCreatorTokensOut
            );
            pairOf[token] = pair;
        }

        creatorOf[token] = voucher.creator;
        _tokensByCreator[voucher.creator].push(token);
        _tokenList.push(token);

        emit TokenCreated(token, voucher.creator, voucher.name, voucher.symbol, voucher.totalSupply, voucher.addLiquidityAtLaunch, pair);

        _settleRelayedFee(voucherHash, token, voucher.fee, gasStart);
    }

    /// @dev Relayed counterpart to _launchWithLiquidity — identical
    /// behavior, just parameterized on an explicit `creator_` everywhere
    /// the original used msg.sender, since the relayer (not the creator) is
    /// msg.sender for this call.
    function _relayedLaunchWithLiquidity(
        address token,
        address creator_,
        uint256 totalSupply_,
        uint256 liquidityEthAmount,
        uint256 creatorBuyEthAmount,
        uint256 minCreatorTokensOut
    ) internal returns (uint256 lpAmount, uint256 lockId, uint256 creatorTokensBought, address pair) {
        require(platformFeeWallet != address(0), "TokenFactory: platform fee wallet not configured");
        require(priceFeed != address(0), "TokenFactory: price feed not configured");
        require(liquidityEthAmount > 0, "TokenFactory: no ETH sent for liquidity");

        IERC20(token).approve(address(router), totalSupply_);
        (uint256 amountTokenUsed, uint256 amountETHUsed, uint256 lpAmountAdded) = router.addLiquidityETH{value: liquidityEthAmount}(
            token,
            totalSupply_,
            _minWithSlippage(totalSupply_),
            _minWithSlippage(liquidityEthAmount),
            address(locker),
            block.timestamp + 15 minutes
        );
        lpAmount = lpAmountAdded;

        pair = IUniswapV2FactoryMinimal(router.factory()).getPair(token, router.WETH());
        require(pair != address(0), "TokenFactory: pair not found after addLiquidityETH");

        uint256 effectiveRewardBps = rewardsDistributor != address(0) ? rewardBps : 0;
        uint256 effectiveCreatorRewardBps = creatorRewardsDistributor != address(0) ? creatorRewardBps : 0;
        LaunchedToken(token).configureTax(
            pair, platformFeeWallet, feeBps, priceFeed, graduationTargetUsd, maxOracleStaleness,
            rewardsDistributor, effectiveRewardBps, creatorRewardsDistributor, effectiveCreatorRewardBps,
            feeWalletDistributor
        );

        uint256 unlockTime = block.timestamp + lpLockDuration;
        lockId = locker.lock(pair, creator_, lpAmount, unlockTime);

        emit LiquidityAdded(token, creator_, liquidityEthAmount, totalSupply_, lpAmount, unlockTime, lockId, pair);

        if (creatorBuyEthAmount > 0) {
            address[] memory path = new address[](2);
            path[0] = router.WETH();
            path[1] = token;
            uint256 effectiveMinOut = _effectiveMinBuyOut(creatorBuyEthAmount, amountETHUsed, amountTokenUsed, minCreatorTokensOut);
            uint256 balBefore = IERC20(token).balanceOf(creator_);
            router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: creatorBuyEthAmount}(
                effectiveMinOut,
                path,
                creator_,
                block.timestamp + 15 minutes
            );
            creatorTokensBought = IERC20(token).balanceOf(creator_) - balBefore;
            require(
                creatorTokensBought <= (totalSupply_ * maxCreatorBuyBps) / 10_000,
                "TokenFactory: creator buy-in exceeds max allowed share of supply"
            );
            emit CreatorBought(token, creator_, creatorBuyEthAmount, creatorTokensBought);
        }
    }

    /// @dev Gas-then-split settlement for a relayed launch. First
    /// reimburses the relayer for the gas it just spent submitting this
    /// very transaction (measured via gasleft() diffing, plus a flat
    /// per-tx overhead buffer, capped at maxRelayerGasReimbursementWei as a
    /// circuit breaker) — this is the "gas fees are taken from that [fee]"
    /// step. Only the true remainder after that gets split 50/50 between
    /// feeTreasury and rewardsDistributor, or 100% feeTreasury if
    /// rewardsDistributor is unset — identical rule to _finalizeLaunch,
    /// just applied to the post-gas remainder instead of the raw fee.
    function _settleRelayedFee(bytes32 voucherHash, address token, uint256 feeCollected, uint256 gasStart) internal {
        if (feeCollected == 0) return;

        uint256 gasUsed = (gasStart - gasleft()) + RELAY_GAS_OVERHEAD;
        uint256 gasReimbursement = gasUsed * tx.gasprice;
        if (maxRelayerGasReimbursementWei > 0 && gasReimbursement > maxRelayerGasReimbursementWei) {
            gasReimbursement = maxRelayerGasReimbursementWei;
        }
        if (gasReimbursement > feeCollected) {
            gasReimbursement = feeCollected; // relayer eats any shortfall rather than the launch reverting over it
        }

        if (gasReimbursement > 0) {
            (bool sentGas, ) = payable(relayer).call{value: gasReimbursement}("");
            require(sentGas, "TokenFactory: relayer gas reimbursement failed");
        }

        uint256 netFee = feeCollected - gasReimbursement;
        uint256 toRewards;
        uint256 toTreasury;
        if (netFee > 0) {
            if (rewardsDistributor != address(0)) {
                toRewards = netFee / 2;
                toTreasury = netFee - toRewards;
                if (toRewards > 0) {
                    (bool sentRewards, ) = rewardsDistributor.call{value: toRewards}("");
                    require(sentRewards, "TokenFactory: rewards transfer failed");
                }
                (bool sent, ) = feeTreasury.call{value: toTreasury}("");
                require(sent, "TokenFactory: fee transfer failed");
            } else {
                toTreasury = netFee;
                (bool sent, ) = feeTreasury.call{value: netFee}("");
                require(sent, "TokenFactory: fee transfer failed");
            }
        }

        emit RelayedFeeSettled(voucherHash, token, feeCollected, gasReimbursement, toTreasury, toRewards);
    }

    /// @dev Everything specific to seeding the pool itself, split out of
    /// _createWithLiquidity() to keep stack depth shallow. Seeds the pool
    /// with the full token supply, points the token's tax at the resulting
    /// pair, locks the LP to the creator, and optionally executes the
    /// creator's same-transaction buy-in — capped at maxCreatorBuyBps of
    /// totalSupply_ as an anti-rug safeguard (see the require below).
    function _launchWithLiquidity(
        address token,
        uint256 totalSupply_,
        uint256 liquidityEthAmount,
        uint256 creatorBuyEthAmount,
        uint256 minCreatorTokensOut
    ) internal returns (uint256 lpAmount, uint256 lockId, uint256 creatorTokensBought, address pair) {
        require(platformFeeWallet != address(0), "TokenFactory: platform fee wallet not configured");
        require(priceFeed != address(0), "TokenFactory: price feed not configured");
        require(liquidityEthAmount > 0, "TokenFactory: no ETH sent for liquidity");

        IERC20(token).approve(address(router), totalSupply_);
        (uint256 amountTokenUsed, uint256 amountETHUsed, uint256 lpAmountAdded) = router.addLiquidityETH{value: liquidityEthAmount}(
            token,
            totalSupply_,
            _minWithSlippage(totalSupply_), // 5–8% slippage tolerance — see liquiditySlippageBps
            _minWithSlippage(liquidityEthAmount),
            address(locker), // LP tokens mint straight to the locker — never pass through this factory
            block.timestamp + 15 minutes
        );
        lpAmount = lpAmountAdded;

        pair = IUniswapV2FactoryMinimal(router.factory()).getPair(token, router.WETH());
        require(pair != address(0), "TokenFactory: pair not found after addLiquidityETH");

        // rewardBps only ever actually applies once rewardsDistributor is
        // set — netting it to 0 here (rather than trusting the stored
        // default) means rewardBps can safely be pre-configured (its
        // default above is nonzero) well before the platform token or its
        // distributor exist, with zero effect on any launch until
        // setRewardsDistributor is actually called.
        uint256 effectiveRewardBps = rewardsDistributor != address(0) ? rewardBps : 0;
        uint256 effectiveCreatorRewardBps = creatorRewardsDistributor != address(0) ? creatorRewardBps : 0;
        LaunchedToken(token).configureTax(
            pair, platformFeeWallet, feeBps, priceFeed, graduationTargetUsd, maxOracleStaleness,
            rewardsDistributor, effectiveRewardBps, creatorRewardsDistributor, effectiveCreatorRewardBps,
            feeWalletDistributor
        );

        uint256 unlockTime = block.timestamp + lpLockDuration;
        lockId = locker.lock(pair, msg.sender, lpAmount, unlockTime);

        emit LiquidityAdded(token, msg.sender, liquidityEthAmount, totalSupply_, lpAmount, unlockTime, lockId, pair);

        // Optional creator buy-in: an ordinary swap against the pool that
        // was just created above, in the same transaction, sent to
        // msg.sender like any other buyer's swap would be — including
        // paying the tax just configured above, same as anyone else's buy
        // would. Nothing here mints tokens or bypasses the pool's pricing.
        //
        // Anti-rug cap: capped at maxCreatorBuyBps of totalSupply_, checked
        // against the actual net tokens the creator received (post-tax),
        // not an estimate — so there's no way to structure a buy-in that
        // lands over the cap. A buy-in that would exceed it reverts the
        // entire launch (liquidity add included), rather than silently
        // clamping the swap or letting it through — the creator resubmits
        // with a smaller buyEthAmount instead.
        if (creatorBuyEthAmount > 0) {
            address[] memory path = new address[](2);
            path[0] = router.WETH();
            path[1] = token;
            uint256 effectiveMinOut = _effectiveMinBuyOut(creatorBuyEthAmount, amountETHUsed, amountTokenUsed, minCreatorTokensOut);
            uint256 balBefore = IERC20(token).balanceOf(msg.sender);
            router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: creatorBuyEthAmount}(
                effectiveMinOut,
                path,
                msg.sender,
                block.timestamp + 15 minutes
            );
            creatorTokensBought = IERC20(token).balanceOf(msg.sender) - balBefore;
            require(
                creatorTokensBought <= (totalSupply_ * maxCreatorBuyBps) / 10_000,
                "TokenFactory: creator buy-in exceeds max allowed share of supply"
            );
            emit CreatorBought(token, msg.sender, creatorBuyEthAmount, creatorTokensBought);
        }
    }

    function tokensOf(address creator_) external view returns (address[] memory) {
        return _tokensByCreator[creator_];
    }

    function allTokens() external view returns (address[] memory) {
        return _tokenList;
    }

    /// @notice Previews the address createToken()/relayedCreateToken() will
    /// deploy to for a given (creator, salt) pair, without spending any gas
    /// or sending a transaction — a pure function of (this factory's own
    /// address, tokenImplementation, creator, salt). `creator_` must be the
    /// same address that will actually call createToken() (msg.sender) or,
    /// for a relayed launch, the voucher's `creator` field — see
    /// _deriveTokenSalt for why the address is bound to the creator. The
    /// front end (and scripts/launch.js) use this only to double-check an
    /// off-chain-mined salt actually produces the expected address before
    /// submitting the real transaction; the deploy itself never calls this,
    /// it just runs the identical CREATE2 computation inline via
    /// Clones.cloneDeterministic.
    function predictTokenAddress(address creator_, uint256 salt) external view returns (address) {
        return Clones.predictDeterministicAddress(tokenImplementation, _deriveTokenSalt(creator_, salt), address(this));
    }

    // ---- admin ----

    /// @notice Updates the flat fee for "Deploy Token" (no liquidity). See
    /// the contract-level note above on why this is a fixed wei amount —
    /// keeping it near a USD target (e.g. $50) as ETH's price moves is the
    /// caller's job, typically via scripts/updateFees.js on a schedule.
    function setDeployFee(uint256 newFee) external onlyOwner {
        deployFee = newFee;
        emit DeployFeeUpdated(newFee);
    }

    /// @notice Updates the flat fee for "Deploy and Add Liquidity (Launch)",
    /// charged on top of the liquidity/buy-in ETH. See setDeployFee.
    function setLaunchFee(uint256 newFee) external onlyOwner {
        launchFee = newFee;
        emit LaunchFeeUpdated(newFee);
    }

    function setLpLockDuration(uint256 newDuration) external onlyOwner {
        lpLockDuration = newDuration;
        emit LpLockDurationUpdated(newDuration);
    }

    function setFeeTreasury(address newTreasury) external onlyOwner {
        require(newTreasury != address(0), "TokenFactory: invalid treasury");
        feeTreasury = newTreasury;
        emit FeeTreasuryUpdated(newTreasury);
    }

    /// @notice Updates the anti-rug ceiling on a creator's own
    /// same-transaction buy-in, in bps of totalSupply_ (500 = 5.00%).
    /// Applies to launches from this point forward — a launch already
    /// mined keeps whatever cap was in effect when it ran, same as every
    /// other "applies going forward" setting here.
    function setMaxCreatorBuyBps(uint256 newBps) external onlyOwner {
        require(newBps <= 10_000, "TokenFactory: bps cannot exceed 100%");
        maxCreatorBuyBps = newBps;
        emit MaxCreatorBuyBpsUpdated(newBps);
    }

    /// @notice Adjusts the addLiquidityETH slippage tolerance, kept to a
    /// fixed 5.00%–8.00% band on purpose — narrow enough that it never
    /// stops meaning anything, wide enough to cover ordinary reserve noise
    /// without the launch spuriously reverting. Applies to every launch
    /// (direct or gasless-relayed) from this point forward; a launch
    /// already in flight uses whatever value was in effect when it read it.
    function setLiquiditySlippageBps(uint256 newBps) external onlyOwner {
        require(newBps >= MIN_LIQUIDITY_SLIPPAGE_BPS, "TokenFactory: slippage below 5% floor");
        require(newBps <= MAX_LIQUIDITY_SLIPPAGE_BPS, "TokenFactory: slippage above 8% ceiling");
        liquiditySlippageBps = newBps;
        emit LiquiditySlippageBpsUpdated(newBps);
    }

    /// @notice Adjusts the creator buy-in's slippage tolerance, same fixed
    /// 5.00%–8.00% band as setLiquiditySlippageBps, for the same reasons.
    function setBuyInSlippageBps(uint256 newBps) external onlyOwner {
        require(newBps >= MIN_LIQUIDITY_SLIPPAGE_BPS, "TokenFactory: slippage below 5% floor");
        require(newBps <= MAX_LIQUIDITY_SLIPPAGE_BPS, "TokenFactory: slippage above 8% ceiling");
        buyInSlippageBps = newBps;
        emit BuyInSlippageBpsUpdated(newBps);
    }

    /// @notice Points deployFee/launchFee's 50% rewards share, and every
    /// future launch's per-token reward diversion, at a
    /// PlatformRewardsDistributor. address(0) disables the entire feature
    /// (see _finalizeLaunch and rewardBps above) — fully reversible, and
    /// never touches a token or launch that already happened.
    function setRewardsDistributor(address newDistributor) external onlyOwner {
        rewardsDistributor = newDistributor;
        emit RewardsDistributorUpdated(newDistributor);
    }

    /// @notice See setRewardsDistributor above — identical convention,
    /// separate distributor. Wired once, whenever CreatorRewardsDistributor
    /// is deployed; nothing about flipping this on ever touches a token or
    /// launch that already happened.
    function setCreatorRewardsDistributor(address newDistributor) external onlyOwner {
        creatorRewardsDistributor = newDistributor;
        emit CreatorRewardsDistributorUpdated(newDistributor);
    }

    /// @notice See setRewardsDistributor above — identical convention,
    /// separate distributor. Wired once, whenever FeeWalletDistributor is
    /// deployed; nothing about flipping this on ever touches a token or
    /// launch that already happened.
    function setFeeWalletDistributor(address newDistributor) external onlyOwner {
        feeWalletDistributor = newDistributor;
        emit FeeWalletDistributorUpdated(newDistributor);
    }

    /// @notice Points relayedCreateToken's onlyRelayer gate at the
    /// platform's relayer hot wallet. address(0) (the default) disables
    /// gasless relayed launches entirely — depositForRelayedLaunch still
    /// accepts deposits either way, so anything deposited while this is
    /// unset just sits there reclaimable once its deadline passes, rather
    /// than being stuck. Fully reversible, and never touches a launch that
    /// already happened.
    ///
    /// Enabling a relayer (newRelayer != address(0)) requires
    /// maxRelayerGasReimbursementWei to already be set to a real, non-zero
    /// value — the default of 0 means "no cap" on how much of a launch's
    /// fee _settleRelayedFee can pay itself back as gas reimbursement, so a
    /// relayer is never turned on with that safety circuit breaker silently
    /// left wide open. Call setMaxRelayerGasReimbursement with a value
    /// sized to real gas costs on this chain before (or in the same
    /// deployment script as) enabling the relayer.
    function setRelayer(address newRelayer) external onlyOwner {
        if (newRelayer != address(0)) {
            require(
                maxRelayerGasReimbursementWei > 0,
                "TokenFactory: set maxRelayerGasReimbursementWei before enabling a relayer"
            );
        }
        relayer = newRelayer;
        emit RelayerUpdated(newRelayer);
    }

    /// @notice Updates the circuit-breaker cap on how much gas
    /// reimbursement a single relayedCreateToken call can pay itself, in
    /// wei. 0 means no cap. Protects against a compromised or
    /// malfunctioning relayer key inflating tx.gasprice to drain more than
    /// a real deploy could plausibly cost.
    /// @notice FIX (post-audit, HoodLaunch_TokenFactory_LaunchedToken_Audit —
    /// Finding F-2): setRelayer() only ever checked
    /// maxRelayerGasReimbursementWei > 0 at the moment a relayer was
    /// *enabled* — this setter had no corresponding check, so it could be
    /// called with newCapWei == 0 at any later time, including while a
    /// relayer was already active, silently reopening the circuit breaker
    /// setRelayer() exists to enforce. Now rejects zeroing the cap while a
    /// relayer is configured, so the invariant holds continuously instead of
    /// only at the one moment setRelayer() itself checks it.
    function setMaxRelayerGasReimbursement(uint256 newCapWei) external onlyOwner {
        require(
            relayer == address(0) || newCapWei > 0,
            "TokenFactory: cannot zero the gas reimbursement cap while a relayer is active"
        );
        maxRelayerGasReimbursementWei = newCapWei;
        emit MaxRelayerGasReimbursementUpdated(newCapWei);
    }

    /// @notice Update the tax defaults applied to pools created from this
    /// point forward. Existing tokens are unaffected — each one snapshots
    /// these values into its own storage the moment configureTax() runs.
    /// platformFeeWallet_ and priceFeed_ may still be set to address(0)
    /// deliberately — that's the documented way to leave the platform tax
    /// unconfigured for launches going forward (_launchWithLiquidity simply
    /// refuses to launch until both are set again). feeBps_,
    /// graduationTargetUsd_, and maxOracleStaleness_ get real bounds below
    /// so a mistyped — or maliciously chosen — value can't silently brick
    /// every future launch's transfers or make its tax effectively
    /// confiscatory (feeBps_ above MAX_FEE_BPS) or defeat the tax from block one
    /// (graduationTargetUsd_ == 0) — mirrors the same-style bound already
    /// enforced on setMaxCreatorBuyBps. rewardBps_ is the new addition: how
    /// much of feeBps_ gets carved off to rewardsDistributor going
    /// forward — must never exceed feeBps_ itself, same reasoning as every
    /// other bound here.
    function setTaxDefaults(
        address platformFeeWallet_,
        uint256 feeBps_,
        address priceFeed_,
        uint256 graduationTargetUsd_,
        uint256 maxOracleStaleness_,
        uint256 rewardBps_,
        uint256 creatorRewardBps_
    ) external onlyOwner {
        require(feeBps_ <= MAX_FEE_BPS, "TokenFactory: feeBps exceeds MAX_FEE_BPS ceiling");
        require(graduationTargetUsd_ > 0, "TokenFactory: graduation target must be > 0");
        require(maxOracleStaleness_ > 0, "TokenFactory: oracle staleness must be > 0");
        require(rewardBps_ + creatorRewardBps_ <= feeBps_, "TokenFactory: rewardBps+creatorRewardBps cannot exceed feeBps");
        platformFeeWallet = platformFeeWallet_;
        feeBps = feeBps_;
        priceFeed = priceFeed_;
        graduationTargetUsd = graduationTargetUsd_;
        maxOracleStaleness = maxOracleStaleness_;
        rewardBps = rewardBps_;
        creatorRewardBps = creatorRewardBps_;
        emit TaxDefaultsUpdated();
    }

    /// @notice Escape hatch for an already-launched token whose price feed
    /// has gone permanently stale or was never a real, maintained feed —
    /// see LaunchedToken.updatePriceFeed. Owner-only, and deliberately
    /// narrow: this can only repoint that one token's oracle inputs, never
    /// its fee rate, fee wallet, pair, or taxActive directly. Graduation
    /// still requires the same market-cap/confirmation-window check as
    /// ever; this only unblocks that path from behind a dead oracle. As of
    /// LaunchedToken.updatePriceFeed's own freshness guard, this call
    /// reverts outright if the token's current feed can still report a
    /// fresh price — it cannot be used to repoint a healthy, currently-live
    /// token's oracle inputs on a whim.
    function updateTokenPriceFeed(address token, address newPriceFeed_, uint256 newMaxOracleStaleness_) external onlyOwner {
        LaunchedToken(token).updatePriceFeed(newPriceFeed_, newMaxOracleStaleness_);
        emit TokenPriceFeedUpdated(token, newPriceFeed_, newMaxOracleStaleness_);
    }
}

